window.__D("text/zohar-hebrew-translation/c008",{"p":[[9522011348,"<p>וְהוּא עָבַר לִפְנֵיהֶם וַיִּשְׁתַּחוּ אַרְצָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (שמות לד) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר כִּי ה' קַנָּא שְׁמוֹ. וְכִי יַעֲקֹב, שֶׁהוּא בְּחִיר הָאָבוֹת, שֶׁנִּבְחַר חֵלֶק שָׁלֵם לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְהוּא הִתְקָרֵב אֵלָיו יוֹתֵר (ס\"א ונשלם למעלה ולמטה), אֵיךְ הִשְׁתַּחֲוָה לְאוֹתוֹ עֵשָׂו הָרָשָׁע שֶׁהוּא בְּצַד שֶׁל אֵל אַחֵר, וּמִי שֶׁסּוֹגֵד לוֹ - סוֹגֵד לְאֵל אַחֵר? אִם תֹּאמַר מִשּׁוּם שֶׁאָמְרוּ, שׁוּעָל בִּשְׁעָתוֹ הִשְׁתַּחֲוֵה לוֹ - לֹא כָּךְ, שֶׁהֲרֵי עֵשָׂו כְּמוֹ אֵל אַחֵר הָיָה, וְיַעֲקֹב לֹא יִשְׁתַּחֲוֶה לְאוֹתוֹ צַד וּלְאוֹתוֹ חֵלֶק כְּלָל.</p>\n<p>(פתח רבי אבא ואמר), אֶלָּא כָּתוּב (שמואל א כה) וַאֲמַרְתֶּם כֹּה לֶחָי וְאַתָּה שָׁלוֹם וּבֵיתְךְ שָׁלוֹם וְכָל אֲשֶׁר לְךְ שָׁלוֹם. וַהֲרֵי נִתְבָּאֵר שֶׁאָסוּר (לו) לְהַקְדִּים שָׁלוֹם לָרְשָׁעִים, וְכֵיוָן שֶׁאָסוּר, אֵיךְ מָצָאנוּ שֶׁדָּוִד אָמַר פָּסוּק זֶה לְנָבָל? אֶלָּא הֲרֵי פֵּרְשׁוּהָ שֶׁאָמַר לַקָּדוֹשׁ- בָּרוּךְ-הוּא כְּדֵי לְקַשֵּׁר אוֹתוֹ לְחַי, וְחָשַׁב נָבָל שֶׁעָלָיו אָמַר.</p>\n<p>כְּמוֹ זֶה (בראשית מז) וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה, וְכִי אֶל בְּנוֹ הוּא הִשְׁתַּחֲוָה? אֶלָּא לִמְקוֹם הַשְּׁכִינָה כָּרַע וְהִשְׁתַּחֲוָה, אַף כָּאן וְהוּא עָבַר לִפְנֵיהֶם. מַה זֶּה וְהוּא? זוֹ שְׁכִינָה עֶלְיוֹנָה שֶׁהָיְתָה הוֹלֶכֶת לְפָנָיו (כרע), וְזוֹהִי שְׁמִירָה עֶלְיוֹנָה. כֵּיוָן שֶׁרָאָה יַעֲקֹב, אָמַר, הִנֵּה זְמַן לְהִשְׁתַּחֲווֹת לַקָּדוֹשׁ-בָּרוּךְ-הוּא שֶׁהָיָה הוֹלֵךְ עִמּוֹ.</p>\n<p>כָּרַע וְהִשְׁתַּחֲוָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו, וְלֹא כָתוּב וַיִּשְׁתַּחוּ לְעֵשָׂו. אֶלָּא כֵּיוָן שֶׁרָאָה שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹלֵךְ עִמּוֹ, אָז הִשְׁתַּחֲוָה כְּנֶגְדּוֹ, כְּדֵי שֶׁלֹּא לָתֵת כָּבוֹד לְהִשְׁתַּחֲווֹת לְאַחֵר פְּרָט לוֹ, וְהַכֹּל הוּא כָּרָאוּי. אַשְׁרֵי הַצַּדִּיקִים שֶׁכָּל מַעֲשֵׂיהֶם שֶׁעוֹשִׂים בִּשְׁבִיל כְּבוֹד רִבּוֹנָם הוּא, וּכְדֵי שֶׁלֹּא יִסְטוּ יָמִינָה וּשְׂמֹאלָה.</p>"],[9522011349,"<p>וַיָּרָץ עֵשָׂו לִקְרָאתוֹ וַיְחַבְּקֵהוּ וַיִּפֹּל עַל צַוָּארָו. צַוָּארוֹ כָּתוּב חָסֵר. וַיִּשָּׁקֵהוּ וַיִּבְכּוּ. רַבִּי יִצְחָק אָמַר, (ישעיה נז) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ כִּי הַשְׁקֵט לֹא יוּכַל וַיִּגְרְשׁוּ מֵימָיו רֶפֶשׁ וָטִיט. פָּסוּק זֶה נִתְבָּאֵר. וּבְדִבְרֵי תוֹרָה יֵשׁ כַּמָּה סוֹדוֹת עֶלְיוֹנִים מְשֻׁנִּים זֶה מִזֶּה, וְהַכֹּל אֶחָד.</p>\n<p>וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ כִּי הַשְׁקֵט לֹא יוּכָל - זֶה עֵשָׂו שֶׁכָּל מַעֲשָׂיו בְּרֶשַׁע וּבְחֵטְא, שֶׁהֲרֵי כְּשֶׁבָּא יַעֲקֹב אֵלָיו, מַעֲשָׂיו לֹא הָיוּ בְשָׁלוֹם. וַיִּפֹּל עַל צַוָּארָו - אֶחָד. צַוָּארוֹ זוֹ יְרוּשָׁלַיִם, שֶׁהִיא צַוָּארוֹ שֶׁל כָּל הָעוֹלָם. וַיִּפֹּל עַל צַוָּארָו וְלֹא עַל צַוָּארָיו, מִשּׁוּם שֶׁפַּעֲמַיִם נֶחֱרַב בֵּית הַמִּקְדָּשׁ - אֶחָד מִבָּבֶל, וְאֶחָד מִזַּרְעוֹ שֶׁל עֵשָׂו, שֶׁהִפִּיל עַצְמוֹ עָלָיו פַּעַם אֶחָד וְהֶחֱרִיבוֹ, וְעַל זֶה וַיִּפֹּל עַל צַוָּארָו - אֶחָד.</p>\n<p>וַיִּשָּׁ\"קֵהוּ נָקוּד לְמַעְלָה, כִּי לֹא נְשָׁקוֹ בִּרְצוֹנוֹ. וְשָׁנִינוּ, מַה זֶּה שֶׁכָּתוּב (משלי כז) וְנַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא? זֶה בִּלְעָם כְּשֶׁבֵּרַךְ אֶת יִשְׂרָאֵל, שֶׁהֲרֵי לֹא בֵרְכָם בִּרְצוֹן הַלֵּב. אַף כָּאן נַעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא - זֶה עֵשָׂו.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כָּתוּב (תהלים ג) קוּמָה ה' הוֹשִׁיעֵנִי אֱלֹהַי כִּי הִכִּיתָ אֶת כָּל אֹיְבַי לֶחִי שִׁנֵּי רְשָׁעִים שִׁבַּרְתָּ. וְשָׁנִינוּ, אַל תִּקְרֵי שִׁבַּרְתָּ אֶלָּא שִׁרְבַּבְתָּ, שֶׁהֲרֵי גָּדְלוּ שִׁנָּיו וְחָשַׁב לִנְשֹׁךְ אוֹתוֹ וְכוּ'. וְעַל זֶה וַיִּבְכּוּ, זֶה בָּכָה וְזֶה בָּכָה, וּבֵאֲרוּהָ הַחֲבֵרִים.</p>\n<p>בֹּא רְאֵה כַּמָּה הָיָה לִבּוֹ וּרְצוֹנוֹ שֶׁל עֵשָׂו לְיַעֲקֹב, שֶׁהֲרֵי אֲפִלּוּ בְּאוֹתָהּ שָׁעָה חָשַׁב לְאֹרֶךְ זְמַן (באריכות הימים) לַעֲשׂוֹת לוֹ רָעוֹת וּלְקַטְרֵג לוֹ, וְעַל זֶה וַיִּבְכּוּ. זֶה הָיָה בּוֹכֶה שֶׁלֹּא הָיָה חוֹשֵׁב לְהִנָּצֵל מִיָּדוֹ, וְזֶה הָיָה בּוֹכֶה מִשּׁוּם שֶׁאָבִיו הָיָה קַיָּם וְלֹא יָכוֹל לוֹ.</p>\n<p>אָמַר רַבִּי אַבָּא, וַדַּאי נֶחֱלַשׁ רָגְזוֹ שֶׁל עֵשָׂו בְּשָׁעָה שֶׁרָאָה אֶת יַעֲקֹב. מָה הַטַּעַם? מִשּׁוּם שֶׁהֲרֵי הִסְכִּים עִמּוֹ אוֹתוֹ מְמֻנֶּה שֶׁל עֵשָׂו, וְעַל זֶה לֹא יָכֹל עֵשָׂו לִשְׁלֹט בְּרָגְזוֹ, שֶׁהֲרֵי כָּל הַדְּבָרִים שֶׁל הָעוֹלָם הַזֶּה תְּלוּיִים לְמַעְלָה, וּכְשֶׁהִסְכִּימוּ לְמַעְלָה בַּתְּחִלָּה - הִסְכִּימוּ לְמַטָּה. הַשִּׁלְטוֹן אֵינוֹ לְמַטָּה עַד שֶׁנִּתָּן הַשִּׁלְטוֹן לְמַעְלָה, וְהַכֹּל תָּלוּי זֶה בָּזֶה.</p>"],[9522011350,"<p>יַעָבָר נָא אֲדנִי לִפְנֵי עַבְדּוֹ וַאֲנִי אֶתְנַהֲלָה לְאִטִּי וְגוֹ'. אָמַר רַבִּי אֶלְעָזָר, הַיְנוּ מַה שֶּׁאָמַרְנוּ בַּתְּחִלָּה, שֶׁיַּעֲקֹב לֹא רָצָה עַכְשָׁו אוֹתָן בְּרָכוֹת רִאשׁוֹנוֹת שֶׁבֵּרְכוֹ אָבִיו, (משום שכתוב (איכה ג) טוב לגבר כי ישא על בנעוריו, וכתוב (משלי לא) ותשחק ליום אחרון) וַעֲדַיִן לֹא הִתְקַיְּמוּ בוֹ אֲפִלּוּ אֶחָד מֵהֶם, מִשּׁוּם שֶׁהֶעֱבִיר אוֹתָם לְסוֹף הַיָּמִים בְּשָׁעָה שֶׁיִּצְטָרְכוּ לְבָנָיו מוּל כָּל עַמֵּי הָעוֹלָם.</p>\n<p>וְלָכֵן בְּשָׁעָה שֶׁאָמַר עֵשָׂו נִסְעָה וְנֵלֵכָה, וּנְחַלֵּק הָעוֹלָם הַזֶּה כְּאֶחָד וְנִשְׁלֹט כְּאֶחָד - מָה אָמַר יַעֲקֹב יַעֲבָר? נָא אֲדנִי לִפְנֵי עַבְדּוֹ. יַקְדִּים עֵשָׂו שִׁלְטוֹנוֹ עַכְשָׁו בָּעוֹלָם הַזֶּה, יַעֲבָר נָא, כְּמוֹ שֶׁנֶּאֱמַר (מיכה ב) וַיַּעֲבֹר מַלְכָּם לִפְנֵיהֶם וַה' בְּרֹאשָׁם, הַקְדֵּם אַתָּה שִׁלְטוֹנְךְ בַּתְּחִלָּה בָּעוֹלָם הַזֶּה - וַאֲנִי אֶתְנַהֲלָה לְאִטִּי, אֲנִי אַעֲלֶה עַצְמִי לְאוֹתוֹ עוֹלָם הַבָּא וּלְסוֹף הַיָּמִים, לְאוֹתָם יָמִים שֶׁהוֹלְכִים לְאַט.</p>\n<p>לְרֶגֶל הַמְּלָאכָה - אֵיזוֹ מְלָאכָה? זוֹ אַסְפַּקְלַרְיָה שֶׁלֹּא מְאִירָה שֶׁבָּהּ נַעֲשָׂה מַעֲשֵׂה הָעוֹלָם. אֲשֶׁר לְפָנַי - זוֹהִי מִלִּפְנֵי ה' בְּכָל מָקוֹם. וּלְרֶגֶל הַיְלָדִים - זֶהוּ סוֹד שֶׁל הַכְּרוּבִים לְהַרְאוֹת סוֹד הָאֱמוּנָה שֶׁהוּא נִדְבָּק בָּהֶם.</p>\n<p>עַד אֲשֶׁר אָבֹא אֶל אֲדנִי שֵׂעִירָה - אֲנִי אֶסְבֹּל גָּלוּת שֶׁלְּךְ עַד שֶׁיָּבֹא וְיַגִּיעַ זְמַנִּי לִשְׁלֹט עַל הַר עֵשָׂו, כְּמוֹ שֶׁנֶּאֱמַר (עובדיה א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו, וְאָז וְהָיְתָה לַה' הַמְּלוּכָה.</p>"],[9522011351,"<p>וְיַעָקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת וּלְמִקְנֵהוּ עָשָׂה סֻכֹּת עַל כֵּן קָרָא שֵׁם הַמָּקוֹם סֻכּוֹת. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים קכז) שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה אִם ה' לֹא יִבְנֶה בַיִת וְגוֹ', אִם ה' לֹא יִשְׁמָר עִיר וְגוֹ'. בֹּא רְאֵה, בְּשָׁעָה שֶׁעָלָה בִּרְצוֹן הַקָּדוֹשׁ בָּרוּךְ הוּא לִבְרֹא עוֹלָם, הוֹצִיא מִתּוֹךְ נִיצוֹץ חָזָק קֶשֶׁר אֶחָד, וְהִתְלַהֵט מִתּוֹךְ הַחֹשֶׁךְ, וְנִשְׁאָר בַּעֲלִיָּה וְיָרַד לְמַטָּה. אוֹתָהּ חֲשֵׁכָה לָהֲטָה (והתלהטה) בְּמֵאָה שְׁבִילִים דְּרָכִים דַּקִּיקִים גְּדוֹלִים, וְנַעֲשָׂה בַּיִת שֶׁל הָעוֹלָם.</p>\n<p>בַּיִת זֶה הוּא בְּתוֹךְ אֶמְצַע הַכֹּל. כַּמָּה פְתָחִים וַחֲדָרִים לוֹ סָבִיב סָבִיב, מְקוֹמוֹת עֶלְיוֹנִים קְדוֹשִׁים, שָׁם מְקַנְּנוֹת צִפֳּרֵי הַשָּׁמַיִם כָּל אֶחָד וְאֶחָד לְמִינוֹ. בְּתוֹכוֹ יוֹצֵא אִילָן גָּדוֹל אֶחָד וְחָזָק, עֲנָפָיו וּפִרְיוֹ רַב, מָזוֹן לַכֹּל בּוֹ. אוֹתוֹ הָאִילָן עוֹלֶה לְעַנְנֵי הַשָּׁמַיִם, וְנִטְמָן בֵּין שְׁלֹשָׁה הָרִים. מִתַּחַת לִשְׁלֹשֶׁת הֶהָרִים הַלָּלוּ יוֹצֵא, עוֹלֶה לְמַעְלָה וְיוֹרֵד לְמַטָּה.</p>\n<p>הַבַּיִת הַזֶּה מֻשְׁקֶה מִמֶּנּוּ וְגוֹנֵז בְּתוֹכוֹ כַּמָּה גְנָזִים עֶלְיוֹנִים שֶׁלֹּא נוֹדְעוּ, בָּזֶה נִבְנֶה בַּיִת זֶה וְנִתְקָן. אוֹתוֹ הָאִילָן מִתְגַּלֶּה בַּיּוֹם וּמִתְכַּסֶּה בַּלַּיְלָה. וְהַבַּיִת זֶה שׁוֹלֵט בַּלַּיְלָה וּמִתְכַּסֶּה בַּיּוֹם.</p>\n<p>בְּשָׁעָה שֶׁנִּכְנָס הַחֹשֶׁךְ וְנִקְשָׁר בּוֹ שׁוֹלֵט, וְכָל הַפְּתָחִים סְתוּמִים מִכָּל הַצְּדָדִים. אָז כַּמָּה רוּחוֹת פּוֹרְחוֹת בָּאֲוִיר, תְּאֵבוֹת לָדַעַת וּלְהִכָּנֵס בּוֹ, וְנִכְנָסוֹת בֵּין אוֹתָן צִפֳּרִים, וְלוֹקְחוֹת עֵדוּת, וְשָׁטוֹת וְרוֹאוֹת מַה שֶּׁרוֹאוֹת.</p>\n<p>עַד שֶׁמִּתְעוֹרֵר אוֹתוֹ חֹשֶׁךְ שֶׁנִּקְשַׁר בּוֹ, וּמוֹצִיא שַׁלְהֶבֶת אַחַת, וּמַכֶּה בְּכָל הַפַּטִּישִׁים הַחֲזָקִים, וּפוֹתֵחַ פְּתָחִים וּבוֹקֵעַ סְלָעִים. עוֹלָה וְיוֹרֶדֶת אוֹתָהּ שַׁלְהֶבֶת וּמַכָּה בָּעוֹלָם וּמְעוֹרֶרֶת קוֹלוֹת לְמַעְלָה וּלְמַטָּה.</p>\n<p>וְאָז כָּרוֹז אֶחָד עוֹלֶה וְנִקְשָׁר בָּאֲוִיר וְקוֹרֵא. אוֹתוֹ אֲוִיר יוֹצֵא מִתּוֹךְ עַמּוּד עָנָן שֶׁל הַמִּזְבֵּחַ הַפְּנִימִי, וּכְשֶׁיּוֹצֵא מִתְפַּשֵּׁט לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. אֶלֶף אֲלָפִים עוֹמְדִים מִצַּד שֶׁהוּא שְׂמֹאל, וְרִבּוֹא רְבָבוֹת עוֹמְדִים מִצַּד שֶׁהוּא יָמִין, וְהַכָּרוֹז עוֹמֵד בְּקִיּוּמוֹ, קוֹרֵא בְחַיִל וּמַכְרִיז. אָז כַּמָּה אוֹתָם שֶׁמְּתַקְּנִים שִׁירָה וְעוֹבְדִים עֲבוֹדָה, וּשְׁנֵי פְתָחִים נִפְתָּחִים, אֶחָד לְצַד דָּרוֹם וְאֶחָד לְצַד צָפוֹן.</p>\n<p>עוֹלֶה הַבַּיִת הַזֶּה וְנִתָּן וּמִתְקַשֵּׁר בֵּין שְׁנֵי צְדָדִים, וְשִׁירִים מְזַמְּרִים וְתִשְׁבָּחוֹת עוֹלוֹת. אָז נִכְנָס מִי שֶׁנִּכְנָס בְּלַחַשׁ, וְהַבַּיִת מִתְלַהֵט בְּשִׁשָּׁה אוֹרוֹת מְאִירִים זִיו לְכָל צַד, וְנַהֲרוֹת בְּשָׂמִים יוֹצְאִים וּמַשְׁקִים כָּל חַיּוֹת הַשָּׂדֶה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם וְגוֹ', וּמְזַמְּרִים עַד עֲלוֹת הַבֹּקֶר. וּכְשֶׁעוֹלֶה הַבּקֶר, אָז כּוֹכָבִים וּמַזְּלוֹת הַשָּׁמַיִם וְחֵילוֹתֵיהֶם, כֻּלָּם מְשַׁבְּחִים וְאוֹמְרִים שִׁירָה, כְּמוֹ שֶׁנֶּאֱמַר (איוב לח) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים.</p>\n<p>בֹּא רְאֵה, (תהלים קכז) אִם ה' לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ, אִם ה' לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. אִם ה' וְגוֹ' - זֶה הַמֶּלֶךְ הָעֶלְיוֹן שֶׁהוּא בּוֹנֶה אֶת הַבַּית הַזֶּה תָּמִיד וּמְתַקֵּן אוֹתוֹ. אֵימָתַי? כְּשֶׁעוֹלִים הָרְצוֹנוֹת וְהָעֲבוֹדוֹת מִלְּמַטָּה כָּרָאוּי.</p>\n<p>אִם ה' לֹא יִשְׁמָר עִיר, אֵימָתַי? בְּשָׁעָה שֶׁנֶּחְשָׁךְ הַלַּיְלָה וְהַצְּדָדִים הַמְזֻיָּנִים שׁוֹרִים וּמְשׁוֹטְטִים בָּעוֹלָם, וְהַפְּתָחִים סְתוּמִים, וְנִשְׁמָר מִכָּל הַצְּדָדִים שֶׁלֹּא יִתְקָרֵב בּוֹ עָרֵל וְטָמֵא, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה נב) לֹא יוֹסִיף לָבֹא בָךְ עוֹד עָרֵל וְטָמֵא, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַעֲבִירָם מִן הָעוֹלָם.</p>\n<p>מִי עָרֵל וּמִי טָמֵא? אֶלָּא הַכֹּל אֶחָד עָרֵל וְטָמֵא. זֶהוּ שֶׁהִתְפַּתָּה בּוֹ וְהָלַךְ אַחֲרָיו אָדָם וְאִשְׁתּוֹ וְגָרְמוּ מָוֶת לְכָל הָעוֹלָם, וְהוּא הַמְטַמֵּא אֶת הַבַּיִת הַזֶּה עַד אוֹתוֹ זְמַן שֶׁיַּעֲבִירוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא מִן הָעוֹלָם. מִשּׁוּם כָּךְ אִם ה' לֹא יִשְׁמָר עִיר, שָׁוְא וַדַּאי.</p>\n<p>בֹּא רְאֵה, וְיַעֲקֹב נָסַע סֻכֹּתָה, נָסַע כְּנֶגֶד חֶלְקוֹ שֶׁל הָאֱמוּנָה. מַה כָּתוּב לְמַעְלָה? וַיָּשָׁב בַּיּוֹם הַהוּא עֵשָׂו לְדַרְכּוֹ שֵׂעִירָה, וְכָתוּב וְיַעֲקֹב נָסַע סֻכֹּתָה. אֶלָּא כָּל אֶחָד נִפְרַד לַצַּד שֶׁלּוֹ - עֵשָׂו לַצַּד שֶׁל שֵׂעִיר, מַה זֶּה שֵׂעִיר? זוֹ אִשָּׁה זָרָה, אֵל נֵכָר. וְיַעֲקֹב נָסַע סֻכֹּתָה, זוֹ הָאֱמוּנָה הָעֶלְיוֹנָה.</p>\n<p>וַיִּבֶן לוֹ בָּיִת, כְּמוֹ שֶׁנֶּאֱמַר (שם) בֵּית יַעֲקֹב. אָמַר רַבִּי אֶלְעָזָר, שֶׁתִּקֵּן תְּפִלַּת עַרְבִית כָּרָאוּי. וּלְמִקְנֵהוּ עָשָׂה סֻכֹּת, שְׁאָר סֻכּוֹת לִשְׁמֹר אוֹתָם, וְזֶהוּ חֶלְקוֹ.</p>\n<p>וְאָז וַיָּבא יַעֲקֹב שָׁלֵם - שָׁלֵם מֵהַכֹּל, וּבֵאֲרוּהוּ. וְכָתוּב (תהלים עו) וַיְהִי בְשָׁלֵם סֻכּוֹ וְגוֹ', וּבֵאֲרוּהוּ, וְהַכֹּל סוֹד אֶחָד. אָז הִתְחַבְּרָה עִמּוֹ הָאֱמוּנָה כְּשֶׁהָיָה שָׁלֵם, כְּשֶׁהִתְעַטֵּר בַּמָּקוֹם שֶׁרָאוּי לוֹ, וְאָז סֻכָּה זוֹ הִתְעַטְּרָה עִמּוֹ, שֶׁהָיָה שָׁלֵם מֵהָאָבוֹת, שֶׁהָיָה שָׁלֵם מִבָּנָיו, וְזֶהוּ שָׁלֵם, שָׁלֵם לְמַעְלָה שָׁלֵם לְמַטָּה, שָׁלֵם בַּשָּׁמַיִם שָׁלֵם בָּאָרֶץ. שָׁלֵם לְמַעְלָה - שֶׁהוּא כְּלַל הָאָבוֹת, תִּפְאֶרֶת יִשְׂרָאֵל. שָׁלֵם לְמַטָּה - בְּבָנָיו הַקְּדוֹשִׁים. שָׁלֵם בַּשָּׁמַיִם שָׁלֵם בָּאָרֶץ. וְאָז וַיְהִי בְשָׁלֵם סֻכּוֹ, וּבֵאֲרוּהוּ. מִיָּד מַה כָּתוּב? וַתֵּצֵא דִינָה בַּת לֵאָה, וּבֵאֲרוּהוּ הַחֲבֵרִים</p>"],[9522011352,"<p>בֹּא רְאֵה כַּמָּה דְרָגוֹת וּצְדָדִים נִפְרָדִים לְמַעְלָה, וְכֻלָּם מְשֻׁנִּים זֶה מִזֶּה, חַיּוֹת מְשֻׁנּוֹת אֵלּוּ מֵאֵלּוּ, אֵלֶּה מְקַטְרְגִים לִשְׁלֹט עַל אֵלֶּה וְלִטְרֹף טֶרֶף כָּל אֶחָד וְאֶחָד לְמִינוֹ.</p>\n<p>מִצַּד שֶׁל רוּחַ הַטֻּמְאָה כַּמָּה דְרָגוֹת נִפְרָדוֹת, וְכֻלָּם אוֹרְבִים לְקַטְרֵג אֵלֶּה כְּנֶגֶד אֵלֶּה, שֶׁהֲרֵי כָּתוּב (דברים כב) לֹא תַחֲר!שׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו, שֶׁכְּשֶׁמִּתְחַבְּרִים, מְקַטְרְגִים עוֹלָם.</p>\n<p>וּבֹא וּרְאֵה, תְּשׁוּקַת הַדְּרָגוֹת הַטְּמֵאוֹת אֵינָהּ אֶלָּא לְקַטְרֵג בַּצְּדָדִים הַקְּדוֹשִׁים. יַעֲקֹב, שֶׁהוּא קָדוֹשׁ, כֻּלָּם אָרְבוּ לוֹ וְקִטְרְגוּ עִמּוֹ. בַּתְּחִלָּה נְשָׁכוֹ נָחָשׁ, כְּמוֹ שֶׁנֶּאֱמַר וַיִּגַּע בְּכַף יְרֵכוֹ. עַכְשָׁו נְשָׁכוֹ חֲמוֹר.</p>\n<p>שָׁם הוּא עוֹמֵד אֵצֶל הַנָּחָשׁ. עַכְשָׁו שִׁמְעוֹן וְלֵוִי, שֶׁבָּאוּ מִצַּד הַדִּין הַקָּשֶׁה, עָמְדוּ כְּלַפֵּי הַחֲמוֹר וְשָׁלְטוּ עָלָיו בְּכָל הַצְּדָדִים וְנִכְפָּה לִפְנֵיהֶם, כְּמוֹ שֶׁנֶּאֱמַר וְאֶת חֲמוֹר וְאֶת שְׁכֶם בְּנוֹ הָרְגוּ לְפִי חָרֶב. וְשִׁמְעוֹן שֶׁהָיָה (שור), מַזָּלוֹ (הוא) שׁוֹר, בָּא עַל חֲמוֹר וְקִטְרֵג בּוֹ כְּדֵי שֶׁלֹּא יִתְחַבְּרוּ כְאֶחָד, וְנִמְצָא שֶׁהוּא מְקַטְרֵג שֶׁלּוֹ.</p>\n<p>וְכֻלָּם בָּאִים לְקַטְרֵג לְיַעֲקֹב, וְהוּא נִצָּל, וְאַחַר כָּךְ הוּא שׁוֹלֵט עֲלֵיהֶם. אַחַר כָּךְ בָּא שׁוֹר וְנִשְׁלָם בַּחֲמוֹרִים שֶׁכֻּלָּם מִצַּד הַחֲמוֹר - יוֹסֵף שֶׁהוּא שׁוֹר, וּמִצְרַיִם שֶׁהֵם חֲמוֹרִים, שֶׁכָּתוּב בָּהֶם (יחזקאל כג) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם.</p>\n<p>וְעַל זֶה אַחַר כָּךְ בְּנֵי יַעֲקֹב נָפְלוּ בֵּין אוֹתָם חֲמוֹרִים, מִשּׁוּם שֶׁהִזְדַּוֵּג שׁוֹר עִמָּם וְנָשְׁכוּ אוֹתָם עֲצָמוֹת וּבָשָׂר, עַד שֶׁהִתְעוֹרֵר לֵוִי כְּמוֹ מִקֹּדֶם וּפִזֵּר אוֹתָם הַחֲמוֹרִים (שהזדוגו) לִכְפּוֹת אוֹתָם, וְשָׁבַר כֹּחָם מֵהָעוֹלָם, וְהוֹצִיא אֶת הַשּׁוֹר מִשָּׁם. זֶהוּ שֶׁכָּתוּב (שמות יג) וַיִּקַּח מֹשֶׁה אֶת עַצְמוֹת יוֹסֵף עִמּוֹ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁבָּא שִׁמְעוֹן בַּהַתְחָלָה עַל אוֹתוֹ חֲמוֹר, הִתְעוֹרֵר עֲלֵיהֶם דָּם שֶׁנִּמּוֹלוּ, וְאַחַר כָּךְ וַיַּהַרְגוּ כָּל זָכָר. כְּמוֹ זֶה עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי לֵוִי, זֶה מֹשֶׁה, בְּאוֹתָם חֲמוֹרִים בְּמִצְרַיִם. בַּתְּחִלָּה דָּם, אַחַר כָּךְ (שם) וַיַּהֲרֹג ה' כָּל בְּכוֹר בְּאֶרֶץ מִצְרַיִם וְגוֹ'. כָּאן בַּחֲמוֹר הַזֶּה כָּתוּב, וְאֶת כָּל חֵילָם וְאֶת כָּל טַפָּם וְאֶת כָּל בְּהֶמְתָּם וְגוֹ'. שָׁם בְּאוֹתָם חֲמוֹרִים כָּתוּב, (שם) כְּלֵי כֶסֶף וּכְלֵי זָהָב וּשְׂמָלֹת, וְכָתוּב (שם) וְגַם עֵרֶב רַב עָלָה אִתָּם וְצֹאן וּבָקָר וְגוֹ'.</p>\n<p>וְשִׁמְעוֹן וְלֵוִי - זֶה עוֹמֵד אֵצֶל הַחֲמוֹר הַזֶּה, וְזֶה עוֹמֵד אֵצֶל כָּל אוֹתָם חֲמוֹרִים. כֻּלָּם רָצוּ לְהִשְׁתַּתֵּף עִם יַעֲקֹב הַקָּדוֹשׁ וְנִתְקְנוּ לִנְשֹׁךְ אוֹתוֹ, וְהוּא בְּבָנָיו עוֹמֵד לְגַבֵּיהֶם וְכוֹפֶה אוֹתָם תַּחְתָּיו.</p>\n<p>עַכְשָׁו שֶׁעֵשָׂו נָשַׁךְ אוֹתוֹ וְאֶת בָּנָיו, מִי יָקוּם מוּלוֹ? יַעֲקֹב וְיוֹסֵף, זֶה מִצַּד זֶה וְזֶה מִצַּד זֶה, שֶׁכָּתוּב (עובדיה א) וְהָיָה בֵּית יַעֲקֹב אֵשׁ וּבֵית יוֹסֵף לֶהָבָה וּבֵית עֵשָׂו לְקַשׁ וְגוֹ'.</p>\n<p>וַיִּסָּעוּ וַיְהִי חִתַּת אֱלֹהִים עַל הֶעָרִים אֲשֶׁר סְבִיבוֹתֵיהֶם וְלֹא רָדְפוּ אַחֲרֵי בְּנֵי יַעֲקֹב. אָמַר רַבִּי יוֹסֵי, כֻּלָּם הָיוּ מִתְכַּנְּסִים, וּכְשֶׁהָיוּ חוֹגְרִים כְּלֵי זַיִן לַקְּרָב, הָיוּ מְרַתְּתִים וְעוֹזְבִים אוֹתָם, וְלָכֵן לֹא רָדְפוּ אַחֲרֵי בְּנֵי יַעֲקֹב.</p>"],[9522011353,"<p>הָסִירוּ אֶת אֱלֹהֵי הַנֵּכָר וְגוֹ'. הָסִירוּ אֶת אֱלֹהֵי הַנֵּכָר - אֵלֶּה הֵם שֶׁנָּטְלוּ מִשְּׁכֶם כְּלֵי כֶסֶף וְזָהָב שֶׁהָיָה חָקוּק עֲלֵיהֶם עֲבוֹדָה זָרָה שֶׁלָּהֶם. רַבִּי יְהוּדָה אָמַר, עֲבוֹדָה זָרָה הָיוּ מִכֶּסֶף וְזָהָב, וְיַעֲקֹב הִטְמִין אוֹתָם שָׁם כְּדֵי שֶׁלֹּא יֵהָנוּ מִצַּד שֶׁל עֲבוֹדָה זָרָה, שֶׁאָסוּר לְאָדָם לֵהָנוֹת מִמֶּנָּה לְעוֹלָמִים.</p>\n<p>רַבִּי יְהוּדָה וְרַבִּי חִזְקִיָּה הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי חִזְקִיָּה לְרַבִּי יְהוּדָה, מַה זֶּה שֶׁכָּתוּב (שמואל ב יב) וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם מֵעַל רֹאשׁוֹ וּמִשְׁקָלָהּ כִּכַּר זָהָב וְאֶבֶן יְקָרָה וַתְּהִי עַל רֹאשׁ דָּוִד. וְשָׁנִינוּ, שִׁקּוּץ בְּנֵי עַמּוֹן מִלְכֹּם שְׁמוֹ, וְזֶהוּ עֲטֶרֶת מַלְכָּם. מָה הַטַּעַם וַתְּהִי עַל רֹאשׁ דָּוִד, וּמָה הַטַּעַם כָּתוּב שִׁקּוּץ, שֶׁהֲרֵי בִּשְׁאָר אֱלֹהֵי הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה כָּתוּב אֱלֹהֵי הָעַמִּים, אֱלֹהִים אֲחֵרִים, אֵל נֵכָר, אֵל אַחֵר, וּבָזֶה אָמַר שִׁקּוּץ אֶחָד.</p>\n<p>אָמַר לוֹ, וּבְכָל אֱלֹהֵי הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה כָּךְ קָרָא לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (דברים כג) וַתִּרְאוּ אֶת שִׁקּוּצֵיהֶם וְאֶת גִּלּוּלֵיהֶם. וּמַה שֶּׁאָמַר וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם, שֶׁהוּא מִלְכּוֹם - כָּךְ הוּא וַדַּאי. אֶלָּא אִתַּי הַגִּתִּי, עַד שֶׁלֹּא הִתְגַּיֵּר, אָז הוּא שָׁבַר אֶת אוֹתָהּ עֲטֶרֶת שֶׁל אוֹתוֹ מִלְכּוֹם, אוֹתָהּ דְּמוּת שֶׁחֲקוּקָה עָלֶיהָ וּפָגַם אוֹתָהּ, אָז הוּא עָשָׂה אוֹתָהּ הֶתֵּר לֵהָנוֹת מִמֶּנָּה, וְהָיְתָה עַל רֹאשׁוֹ. וּבֹא וּרְאֵה, שִׁקּוּץ בְּנֵי עַמּוֹן, נָחָשׁ אֶחָד בַּחֲקִיקָה עֲמֻקָּה הָיָה חָקוּק עַל אוֹתוֹ כֶּתֶר, וְלָכֵן נִקְרָא שִׁקּוּץ, זֻהֲמָא.</p>\n<p>רַבִּי יִצְחָק אָמַר, הָסִירוּ אֶת אֱלֹהֵי הַנֵּכָר - אֵלּוּ שְׁאָר נָשִׁים שֶׁהָיוּ מְבִיאוֹת בְּתוֹכָן כָּל עֲדָיֵיהֶן, וְעַל זֶה כָּתוּב וַיִתְּנוּ אֶל יַעֲקֹב אֶת כָּל אֱלֹהֵי הַנֵּכָר, אֵלּוּ נָשִׁים וְכָל עֲדָיִים וְכָל עֲבוֹדָה זָרָה שֶׁל זָהָב וָכֶסֶף. וַיִּטְמֹן אוֹתָם יַעֲקֹב, כְּדֵי שֶׁלֹּא יֵהָנוּ מִצַּד שֶׁל עֲבוֹדָה זָרָה כְּלָל.</p>\n<p>בֹּא רְאֵה שֶׁיַּעֲקֹב אִישׁ שָׁלֵם בַּכֹּל הָיָה, וְהָיָה נִדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ- הוּא. מַה כָּתוּב? וְנָקוּמָה וְנַעֲלֶה בֵּית אֵל וְאֶעֱשֶׂה שָּׁם מִזְבֵּחַ לָאֵל הָעֹנֶה אֹתִי בְּיוֹם צָרָתִי וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי. מִיָּד - וַיִּתְּנוּ אֶת יַעֲקֹב. מִכָּאן שֶׁצָּרִיךְ הָאָדָם לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהוֹדוֹת לוֹ עַל נִסִּים וְעַל טוֹבוֹת שֶׁעָשָׂה עִמּוֹ, זֶהוּ שֶׁכָּתוּב וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי.</p>\n<p>בֹּא רְאֵה, בַּהַתְחָלָה כָּתוּב וְנָקוּמָה וְנַעֲלֶה בֵּית אֵל וְגוֹ', הִכְלִיל בָּנָיו עִמּוֹ, וְאַחַר כָּךְ כָּתוּב וְאֶעֱשֶׂה שָּׁם מִזְבֵּחַ, וְלֹא כָתוּב וְנַעֲשֶׂה, שֶׁהוֹצִיא אוֹתָם מִכְּלַל זֶה. מָה הַטַּעַם? מִשּׁוּם שֶׁעָלָיו הָיָה הַדָּבָר. יַעֲקֹב תִּקֵּן תְּפִלַּת עַרְבִית וַדַּאי, וְהוּא עָשָׂה מִזְבֵּחַ וְעָלָיו הָיָה הַדָּבָר, וּמִשּׁוּם שֶׁהוּא עָבַר כָּל אוֹתָן צָרוֹת מִיּוֹם שֶׁבָּרַח מִלִּפְנֵי אָחִיו, שֶׁכָּתוּב וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי, וְהֵם בָּאוּ אַחַר כָּךְ לָעוֹלָם, וְעַל זֶה לֹא הִכְנִיס אוֹתָם עִמּוֹ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, מִכָּאן מִי שֶׁנַּעֲשָׂה לוֹ נֵס, צָרִיךְ לְהוֹדוֹת. מִי שֶׁאוֹכֵל לֶחֶם בְּשֻׁלְחָן, הוּא צָרִיךְ לְבָרֵךְ, וְלֹא אַחֵר שֶׁלֹּא אָכַל דָּבָר.</p>"],[9522011354,"<p>וַיִּבֶן שָׁם מִזְבֵּחַ וְגוֹ'. בֹּא רְאֵה, כָּתוּב וַיִּבֶן שָׁם מִזְבֵּחַ, וְלֹא כָתוּב (באלו המזבחות) שֶׁהֶעֱלָה עָלָיו נְסָכִים וְעוֹלוֹת, אֶלָּא מִשּׁוּם שֶׁתִּקֵּן אוֹתָהּ דַּרְגָּה הָרְאוּיָה לְהִתְתַּקֵּן. מִזְבֵּחַ לַה', לְתַקֵּן דַּרְגָּה תַּחְתּוֹנָה לְחַבְּרָהּ בְּדַרְגָּה עֶלְיוֹנָה, וְעַל זֶה וַיִּבֶן שָׁם מִזְבֵּחַ - זוֹ דַּרְגָּה תַּחְתּוֹנָה. לַה' - זוֹ דַּרְגָּה עֶלְיוֹנָה. וַיִּקְרָא לַמָּקוֹם אֵל בֵּית אֵל - שֵׁם זֶה כַּשֵּׁם הָעֶלְיוֹן, מִשּׁוּם שֶׁכְּשֶׁהֵאִירָה מֵהָאֵם, אָז כְּאִמָּהּ בִּתָּהּ וְהַכֹּל אֶחָד.</p>\n<p>כִּי שָׁם נִגְלוּ אֵלָיו הָאֱלֹהִים - מִשּׁוּם שֶׁהֵם לֹא נִמְצָאִים אֶלָּא בַּשְּׁכִינָה, שֶׁהֲרֵי שִׁבְעִים הָיוּ שֶׁהֵם נִמְצָאִים תָּמִיד עִם הַשְּׁכִינָה, וְשִׁבְעִים קָתֶדְרָאוֹת סְבִיב הַשְּׁכִינָה, וְעַל זֶה כִּי שָׁם נִגְלוּ אֵלָיו הָאֱלֹהִים, בְּמָקוֹם זֶה שֶׁהִתְגַּלָּה, שֶׁהֲרֵי כָּתוּב וְהִנֵּה ה' נִצָּב עָלָיו.</p>"],[9522011355,"<p>וַיַּעַל מֵעָלָיו אֱלֹהִים בַּמָּקוֹם אֲשֶׁר דִּבֶּר אִתּוֹ. רַבִּי שִׁמְעוֹן אָמַר, מִכָּאן שֶׁנַּעֲשָׂה מֶרְכָּבָה קְדוֹשָׁה עִם הָאָבוֹת. וּבא וּרְאֵה, יַעֲקֹב הוּא מֶרְכָּבָה קְדוֹשָׁה עֶלְיוֹנָה שֶׁעוֹמֶדֶת לְהָאִיר לַלְּבָנָה, וְהוּא מֶרְכָּבָה לְבַדּוֹ. זֶהוּ שֶׁכָּתוּב וַיַּעַל מֵעָלָיו אֱלֹהִים.</p>\n<p>פָּתַח וְאָמַר, (דברים ד) כִּי מִי גוֹי גָּדוֹל אֲשֶׁר לוֹ אֱלֹהִים קְרֹבִים אֵלָיו בְּכָל קָרְאֵנוּ. אֵלָיו בֹּא רְאֵה כַּמָּה הֵם חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֵין לְךְ עַם וְלָשׁוֹן בְּכָל הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁבָּעוֹלָם שֶׁיֵּשׁ לוֹ אֱלוֹהַּ שֶׁיִּשְׁמַע אוֹתָם כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְזֻמָּן לְקַבֵּל תְּפִלּוֹת וּבַקָּשׁוֹת שֶׁל יִשְׂרָאֵל בְּכָל שָׁעָה שֶׁהֵם צְרִיכִים לְהַשְׁמִיעַ תְּפִלָּה שֶׁהֵם רוֹצִים בִּשְׁבִיל אוֹתָהּ דַּרְגָּה שֶׁלָּהֶם.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לְיַעֲקֹב יִשְׂרָאֵל, שֶׁכָּתוּב לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ, וַיִּקְרָא אֶת שְׁמוֹ. מִי וַיִּקְרָא? זוֹ שְׁכִינָה, כְּמוֹ שֶׁנֶּאֱמַר וַיִּקְרָא אֶל מֹשֶׁה. וַיֹּאמֶר לוֹ אֱלֹהִים,</p>\n<p>לְמַעְלָה בֵּאַרְנוּ שֶׁהֲרֵי נִשְׁלַם בַּכֹּל כָּרָאוּי, וְאָז הִתְעַלָּה בְדַרְגָּתוֹ וְנִשְׁלַם בְּשֵׁם זֶה, וְעַל זֶה וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל, וַהֲרֵי נִתְבָּאֵר.</p>"],[9522011356,"<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבֵּי אֶלְעָזָר, וַדַּאי מַה שֶּׁאָמַרְתָּ שֶׁיַּעֲקֹב בְּחִיר הָאָבוֹת הוּא, וְהוּא אָחוּז לְכָל הַצְּדָדִים, וְקָרָא שְׁמוֹ יִשְׂרָאֵל, וְכָתוּב לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ, וְכָתוּב וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל, לָמָּה חָזַר הַקָּדוֹשׁ בָּרוּךְ הוּא וְקָרָא לוֹ יַעֲקֹב בְּכַמָּה פְעָמִים, וְהַכֹּל קָרְאוּ לוֹ יַעֲקֹב כְּמוֹ מִקֹּדֶם? אִם כָּךְ, מַה זֶּה וְלֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב?</p>\n<p>אָמַר לוֹ, יָפֶה אָמַרְתָּ. פָּתַח וְאָמַר, (ישעיה מב) ה' כַּגִּבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה, פָּסוּק זֶה פֵּרְשׁוּהוּ. אֲבָל בּא רְאֵה, כַּגִּבּוֹר יֵצֵא? גִּבּוֹר צָרִיךְ לִכְתֹּב! כְּאִישׁ מִלְחָמוֹת? אִישׁ מִלְחָמוֹת צָרִיךְ לִכְתֹּב!</p>\n<p>אֶלָּא הֲרֵי נִתְבָּאֵר, ה' בְּכָל מָקוֹם זֶה רַחֲמִים, וַדַּאי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא, שְׁמוֹ הוּא ה', שֶׁכָּתוּב (ישעיה מב) אֲנִי ה' הוּא שְׁמִי. וְרָאִינוּ שֶׁלִּפְעָמִים נִקְרָא שְׁמוֹ אֱלֹהִים, וְהוּא דִין בְּכָל מָקוֹם. אֶלָּא בִּזְמַן שֶׁמִּתְרַבִּים הַצַּדִּיקִים בָּעוֹלָם, ה' שְׁמוֹ, וְנִקְרָא בְּשֵׁם הָרַחֲמִים. וּבִזְמַן שֶׁמִּתְרַבִּים הָרְשָׁעִים בָּעוֹלָם, אֱלֹהִים שְׁמוֹ, וְנִקְרָא בְּשֵׁם אֱלֹהִים. כָּךְ בִּזְמַן שֶׁיַּעֲקֹב לֹא הָיָה בֵּין שׂוֹנְאִים וְלֹא הָיָה בְּאֶרֶץ אַחֶרֶת, קָרָא לוֹ יִשְׂרָאֵל. וְכַאֲשֶׁר הָיָה בֵּין שׂוֹנְאִים אוֹ בְּאֶרֶץ אַחֶרֶת, קָרָא לוֹ יַעֲקֹב.</p>\n<p>אָמַר לוֹ, עֲדַיִן לֹא הִתְיַשֵּׁב הַדָּבָר שֶׁכָּתוּב לֹא יִקָּרֵא, וַהֲרֵי אָנוּ קוֹרְאִים לוֹ. וּמַה שֶּׁאָמַרְתָּ שֶׁכְּשֶׁהָיָה בֵּין שׂוֹנְאִים אוֹ בְּאֶרֶץ אַחֶרֶת קָרָא לוֹ יַעֲקֹב - בּא רְאֵה, כָּתוּב (בראשית לז) וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן, וַהֲרֵי לֹא הָיָה בְּאֶרֶץ אַחֶרֶת?</p>\n<p>אָמַר לוֹ, הֲרֵי בַּתְּחִלָּה נֶאֱמַר כְּמוֹ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא לִפְעָמִים נִקְרָא ה' וְלִפְעָמִים נִקְרָא אֱלֹהִים, כָּךְ גַּם לִפְעָמִים נִקְרָא יִשְׂרָאֵל וְלִפְעָמִים נִקְרָא יַעֲקֹב, וְהַכֹּל בִּדְרָגוֹת יְדועוֹת. וּמַה שֶּׁנֶּאֱמַר לֹא יִקָּרֵא שִׁמְךְ עוֹד יַעֲקֹב, לְהִתְיַשֵּׁב בְּשֵׁם זֶה.</p>\n<p>אָמַר לוֹ, אִם כָּךְ, הֲרֵי כָּתוּב (שם יז) וְלֹא יִקָּרֵא עוֹד אֶת שִׁמְךְ אַבְרָם וְהָיָה שִׁמְךְ אַבְרָהָם. אָמַר לוֹ, שָׁם כָּתוּב וְהָיָה, וְעַל זֶה עוֹמֵד בְּאוֹתוֹ שֵׁם, אֲבָל כָּאן לֹא כָתוּב וְהָיָה, אֶלָּא כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךְ, וְלֹא כָתוּב וְהָיָה שִׁמְךְ יִשְׂרָאֵל, וַאֲפִלּוּ בְּפַעַם אַחַת מַסְפִּיק לוֹ, כָּל שֶׁכֵּן שֶׁלִּפְעָמִים כָּךְ וְלִפְעָמִים כָּךְ. וּכְשֶׁהִתְעַטְּרוּ בָנָיו בְּכֹהֲנִים וּלְוִיִּם וְהִתְעַלּוּ בִּדְרָגוֹת עֶלְיוֹנוֹת, אָז הִתְעַטֵּר בְּשֵׁם זֶה תָּמִיד.</p>"],[9522011357,"<p>עַד שֶׁהָיוּ הוֹלְכִים, אָמַר לוֹ רַבִּי יוֹסֵי לְרַבִּי נִתְבָּאֵר, הֲרֵי נִתְבָּאֵר שֶׁכְּשֶׁמֵּתָה רָחֵל, נָטְלָה הַבַּיִת מִי שֶׁצָּרִיךְ לְהִתַּקֵּן בִּשְׁנֵים עָשָׂר שְׁבָטִים כָּרָאוּי. לָמָּה מֵתָה רָחֵל מִיָּד? אָמַר לוֹ, הֲרֵי לִהְיוֹת שְׁכִינָה מִתְעַטֶּרֶת כָּרָאוּי וְלִהְיוֹת אֵם הַבָּנִים שְׂמֵחָה, וּבוֹ שׁוֹרָה (למעלה) לִטֹּל הַבַּיִת וּלְהִתַּקֵּן. וְעַל זֶה בִּנְיָמִין הוּא תָּמִיד בַּמַּעֲרָב וְלֹא בְּצַד אַחֵר.</p>\n<p>וּבוֹ שׁוֹרָה לְהִתַּקֵּן בִּשְׁנֵים עָשָׂר שְׁבָטִים, וּבוֹ שׁוֹרָה מַלְכוּת הָרָקִיעַ לְהִוָּדַע בָּאָרֶץ. וְסוֹד זֶה, שֶׁכָּל הַתְחָלָה שֶׁבָּאָה לְהִתְוַדֵּעַ, הִיא בְקַשְׁיוּת, וְעַל זֶה יֵשׁ בָּהּ דִּין שֶׁל מָוֶת וּמִשָּׁם מִתְיַשֶּׁבֶת.</p>\n<p>כָּאן כְּשֶׁרוֹצָה לְהִתְתַּקֵּן וְלִטֹּל הַבַּיִת, נַעֲשָׂה דִין בְּרָחֵל, וְאַחַר כָּךְ הִתְתַּקְּנָה לְהִתְיַשֵּׁב. כְּשֶׁרָצָה לְהוֹדִיעַ מַלְכוּת בָּאָרֶץ, שׁוֹרֶה בְּדִין, וְלֹא מִתְיַשֶּׁבֶת הַמַּלְכוּת בְּמָקוֹם כָּרָאוּי עַד שֶׁמִּתְעוֹרֵר דִּין בְּשָׁאוּל לְפִי מַעֲשָׂיו, וְאַחַר כָּךְ הִתְיַשְּׁבָה הַמַּלְכוּת וְנִתְקְנָה.</p>\n<p>בֹּא רְאֵה, כָּל הַתְחָלָה קָשָׁה וְאַחַר כָּךְ נוֹחָה. בְּרֹאשׁ הַשָּׁנָה הַהַתְחָלָה קָשָׁה, שֶׁכָּל הָעוֹלָם נִדּוֹן כָּל אֶחָד וְאֶחָד לְפִי מַעֲשָׂיו, וְאַחַר כָּךְ נוֹחָה, סְלִיחָה וְכִפּוּרִים. מִשּׁוּם שֶׁהָרֵאשִׁית הִיא מִשְּׂמֹאל, וְעַל זֶה דִּינָיו קָשִׁים, וְאַחַר כָּךְ מִתְעוֹרֵר הַיָּמִין, וְעַל זֶה נַעֲשֵׂית נוֹחָה.</p>\n<p>וְלֶעָתִיד לָבֹא עָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהִתְעוֹרֵר בְּשַׁלְוָה עַל שְׁאָר עַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת, וְאַחַר כָּךְ יִתְחַזֵּק עֲלֵיהֶם בְּדִין קָשֶׁה. זֶהוּ שֶׁכָּתוּב (ישעיה מב) ה' כַּגִּבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה יָרִיעַ אַף יַצְרִיחַ עַל אֹיְבָיו יִתְגַּבָּר. ה' בַּתְּחִלָּה, שֶׁהוּא רַחֲמִים, וְאַחַר כָּךְ כַּגִּבּוֹר וְלֹא גִבּוֹר, וְאַחַר כָּךְ כְּאִישׁ מִלְחָמוֹת וְלֹא אִישׁ מִלְחָמוֹת, אַחַר כָּךְ יִתְגַּלֶּה הַחֹזֶק עֲלֵיהֶם וְיִתְחַזֵּק לְהַשְׁמִיד אוֹתָם, שֶׁכָּתוּב יָרִיעַ אַף יַצְרִיחַ עַל אֹיְבָיו יִתְגַּבָּר, וְכָתוּב (זכריה יד) וְיָצָא ה' וְנִלְחַם בַּגּוֹיִם הָהֵם כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב, וְכָתוּב (ישעיה סג) מִי זֶה בָּא מֵאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגוֹ'.</p>\n<p>וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה וַתִּקְרָא שְׁמוֹ בֶּן אוֹנִי וְאָבִיו קָרָא לו בִנְיָמִין. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (נחום א) טוֹב ה' לְמָעוֹז בְּיוֹם צָרָה וְיֹדֵעַ חֹסֵי בוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל הָאִישׁ שֶׁמִּתְחַזֵּק בַּקָּדוֹשׁ-בָּרוּךְ- הוּא, בִּשְׁבִיל שֶׁהַחֹזֶק שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא חֹזֶק, וּבֵאֲרוּהוּ טוֹב ה', כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמה) טוֹב ה' לַכֹּל. לְמָעוֹז - זֶהוּ חֹזֶק שֶׁיֵּשׁ בּוֹ יְשׁוּעוֹת, שֶׁכָּתוּב (שם כח) וּמָעוֹז יְשׁוּעוֹת מְשִׁיחוֹ הוּא. בְּיוֹם צָרָה - בְּיוֹם שֶׁל מְצוּקָה שֶׁמְּצִיקִים שְׁאָר הָעַמִּים לְיִשְׂרָאֵל</p>"],[9522011358,"<p>בֹּא רְאֵה מַה כָּתוּב, (משלי כד) הִתְרַפִּיתָ בְּיוֹם צָרָה צַר כֹּחֶכָה. מַה זֶּה הִתְרַפִּיתָ? מִי שֶׁמַּרְפֶּה יָדָיו מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא לְהִתְחַזֵּק בּוֹ. וְאֵיךְ יַחֲזִיק הָאָדָם בַּקָּדוֹשׁ-בָּרוּךְ-הוּא? יַחֲזִיק בַּתּוֹרָה. שֶׁכָּל מִי שֶׁמַּחֲזִיק בַּתּוֹרָה, מַחֲזִיק בְּעֵץ הַחַיִּים, כִּבְיָכוֹל נוֹתֵן חֹזֶק לִכְנֶסֶת יִשְׂרָאֵל לְהִתְחַזֵּק.</p>\n<p>וְאִם הוּא יִתְרַפֶּה מֵהַתּוֹרָה מַה כָּתוּב? הִתְרַפִּיתָ. אִם הוּא הִתְרַפֶּה מִן הַתּוֹרָה - בְּיוֹם צָרָה צַר כֹּחֶכָה. בְּיוֹם שֶׁתָּבֹא לוֹ מְצוּקָה, כִּבְיָכוֹל דּוֹחֵק אֶת הַשְּׁכִינָה שֶׁהִיא כֹּחוֹ שֶׁל הָעוֹלָם.</p>\n<p>דָּבָר אַחֵר צַר כֹּחֶכָה - בּא רְאֵה, בְּשָׁעָה שֶׁבֶּן אָדָם מִתְרַפֶּה מִן הַתּוֹרָה וְהוֹלֵךְ בְּדֶרֶךְ לֹא כְשֵׁרָה, כַּמָּה בַּעֲלֵי רִיב זְמִינִים לוֹ לִהְיוֹת לוֹ קָטֵגוֹרִים בְּיוֹם צָרָה. וַאֲפִלּוּ נִשְׁמַת הָאָדָם, שֶׁהִיא כֹּחַ וְחֹזֶק שֶׁלּוֹ, הִיא יְרִיבָה שֶׁלּוֹ כְּנֶגְדּוֹ, שֶׁכָּתוּב צַר כֹּחֶכָה, מִשּׁוּם שֶׁהוּא צַר אֵלָיו. אָמַר רַבִּי אַבָּא, בְּשָׁעָה שֶׁבֶּן אָדָם הוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה וְכָל דְּרָכָיו מְתֻקָּנוֹת כָּרָאוּי, כַּמָּה סָנֵגוֹרִים עוֹמְדִים עָלָיו לְהַזְכִּירוֹ לְטוֹב.</p>\n<p>פָּתַח וְאָמַר, (איוב לג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ וַיְחֻנֶּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר. בַּפְּסוּקִים הַלָּלוּ יֵשׁ לְהִתְבּוֹנֵן, וְכִי לֹא גָלוּי הַכֹּל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא צָרִיךְ מַלְאָךְ שֶׁיּאמַר לְפָנָיו טוֹב אוֹ רַע?</p>\n<p>אֶלָּא וַדַּאי שֶׁצָּרִיךְ, שֶׁכַּאֲשֶׁר יֵשׁ לָאָדָם סָנֵגוֹרִים לְהַזְכִּיר זְכוּת שֶׁלּוֹ לְפָנָיו וְאֵין לוֹ (לאדם) קָטֵגוֹרִים, אָז וַיְחֻנֶּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר.</p>\n<p>בֹּא רְאֵה, בַּפָּסוּק הַזֶּה תִּמְצָא בֵּרוּר הַדָּבָר. כָּתוּב אִם יֵשׁ עָלָיו מַלְאָךְ. אִם לֹא כָתוּב יוֹתֵר - יָפֶה הוּא. אֲבָל מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף כָּתוּב, וּמִיהוּ? זֶהוּ הַמַּלְאָךְ הַמְמֻנֶּה עִם הָאָדָם בְּצַד שְׂמֹאל, שֶׁכָּתוּב (תהלים צא) יִפֹּל מִצִּדְּךְ אֶלֶף, וְזֶהוּ צַד שְׂמֹאל, שֶׁכָּתוּב אַחֲרָיו וּרְבָבָה מִימִינֶךְ.</p>\n<p>אֲבָל אֶחָד מִנִּי אָלֶף, זֶהוּ יֵצֶר יֵצֶר הָרָע, שֶׁהוּא אֶחָד מֵאוֹתָם (שהוא) אֶלֶף שֶׁהָיוּ לְצַד שְׂמֹאל, מִשּׁוּם שֶׁהוּא עוֹלֶה לְמַעְלָה וְנוֹטֵל רְשׁוּת. וְעַל זֶה, אִם בֶּן אָדָם הוֹלֵךְ בְּדֶרֶךְ אֱמֶת, אוֹתוֹ יֵצֶר הָרָע הוּא עֶבֶד לוֹ כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (משלי יב) טוֹב נִקְלֶה וְעֶבֶד לוֹ, אָז הוּא עוֹלֶה וְנַעֲשֶׂה סָנֵגוֹר, וְאוֹמֵר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא זְכוּת עַל הָאָדָם, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹמֵר, פְּדָעֵהוּ מֵרֶדֶת שַׁחַת.</p>\n<p>וְעִם כָּל זֶה לֹא חוֹזֵר רֵיקָם, מִשּׁוּם שֶׁנּוֹתְנִים לוֹ אַחֵר לִשְׁלֹט עָלָיו וְלִטֹּל מִמֶּנּוּ אֶת נִשְׁמָתוֹ, מִשּׁוּם שֶׁהִקְדִּים חֲטָאֵי אוֹתוֹ הָאִישׁ וְהוּא כֹּפֶר עַל זֶה. זֶהוּ שֶׁכָּתוּב מָצָאתִי כֹפֶר, לִפְדּוֹת אוֹתוֹ.</p>\n<p>דָּבָר אַחֵר מָצָאתִי כֹפֶר - אוֹתָהּ זְכוּת שֶׁאָמַרְתָּ, הִיא עָלָיו כֹּפֶר לִפְדּוֹת אוֹתוֹ שֶׁלֹּא יֵרֵד לַגֵּיהִנֹּם וְלֹא יָמוּת. וְלָכֵן צָרִיךְ לָאָדָם לָלֶכֶת בְּדֶרֶךְ אֱמֶת כְּדֵי שֶׁיִּהְיֶה לוֹ הַקָּטֵגוֹר סָנֵגוֹר.</p>\n<p>כְּמוֹ זֶה יִשְׂרָאֵל בְּיוֹם הַכִּפּוּרִים שֶׁנּוֹתְנִים לוֹ שָׂעִיר וּמִתְעַסְּקִים עִמּוֹ עַד שֶׁהוֹפֵךְ לִהְיוֹת לָהֶם עֶבֶד, וְעוֹלֶה וּמֵעִיד עֵדוּת לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְנַעֲשֶׂה לָהֶם סָנֵגוֹר. וְעַל זֶה אָמַר שְׁלֹמֹה הַמֶּלֶךְ, (שם כה) אִם רָעֵב שֹׂנַאֲךְ הַאֲכִילֵהוּ לָחֶם וְאִם צָמֵא הַשְׁקֵהוּ מָיִם, וְעַל הַיֵּצֶר הָרָע הַזֶּה זֶה נֶאֱמַר.</p>\n<p>וּמִשּׁוּם זֶה בְּיוֹם צָרָה, כְּשֶׁבֶּן אָדָם מִתְרַפֶּה מִן הַתּוֹרָה, כִּבְיָכוֹל דּוֹחֵק אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עִם אוֹתוֹ יֵצֶר הָרָע שֶׁהוּא נַעֲשֶׂה קָטֵגוֹר. צַר כֹּחֶכָה - צַר כֹּחַ כֹּה, מִשּׁוּם שֶׁהִתְקָרֵב לְפָנָיו לְקַטְרֵג וְנֶחֱלַשׁ הַכֹּחַ.</p>\n<p>בֹּא רְאֵה, טוֹב ה' לְמָעוֹז בְּיוֹם צָרָה, מַה זֶה בְּיוֹם צָרָה? זֶה יַעֲקֹב כְּשֶׁבָּא עָלָיו עֵשָׂו לְקַטְרְגוֹ. וְיוֹדֵעַ חוֹסֵי בוֹ, כְּשֶׁבָּאָה עָלָיו צָרַת דִּינָה. וּבֹא וּרְאֵה, אֵין הַמְקַטְרֵג נִמְצָא עַל הָאָדָם אֶלָּא בִּשְׁעַת סַכָּנָה.</p>\n<p>וּבֹא וּרְאֵה, מִשּׁוּם שֶׁיַּעֲקֹב אֵחַר נִדְרוֹ שֶׁנָּדַר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, הִתְחַזֵּק הַדִּין עַל יְדֵי הַמְקַטְרֵג שֶׁקִּטְרֵג עַל יַעֲקֹב, וְרָצָה דִּין בִּשְׁעַת הַסַּכָּנָה שֶׁהָיְתָה בָּהּ בְּרָחֵל. אָמַר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וַהֲרֵי יַעֲקֹב נָדַר נִדְרוֹ וְלֹא שִׁלֵּם, וַהֲרֵיהוּ חָזָק מֵהַכֹּל בְּעֹשֶׁר וּבְבָנִים וּבְכָל מַה שֶּׁצָּרִיךְ, וְלֹא שִׁלֵּם נִדְרוֹ שֶׁנָּדַר לְפָנֶיךְ, וְלֹא לָקַחְתָּ מִמֶּנּוּ עֹנֶשׁ. מִיָּד? - וַתֵּלֶד רָחֵל וַתְּקַשׁ בְּלִדְתּהּ. מַה זֶּה וַתְּקַשׁ? שֶׁהִתְקַשָּׁה הַדִּין לְמַעְלָה אֵצֶל מַלְאָךְ הַמָּוֶת.</p>\n<p>וְנֶעֱנַשׁ יַעֲקֹב בָּזֶה, מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (משלי כב) וְאִם אֵין לְךְ לְשַׁלֵּם לָמָּה יִקַּח מִשְׁכָּבְךְ מִתַּחְתֶּיךְ, וְעַל זֶה מֵתָה רָחֵל וְנִמְסַר הַדִּין עַל יְדֵי מַלְאַךְ הַמָּוֶת.</p>\n<p>וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁבָּא עֵשָׂו, מֶה עָשָׂה? וַיָּשֶׂם אֶת הַשְּׁפָחוֹת וְאֶת יַלְדֵיהֶן רִאשֹׁנָה וְאֶת לֵאָה וִילָדֶיהָ אַחֲרֹנִים וְאֶת רָחֵל וְאֶת יוֹסֵף אַחֲרֹנִים. מָה הַטַּעַם? מִשּׁוּם שֶׁפָּחַד עַל רָחֵל שֶׁלֹּא יִסְתַּכֵּל אוֹתוֹ רָשָׁע בְּיָפְיָהּ וְלֹא יְקַטְרֵג לוֹ עָלֶיהָ.</p>\n<p>עוֹד מַה כָּתוּב? וַתִּגַּשְׁנָה הַשְּׁפָחוֹת הֵנָּה וְיַלְדֵיהֶן וַתִּשְׁתַּחֲוֶיןָ וַתִּגַּשׁ גַּם לֵאָה וִילָדֶיהָ וַיִּשְׁתַּחֲווּ. נָשִׁים מִלִּפְנֵי גְבָרִים. אֲבָל בְּרָחֵל מַה כָּתוּב? וְאַחַר נִגַּשׁ יוֹסֵף וְרָחֵל, יוֹסֵף מִלִּפְנֵי אִמּוֹ, וְהוּא כִסָּה עָלֶיהָ, וְעַל זֶה כָּתוּב (בראשית מט) בֵּן פֹּרָת יוֹסֵף בֵּן פֹּרָת עֲלֵי עָיִן, שֶׁהִגְדִּיל גּוּפוֹ וְכִסָּה עַל אִמּוֹ. עֲלֵי עָיִן - עֲלֵי עַיִן שֶׁל אוֹתוֹ רָשָׁע.</p>\n<p>וְכָאן נֶעֶנְשָׁה עַל יְדֵי הַיֵּצֶר הָרָע שֶׁקִּטְרֵג בִּשְׁעַת הַסַּכָּנָה, וְנֶעֱנַשׁ יַעֲקֹב עַל נֶדֶר שֶׁלֹּא שִׁלֵּם, וְזֶה קָשֶׁה לְיַעֲקֹב מִכָּל הַצָּרוֹת שֶׁעָבְרוּ עָלָיו. וּמִנַּיִן לָנוּ שֶׁמִּשּׁוּם יַעֲקֹב זֶה הָיָה? שֶׁכָּתוּב (שם מח) מֵתָה עָלַי רָחֵל, עָלַי וַדַּאי, עַל שֶׁאֵחַרְתִּי נִדְרִי.</p>\n<p>רַבִּי יוֹסֵי אָמַר, כָּתוּב (משלי כז) קִלְלַת חִנָּם לֹא תָבֹא, וּבֵאֲרוּהוּ לוֹ בְּוָא\"ו. שֶׁאִם קִלְלַת צַדִּיק הִיא, אֲפִלּוּ שֶׁלֹּא הִתְכַּוֵּן בָּהּ, כֵּיוָן שֶׁיָּצְאָה מִפִּיו נָטַל אוֹתָהּ אוֹתוֹ יֵצֶר הָרָע וְקִטְרֵג בָּהּ בִּשְׁעַת הַסַּכָּנָה.</p>\n<p>יַעָקֹב אָמַר (בראשית לא) עִם אֲשֶׁר תִּמְצָא אֶת אֱלֹהֶיךְ לֹא יִחְיֶה. וְאַף עַל גַּב שֶׁהוּא לֹא הָיָה יוֹדֵעַ, נָטַל אוֹתוֹ דָבָר אוֹתוֹ שָׂטָן שֶׁנִּמְצָא תָמִיד אֵצֶל בְּנֵי אָדָם. וְעַל זֶה שָׁנִינוּ, לְעוֹלָם לֹא יִפְתַּח אָדָם פִּיו לַשָּׂטָן, מִשּׁוּם שֶׁנּוֹטֵל אוֹתוֹ הַדִּבּוּר וּמְקַטְרֵג בּוֹ לְמַעְלָה וּלְמַטָּה, כָּל שֶׁכֵּן מִלָּה שֶׁל חָכָם אוֹ מִלָּה שֶׁל צַדִּיק, וְעַל שְׁנֵי אֵלֶּה נֶעֶנְשָׁה רָחֵל.</p>"],[9522011359,"<p>וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה. אָמַר רַבִּי אַבָּא, וְכִי כֵּיוָן שֶׁאָמַר וַיְהִי בְּצֵאת נַפְשָׁהּ לֹא יָדַעְנוּ כִּי מֵתָה? אֶלָּא צָרִיךְ מִשּׁוּם שֶׁלֹּא חָזְרָה לְגוּפָהּ יוֹתֵר, וּמֵתָה רָחֵל מִיתַת הַגּוּף, מִשּׁוּם שֶׁיֵּשׁ בְּנֵי אָדָם שֶׁנִּשְׁמָתָם יוֹצֵאת וְחוֹזֶרֶת לִמְקוֹמָהּ, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א ל) וַתָּשָׁב רוּחוֹ (נפשו) אֵלָיו, (בראשית מב) וַיֵּצֵא לִבָּם, (שיר ה) נַפְשִׁי יָצְאָה בְּדַבְּרוֹ, (מלכים א יז) לֹא נוֹתְרָה בּוֹ נְשָׁמָה. אֲבָל זוֹ יָצְאָה נִשְׁמָתָהּ וְלֹא חָזְרָה לִמְקוֹמָהּ וּמֵתָה רָחֵל.</p>\n<p>וַתִּקְרָא שְׁמוֹ בֶּן אוֹנִי, הַקַּשְׁיוּת שֶׁל הַדִּין שֶׁנִּגְזַר עָלֶיהָ. וְיַעֲקֹב הֶחֱזִיר אוֹתוֹ וְקָשַׁר אוֹתוֹ לְיָמִין, מִשּׁוּם שֶׁאֶת הַמַּעֲרָב צָרִיךְ לְקָשְׁרוֹ לְיָמִין. וְאַף עַל גַּב שֶׁהוּא בֶּן אוֹנִי, צַד שֶׁל הַדִּין הַקָּשֶׁה - בֵּן יָמִין הוּא, שֶׁהֲרֵי בְּיָמִין הִתְקַשְּׁרָה,</p>\n<p>וְנִקְבְּרָה בַּדֶּרֶךְ כְּמוֹ שֶׁנִּתְבָּאֵר, הֲרֵי הִתְגַּלְּתָה מִיתָתָהּ וּקְבוּרָתָהּ, אֲבָל לֵאָה לֹא הִתְגַּלְּתָה מִיתָתָהּ וּקְבוּרָתָהּ, וְאַף עַל גַּב שֶׁאַרְבַּע הָאִמָּהוֹת הַלָּלוּ סוֹד יֵשׁ לָהֶם, וּבֵאֲרוּהוּ.</p>"],[9522011360,"<p>וַיַּצֶב יַעֲקֹב מַצֵּבָה עַל קְבוּרָתָהּ. אָמַר רַבִּי יוֹסֵי, מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא הִתְכַּסָּה מְקוֹמָהּ עַד הַיּוֹם שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת מֵתִים, כְּמוֹ שֶׁנֶּאֱמַר עַד הַיּוֹם, עַד אוֹתוֹ יוֹם מַמָּשׁ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, עַד יוֹם שֶׁתַּחֲזֹר שְׁכִינָה מִגָּלוּת יִשְׂרָאֵל בְּאוֹתוֹ מָקוֹם, כְּמוֹ שֶׁנֶּאֱמַר (ירמיה לא) וְיֵשׁ תִּקְוָה לְאַחֲרִיתֵךְ נְאֻם ה' וְשָׁבוּ בָנִים לִגְבוּלָם. וְזוֹ שְׁבוּעָה שֶׁנִּשְׁבַּע לָהּ הַקָּדוֹשׁ בָּרוּךְ הוּא, וַעֲתִידִים יִשְׂרָאֵל כְּשֶׁיָּשׁוּבוּ מֵהַגָּלוּת לַעֲמֹד עַל אוֹתָהּ קְבוּרַת רָחֵל וְלִבְכּוֹת שָׁם, כְּמוֹ שֶׁהִיא בָּכְתָה עַל גָּלוּת יִשְׂרָאֵל, וְעַל זֶה כָּתוּב (שם) בִּבְכִי יָבֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם וְגוֹ', וְכָתוּב (שם) כִּי יֵשׁ שָׂכָר לִפְעֻלָּתֵךְ. וּבְאוֹתָהּ שָׁעָה עֲתִידָה רָחֵל, שֶׁהִיא בַּדֶּרֶךְ, לִשְׂמֹחַ בְּיִשְׂרָאֵל וְעִם הַשְּׁכִינָה, וּבֵאֲרוּהוּ הַחֲבֵרִים.</p>"],[9522011361,"<p>וַיְהִי בִּשְׁכֹּן יִשְׂרָאֵל בָּאָרֶץ הַהִיא וַיֵּלֶךְ רְאוּבֵן וַיִּשְׁכַּב אֶת בִּלְהָה פִּילֶגֶשׁ אָבִיו וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְנֵי יַעֲקֹב שְׁנֵים עָשָׂר. רַבִּי אֶלְעָזָר אָמַר, וַיְהִי בִּשְׁכֹּן יִשְׂרָאֵל בָּאָרֶץ הַהִיא, שֶׁהֲרֵי לֵאָה וְרָחֵל מֵתוּ, וְנָטְלָה הַבַּיִת מִי שֶׁנָּטְלָה.</p>\n<p>וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁרְאוּבֵן הָלַךְ וְשָׁכַב עִם בִּלְהָה? אֶלָּא בְּכָל זְמַנָּן שֶׁל לֵאָה וְרָחֵל, שְׁכִינָה שָׁרְתָה עֲלֵיהֶן, וְעַכְשָׁו שֶׁמֵּתוּ, שְׁכִינָה לֹא נִפְרְדָה מֵהַבַּיִת, וְשׁוֹרָה בַּבַּיִת בַּמִּשְׁכָּן שֶׁל בִּלְהָה. וְאַף עַל גַב שֶׁשְּׁכִינָה רָצְתָה לִטֹּל הַבַּיִת כָּרָאוּי, אִלְמָלֵא יַעֲקֹב לֹא נִמְצָא בְּזִוּוּג זָכָר וּנְקֵבָה, לֹא שׁוֹרָה שְׁכִינָה בְּגִלּוּי בַּבַּיִת, וְעַל זֶה עָמְדָה שְׁכִינָה בְּמִשְׁכַּן בִּלְהָה. וּבָא רְאוּבֵן, מִשּׁוּם שֶׁרָאָה שֶׁבִּלְהָה יָרְשָׁה מְקוֹם אִמּוֹ, הָלַךְ וּבִלְבֵּל הַמִּטָּה, וְעַל שֶׁעָמְדָה שְׁכִינָה עָלֶיהָ כָּתוּב בּוֹ וַיִּשְׁכַּב אֶת בִּלְהָה.</p>\n<p>רַבִּי יֵיסָא אָמַר, שֶׁיָּשַׁן עַל אוֹתָהּ מִטָּה וְלֹא חָשַׁשׁ לִכְבוֹד הַשְּׁכִינָה, וּמִשּׁוּם כָּךְ לֹא נִפְגַּם מֵחֶשְׁבּוֹן הַשְּׁבָטִים, וּבָא הַפָּסוּק וְעָשָׂה חֶשְׁבּוֹן, מִשּׁוּם כָּךְ כָּתוּב בְּכוֹר יַעֲקֹב רְאוּבֵן, וְהַפָּסוּק עָשָׂה אוֹתוֹ רֹאשׁ לְכָל הַשְּׁבָטִים.</p>\n<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְגוֹ' - כָּל דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כֻּלָּם יְשָׁרִים וְדַרְכֵי אֱמֶת, וּבְנֵי הָעוֹלָם לֹא יוֹדְעִים וְלֹא מַשְׁגִּיחִים עַל מָה הֵם עוֹמְדִים. וְעַל זֶה וְצַדִּיקִים יֵלְכוּ בָם - מִשּׁוּם שֶׁהֵם יוֹדְעִים דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמִשְׁתַּדְּלִים בַּתּוֹרָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, הוּא יוֹדֵעַ וְהוֹלֵךְ בָּהֶם שֶׁלֹּא סוֹטֶה יָמִינָה וּשְׂמֹאלָה.</p>\n<p>וּפֹשְׁעִים יִכָּשְׁלוּ בָם - אֵלֶּה הֵם הָרְשָׁעִים שֶׁלֹּא מִשְׁתַּדְּלִים בַּתּוֹרָה וְלֹא מִסְתַּכְּלִים בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא יוֹדְעִים לְאָן הַדְּרָכִים הוֹלְכוֹת, וּמִשּׁוּם שֶׁלֹּא יוֹדְעִים לְהִסְתַּכֵּל וְלֹא מִשְׁתַּדְּלִים בַּתּוֹרָה, הֵם נִכְשָׁלִים בָּהֶם בְּאוֹתָם דְּרָכָיו בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, כָּל אָדָם שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, נִשְׁמָתוֹ עוֹלָה בְּאוֹתָם דְּרָכִים וּשְׁבִילִים (שהם בתורה) שֶׁל הַתּוֹרָה, וְאוֹתָם דְּרָכִים וּשְׁבִילִים שֶׁל הַתּוֹרָה הֵם יְדוּעִים, וְאוֹתָם שֶׁיּוֹדְעִים דַּרְכֵי הַתּוֹרָה בָּעוֹלָם הַזֶּה יֵלְכוּ בָהֶם בְּאוֹתוֹ עוֹלָם, כְּשֶׁיֵּצְאוּ מִן הָעוֹלָם הַזֶּה.</p>\n<p>וְאִם לֹא הִשְׁתַּדְּלוּ בַּתּוֹרָה בָּעוֹלָם הַזֶּה וְלֹא יוֹדְעִים דְּרָכִים וּשְׁבִילִים, כְּשֶׁיֵּצְאוּ מִן הָעוֹלָם הַזֶּה לֹא יֵדְעוּ לָלֶכֶת בְּאוֹתָם דְּרָכִים וּשְׁבִילִים, וְנִכְשָׁלִים בָּהֶם. וְאָז יֵלֵךְ בִּדְרָכִים אֲחֵרוֹת שֶׁאֵינָן דַּרְכֵי הַתּוֹרָה, וְיִתְעוֹרְרוּ אֵלָיו בְּכַמָּה דִינִים וְיֵעָנֵשׁ בָּהֶם.</p>\n<p>וּמִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה מַה כָּתוּב? (משלי ו) בְּשָׁכְבְּךְ תִּשְׁמֹר עָלֶיךְ וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךְ. בְּשָׁכְבְּךְ - בַּקֶּבֶר, הַתּוֹרָה תִּשְׁמֹר עָלֶיךְ מִדִּין אוֹתוֹ הָעוֹלָם. וַהֲקִיצוֹתָ - כְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא יְעוֹרֵר רוּחוֹת וּנְשָׁמוֹת לְהַחֲיוֹת מֵתִים, אָז הִיא תְשִׂיחֶךְ, הִיא תִהְיֶה סָנֵגוֹר עַל הַגּוּף בִּשְׁבִיל שֶׁיָּקוּמוּ אוֹתָם גּוּפִים שֶׁהִשְׁתַּדְּלוּ בַּתּוֹרָה כָּרָאוּי, וְאֵלֶּה הֵם שֶׁיָּקוּמוּ בַּתְּחִלָּה לְחַיֵּי עוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (דניאל יב) וְרַבִּים מִיְּשֵׁנֵי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְגוֹ'. וְאֵלֶּה הֵם לְחַיֵּי עוֹלָם, מִשּׁוּם שֶׁהִתְעַסְּקוּ בְּחַיֵּי עוֹלָם שֶׁהִיא הַתּוֹרָה.</p>\n<p>וּבֹא רְאֵה, כָּל אֵלּוּ שֶׁהִשְׁתַּדְּלוּ בַּתּוֹרָה, אוֹתוֹ הַגּוּף יִתְקַיֵּם וְהַתּוֹרָה תָּגֵן עָלָיו, מָה הַטַּעַם? מִשּׁוּם שֶׁבְּאוֹתָהּ שָׁעָה יְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא רוּחַ אַחַת שֶׁכְּלוּלָה מֵאַרְבַּע רוּחוֹת, וְאוֹתָהּ רוּחַ הַכּוֹלֶלֶת אַרְבַּע רוּחוֹת תִּזְדַּמֵּן לְכָל אוֹתָם שֶׁהִשְׁתַּדְּלוּ בַּתּוֹרָה לְהַחֲיוֹתָם בְּרוּחַ זוֹ בִּשְׁבִיל שֶׁיִּתְקַיֵּם לְעוֹלָמִים.</p>\n<p>וְאִם תֹּאמַר, הֲרֵי כָּתוּב (יחזקאל לז) מֵאַרְבַּע רוּחוֹת בּאִי הָרוּחַ, לָמָּה לֹא הִתְקַיְּמוּ, שֶׁהֲרֵי כֻּלָּם מֵתוּ כְּמִקֹּדֶם? בֹּא רְאֵה, אוֹתוֹ זְמַן שֶׁהֵקִים הַקָּדוֹשׁ בָּרוּךְ הוּא עַל יְדֵי יְחֶזְקֵאל אוֹתָם הַמֵּתִים, אוֹתוֹ (זמן העתיד) רוּחַ, אַף עַל גַּב שֶׁהָיָה מֵאַרְבַּע רוּחוֹת, לֹא יָרַד לְקַיְּמָם בְּקִיּוּם, אֶלָּא לְהַרְאוֹת שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַחֲיוֹת מֵתִים בְּאוֹתָהּ צוּרָה וּלְקַיְּמָם בָּרוּחַ שֶׁנִּכְלְלָה בְּצוּרָה זוֹ. וְאַף עַל גַּב שֶׁחָזְרוּ הָעֲצָמוֹת בְּאוֹתָהּ שָׁעָה כְּמוֹ שֶׁהָיָה, הַקָּדוֹשׁ בָּרוּךְ הוּא רָצָה לְהַרְאוֹת לְכָל הָעוֹלָם שֶׁהוּא עָתִיד לְהַחֲיוֹת מֵתִים (מה כתוב? (ישעיה כו) יחיו מתיך נבלתי יקומון, על זה אותה רוח שעתידה לרדת בהם צדיקים) (ס\"א ועל זה אותה רוח שעתידה לרדת בהם צדיקים מה כתוב? מארבע רוחות באי הרוח, רוח שנכללה בארבע), מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְקַיֵּם אוֹתָם קִיּוּם שָׁלֵם בָּעוֹלָם כָּרָאוּי, וְאוֹתָם שֶׁהִשְׁתַּדְּלוּ בַּתּוֹרָה בָּעוֹלָם הַזֶּה, הִיא עוֹמֶדֶת עַל הָאָדָם וְנַעֲשֵׂית סָנֵגוֹרְיָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, כָּל אוֹתָם דִּבְרֵי תוֹרָה וְכָל אוֹתָהּ תּוֹרָה שֶׁהִשְׁתַּדֵּל בָּהּ הָאָדָם בָּעוֹלָם הַזֶּה, אוֹתָם דְּבָרִים וְאוֹתָהּ תּוֹרָה עוֹמְדִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְאוֹמֶרֶת לְפָנָיו, וְהִיא מְרִימָה קוֹלוֹת וְלֹא שׁוֹכֶכֶת, וּלְאוֹתוֹ זְמַן הִיא תָשִׂיחַ וְתֹאמַר כְּפִי שֶׁהִתְדַּבֵּק בָּהּ הָאָדָם וְהִשְׁתַּדֵּל בָּהּ בָּעוֹלָם הַזֶּה, וְעַל זֶה הֵם יָקוּמוּ בְּקִיּוּם שָׁלֵם לְחַיֵּי עוֹלָם, כְּמוֹ שֶׁאָמַרְנוּ, וּמִשּׁוּם כָּךְ (הושע יד) כִּי יְשָׁרִים דַּרְכֵי ה' וְצַדִּיקִים יֵלְכוּ בָם וּפֹשְׁעִים יִכָּשְׁלוּ בָּם.</p>\n<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (שמואל א ב) וְעֵלִי זָקֵן מְאֹד וְשָׁמַע אֵת כָּל אֲשֶׁר יַעֲשׂוּן בָּנָיו לְכָל יִשְׂרָאֵל וְאֵת אֲשֶׁר יִשְׁכְּבֻן אֶת הַנָּשִׁים הַצֹבְאוֹת פֶּתַח אֹהֶל מוֹעֵד. וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁכֹּהֲנֵי ה' יַעֲשׂוּ מַעֲשֶׂה זֶה, וַהֲרֵי מִקֹּדֶם לְכָךְ נֶאֱמַר וּפֵרְשָׁה תוֹרָה אוֹתוֹ הַחֵטְא שֶׁלָּהֶם, שֶׁכָּתוּב (שם) כִּי נִאֲצוּ הָאֲנָשִׁים אֵת מִנְחַת ה', וְכָתוּב וּמִשְׁפַּט הַכֹּהֲנִים מֵאֵת הָעָם כָּל אִישׁ זבֵחַ זֶבַח וְגוֹ', וְכָתוּב גַּם בְּטֶרֶם יַקְטִרוּן אֶת הַחֵלֶב וּבָא נַעַר הַכֹּהֵן וְאָמַר לָאִישׁ הַזֹּבֵחַ תְּנָה בָשָׂר לִצְלוֹת לַכֹּהֵן וְגוֹ', וְכָתוּב וְאָמַר לוֹ כִּי עַתָּה תִתֵּן וְאִם לֹא לָקַחְתִּי בְחָזְקָה, וְעַל זֶה וַתְּהִי חַטַּאת הַנְּעָרִים גְּדלָה מְאֹד וְגוֹ', וְכָל זֶה לֹא הָיוּ נוֹטְלִים אֶלָּא מֵאוֹתָם חֲלָקִים שֶׁהָיוּ לַכֹּהֲנִים לֶאֱכֹל מֵהֶם, וְעַל שֶׁהָיָה הַקָּרְבָּן קַלִּיל בְּעֵינֵיהֶם נֶעֶנְשׁוּ, וְכָאן אָמַר אֵת אֲשֶׁר יִשְׁכְּבֻן אֶת הַנָּשִׁים הַצֹבְאוֹת</p>\n<p>אֶלָּא? חַס וְחָלִילָה שֶׁהָיוּ עוֹשִׂים עֲבֵרָה זוֹ, כָּל שֶׁכֵּן בְּאוֹתוֹ מָקוֹם קָדוֹשׁ, שֶׁלֹּא יָקוּמוּ כָּל יִשְׂרָאֵל וְיַהַרְגוּ אוֹתָם. אֶלָּא מִשּׁוּם שֶׁהָיוּ מְעַכְּבִים אוֹתָם לְהִכָּנֵס לַמִּקְדָּשׁ וּמוֹחִים בִּידֵיהֶם שֶׁלֹּא לְהִכָּנֵס לְהִתְפַּלֵּל תְּפִלָּה עַד שֶׁהַקָּרְבָּנוֹת נַעֲשׂוּ, מִשּׁוּם שֶׁהֵן לֹא מְבִיאוֹת קָרְבָּנוֹת לִטֹּל חֵלֶק מֵהֶם, וּמִשּׁוּם כָּךְ מְעַכְּבִים אוֹתָן, וּמִשּׁוּם כָּךְ אוֹתָן נָשִׁים הָיוּ מְבַקְשׁוֹת מֵהֶם לְהִכָּנֵס לְשָׁם, וְעַל זֶה כָּתוּב אֵת אֲשֶׁר יִשְׁכְּבֻן אֶת הַנָּשִׁים, שֶׁמְּעַכְּבִים אוֹתָן כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>כְּמוֹ זֶה וַיִּשְׁכַּב אֶת בִּלְהָה. חַס וְשָׁלוֹם שֶׁהוּא שָׁכַב עִמָּהּ, אֶלָּא מִשּׁוּם שֶׁעִכֵּב אוֹתָהּ לְשַׁמֵּשׁ עִם אָבִיו שִׁמּוּשׁ שֶׁל מִצְוָה, וְזֶה הוּא בִּלְבּוּל הַמִּטָּה, וְעָשָׂה כְּנֶגֶד הַשְּׁכִינָה הַמַּעֲשֶׂה הַזֶּה. שֶׁבְּכָל מָקוֹם שֶׁשִּׁמּוּשׁ מִצְוָה נִמְצָא, שְׁכִינָה שׁוֹרָה עַל אוֹתוֹ מָקוֹם וְנִמְצֵאת שָׁם, וּמִי שֶׁגּוֹרֵם לְעַכֵּב שִׁמּוּשׁ שֶׁל מִצְוָה, גּוֹרֵם שֶׁתִּסְתַּלֵּק שְׁכִינָה מִן הָעוֹלָם, וְעַל זֶה כָּתוּב (בראשית מט) כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךְ אָז חִלַּלְתָּ יְצוּעִי עָלָה. וּמִשּׁוּם זֶה כָּתוּב וַיִּשְׁכַּב אֶת בִּלְהָה פִּילֶגֶשׁ אָבִיו וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְנֵי יַעֲקֹב שְׁנֵים עָשָׂר. כֻּלָּם הָיוּ בַּמִּנְיָן, וְלֹא נִגְרְעָה מִזְּכוּת שֶׁלָּהֶם כְּלוּם.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, מָה הַטַּעַם בַּתְּחִלָּה יִשְׂרָאֵל וְאַחַר כָּךְ יַעֲקֹב, שֶׁכָּתוּב וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְנֵי יַעֲקֹב שְׁנֵים עָשָׂר? אֶלָּא כְּשֶׁבָּא רְאוּבֵן וּבִלְבֵּל אוֹתָהּ מִטָּה, אָמַר: וּמַה שְּׁנֵים עָשָׂר שְׁבָטִים הָיוּ לְאַבָּא בָּעוֹלָם וְלֹא יוֹתֵר, וְעַכְשָׁו רוֹצֶה לְהוֹלִיד בָּנִים, אוּלַי אָנוּ פְּגוּמִים שֶׁהוּא רוֹצֶה לְהוֹלִיד אֲחֵרִים כְּמוֹ מִקֹּדֶם. מִיָּד בִּלְבֵּל אוֹתָהּ מִטָּה וְהִתְעַכֵּב אוֹתוֹ שִׁמּוּשׁ כְּאִלּוּ עָשָׂה קָלוֹן לַשְּׁכִינָה שֶׁשָּׁרְתָה עַל אוֹתָהּ מִטָּה, וְעַל זֶה כָּתוּב וַיִּשְׁמַע יִשְׂרָאֵל, שֶׁהֲרֵי בְּשֵׁם זֶה הִתְעַלָּה תּוֹךְ שְׁנֵים עָשָׂר שֶׁהִתְכַּסּוּ, שֶׁהֵם שְׁנֵים עָשָׂר נַהֲרוֹת אֲפַרְסְמוֹן זַךְ.</p>\n<p>וַיִּהְיוּ בְנֵי יַעֲקֹב שְׁנֵים עָשָׂר - אֵלּוּ שְׁנֵים עָשָׂר שְׁבָטִים שֶׁהַשְּׁכִינָה הִתְתַּקְּנָה בָהֶם, וּמִי הֵם? אֵלּוּ שֶׁהַתּוֹרָה חָזְרָה וְעָשְׂתָה לָהֶם חֶשְׁבּוֹן כְּמוֹ מִקֹּדֶם, כֻּלָּם קְדוֹשִׁים, כֻּלָּם רְאוּיִים לַשְּׁכִינָה לְהִסְתַּכֵּל בִּקְדֻשַּׁת רִבּוֹנָם. שֶׁאִלּוּ עָשָׂה אוֹתוֹ מַעֲשֶׂה, לֹא יָבֹא רְאוּבֵן בַּמִּנְיָן.</p>\n<p>וְעִם כָּל זֶה נֶעֱנַשׁ שֶׁנִּטְּלָה מִמֶּנּוּ בְּכוֹרָתוֹ וְנִתְּנָה לְיוֹסֵף, כְּמוֹ שֶׁנֶּאֱמַר (דה\"א ה) וּבְנֵי רְאוּבֵן בְּכוֹר יִשְׂרָאֵל כִּי הוּא הַבְּכוֹר וּבְחַלְּלוֹ יְצוּעֵי אָבִיו נִתְּנָה בְּכֹרָתוֹ (לבני) לְיוֹסֵף. בֹּא רְאֵה, (דניאל ב) שֶׁיִּהְיֶה שֵׁם הָאֵל מְבֹרָךְ מִן הָעוֹלָם וְעַד הָעוֹלָם. שֶׁכָּל מַעֲשָׂיו אֱמֶת וּדְרָכָיו דִּין, וְכָל מַה שֶּׁהוּא עוֹשֶׂה, הַכֹּל הוּא בְחָכְמָה עֶלְיוֹנָה.</p>\n<p>בֹּא רְאֵה כַּמָּה גוֹרֵם מַעֲשֵׂה אָדָם, שֶׁהֲרֵי כָּל מִי (מה) שֶׁהוּא עוֹשֶׂה, נִרְשָׁם וְעוֹמֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא. שֶׁהֲרֵי יַעֲקֹב, בְּשָׁעָה שֶׁנִּכְנַס לְלֵאָה, כָּל אוֹתוֹ הַלַּיְלָה הָיָה רְצוֹנוֹ וְלִבּוֹ בְּרָחֵל, שֶׁחָשַׁב שֶׁהִיא רָחֵל, וּמֵאוֹתוֹ שִׁמּוּשׁ וְטִפָּה רִאשׁוֹנָה וּמֵאוֹתוֹ רָצוֹן הִתְעַבְּרָה לֵאָה, וּבֵאֲרוּהוּ, שֶׁהֲרֵי אִלְמָלֵא שֶׁיַּעֲקֹב לֹא יָדַע, לֹא יַעֲלֶה רְאוּבֵן בַּחֶשְׁבּוֹן. וְעַל זֶה לֹא הִתְעַלָּה בְּשֵׁם יָדוּעַ, אֶלָּא שְׁמוֹ סְתָם רְאוּבֵן.</p>\n<p>וְעִם כָּל זֶה חָזַר מַעֲשָׂיו לִמְקוֹמוֹ, כְּמוֹ שֶׁאוֹתוֹ רָצוֹן רִאשׁוֹן נַעֲשָׂה בְּרָחֵל, אוֹתוֹ רָצוֹן חָזַר בָּהּ, שֶׁהֲרֵי בְּכוֹרָתוֹ חָזְרָה לְיוֹסֵף בְּכוֹר רָחֵל, מָקוֹם שֶׁהָרָצוֹן הָיָה בְּרָחֵל, וְהַכֹּל עוֹלֶה לִמְקוֹמוֹ, מִשּׁוּם שֶׁכָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא אֱמֶת וּזְכוּת.</p>"],[9522011362,"<p>רַבִּי חִזְקִיָּה מָצָא יוֹם אֶחָד אֶת רַבִּי יוֹסֵי שֶׁהָיְתָה נִשְׁמֶטֶת חֲתִיכַת בָּשָׂר לְתוֹךְ לַהֲבוֹת הָאֵשׁ, וְהָיָה עוֹלֶה קִטּוֹר הֶעָשָׁן לְמַעְלָה. אָמַר לוֹ, אִלּוּ קִטּוֹר הֶעָשָׁן שֶׁל הַקָּרְבָּן שֶׁהָיָה עוֹלֶה עַל גַּבֵּי הַמִּזְבֵּחַ הָיָה עוֹלֶה תָמִיד כְּמוֹ זֶה, לֹא שׁוֹרֶה רֹגֶז בָּעוֹלָם, וְיִשְׂרָאֵל לֹא הָיוּ גוֹלִים מֵעַל הָאָרֶץ.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שיר ג) מִי זֹאת עֹלָה מִן הַמִּדְבָּר כְּתִימְרוֹת עָשָׁן מְקֻטֶּרֶת מֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל. מִי זֹאת עֹלָה? בֹּא רְאֵה, בִּזְמַן שֶׁהָיוּ יִשְׂרָאֵל הוֹלְכִים בַּמִּדְבָּר, הַשְּׁכִינָה הָלְכָה לִפְנֵיהֶם, וְהֵם הָלְכוּ אַחֲרֶיהָ, שֶׁכָּתוּב (שמות יג) וַה' הֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן לַנְחֹתָם הַדֶּרֶךְ וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם וְגוֹ'. וְלָכֵן כָּתוּב (ירמיה ב) כֹּה אָמַר ה' זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלֹתָיִךְ לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר וְגוֹ'.</p>\n<p>וּשְׁכִינָה הָיְתָה הוֹלֶכֶת וְכָל עַנְנֵי הַכָּבוֹד עִמָּהּ. וּכְשֶׁהָיְתָה שְׁכִינָה נוֹסַעַת, הָיוּ נוֹסְעִים, כַּכָּתוּב (במדבר ט) וּלְפִי הֵעָלוֹת הֶעָנָן מֵעַל הָאֹהֶל וְאַחֲרֵי כֵן יִסְעוּ בְּנֵי יִשְׂרָאֵל וְגוֹ'. וּכְשֶׁהִיא עוֹלָה, אוֹתוֹ עָנָן עוֹלֶה עַד לְמַעְלָה, וְכָל בְּנֵי הָעוֹלָם רוֹאִים וְשׁוֹאֲלִים וְאוֹמְרִים, מִי זֹאת עֹלָה מִן הַמִּדְבָּר כְּתִימְרוֹת עָשָׁן.</p>\n<p>אוֹתוֹ עָנָן שֶׁל הַשְּׁכִינָה שֶׁנִּרְאָה עָשָׁן. מָה הַטַּעַם הִיא עָשָׁן? מִשּׁוּם שֶׁהָאֵשׁ שֶׁהִדְלִיקוּ אַבְרָהָם וְיִצְחָק בְּנוֹ הָיְתָה אֲחוּזָה בָּהּ וְלֹא זָזָה מִמֶּנָּה, וְכַאֲשֶׁר נֶאֶחְזָה אוֹתָהּ הָאֵשׁ בְּתוֹכָהּ, הָיְתָה עוֹלָה עָנָן (נ\"א עשן).</p>\n<p>וְעִם כָּל זֶה, מְקֻטֶּרֶת מֹר וּלְבוֹנָה. מַה זֶּה מְקֻטֶּרֶת? מִתְקַשֶּׁרֶת בִּשְׁנֵי צְדָדִים אֲחֵרִים, עָנָן שֶׁל אַבְרָהָם לְיָמִין, עָנָן שֶׁל יִצְחָק לִשְׂמֹאל. מִכֹּל אַבְקַת רוֹכֵל - זֶה יַעֲקֹב.</p>\n<p>דָּבָר אַחֵר - זֶה יוֹסֵף הַצַּדִּיק, מִשּׁוּם שֶׁאֲרוֹנוֹ שֶׁל יוֹסֵף הָיָה הוֹלֵךְ אֵלָיו. לָמָּה רוֹכֵל? מִשּׁוּם שֶׁהָיָה רָכִיל אֶת אֶחָיו לְאָבִיו. דָּבָר אַחֵר לָמָּה רוֹכֵל - אֶלָּא מַה חֶנְוָנִי זֶה שֶׁצְּרוֹרוֹת עֲצֵי בְשָׂמִים וְאַבְקוֹת עָלִים מְרִיחִים כֻּלָּם בְּיָדוֹ - כָּךְ גַּם יוֹסֵף, הוּא קִיּוּם הַתּוֹרָה, מִשּׁוּם שֶׁהוּא קִיֵּם אוֹתָהּ, מִשּׁוּם שֶׁכָּל מִצְווֹת הַתּוֹרָה קְשׁוּרוֹת לִשְׁמִירַת בְּרִית קֹדֶשׁ.</p>\n<p>וְלָכֵן שְׁכִינָה קְשׁוּרָה לְאַבְרָהָם יִצְחָק וְיַעֲקֹב וְיוֹסֵף, כְּאֶחָד הֵם, וּדְמוּת אַחַת לָהֶם. זֶהוּ שֶׁכָּתוּב (בראשית לז) אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף. וּמִשּׁוּם כָּךְ מִכֹּל אַבְקַת רוֹכֵל, מִשּׁוּם שֶׁמִּמָּקוֹם שֶׁהַנָּהָר שֶׁשׁוֹפֵעַ וְיוֹצֵא, הַכֹּל מֻשְׁקִים וְכָל הַפָּנִים מְאִירוֹת.</p>\n<p>וּבֹא וּרְאֵה, כְּשֶׁהָיוּ יִשְׂרָאֵל בָּאָרֶץ וְהָיוּ מַקְרִיבִים קָרְבָּנוֹת, כֻּלָּם הָיוּ מִתְקָרְבִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא כָּרָאוּי, וּכְשֶׁקָּרְבָּן נַעֲשָׂה וְהֶעָשָׁן עוֹלֶה בְּדֶרֶךְ יָשָׁר, אָז הָיוּ יוֹדְעִים שֶׁעֲשַׁן הַמִּזְבֵּחַ הִדְלִיק מְנוֹרָה שֶׁרְאוּיָה לְהִדָּלֵק, וְכָל הַפָּנִים מְאִירוֹת וְהַמְּנוֹרוֹת דּוֹלְקוֹת.</p>\n<p>וּמִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ אֵין לְךְ יוֹם וָיוֹם שֶׁאֵין בּוֹ זַעַם וְרֹגֶז, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם, וּפָרְשָׁה הַחֶדְוָה מִלְמַעְלָה וּמִלְּמַטָּה, וְיִשְׂרָאֵל הוֹלְכִים בַּגָּלוּת, וְהֵם בְּרָשׁוּת שֶׁל עֲבוֹדוֹת זָרוֹת אֲחֵרוֹת, וְאָז הִתְקַיֵּם הַפָּסוּק שֶׁכָּתוּב (דברים כח) וְעָבַדְתָּ שָּׁם אֱלֹהִים אֲחֵרִים.</p>\n<p>וְכָל זֶה לָמָּה? מִשּׁוּם שֶׁכָּתוּב (שם) תַּחַת אֲשֶׁר לֹא עָבַדְתָּ אֶת ה' אֱלֹהֶיךְ בְּשִׂמְחָה וּבְטוּב לֵבָב מֵרֹב כֹּל. מַה זֶּה מֵרֹב כֹּל? כָּאן מֵרֹב כֹּל, וְשָׁם מֵחֹסֶר כֹּל.</p>\n<p>עַד שֶׁיִּתְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא וְיִפְדֶּה אוֹתָם מִבֵּין הָעַמִּים, כְּמוֹ שֶׁנֶּאֱמַר (שם ל) וְשָׁב ה' אֱלֹהֶיךְ אֶת שְׁבוּתְךְ וְרִחֲמֶךְ וְשָׁב וְקִבֶּצְךְ מִכָּל הָעַמִּים אֲשֶׁר הֱפִיצְךְ ה' אֱלֹהֶיךְ שָׁמָּה. וְכָתוּב אִם יִהְיֶה נִדַּחֲךְ בִּקְצֵה הַשָּׁמָיִם מִשָּׁם יְקַבֶּצְךְ וְגוֹ'.</p>"],[9522011363,"<p>וְאֵלֶּה תֹּלְדוֹת עֵשָׂו הוּא אֱדוֹם. בֹּא רְאֵה, בְּחַיֵּי יִצְחָק לֹא נִמְנוּ בְּנֵי עֵשָׂו כְּמוֹ שֶׁנִּמְנוּ בְּנֵי יַעֲקֹב, שֶׁהֲרֵי עַד שֶׁלֹּא מֵת יִצְחָק הֵם נִמְנוּ, אֲבָל בְּעֵשָׂו מַה כָּתוּב? וַיִּגְוַע יִצְחָק וַיָּמָת וָיֵּאָסֶף אֶל עַמָּיו זָקֵן וּשְׂבַע יָמִים וַיִּקְבְּרוּ אֹתוֹ עֵשָׂו וְיַעֲקֹב בָּנָיו. אַחֲרָיו מַה כָּתוּב? וְאֵלֶּה תֹּלְדוֹת עֵשָׂו הוּא אֱדוֹם. מָה הַטַּעַם? מִשּׁוּם שֶׁאֵינוֹ בְּחֶלְקוֹ וּבִירֻשָּׁתוֹ וּבְגוֹרָלוֹ, אֶלָּא יַעֲקֹב וּבָנָיו. וְלָכֵן יַעֲקֹב וּבָנָיו הֵם חֶלְקוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְנִכְנָסִים בַּחֶשְׁבּוֹן. אֲבָל עֵשָׂו שֶׁאֵינוֹ בַּחֵלֶק שֶׁל צַד הָאֱמוּנָה, עָשָׂה חֶשְׁבּוֹנוֹ אַחַר שֶׁמֵּת יִצְחָק, וְנִפְרַד חֶלְקוֹ לְמָקוֹם אַחֵר.</p>\n<p>בֹּא רְאֵה, אַחֲרֵי שֶׁמֵּת יִצְחָק וְעֵשָׂו נִפְרַד לַצַּד שֶׁלּוֹ, מַה כָּתוּב? וַיִּקַּח עֵשָׂו אֶת נָשָׁיו וְגוֹ' מִפְּנֵי יַעֲקֹב אָחִיו. שֶׁהִשְׁאִיר לְיַעֲקֹב קֶרֶן וְרֶוַח שִׁעְבּוּד מִצְרַיִם, וְהָאָרֶץ, וּמָכַר לוֹ חֶלְקוֹ בִּמְעָרַת הַמַּכְפֵּלָה, וְהָלַךְ לוֹ מִן הָאָרֶץ וּמִן הָאֱמוּנָה וּמֵחֶלְקוֹ, שֶׁהָלַךְ לוֹ מֵהַכֹּל.</p>\n<p>בֹּא רְאֵה כַּמָּה הָיָה חֶלְקוֹ שֶׁל יַעֲקֹב טוֹב בַּכֹּל מִשּׁוּם שֶׁלֹּא נִשְׁאַר עֵשָׂו עִמּוֹ וְנִפְרַד מִמֶּנּוּ וְהָלַךְ לוֹ לְחֶלְקוֹ וּלְגוֹרָלוֹ, וְנִשְׁאַר יַעֲקֹב אָחוּז בִּירֻשַּׁת אָבִיו וּבִירֻשַּׁת אֲבוֹתָיו. וְעַל זֶה וַיֵּלֶךְ אֶל אֶרֶץ מִפְּנֵי יַעֲקֹב אָחִיו. מַה זֶּה מִפְּנֵי יַעֲקֹב אָחִיו? שֶׁלֹּא רָצָה חֶלְקוֹ וִירֻשָּׁתוֹ וְגוֹרַל הָאֱמוּנָה שֶׁלּוֹ. אַשְׁרֵי חֶלְקוֹ שֶׁל יַעֲקֹב, עָלָיו כָּתוּב (דברים לב) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ.</p>"],[9522011364,"<p>וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. רַבִּי יֵיסָא פָּתַח וְאָמַר, (עובדיה א) הִנֵּה קָטֹן נְתַתִּיךְ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד. בֹּא רְאֵה, כְּשֶׁעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם וְחִלֵּק אֶת הָאָרֶץ לְשִׁבְעָה תְּחוּמֵי חֲלָקִים כְּנֶגֶד שִׁבְעִים מְמֻנִּים גְּדוֹלִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חִלֵּק אוֹתָם לְשִׁבְעִים עַמִּים, כָּל אֶחָד וְאֶחָד כָּרָאוּי לוֹ, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם בְּהַפְרִידוֹ בְּנֵי אָדָם יַצֵּב גְּבֻלֹת עַמִּים.</p>\n<p>וּמִכָּל הַמְמֻנִּים הַגְּדוֹלִים שֶׁנִּמְסְרוּ לִשְׁאָר הָעַמִּים אֵין בָּהֶם בָּזוּי לְפָנָיו כַּמְמֻנֶּה שֶׁל עֵשָׂו, מָה הַטַּעַם? מִשּׁוּם שֶׁהַצַּד שֶׁל עֵשָׂו הוּא צַד הַטֻּמְאָה, וְצַד הַטֻּמְאָה הוּא קָלוֹן לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מֵאוֹתָן דְּרָגוֹת קְטַנּוֹת שֶׁאַחַר הָרֵיחַיִם, שֶׁבָּא מֵהָרֵיקָנוּת שֶׁל הַמִּדּוֹת הָאֲדֻמּוֹת, וְעַל זֶה הִנֵּה קָטֹן נְתַתִּיךְ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד, שֶׁכָּתוּב (בראשית ג) עַל גְּחֹנְךְ תֵלֵךְ וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךְ. מְאֹד, כְּמוֹ שֶׁנֶּאֱמַר אַתָּה מִכָּל הַבְּהֵמָה וּמִכֹּל חַיַּת הַשָּׂדֶה.</p>\n<p>בֹּא רְאֵה, בַּדְּרָגוֹת הַתַּחְתּוֹנוֹת יֵשׁ דְּרָגוֹת עַל דְּרָגוֹת, כֻּלָּם מְשֻׁנִּים זֶה מִזֶּה, וְכָל הַדְּרָגוֹת נִפְרָדוֹת הֵן, וּקְשׁוּרוֹת אֵלֶּה בְאֵלֶּה, וּמַלְכוּת נִפְרֶדֶת זֶה מִזֶּה, וּמַלְכוּת קְשׁוּרָה בְמַלְכוּת, זֶה נִכְנָס וְזֶה עוֹלֶה, אֲחוּזִים בְּקֶשֶׁר אֶחָד.</p>\n<p>לְאוֹתוֹ קֶשֶׁר יֵשׁ קוֹמָה אַחַת, וּשְׁלֹשָׁה קְשָׁרִים לְאוֹתָהּ קוֹמָה. בְּכָל קֶשֶׁר וְקֶשֶׁר עֲטָרָה אַחַת, וּבְכָל עֲטָרָה וַעֲטָרָה שְׁלִיטָה אַחַת,</p>\n<p>וְהִתְמַנָּה בָּעִטּוּר שֶׁלְּמַעְלָה, וְהִתְמַנָּה וְיָרַד לְמַטָּה, עַד שֶׁהִתְקַשְּׁרוּ בוֹ כּוֹכָבִים וּמַזָּלוֹת. כָּל אֶחָד וְאֶחָד נִפְרָד בּוֹ כּוֹכָב אֶחָד וּמַזָּל אֶחָד, וְכָל הַכּוֹכָבִים מְזֻמָּנִים הֵם בְּאוֹתָן דְּרָגוֹת שֶׁלְּמַעְלָה. וְעַל זֶה כָּל דַּרְגָּה וְדַרְגָּה מִתְעַטֶּרֶת בִּמְקוֹמוֹת יְדוּעִים כָּרָאוּי.</p>\n<p>וּכְשֶׁנִּפְרָדוֹת הַדְּרָגוֹת נִמְצָא קֶשֶׁר הַמַּפְסִיק, עַד שֶׁמִּתְקַשְּׁרִים לַצַּד שֶׁנִּרְאֶה לָהֶם, וְהַצְּדָדִים שֶׁל דַּרְגּוֹת הַטֻּמְאָה שֶׁהֵם בְּצַד שְׂמֹאל, כֻּלָּם נִפְרָדִים לְכַמָּה דְרָכִים וּשְׁבִילִים מִצִּדֵּי הַגְּבוּרוֹת הָאֲדֻמּוֹת, וְלָכֵן תְּלוּיוֹת הַגְּבוּרוֹת לְמַטָּה לְאֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת. וְעַל זֶה הִנֵּה קָטֹן נְתַתִּיךְ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד, כְּמוֹ שֶׁאָמַ רְנוּ.</p>\n<p>בֹּא רְאֵה, וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם, בְּאֶרֶץ - בַּצַּד שֶׁל הַדַּרְגָּה שֶׁלּוֹ שֶׁהִיא דַּרְגַּת עֵשָׂו, שֶׁכָּתוּב עֵשָׂו הוּא אֱדוֹם, וְכֻלָּם בָּאִים מִצַּד שֶׁל רוּחַ הַטֻּמְאָה. לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל - מִשּׁוּם שֶׁאוֹתָן דְּרָגוֹת שֶׁעוֹמְדוֹת בְּבֵית הַשְּׁעָרִים לְמַטָּה קוֹדְמוֹת. וְלָכֵן אָמַר יַעֲקֹב יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ, בִּשְׁבִיל דַּרְגוֹתָיו הָרִאשׁוֹנוֹת הֵן לְהִכָּנֵס, וּמִשּׁוּם כָּךְ לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. שֶׁעַד עַכְשָׁו טֶרֶם הִגִּיעַ זְמַנָּהּ שֶׁל מַלְכוּת הַשָּׁמַיִם לִשְׁלֹט וּלְהֵאָחֵז בִּבְנֵי יִשְׂרָאֵל, וְלָכֵן אָמַר יַעֲבָר נָא אֲדנִי לִפְנֵי עַבְדּוֹ.</p>\n<p>וּכְשֶׁהֻשְׁלְמוּ דְּרָגוֹת אֵלּוּ בַּתְּחִלָּה, אַחַר כָּךְ מִתְעוֹרֶרֶת מַלְכוּת הַשָּׁמַיִם לִשְׁלֹט עַל הַתַּחְתּוֹנִים, וּכְשֶׁשּׁוֹרָה, שׁוֹרָה בַּקָּטָן שֶׁל כָּל הַשְּׁבָטִים, שֶׁהוּא בִּנְיָמִין, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סח) שָׁם בִּנְיָמִין צָעִיר רוֹדֵם וְגוֹ'. וּבוֹ שׁוֹרָה לְהִתְעוֹרֵר הַמַּלְכוּת. אַחַר כָּךְ בָּאָה הַמַּלְכוּת לִמְקוֹמָהּ וְעוֹמֶדֶת עִמּוֹ שֶׁלֹּא תָזוּז לְעוֹלָמִים.</p>"],[9522011365,"<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (ישעיה מד) וְעַתָּה שְׁמַע יַעֲקֹב עַבְדִּי וְיִשְׂרָאֵל בָּחַרְתִּי בוֹ. כֹּה אָמַר ה' עֹשֶׂךְ וְיֹצֶרְךְ מִבֶּטֶן יַעְזְרֶךָּ אַל תִּירָא עַבְדִּי יַעֲקֹב וִישֻׁרוּן בָּחַרְתִּי בוֹ. בּא רְאֵה כַּמָּה הִבְטִיחַ לָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לְיִשְׂרָאֵל בְּכַמָּה מְקוֹמוֹת (כדי) לְזַכּוֹתָם לָעוֹלָם הַבָּא, שֶׁהֲרֵי לֹא הִתְרַצָּה לְחֶלְקוֹ לְכָל עַם וְלָשׁוֹן פְּרָט לְיִשְׂרָאֵל לְבַדָּם. וְלָכֵן נָתַן לָהֶם תּוֹרַת אֱמֶת, לִזְכּוֹת בָּהּ וְלָדַעַת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כְּדֵי שֶׁיִּירְשׁוּ אֶרֶץ הַקְּדוֹשָׁה, שֶׁכָּל מִי שֶׁזּוֹכֶה בָּאָרֶץ הַקְּדוֹשָׁה הַזּוֹ, יֵשׁ לוֹ חֵלֶק לָעוֹלָם הַבָּא, כְּמוֹ שֶׁנֶּאֱמַר (שם ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>שָׁלֹשׁ דְּרָגוֹת כָּאן: בַּתְּחִלָּה יַעֲקֹב, אַחַר כָּךְ יִשְׂרָאֵל, וְאַחַר כָּךְ יְשׁוּרוּן. בֹּא רְאֵה, יַעֲקֹב הֲרֵי כְּבָר בֵּאֲרוּהוּ, יִשְׂרָאֵל אַף גַם כָּךְ, וְאַף עַל גַּב שֶׁדְּרָגוֹת אֵלּוּ כְּאַחַת.</p>\n<p>יְשׁוּרוּן לָמָּה נִקְרְאוּ יִשְׂרָאֵל בְּשֵׁם זֶה? אֶלָּא יִשְׂרָאֵל וִישׁוּרוּן הַכֹּל אֶחָד. יְשׁוּרוּן, כְּמוֹ שֶׁנֶּאֱמַר (איוב לג) יָשֹׁר עַל אֲנָשִׁים, מִשּׁוּם שֶׁנָּטַל שׁוּרָה לְצַד זֶה וּלְצַד זֶה, וּמִשּׁוּם אוֹתָן שְׁתֵּי שׁוּרוֹת נִקְרָא יְשׁוּרוּן, וְזֶהוּ יִשְׂרָאֵל.</p>\n<p>יִשְׂרָאֵל עַל שֶׁנָּטַל גְּדֻלָּה וְתֹקֶף מֵהַכֹּל. יִשְׂרָאֵל (ישורון) עַל אוֹתָם חֲלָקִים שְׁנֵי צְדָדִים שְׁתֵּי שׁוּרוֹת, כְּמוֹ שֶׁאָמַרְנוּ, וְהַכֹּל אֶחָד.</p>\n<p>וְכָל אוֹתָם שֵׁמוֹת עוֹלִים לְאֶחָד. יַעֲקֹב עַבְדִּי, לִפְעָמִים הוּא עֶבֶד, כְּמוֹ עֶבֶד שֶׁיֵּשׁ לוֹ מִצְוַת אֲדוֹנוֹ וְלַעֲשׂוֹת רְצוֹנוֹ. וְכֵן יִשְׂרָאֵל בָּחַרְתִּי בוֹ, לְהַשְׁרוֹת עָלָיו, וְהַכֹּל הוּא בְּסוֹד עֶלְיוֹן. כָּתוּב (ישעיה מג) בֹּרַאֲךְ יַעֲקֹב וְיֹצֶרְךְ יִשְׂרָאֵל, וְכָתוּב כֹּה אָמַר ה' עֹשֶׂךְ. כָּל הַדְּרָגוֹת הַלָּלוּ עוֹלוֹת לְאֶחָד, וַהֲרֵי נֶאֱמַר, בּוֹרֵ\"א, יוֹצֵ\"ר, עוֹשֶׂ\"ה, וְכָל הַדְּרָגוֹת אֵלֶּה עַל אֵלֶּה וְכֻלָּן אֶחָד.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הִתְרַצָּה בָהֶם מִכָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כוֹכָבִים וּמַזָּלוֹת, מִשּׁוּם שֶׁבְּכֻלָּם כָּתוּב (ירמיה י) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתֻּעִים בְּעֵת פְּקֻדָּתָם יֹאבֵדוּ, בְּשָׁעָה שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עָתִיד לְבַעֵר אוֹתָם מִן הָעוֹלָם וְיִשָּׁאֵר הוּא לְבַדּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ב) וְנִשְׂגָּב ה' לְבַדּוֹ בַּיּוֹם הַהוּא.</p>"],[9522011366,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (שם מא) אַל תִּירְאִי תּוֹלַעַת יַעֲקֹב מְתֵי יִשְׂרָאֵל אֲנִי עֲזַרְתִּיךְ נְאֻם ה' וְגֹאֲלֵךְ קְדוֹשׁ יִשְׂרָאֵל. בֹּא רְאֵה, כָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת שֶׁל הָעוֹלָם, הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן אוֹתָם לִמְמֻנִּים שַׁלִּיטִים יְדוּעִים כְּמוֹ שֶׁנֶּאֱמַר, וְכֻלָּם הוֹלְכִים אַחֲרֵי אֱלֹהֵיהֶם, כְּמוֹ שֶׁכָּתוּב (מיכה ד) כִּי כָל הָעַמִּים יֵלְכוּ אִישׁ בְּשֵׁם אֱלֹהָיו. וְכֻלָּם שׁוֹפְכִים דָּמִים וְעוֹרְכִים קְרָבוֹת אֵלּוּ בְּאֵלּוּ, גּוֹזְלִים רוֹצְחִים וְנוֹאֲפִים, וּמְעֹרָבִים בְּכַמָּה מַעֲשִׂים רָעִים, וּמִתְחַזְּקִים בְּכֹחָם לְהָרַע.</p>\n<p>וּלְיִשְׂרָאֵל אֵין תֹּקֶף וְכֹחַ לְנַצֵּחַ אוֹתָם פְּרָט לַפֶּה שֶׁלָּהֶם, כַּתּוֹלַעַת הַזּוֹ שֶׁאֵין לָהּ תֹּקֶף וְכֹחַ אֶלָּא בְּפִיהָ, וּבְפִיהָ הִיא שׁוֹבֶרֶת הַכֹּל, וְלָכֵן נִקְרְאוּ יִשְׂרָאֵל תּוֹלַעַת.</p>\n<p>עוֹד, אַל תִּירְאִי תּוֹלַעַת יַעֲקֹב - מַה תּוֹלַעַת אֵין בְּרִיָּה בָּעוֹלָם כְּמוֹ תּוֹלַעַת הַמֶּשִׁי הַזּוֹ שֶׁטּוֹוִים בּוֹ, שֶׁמִּמֶּנָּה יוֹצְאִים כָּל לְבוּשֵׁי כָבוֹד, לְבוּשֵׁי הַמְּלָכִים, אַחַר כָּךְ זוֹרַעַת זְרָעִים וּמֵתָה, וּמֵאוֹתוֹ הַזֶּרַע שֶׁנִּשְׁאָר מִמֶּנָּה מִתְקַיֶּמֶת כְּמוֹ מִקֹּדֶם וַהֲרֵיהִי בְּקִיּוּם - כָּךְ יִשְׂרָאֵל הֵם כְּמוֹ הַתּוֹלַעַת הַזּוֹ, שֶׁאַף עַל פִּי שֶׁמֵּתִים, יַחְזְרוּ וְיִתְקַיְּמוּ בָעוֹלָם כְּמוֹ מִקֹּדֶם.</p>\n<p>וַהֲרֵי נֶאֱמַר (שכתוב) (ירמיה יח) (כי) (הנה) כַחֹמֶר בְּיַד הַיּוֹצֵר כֵּן אַתֶּם בְּיָדִי בֵּית יִשְׂרָאֵל. מַה זֶּה כַּחֹמֶר? אֶלָּא זֶהוּ חֹמֶר שֶׁל אוֹתָהּ זְכוּכִית, שֶׁאַף עַל גַּב שֶׁנִּשְׁבָּר - נִתְקָן, וְיֵשׁ לוֹ תַּקָּנָה כְּמוֹ מִקֹּדֶם.</p>\n<p>מְתֵי יִשְׂרָאֵל - זֶה עֵץ הַחַיִּים. שֶׁמִּשּׁוּם שֶׁיִּשְׂרָאֵל דְּבוּקִים בְּעֵץ הַחַיִּים, לָכֵן יִהְיוּ לָהֶם חַיִּים וְיָקוּמוּ מִן הֶעָפָר וְיִתְקַיְּמוּ בָעוֹלָם וְיִהְיוּ לְעַם אֶחָד לַעֲבֹד אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (צפניה ג) לִקְרֹא כֻלָּם בְּשֵׁם ה' לְעָבְדוֹ שְׁכֶם אֶחָד.</p>"],[9522011367,"<p>רַבִּי אֶלְעָזָר וְרַבִּי יִצְחָק הָיוּ הוֹלְכִים בַּדֶּרֶךְ, וְהִגִּיעַ זְמַן קְרִיאַת שְׁמַע, וְקָם רַבִּי אֶלְעָזָר וְקָרָא קְרִיאַת שְׁמַע וְהִתְפַּלֵּל תְּפִלָּתוֹ. אַחַר כָּךְ אָמַר לוֹ רַבִּי יִצְחָק, וַהֲרֵי שָׁנִינוּ, שֶׁעַד שֶׁלֹּא יֵצֵא אָדָם לְדַרְכּוֹ, צָרִיךְ לִטֹּל רְשׁוּת מֵרִבּוֹנוֹ וּלְהִתְפַּלֵּל תְּפִלָּתוֹ.</p>\n<p>אָמַר לוֹ, מִשּׁוּם שֶׁכְּשֶׁיָּצָאתִי לֹא הָיָה זְמַן תְּפִלָּה וְלֹא הִגִּיעַ זְמַן קְרִיאַת שְׁמַע. עַכְשָׁו שֶׁהַשֶּׁמֶשׁ מְאִירָה, הִתְפַּלַּלְתִּי. אֲבָל עַד שֶׁלֹּא יָצָאתִי לַדֶּרֶךְ, בִּקַּשְׁתִּי בַקָּשָׁתִי מִמֶּנּוּ וְנִמְלַכְתִּי בוֹ, אֲבָל תְּפִלָּה זוֹ לֹא הִתְפַּלַּלְתִּי.</p>\n<p>שֶׁהֲרֵי אֲנִי עוֹסֵק בַּתּוֹרָה מֵחֲצוֹת הַלַּיְלָה, וְכַאֲשֶׁר הִגִּיעַ הַבֹּקֶר, עַד עַכְשָׁו לֹא הָיָה זְמַן לְהִתְפַּלֵּל תְּפִלָּה, מִשּׁוּם שֶׁאוֹתָהּ שָׁעָה שֶׁל קַדְרוּת הַשַּׁחַר נִמְצֵאת אִשָּׁה מְדַבֶּרֶת עִם בַּעְלָהּ וְהֵם בְּסוֹד כְּאֶחָד, שֶׁהִיא רוֹצָה לָלֶכֶת לְמִשְׁכָּנָהּ עִם עַלְמוֹתֶיהָ שֶׁיּוֹשְׁבוֹת עִמָּהּ, וְלָכֵן לֹא צָרִיךְ הָאָדָם לְהַפְסִיק דִּבּוּרָם כְּשֶׁמְּחֻבָּרִים כְּאֶחָד וּלְהַכְנִיס דָּבָר אַחֵר בֵּינֵיהֶם.</p>\n<p>וְעַכְשָׁו שֶׁהֵאִיר הַשֶּׁמֶשׁ, הוּא זְמַן הַתְּפִלָּה לְהִתְפַּלֵּל, כְּמוֹ שֶׁבֵּאֲרוּהוּ, שֶׁכָּתוּב (תהלים עב) יִירָאוּךְ עִם שָׁמֶשׁ. מַהוּ עִם שָׁמֶשׁ? לִשְׁמֹר אוֹר הַשֶּׁמֶשׁ עִמָּנוּ לְהָאִיר לָהּ, שֶׁהֲרי יֵרָאֶה עִם הַשֶּׁמֶשׁ צָרִיךְ, וְלֹא לְהַפְרִידָם. וּכְשֶׁלֹּא מֵאִיר הַיּוֹם, הוּא לֹא יֵרָאֶה עִם הַשֶּׁמֶשׁ, וְצָרִיךְ לְחַבֵּר אוֹתָם כְּאֶחָד, וְזֶהוּ עִם שָׁמֶשׁ.</p>\n<p>הָלְכוּ, כְּשֶׁהִגִּיעוּ לְבֵית שָׂדֶה אֶחָד יָשְׁבוּ. זָקְפוּ עֵינֵיהֶם וְרָאוּ הַר אֶחָד שֶׁהָיוּ עוֹלִים בְּרוּמוֹ בְּרִיּוֹת מְשֻׁנּוֹת. פָּחַד רַבִּי יִצְחָק. אָמַר לוֹ רַבִּי אֶלְעָזָר, לָמָּה אַתָּה פּוֹחֵד? אָמַר לוֹ, רָאִיתִי שֶׁהָהָר הַזֶּה קָשֶׁה, וְרָאִיתִי אֶת הַבְּרִיּוֹת הַלָּלוּ שֶׁהֵן מְשֻׁנּוֹת, וּפָחַדְתִּי שֶׁלֹּא יָצֵרוּ לָנוּ. אָמַר לוֹ, מִי שֶׁפּוֹחֵד - מֵחֲטָאִים שֶׁבְּיָדָיו יֵשׁ לוֹ לִפְחֹד. בֹּא רְאֵה, אֵין אֵלֶּה מֵאוֹתָן בְּרִיּוֹת קָשׁוֹת שֶׁהָיוּ נִמְצָאוֹת בֶּהָרִים.</p>"],[9522011368,"<p>פָּתַח וְאָמַר: וְאֵלֶּה בְנֵי צִבְעוֹן וְאַיָּה וַעֲנָה הוּא עֲנָה אֲשֶׁר מָצָא אֶת הַיֵּמִם וְגוֹ'. פָּסוּק זֶה בֵּאֲרוּהוּ, אֲבָל בֹּא רְאֵה, אֵין אֵלֶּה אוֹתָם שֶׁכָּתוּב בָּהֶם (דברים ב) הָאֵמִים לְפָנִים יָשְׁבוּ בָהּ וְגוֹ', וּבְנֵי עֵשָׂו יִירָשׁוּם וְגוֹ'.</p>\n<p>אֲבָל אֵלֶּה שֶׁאָמַר הַכָּתוּב אֲשֶׁר מָצָא אֶת הַיֵּמִם בַּמִּדְבָּר, יֵמִם כָּתוּב (חסר י'), אֵלּוּ הָיוּ בְּרִיּוֹת מְשֻׁנּוֹת. שֶׁכַּאֲשֶׁר גֹּרַשׁ קַיִן מֵעַל פְּנֵי הָאֲדָמָה, כַּכָּתוּב (בראשית ד) הֵן גֵּרַשְׁתָּ אֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה וּמִפָּנֶיךְ אֶסָּתֵר, וְכָתוּב וַיֵּשֶׁב בְּאֶרֶץ נוֹד, וּבֵאֲרוּהוּ.</p>\n<p>מִבְּנֵי בָנָיו בְּצַד שֶׁל רוּחוֹת וּסְעָרוֹת וּמַזִּיקִים וְאֵלֶּה עָמְדוּ, שֶׁהֲרֵי כְּשֶׁרָצָה לְהִתְקַדֵּשׁ יוֹם הַשַּׁבָּת, נִבְרְאוּ מֵאוֹתוֹ צַד רוּחוֹת קַיָּמוֹת מְעוֹפְפוֹת (מאירות) בְּלִי גוּף, וְאֵלֶּה אֵינָם לֹא מִיּוֹם שַׁבָּת וְלֹא מִיּוֹם שִׁשִּׁי, וְנִשְׁאֲרוּ אֵלּוּ יוֹמַיִם בָּהֶם בְּסָפֵק, וְלָכֵן לֹא הִתְקַיְּמוּ לֹא מִזֶּה וְלֹא מִזֶּה.</p>\n<p>וְהָלְכוּ וְהִתְפַּשְּׁטוּ בְּאוֹתוֹ צַד שֶׁל קַיִן, וְהִתְלַבְּשׁוּ בְּאוֹתוֹ צַד, וְלֹא הִתְלַבְּשׁוּ לְהִתְקַיֵּם, וְנִקְרְאוּ יֵמִ\"ם חָסֵר, שֶׁלֹּא הִתְקַיְּמוּ לֹא בְּיוֹם זֶה וְלֹא בְּיוֹם זֶה, וְנִרְאִים לִבְנֵי אָדָם. וְהוּא מָצָא אוֹתָם וְלִמְּדוּ אוֹתוֹ לְהָבִיא מַמְזֵרִים לָעוֹלָם, וְהֵם הוֹלְכִים בֵּין הֶהָרִים וְעוֹמְדִים בְּגוּף פַּעַם אַחַת בַּיּוֹם, וְאַחַר כָּךְ מִתְפַּשְּׁטִים מִמֶּנּוּ.</p>\n<p>בֹּא רְאֵה, הָעֲנָה הַזֶּה הָיָה מַמְזֵר, שֶׁבָּא צִבְעוֹן עַל אִמּוֹ וְהוֹלִיד מַמְזֵר, וְזֶה בָּא מִצַּד רוּחַ הַטֻּמְאָה שֶׁנִּדְבַּק בּוֹ, וְלָכֵן מָצָא אוֹתָם וְלִמְּדוּ אוֹתוֹ כָּל מִינֵי צַד הַטֻּמְאָה בִּשְׁבִיל זֶה.</p>\n<p>וּבֹא וּרְאֵה, אֵלֶּה הֵם וְכַמָּה אֲחֵרִים נִפְרָדִים אֵלֶּה מֵאֵלֶּה, כֻּלָּם בָּאִים מֵאוֹתוֹ צַד וְהוֹלְכִים בַּמִּדְבָּר וְנִרְאִים שָׁם, מִשּׁוּם שֶׁהַמִּדְבָּר הוּא מָקוֹם חָרֵב וְהוּא בֵּית מוֹשָׁבָם. וְעִם כָּל זֶה, כָּל אָדָם שֶׁהוֹלֵךְ בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְיָרֵא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא, לֹא פוֹחֵד מֵהֶם. הָלְכוּ וְנִכְנְסוּ בְּהַר.</p>\n<p>אָמַר רַבִּי יִצְחָק, כְּמוֹ זֶה כָּל אוֹתָם הָרִים חֲרֵבִים, מְקוֹם מוֹשָׁב שֶׁלָּהֶם הוּא. אָמַר לוֹ, כָּךְ זֶה, וְכָל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה כָּתוּב עֲלֵיהֶם (תהלים קכא) ה' יִשְׁמָרְךְ מִכָּל רָע יִשְׁמֹר אֶת נַפְשֶׁךְ ה' יִשְׁמָר צֵאתְךְ וּבוֹאֶךְ מֵעַתָּה וְעַד עוֹלָם.</p>"],[9522011369,"<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (שם קיא) הַלְלוּיָהּ אוֹדֶה ה' בְּכָל לֵבָב בְּסוֹד יְשָׁרִים וְעֵדָה, פָּסוּק זֶה פֵּרְשׁוּהוּ, אֲבָל בֹּא רְאֵה, דָּוִד הַמֶּלֶךְ כָּל יָמָיו הָיָה מִשְׁתַּדֵּל בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהָיָה קָם בַּחֲצוֹת הַלַּיְלָה וּמְשַׁבֵּחַ וּמוֹדֶה בְּשִׁירוֹת וְתִשְׁבָּחוֹת כְּדֵי לְתַקֵּן מְקוֹמוֹ בַּמַּלְכוּת שֶׁל מַעְלָה.</p>\n<p>שֶׁכְּשֶׁמִּתְעוֹרֵר רוּחַ צָפוֹן בַּחֲצוֹת הַלַּיְלָה, הָיָה יוֹדֵעַ שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בְּאוֹתָהּ שָׁעָה מִתְעוֹרֵר בְּגַן עֵדֶן לְהִשְׁתַּעֲשֵׁעַ עִם הַצַּדִּיקִים, וְהוּא הָיָה קָם בְּאוֹתָהּ שָׁעָה וּמִתְגַּבֵּר בְּשִׁירִים וְתִשְׁבָּחוֹת עַד שֶׁעוֹלֶה הַשַּׁחַר.</p>\n<p>מִשּׁוּם שֶׁכְּשֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בְּגַן עֵדֶן, הֲרֵי בֵּאַרְנוּ שֶׁהוּא וְכָל הַצַּדִּיקִים שֶׁבַּגָּן, כֻּלָּם מַקְשִׁיבִים לְקוֹלוֹ, כַּכָּתוּב (שיר ח) חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי. וְלֹא עוֹד, אֶלָּא חוּט שֶׁל חֶסֶד מָשׁוּךְ עָלָיו בַּיּוֹם, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמּי. וְלֹא עוֹד, אֶלָּא שֶׁאוֹתָם דִּבְרֵי תוֹרָה שֶׁהוּא אוֹמֵר, כֻּלָּם עוֹלִים וּמִתְעַטְּרִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלָכֵן דָּוִד הַמֶּלֶךְ הָיָה מִשְׁתַּדֵּל בַּלַּיְלָה בַּעֲבוֹדַת אֲדוֹנוֹ.</p>\n<p>בֹּא רְאֵה, הַלְלוּיָהּ, בְּכָל אוֹתָן שִׁירוֹת וְתִשְׁבָּחוֹת שֶׁדָּוִד אָמַר, הֲרֵי שָׁנִינוּ שֶׁלְּמַעְלָה מִכֻּלָּם הוּא הַלְלוּיָהּ, וּבֵאֲרוּהוּ, מָה הַטַּעַם? מִשּׁוּם שֶׁכּוֹלֵל הַשֵּׁם וְהַשֶּׁבַח כְּאֶחָד. מַה שֵּׁם וּמַה שֶּׁבַח? שֵׁם זֶה י\"ה. הַשֶּׁבַח מַהוּ? אֶלָּא זוֹ כְּנֶסֶת יִשְׂרָאֵל שֶׁהִיא (הלל בגימטריא ה\"ס, שהוא אדנ\"י) מְתַקֶּנֶת שֶׁבַח תָּמִיד לַקָּדוֹשׁ-בָּרוּךְ-הוּא וְלֹא שׁוֹקֶטֶת, כְּמוֹ שֶׁנֶּאֱמַר (שם פג) אֱלֹהִים אַל דֳּמִי לָךְ אַל תֶּחֱרָשׁ וְאַל תִּשְׁקֹט אֵל. מִשּׁוּם שֶׁסִּדּוּר הַשֶּׁבַח הִיא מְסַדֶּרֶת וּמְשַׁבַּחַת תָּמִיד אֵלָיו, וְלָכֵן שֵׁם וְשֶׁבַח כְּאֶחָד.</p>\n<p>אוֹדֶה ה' בְּכָל לֵבָב, כְּמוֹ שֶׁבֵּאֲרוּהוּ - בַּיֵּצֶר הַטּוֹב וּבַיֵּצֶר הָרָע, מִשּׁוּם שֶׁהֵם נִמְצָאִים תָּמִיד אֵצֶל הָאָדָם, כְּמוֹ שֶׁנֶּאֱמַר (דברים ו) בְּכָל לְבָבְךְ, וּבֵאֲרוּהוּ.</p>\n<p>בְּסוֹד יְשָׁרִים וְעֵדָה - אֵלּוּ הֵם יִשְׂרָאֵל שֶׁכָּל הַדְּרָגוֹת מִתְעַטְּרוֹת בָּהֶם, כֹּהֲנִים וּלְוִיִּם, צַדִּיקִים וַחֲסִידִים, יְשָׁרִים. וְעֵדָה, כְּמוֹ שֶׁנֶּאֱמַר (תהלים פג) נִצָּב בַּעֲדַת אֵל. וְהֵם סוֹד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַטֵּר בָּהֶם.</p>\n<p>וְלָכֵן צָרִיךְ הָאָדָם לְשַׁבֵּחַ אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא תָּמִיד, מִשּׁוּם שֶׁהוּא מִתְרַצֶּה בְּשִׁירִים וְתִשְׁבָּחוֹת, וּמִי שֶׁיּוֹדֵעַ לְשַׁבֵּחַ לוֹ לְהַקָּדוֹשׁ בָּרוּךְ הוּא כָּרָאוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַבֵּל תְּפִלָּתוֹ וּמַצִּילוֹ. זֶהוּ שֶׁכָּתוּב (שם צא) אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי וְגוֹ', אֹרֶךְ יָמִים וְגוֹ'.</p>"],[9522011370,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שם לב) אַתָּה סֵתֶר לִי מִצַּר תִּצְּרֵנִי רָנֵּי פַלֵּט תְּסוֹבְבֵנִי סֶלָה. אַתָּה סֵתֶר לִי - זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁהוּא סֵתֶר וּמָגֵן לְאָדָם שֶׁהוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, וְהוּא מִסְתַּתֵּר בְּצֵל כְּנָפָיו, שֶׁלֹּא יְכוֹלִים לְהָרַע לוֹ. מִצַּר תִּצְּרֵנִי - מִלְמַעְלָה וּמִלְּמַטָּה. לְמַעְלָה יֵשׁ לָאָדָם יְרִיבִים, אַף לְמַטָּה כָּךְ גַּם, וּמִיהוּ? זֶהוּ יֵצֶר הָרָע שֶׁהוּא צַר לְמַעְלָה וְצַר לְמַטָּה, וְאִלְמָלֵא יֵצֶר הָרָע - לֹא נִמְצָא בַּעַל רִיב לְאָדָם בָּעוֹלָם. בִּשְׁבִיל כָּךְ מִצַּר תִּצְּרֵנִי.</p>\n<p>רָנֵּי פַלֵּט תְּסוֹבְבֵנִי סֶלָה, הָיָה צָרִיךְ לִכְתֹּב יְסוֹבְבֵנִי סֶלָה, מַה זֶּה תְּסוֹבְבֵנִי? אֵלּוּ שִׁירִים שֶׁיֵּשׁ בָּהֶם דְּרָגוֹת לְהַצָּלָה, תְּסוֹבְבֵנִי בָּהֶם לְהַצִּילֵנִי בַּדֶּרֶךְ. וּפָסוּק זֶה הוּא גַּם כַּסֵּדֶר וְגַם לְמַפְרֵעַ, מִצַּד זֶה וּמִצַּד זֶה.</p>\n<p>בֹּא רְאֵה, בְּשִׁירִים וְתִשְׁבָּחוֹת הַלָּלוּ שֶׁאָמַר דָּוִד יֵשׁ בָּהּ סוֹדוֹת וּדְבָרִים עֶלְיוֹנִים בְּסוֹדוֹת הַחָכְמָה, מִשּׁוּם שֶׁכֻּלָּם נֶאֶמְרוּ בְּרוּחַ הַקֹּדֶשׁ, שֶׁהָיָה שׁוֹרֶה רוּחַ הַקֹּדֶשׁ עַל דָּוִד וְהָיָה אוֹמֵר שִׁירָה, וְלָכֵן כֻּלָּם נֶאֶמְרוּ בְּסוֹדוֹת הַחָכְמָה.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהלים קיח) דָּחֹה דְחִיתַנִי לִנְפֹּל וַה' עֲזָרָנִי. דָּחֹה דְחִיתַנִי, דָּחֹה דָחוּנִי הָיָה צָרִיךְ לִכְתֹּב! מַה זֶּה דָּחֹה דְחִיתַנִי? אֶלָּא זֶה צַד הָאַחֵר שֶׁדּוֹחֶה אֶת הָאָדָם תָּמִיד וְרוֹצֶה לִדְחוֹת אוֹתוֹ וּלְהַסְטוֹתוֹ מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזֶהוּ יֵצֶר הָרָע שֶׁנִּמְצָא תָמִיד אֵצֶל הָאָדָם, וּכְנֶגְדּוֹ חָזַר דָּוִד וְאָמַר דָּחֹה דְחִיתַנִי לִנְפֹּל, מִשּׁוּם שֶׁהוּא הָיָה מִשְׁתַּדֵּל אֵלָיו בְּכָל אוֹתָן צָרוֹת לְהַסְטוֹתוֹ מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא. וְעָלָיו אָמַר דָּוִד, דָּחֹה דְחִיתַנִי לִנְפֹּל - בַּגֵּיהִנֹּם, וַה' עֲזָרָנִי - שֶׁלֹּא נִמְסַרְתִּי לְיָדְךְ. וְעַל זֶה יֵשׁ לָאָדָם לְהִזָּהֵר מִמֶּנּוּ כְּדֵי שֶׁלֹּא יִשְׁלֹט עָלָיו, וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתוֹ בְּכָל דְּרָכָיו, שֶׁכָּתוּב (משלי יג) אָז תֵּלֵךְ לָבֶטַח דַּרְכֶּךְ וְרַגְלְךְ לֹא תִגּוֹף, (שם ד) בְּלֶכְתְּךְ לֹא יֵצַר צַעֲדֶךְ וְאִם תָּרוּץ לֹא תִכָּשֵׁל, וְכָתוּב (שם) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וָאוֹר עַד נְכוֹן הַיּוֹם.</p>\n<p>אָמַר רַבִּי יְהוּדָה, אַשְׁרֵיהֶם יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (ישעיה ס) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִירְשׁוּ אָרֶץ. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011371,"<p>וַיִּשֱׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן. רַבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים לד) רַבּוֹת רָעוֹת צַדִּיק וּמִכֻּלָּם יַצִּילֶנּוּ ה' בֹּא רְאֵה כַּמָּה מְקַטְרְגִים יֵשׁ לוֹ לָאָדָם מִן הַיּוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן בּוֹ נְשָׁמָה (ד\"א לאדם) (להתקים) בָּעוֹלָם הַזֶּה, שֶׁכֵּיוָן שֶׁאָדָם יוֹצֵא לַאֲוִיר הָעוֹלָם, מִיָּד מִזְדַּמֵּן לְהִשְׁתַּתֵּף עִמּוֹ יֵצֶר הָרָע, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁכָּתוּב (בראשית ד) לַפֶּתַח חַטָּאת רֹבֵץ וְגוֹ', וְאָז מִשְׁתַּתֵּף עִמּוֹ יֵצֶר הָרָע.</p>\n<p>וּבֹא וּרְאֵה שֶׁכָּךְ הוּא, שֶׁהֲרֵי הַבְּהֵמוֹת מִיּוֹם שֶׁנּוֹלָדִים, שׁוֹמְרִים אֶת עַצְמָם וּבוֹרְחִים מִתּוֹךְ הָאֵשׁ וּמִכָּל הַמְּקוֹמוֹת הָרָעִים, וְאָדָם מִיָּד בָּא לִזְרֹק אֶת עַצְמוֹ לְתוֹךְ הָאֵשׁ, מִשּׁוּם שֶׁיֵּצֶר הָרָע שָׁרוּי בְּתוֹכוֹ, וּמִיָּד מֵסִיט אוֹתוֹ לְדֶרֶךְ רָעָה.</p>\n<p>וּבֵאַרְנוּ, שֶׁכָּתוּב (קהלת ד) טוֹב יֶלֶד מִסְכֵּן וְחָכָם מִמֶּלֶךְ זָקֵן וּכְסִיל אֲשֶׁר לֹא יָדַע לְהִזָּהֵר עוֹד. טוֹב יֶלֶד - זֶהוּ יֵצֶר הַטּוֹב, שֶׁהוּא יֵצֶר טוֹב שֶׁהוּא יֶלֶד מִיָּמִים מוּעָטִים עִם הָאָדָם, שֶׁהֲרֵי מִשְּׁלֹשָׁה עָשָׂר שָׁנִים וִאֵילָךְ (עמו), כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>מִמֶּלֶךָֹ זָקֵן וּכְסִיל. מִמֶּלֶךְ - זֶה הוּא יֵצֶר הָרָע, שֶׁהוּא נִקְרָא מֶלֶךְ וְשַׁלִּיט בָּעוֹלָם עַל בְּנֵי אָדָם. זָקֵן וּכְסִיל - שֶׁהוּא זָקֵן וַדַּאי, כְּמוֹ שֶׁבֵּאֲרוּהוּ, שֶׁכַּאֲשֶׁר אָדָם נוֹלָד וְיוֹצֵא לַאֲוִיר הָעוֹלָם, הוּא מִזְדַּמֵּן עִם הָאָדָם, וְעַל כֵּן הוּא מֶלֶךְ זָקֵן וּכְסִיל.</p>\n<p>אֲשֶׁר לֹא יָדַע לְהִזָּהֵר עוֹד, לֹא כָתוּב לְהַזְהִיר אֶלָּא לְהִזָּהֵר, מִשּׁוּם שֶׁהוּא כְּסִיל, וְעָלָיו אָמַר שְׁלֹמֹה, עָלָיו הַשָּׁלוֹם, (קהלת ב) וְהַכְּסִיל בַּחֹשֶׁךְ הוֹלֵךְ, שֶׁהֲרֵי מִפְּסֹלֶת הַחֹשֶׁךְ הוּא בָּא, וְאֵין לוֹ אוֹר לְעוֹלָמִים.</p>\n<p>רַבִּי שִׁמְעוֹן אָמַר, בּא רְאֵה, כָּתוּב טוֹב יֶלֶד מִסְכֵּן וְחָכָם, מִי זֶה יֶלֶד מִסְכֵּן? הֲרֵי בֵּאֲרוּהָ, וְנִתְבָּאֵר שֶׁהוּא יֵצֶר טוֹב. אֲבָל טוֹב יֶלֶד, זֶהוּ שֶׁכָּתוּב (תהלים לז) נַעַר הָיִיתִי גַּם זָקַנְתִּי, וְזֶה הוּא נַעַר שֶׁהוּא יֶלֶד מִסְכֵּן, שֶׁאֵין לוֹ מֵעַצְמוֹ כְּלוּם. וְלָמָּה נִקְרָא נַעַר? מִשּׁוּם שֶׁיֵּשׁ לוֹ חִדּוּשׁ הַלְּבָנָה שֶׁתָּמִיד מִתְחַדֶּשֶׁת, וְתָמִיד הוּא יֶלֶד מִסְכֵּן, כְּמוֹ שֶׁאָמַרְנוּ. וְחָכָם, מִשּׁוּם שֶׁשּׁוֹרָה בּוֹ חָכְמָה.</p>\n<p>מִמֶּלֶךָ זָקֵן - זֶהוּ יֵצֶר הָרָע, כְּמוֹ שֶׁנֶּאֱמַר, שֶׁהֲרֵי מִיּוֹם שֶׁהָיָה לֹא יָצָא מִטֻּמְאָתוֹ לְעוֹלָמִים. וְהוּא כְּסִיל, שֶׁכָּל דְּרָכָיו הֵם לְדֶרֶךְ רָעָה, וְהוֹלֵךְ וּמְסַטֶּה אֶת בְּנֵי הָאָדָם וְלֹא יוֹדֵעַ לְהִזָּהֵר, וְהוּא בָּא עִם אָדָם בַּעֲלִילוֹת כְּדֵי לְהַסְטוֹתָם מִדֶּרֶךְ טוֹבָה לְדֶרֶךְ רָעָה.</p>\n<p>בֹּא רְאֵה, עַל זֶה מַקְדִּים עִם אָדָם בַּיּוֹם שֶׁנּוֹלָד, כְּדֵי שֶׁיַּאֲמִין לוֹ, שֶׁהֲרֵי כְּשֶׁבָּא יֵצֶר הַטּוֹב, לֹא יָכוֹל הָאָדָם לְהַאֲמִין לוֹ, וְדוֹמֶה עָלָיו כְּמַעֲמָסָה. כְּמוֹ זֶה שָׁנִינוּ, מִי הוּא רָשָׁע עָרוּם? זֶהוּ מִי שֶׁמַּקְדִּים לִטְעֹן דְּבָרָיו לִפְנֵי הַדַּיָּן טֶרֶם יָבֹא חֲבֵרוֹ בַּעַל הַדִּין, כְּמוֹ שֶׁנֶּאֱמַר (משלי יח) צַדִּיק הָרִאשׁוֹן בְּרִיבוֹ וְגוֹ'.</p>\n<p>כְּמוֹ זֶה (הוא נ\"א הזה) רָשָׁע עָרוּם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ג) וְהַנָּחָשׁ הָיָה עָרוּם, וְהוּא מַקְדִּים וְשׁוֹרֶה עִמּוֹ שֶׁל אָדָם בְּטֶרֶם יָבֹא חֲבֵרוֹ לִשְׁרוֹת עָלָיו. וּמִשּׁוּם שֶׁהוּא מַקְדִּים, וְהִנֵּה טוֹעֵן טַעֲנָתוֹ עִמּוֹ - כְּשֶׁבָּא חֲבֵרוֹ, שֶׁהוּא יֵצֶר הַטּוֹב, מֵרֵעַ אֶת הָאָדָם עִמּוֹ וְלֹא יָכוֹל לִזְקֹף רֹאשׁוֹ כְּאִלּוּ הִטְעִין עַל כְּתֵפוֹ כָּל הַמַּשָּׂאוֹת שֶׁל הָעוֹלָם בִּגְלַל אוֹתוֹ רָשָׁע עָרוּם שֶׁהִקְדִּים עִמּוֹ. וְעַל זֶה אָמַר שְׁלֹמֹה (קהלת ט) וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה וּדְבָרָיו אֵינָם נִשְׁמָעִים, מִשּׁוּם שֶׁהִנֵּה הִקְדִּים אַחֵר.</p>\n<p>וְעַל כֵּן, כָּל דַּיָּן שֶׁמְּקַבֵּל מֵאָדָם דָּבָר בְּטֶרֶם יָבֹא חֲבֵרוֹ, כְּאִלּוּ קִבֵּל עָלָיו תּוֹעֵבָה אַחֶרֶת לָאֱמוּנָה, אֶלָּא (משלי שם) וּבָא רֵעֵהוּ וַחֲקָרוֹ, וְזֶה הוּא דֶּרֶךְ שֶׁל אָדָם צַדִּיק. שֶׁהֲרֵי הָאָדָם הַצַּדִּיק הַזֶּה שֶׁלֹּא הֶאֱמִין לְאוֹתוֹ רָשָׁע עָרוּם שֶׁל יֵצֶר הָרָע בְּטֶרֶם יָבֹא חֲבֵרוֹ, שֶׁהוּא יֵצֶר הַטּוֹב. וּמִשּׁוּם זֶה בְּנֵי אָדָם נִכְשָׁלִים לָעוֹלָם הַבָּא.</p>\n<p>אֲבָל אוֹתוֹ צַדִּיק שֶׁפּוֹחֵד מֵרִבּוֹנוֹ, כַּמָּה רָעוֹת סוֹבֵל בָּעוֹלָם הַזֶּה כְּדֵי שֶׁלֹּא יַאֲמִין וְלֹא יִשְׁתַּתֵּף עִם אוֹתוֹ יֵצֶר הָרָע, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מַצִּיל אוֹתוֹ מִכֻּלָּם. זֶהוּ שֶׁכָּתוּב (תהלים לד) רַבּוֹת רָעוֹת צַדִּיק וּמִכֻּלָּם יַצִּילֶנּוּ ה'. לֹא כָתוּב רַבּוֹת רָעוֹת לַצַּדִּיק, אֶלָּא צַדִּיק, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה בּוֹ, וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְרֻצֶּה מֵאוֹתוֹ הָאָדָם וּמַצִּיל אוֹתוֹ מִן הַכֹּל בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אַשְׁרֵי חֶלְקוֹ.</p>\n<p>בֹּא רְאֵה כַּמָּה רָעוֹת עָבְרוּ עָלָיו עַל יַעֲקֹב כְּדֵי שֶׁלֹּא יִתְדַּבֵּק בְּאוֹתוֹ הַיֵּצֶר הָרָע וְיִתְרַחֵק מֵחֶלְקוֹ, וּמִשּׁוּם כָּךְ סָבַל כַּמָּה עֳנָשִׁים וְכַמָּה רָעוֹת וְלֹא שָׁקַט. פָּתַח וְאָמַר, (איוב ג) לֹא שָׁלַוְתִּי וְלֹא שָׁקַטְתִּי וְלֹא נַחְתִּי וַיָּבא רֹגֶז. בּא רְאֵה כַּמָּה רָעוֹת סוֹבְלִים הַצַּדִּיקִים בָּעוֹלָם הַזֶּה, רָעוֹת עַל רָעוֹת, כְּאֵבִים עַל כְּאֵבִים, כְּדֵי לְזַכּוֹת אוֹתָם לָעוֹלָם הַבָּא.</p>\n<p>יַעָקֹב כַּמָּה רָעוֹת סָבַל, רָעוֹת עַל רָעוֹת תָּמִיד, כְּמוֹ שֶׁנֶּאֱמַר לֹא שָׁלַוְתִּי - בְּבֵית לָבָן, וְלֹא יָכֹלְתִּי לְהִנָּצֵל מִמֶּנּוּ. וְלֹא שָׁקַטְתִּי - מֵעֵשָׂו, מֵאוֹתוֹ הַצַּעַר שֶׁצִּעֵר אוֹתִי הַמְמֻנֶּה הַהוּא שֶׁלּוֹ, וְאַחַר כָּךְ הַפַּחַד שֶׁל עֵשָׂו. וְלֹא נַחְתִּי - מִן דִּינָה וּמִן שְׁכֶם.</p>\n<p>וַיָּבֹא רֹגֶז - זֶה הָרֹגֶז וְהָעִרְבּוּבְיָה שֶׁל יוֹסֵף שֶׁהוּא קָשֶׁה מִן הַכֹּל, וּמִתּוֹךְ אַהֲבָתוֹ שֶׁל יַעֲקֹב אֶל יוֹסֵף, שֶׁהוּא סוֹד הַבְּרִית, נִכְנַס לְמִצְרַיִם, כִּי אַחַר כָּךְ כָּתוּב (שמות ו) וָאֶזְכֹּר אֶת בְּרִיתִי, שֶׁתִּמָּצֵא הַשְּׁכִינָה (נ\"א: שמש) שָׁם עִמּוֹ.</p>\n<p>וַיִּשֱׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן. רַבִּי יוֹסֵי פָּתַח, (ישעיה נז) הַצַּדִּיק אָבָד וְאֵין אִישׁ שָׂם עַל לֵב וְאַנְשֵׁי חֶסֶד נֶאֱסָפִים בְּאֵין מֵבִין כִּי מִפְּנֵי הָרָעָה נֶאֱסַף הַצַּדִּיק. הַצַּדִּיק אָבָד, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ בָּעוֹלָם וְאֵין הָעוֹלָם כָּרָאוּי, וּמִזְדַּמֵּן הַדִּין לִשְׁרוֹת עַל הָעוֹלָם, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵל אֶת הַצַּדִּיק שֶׁנִּמְצָא בֵּינֵיהֶם כְּדֵי שֶׁיִּשְׁרֶה הַדִּין עַל כָּל הָאֲחֵרִים וְלֹא יִמָּצֵא מִי שֶׁיָּגֵן עֲלֵיהֶם.</p>\n<p>שֶׁהֲרֵי כָּל זְמַן שֶׁהַצַּדִּיק שׁוֹרֶה בָּעוֹלָם, הַדִּין לֹא יָכוֹל לִשְׁלֹט עַל הָעוֹלָם. מִנַּיִן לָנוּ? מִמֹּשֶׁה, שֶׁכָּתוּב (תהלים קו) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי מֹשֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו וְגוֹ'. וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵל אֶת הַצַּדִּיק מִבֵּינֵיהֶם וּמְסַלֵּק אוֹתוֹ מִן הָעוֹלָם, וְאָז נִפְרָע וְגוֹבֶה אֶת שֶׁלּוֹ. סוֹף הַפָּסוּק - כִּי מִפְּנֵי הָרָעָה נֶאֱסַף הַצַּדִּיק. בְּטֶרֶם תָּבֹא הָרָעָה לִשְׁלֹט עַל הָעוֹלָם נֶאֱסַף הַצַּדִּיק (ד\"א כי מפני הרעה נאסף, טרם תשלט הרעה בעולם). דָּבָר אַחֵר כִּי מִפְּנֵי הָרָעָה - זֶה יֵצֶר הָרָע.</p>\n<p>בֹּא רְאֵה, יַעֲקֹב הָיָה בְּחִיר הָאָבוֹת, וְהוּא עוֹמֵד לְהִתְקַיֵּם בַּגָּלוּת, אֲבָל מִתּוֹךְ שֶׁהוּא צַדִּיק, הִתְעַכֵּב הַדִּין שֶׁלֹּא יִשְׁלֹט בָּעוֹלָם, שֶׁהֲרֵי כָּל יְמֵי יַעֲקֹב לֹא שָׁרָה הַדִּין עַל הָעוֹלָם וְהָרָעָב הִתְבַּטֵּל.</p>\n<p>וְאַף כָּךְ בִּימֵי יוֹסֵף, שֶׁהוּא דְמוּת אָבִיו, (כיון שהוא מת מיד) לֹא שָׁרְתָה הַגָּלוּת (הדין על העולם), מִשּׁוּם שֶׁהוּא הֵגֵן עֲלֵיהֶם כָּל יָמָיו. כֵּיוָן שֶׁהוּא מֵת, מִיָּד שָׁרְתָה עֲלֵיהֶם הַגָּלוּת, כְּמוֹ שֶׁנֶּאֱמַר (שמות א) וַיָּמָת יוֹסֵף וְגוֹ', וְסָמוּךְ לוֹ - הָבָה נִּתְחַכְּמָה לוֹ. וְכָתוּב וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבֹדָה קָשָׁה בְּחֹמֶר וּבִלְבֵנִים וְגוֹ'.</p>\n<p>כְּמוֹ כֵן בְּכָל מָקוֹם שֶׁשָּׁרוּי צַדִּיק (על) בָּעוֹלָם, בִּשְׁבִילוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא יָגֵן עַל הָעוֹלָם, וְכָל זְמַן שֶׁהוּא קַיָּם, הַדִּין לֹא שׁוֹרֶה עַל הָעוֹלָם, וְהִנֵּה נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו, מַה זֶּה מְגוּרֵי אָבִיו? כְּמוֹ שֶׁנֶּאֱמַר (ירמיה ו) מָגוֹר מִסָּבִיב, שֶׁכָּל יָמָיו הָיָה פּוֹחֵד וְהָיָה בְּפַחַד. וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו. רַבִּי אֶלְעָזָר אָמַר, שֶׁהִתְקַשֵּׁר וְיָשַׁב בְּאוֹתוֹ מָקוֹם שֶׁנֶּאֱחַז בַּחֹשֶׁךְ. אֶרֶץ מְגוּרֵי אָבִיו דַּוְקָא, בְּאֶרֶץ כְּנָעַן, נִקְשַׁר הַמָּקוֹם לִמְקוֹמוֹ. מְגוּרֵי אָבִיו - זֶה הַדִּין הַקָּשֶׁה. בְּאֶרֶץ מְגוּרֵי אָבִיו, כְּמוֹ שֶׁנֶּאֱמַר אוֹתוֹ הַדִּין הָרָפֶה, שֶׁהִיא הָאָרֶץ שֶׁנֶּאֶחְזָה מִן הַדִּין הַקָּשֶׁה, וּבוֹ הִתְיַשֵּׁב יַעֲקֹב וְנֶאֱחַז בּוֹ (ואותה ארץ היא האספקלריה שאינה מאירה).</p>"],[9522011372,"<p>אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף וְגוֹ'. אַחַר שֶׁהִתְיַשֵּׁב יוֹסֵף עִם יַעֲקֹב וְהִזְדַּוֵּג הַשֶּׁמֶשׁ עִם הַלְּבָנָה, אָז הִתְחִיל לַעֲשׂוֹת תּוֹלָדוֹת. וּמִי הוּא שֶׁעוֹשֶׂה תוֹלָדוֹת? חָזַר וְאָמַר יוֹסֵף. שֶׁהֲרֵי אוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא הוּא עוֹשֶׂה תוֹלָדוֹת, מִשּׁוּם שֶׁאֵין מֵימָיו פּוֹסְקִים לְעוֹלָמִים, וְהוּא עוֹשֶׂה תּוֹלָדוֹת בָּאָרֶץ הַזּוֹ וּמִמֶּנּוּ יוֹצְאִים תּוֹלָדוֹת לָעוֹלָם.</p>\n<p>שֶׁהֲרֵי הַשֶּׁמֶשׁ, אַף עַל גַּב שֶׁהִתְקָרֵב לַלְּבָנָה, לֹא עוֹשֶׂה פֵּרוֹת, רַק אוֹתָהּ הַדַּרְגָּה שֶׁנִּקְרֵאת צַדִּיק, וְיוֹסֵף הוּא הַדַּרְגָּה שֶׁל יַעֲקֹב לַעֲשׂוֹת פֵּרוֹת וּלְהוֹצִיא תוֹלָדוֹת לָעוֹלָם, וּמִשּׁוּם כָּךְ כָּתוּב אֵלֶּה תֹּלְדוֹת יוֹסֵף.</p>\n<p>אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף - כָּל מִי שֶׁהָיָה מִסְתַּכֵל בִּדְמוּת יוֹסֵף, הָיָה אוֹמֵר שֶׁזּוֹ הִיא דְּמוּת יַעֲקֹב. בֹּא רְאֵה שֶׁבְּכָל בְּנֵי יַעֲקֹב לֹא כָתוּב אֵלֶּה תּוֹלְדוֹת יַעֲקֹב רְאוּבֵן, פְּרָט לְיוֹסֵף, שֶׁדְּמוּתוֹ דּוֹמָה לִדְמוּת אָבִיו.</p>\n<p>בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה - אָמַר רַבִּי אַבָּא, רָמַז לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִנֵּה כְּשֶׁנֶּאֱבַד מִמֶּנּוּ יוֹסֵף הָיָה בֶּן שְׁבַע עֶשְׂרֵה שָׁנִים, וְכָל אוֹתָם יָמִים שֶׁנִּשְׁאֲרוּ שֶׁלֹּא רָאָה אֶת יוֹסֵף, הָיָה בּוֹכֶה עַל אוֹתָם שְׁבַע עֶשְׂרֵה הַשָּׁנִים, וּכְמוֹ שֶׁהָיָה בּוֹכֶה עָלָיו - הַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ שְׁבַע עֶשְׂרֵה שָׁנִים אֲחֵרוֹת שֶׁהִתְקַיֵּם בְּאֶרֶץ מִצְרַיִם בְּשִׂמְחָה, בְּכָבוֹד וּבִשְׁלֵמוּת הַכֹּל. שֶׁבְּנוֹ יוֹסֵף הָיָה מֶלֶךְ, וְכָל בָּנָיו הָיוּ לְפָנָיו. אוֹתָן שְׁבַע עֶשְׂרֵה שָׁנִים הָיוּ חַיִּים אֶצְלוֹ, וּמִשּׁוּם כָּךְ בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה הוּא הָיָה כְּשֶׁנֶּאֱבַד מִמֶּנּוּ.</p>"],[9522011373,"<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (איוב לד) לָכֵן אַנְשֵׁי לֵבָב שִׁמְעוּ לִי חָלִלָה לָאֵל מֵרֶשַׁע וְשַׁדַּי מֵעָוֶל, כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִאֶנּוּ. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אוֹתוֹ עַל הַדִּין, וְעַל הַדִּין הִתְקַיֵּם, וְכָל הַמַּעֲשִׂים שֶׁל הָעוֹלָם הֵם עוֹמְדִים בַּדִּין חוּץ מִשֶּׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּדֵי לְקַיֵּם אֶת הָעוֹלָם שֶׁלֹּא יֹאבַד. פָּרַשׂ עָלָיו רַחֲמִים, וְאוֹתָם הָרַחֲמִים מְעַכְּבִים אֶת הַדִּין שֶׁלֹּא יְכַלֶּה אֶת הָעוֹלָם, וְעַל הָרַחֲמִים מִתְנַהֵג הָעוֹלָם וּמִתְקַיֵּם בִּשְׁבִילָם.</p>\n<p>וְאִם תֹּאמַר שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה דִין בָּאָדָם בְּלִי דִין, הֲרֵי נֶאֱמַר, שֶׁכַּאֲשֶׁר הַדִּין שׁוֹרֶה עַל הָאָדָם כְּשֶׁהוּא צַדִּיק, מִשּׁוּם אַהֲבָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא אֵלָיו הִיא, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מְרַחֵם עָלָיו בְּאַהֲבָה לְקָרֵב אוֹתוֹ אֵלָיו, מְשַׁבֵּר אֶת הַגּוּף כְּדֵי לְהַשְׁלִיט אֶת הַנְּשָׁמָה, וְאָז מִתְקָרֵב הָאָדָם אֵלָיו בְּאַהֲבָה כָּרָאוּי, וְהַנְּשָׁמָה שׁוֹלֶטֶת וְהַגּוּף נֶחֱלָשׁ.</p>\n<p>וְצָרִיךְ גּוּף חַלָּשׁ וְנֶפֶשׁ חֲזָקָה שֶׁמִּתְגַּבֶּרֶת בְּחֹזֶק, וְאָז הוּא אָהוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁאָמְרוּ הַחֲבֵרִים, נוֹתֵן הַקָּדוֹשׁ בָּרוּךְ הוּא לַצַּדִּיק צַעַר בָּעוֹלָם הַזֶּה כְּדֵי לְזַכּוֹת אוֹתוֹ לָעוֹלָם הַבָּא.</p>\n<p>וְכַאֲשֶׁר הַנְּשָׁמָה חַלָּשָׁה וְגוּף חָזָק, הוּא שׂוֹנְאוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁאֵינוֹ מְרֻצֶּה בּוֹ, לֹא נוֹתֵן לוֹ צַעַר בָּעוֹלָם הַזֶּה, אֶלָּא דְּרָכָיו מְתֻקָּנוֹת וְהוּא בִּשְׁלֵמוּת יְתֵרָה, מִשּׁוּם שֶׁאִם עוֹשֶׂה צְדָקָה אוֹ חֶסֶד, הַקָּדוֹשׁ בָּרוּךְ הוּא מְשַׁלֵּם לוֹ אֶת שְׂכָרוֹ בָּעוֹלָם הַזֶּה, וְלֹא יִהְיֶה לוֹ חֵלֶק בָּעוֹלָם הַהוּא. וְזֶהוּ שֶׁתִּרְגֵּם אוּנְקְלוּס (דברים ז) וּמְשַׁלֵּם לְשׂוֹנְאָיו וְגוֹ' - מְשַׁלֵּם לְשׂוֹנְאָיו טוֹבוֹת שֶׁהֵם עוֹשִׂים (הוא), וּמִשּׁוּם כָּךְ אוֹתוֹ צַדִּיק שֶׁנִּשְׁבָּר תָּמִיד הוּא אָהוּב שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וְהַדְּבָרִים הַלָּלוּ כְּשֶׁבָּדַק, וְלֹא מָצָא חֵטְא בְּיָדוֹ שֶׁנֶּעֱנַשׁ עָלָיו.</p>\n<p>כָּאן יֵשׁ לְהִסְתַּכֵּל בְּכַמָּה צְדָדִים, אֶחָד - שֶׁהִנֵּה רָאִינוּ שֶׁאֵין הַשְּׁכִינָה שׁוֹרָה בְּמָקוֹם עָצוּב, אֶלָּא בְּמָקוֹם שֶׁיֵּשׁ בּוֹ שִׂמְחָה. אִם אֵין בּוֹ שִׂמְחָה, אֵין שְׁכִינָה שׁוֹרָה בְּאוֹתוֹ מָקוֹם, כְּמוֹ שֶׁנֶּאֱמַר (מלכים ב ג) וְעַתָּה קְחוּ לִי מְנַגֵּן וְהָיָה כְּנַגֵּן הַמְנַגֵּן וַתְּהִי עָלָיו יַד ה'. שֶׁהֲרֵי וַדַּאי שֶׁשְּׁכִינָה לֹא שׁוֹרָה בְּמָקוֹם עָצוּב. מִנַּיִן לָנוּ? מִיַּעֲקֹב, שֶׁמִּשּׁוּם שֶׁהָיָה עָצוּב עַל יוֹסֵף הִסְתַּלְּקָה מִמֶּנּוּ שְׁכִינָה. כֵּיוָן שֶׁבָּאָה לוֹ הַשִּׂמְחָה עַל בְּשׂוֹרַת יוֹסֵף, מִיָּד וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. כָּאן בַּצַּדִּיק הַזֶּה שֶׁנִּשְׁבָּר, כֵּיוָן שֶׁהוּא חַלָּשׁ וְנִשְׁבָּר בְּמַכְאוֹבִים, אֵיפֹה הַשִּׂמְחָה? שֶׁהֲרֵי הוּא בְּעֶצֶב וְאֵין עִמּוֹ כְּלָל שִׂמְחָה.</p>\n<p>וְאֶחָד - שֶׁהִנֵּה רָאִינוּ כַּמָּה אֲהוּבִים הָיוּ צַדִּיקִים לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא נִשְׁבְּרוּ בָּחֳלָאִים וְלֹא בְּמַכְאוֹבִים, וְלֹא נֶחֱלַשׁ גּוּפָם לְעוֹלָמִים, לָמָּה לֹא אֵלֶּה כְּאֵלֶּה - שֶׁאֵלֶּה נִשְׁבְּרוּ, וְאֵלֶּה עוֹמְדִים בְּגוּפָם כָּרָאוּי?</p>\n<p>וְאִם תֹּאמַר שֶׁהִנֵּה אֵלֶּה שֶׁעָמְדוּ בְּקִיּוּם כָּרָאוּי מִשּׁוּם שֶׁהֵם צַדִּיקִים בְּנֵי צַדִּיקִים הֵם, כְּמוֹ שֶׁבֵּאֲרוּהוּ, וְאֵלּוּ הָאֲחֵרִים צַדִּיקִים וְלֹא בְּנֵי צַדִּיקִים - הִנֵּה רָאִינוּ צַדִּיקִים בְּנֵי צַדִּיקִים, שֶׁהִנֵּה אָבִיו שֶׁל זֶה צַדִּיק בֶּן צַדִּיק, וְהוּא צַדִּיק, לָמָּה נִשְׁבָּר גּוּפוֹ בְּמַכְאוֹבִים וְכָל יָמָיו בְּצַעַר?</p>\n<p>אֶלָּא כָּאן הוּא סוֹד, שֶׁהִנֵּה כָּל מַעֲשֵׂי הַקָּדוֹשׁ בָּרוּךְ הוּא בֶּאֱמֶת וָצֶדֶק, (איוב לד) כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִאֶנּוּ. מָצָאנוּ בְּסִפְרֵי הָרִאשׁוֹנִים סוֹד אֶחָד, וְאֶצְלוֹ סוֹד אַחֵר אֶחָד שֶׁהוּא שְׁנַיִם, שֶׁהֲרֵי יֵשׁ לִפְעָמִים שֶׁהַלְּבָנָה בְּחִסָּרוֹן וְשׁוֹרָה בְדִין וְאֵין הַשֶּׁמֶשׁ נִמְצָא אֶצְלָהּ, וּבְכָל זְמַן וּבְכָל שָׁעָה יֵשׁ לָהּ לְהוֹצִיא נְשָׁמוֹת לִבְנֵי אָדָם כְּמוֹ שֶׁלָּקְטָה בָּרִאשׁוֹנָה, וּמוֹצִיאָה אוֹתָם כָּעֵת בִּזְמַן שֶׁהִיא עוֹמֶדֶת בְּדִין, וּמִי שֶׁלּוֹקֵחַ אוֹתָהּ בְּאוֹתוֹ זְמַן, יִהְיֶה תָמִיד בְּחִסָּרוֹן וְהָעֹנִי הוֹלֵךְ אֵלָיו, וְנִשְׁבָּר תָּמִיד בְּדִין כָּל יְמֵי הָאָדָם, בֵּין חַיָּב בֵּין זַכַּאי, רַק שֶׁתְּפִלָּה מְבַטֶּלֶת אֶת כָּל גִּזְרֵי הַדִּינִים וְיָכוֹל לְסַלְּקָם בִּתְפִלָּה.</p>\n<p>וְאוֹתוֹ הַזְּמַן שֶׁאוֹתָהּ הַדַּרְגָּה עוֹמֶדֶת בִּשְׁלֵמוּת, וְאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא מִשְׁתַּמֵּשׁ בָּהּ, אָז אוֹתָהּ הַנְּשָׁמָה שֶׁיָּצְאָה וְנִדְבְּקָה בּוֹ בְּאוֹתוֹ הָאָדָם, אוֹתוֹ הָאָדָם מֻשְׁלָם בַּכֹּל - בְּעֹשֶׁר, בְּבָנִים וּבִשְׁלֵמוּת הַגּוּף.</p>\n<p>וְהַכּל מִשּׁוּם אוֹתוֹ הַמַּזָּל שֶׁשּׁוֹפֵעַ וְיוֹצֵא וּמִתְחַבֵּר בְּאוֹתָהּ הַדַּרְגָּה לְהִשְׁתַּלֵּם בּוֹ וּלְהִתְבָּרֵךְ מִמֶּנּוּ, וְעַל כֵּן הַכֹּל בְּמַזָּל הַדָּבָר תָּלוּי. וְעַל כֵּן שָׁנִינוּ, בָּנִים, חַיִּים וּמְזוֹנוֹת - לֹא בִזְכוּת תְּלוּיִים, אֶלָּא בְּמַזָּל הַדָּבָר תָּלוּי, שֶׁהֲרֵי בִּזְכוּת אֵינוֹ אֶלָּא עַד שֶׁמִּתְמַלֵּאת וּמְאִירָה מִן הַמַּזָּל.</p>\n<p>וּמִשּׁוּם כָּךְ, כָּל אוֹתָם שֶׁנִּשְׁבְּרוּ בָּעוֹלָם הַזֶּה, וְהֵם צַדִּיקֵי אֱמֶת, כֻּלָּם נִשְׁבָּרִים בָּעוֹלָם הַזֶּה וְנִדּוֹנִים בְּדִין. מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתָהּ הַנֶּפֶשׁ גָּרְמָה לָהֶם, וְעַל כֵּן חָס עֲלֵיהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא לָעוֹלָם הַבָּא.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, כָּל מַה שֶּׁעוֹשֶׂה הַקָּדוֹשׁ בָּרוּךְ הוּא הוּא בְּדִין, כְּדֵי לְטַהֵר אוֹתָהּ הַנֶּפֶשׁ לְהָבִיא אוֹתָהּ לָעוֹלָם הַבָּא (ומשום כך כל מעשיו של הקדוש ברוך הוא) (נ\"א: משום שכל מעשי הקדוש ברוך הוא) הֵם בְּדִין וֶאֱמֶת, וּכְדֵי לְהַעֲבִיר מִמֶּנּוּ אוֹתָהּ זֻהֲמָה שֶׁקִּבְּלָה בָּעוֹלָם הַזֶּה, וְעַל כֵּן נִשְׁבָּר אוֹתוֹ הַגּוּף וְנִטְהֶרֶת הַנֶּפֶשׁ, וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה לְאוֹתוֹ הַצַּדִּיק שֶׁיִּסְבֹּל יִסּוּרִים וּמַכְאוֹבִים בָּעוֹלָם הַזֶּה וְיִתְנַקֶּה מִן הַכֹּל וְיִזְכֶּה לְחַיֵּי עוֹלָם, וְעַל כֵּן כָּתוּב (תהלים יא) ה' צַדִּיק יִבְחָן, וַדַּאי, וְהִנֵּה נִתְבָּאֵר.</p>"],[9522011374,"<p>רַבִּי שִׁמְעוֹן פָּתַח, (ויקרא כא) אַךְ אֶל הַפָּרֹכֶת לֹא יָבֹא וְאֶל הַמִּזְבֵּחַ לֹא יִגָּשׁ כִּי מוּם בּוֹ וְלֹא יְחַלֵּל אֶת מִקְדָּשַׁי כִּי אֲנִי ה' מְקַדְּשׁוֹ. אַךְ אֶל הַפָּרֹכֶת לֹא יָבא - בֹּא רְאֵה, בְּאוֹתָהּ שָׁעָה שֶׁאוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, מוֹצִיא כָּל אוֹתָן הַנְּשָׁמוֹת וְהַנְּקֵבָה מִתְעַבֶּרֶת, כֻּלָּם עוֹמְדִים בִּפְנִים בְּחָצֵר לִפְנִים מֵחָצֵר מְצֻפֶּה שְׁטִיחִים.</p>\n<p>וּכְשֶׁהַלְּבָנָה נִפְגֶּמֶת בְּאוֹתוֹ צַד שֶׁל הַנָּחָשׁ הָרָע, אָז כָּל אוֹתָן נְשָׁמוֹת שֶׁיּוֹצְאוֹת, אַף עַל גַּב שֶׁכֻּלָּן טְהוֹרוֹת וְכֻלָּן קְדוֹשׁוֹת - הוֹאִיל וְנָפְלוּ בַּפְּגָם, בְּכָל אוֹתָם מְקוֹמוֹת שֶׁהִגִּיעוּ אוֹתָן הַנְּשָׁמוֹת, כֻּלָּם נִשְׁבְּרוּ וְנִפְגְּמוּ בְּכַמָּה צַעַר וְכַמָּה כְאֵבִים, וְאֵלּוּ הֵם (נשמות ומקומות) (נ\"א: נשמות של מקומות של פגם) שֶׁמִּתְרַצֶּה בָהֶם הַקָּדוֹשׁ בָּרוּךְ הוּא אַחַר שֶׁנִּשְׁבְּרוּ, וְאַף עַל גַּב שֶׁהַנְּשָׁמוֹת בְּעֵצֶב וְלֹא בִשְׁמָחוֹת.</p>\n<p>סוֹד הַדָּבָר שׁוֹרִים כְּמוֹ שֶׁלְּמַעְלָה, הַגּוּף נִפְגָּם, וְהַנְּשָׁמָה בִּפְנִים כְּמוֹ שֶׁלְּמַעְלָה, וְזֶה כְּמוֹ זֶה. וּמִשּׁוּם כָּךְ אֵלּוּ הֵם שֶׁצְּרִיכוֹת לְהִתְחַדֵּשׁ בְּהִתְחַדְּשׁוּת הַלְּבָנָה, וְעַל אֵלּוּ כָּתוּב (ישעיה סו) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבֹא כָל בָּשָׂר לְהִשְׁתַּחֲות לְפָנַי אָמַר ה'. כָּל בָּשָׂר וַדַּאי, שֶׁאֵלּוּ יִתְחַדְּשׁוּ בַּכֹּל. וּצְרִיכִים לְהִתְחַדֵּשׁ בְּהִתְחַדְּשׁוּת הַלְּבָנָה.</p>\n<p>וְאֵלּוּ הֵם בְּשֻׁתָּפוּת אַחַת עִם הַלְּבָנָה פְּגוּמִים בְּאוֹתוֹ הַפְּגָם שֶׁלָּהּ, וּמִשּׁוּם כָּךְ הִיא תָמִיד שׁוֹרָה בְתוֹכָם, שֶׁאֵינָהּ עוֹזֶבֶת אוֹתָם, כְּמוֹ שֶׁנֶּאֱמַר (שם נז) וְאֶת דַּכָּא וּשְׁפַל רוּחַ, וְכָתוּב (תהלים לד) קָרוֹב ה' לְנִשְׁבְּרֵי לֵב. לְאוֹתָם שֶׁסּוֹבְלִים עִם הַלְּבָנָה, אוֹתוֹ הַפְּגָם הֵם קְרוֹבִים לָהּ תָּמִיד. וְעַל זֶה לְהַחֲיוֹת לֵב נִדְכָּאִים, בְּאוֹתָם הַחַיִּים שֶׁבָּאִים לָהּ לְהִתְחַדֵּשׁ יִהְיֶה לָהֶם חֶלְקָם, אוֹתָם שֶׁסּוֹבְלִים עִמָּהּ יִתְחַדְּשׁוּ עִמָּהּ.</p>\n<p>וְאֵלּוּ נִקְרָאִים יִסּוּרִים שֶׁל אַהֲבָה. שֶׁל אַהֲבָה הֵם, וְלֹא מֵאוֹתוֹ הָאָדָם. שֶׁל אַהֲבָה, אוֹתָם שֶׁנִּפְגָּם הָאוֹר שֶׁל הָאַהֲבָה הַקְּטַנָּה שֶׁנִּדְחֵית מֵאַהֲבָה רַבָּה. מִשּׁוּם כָּךְ אֵלֶּה הֵם חֲבֵרִים מְשֻׁתָּפִים עִמָּהּ. אַשְׁרֵי חֶלְקָם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁהֵם זָכוּ לָזֶה לִהְיוֹת חֲבֵרִים עִמָּהּ, עֲלֵיהֶם כָּתוּב (שם קכב) לְמַעַן אַחַי וְרֵעַי וְגוֹ'.</p>"],[9522011375,"<p>פָּתַח וְאָמַר, (ישעיה נב) הִנֵּה יַשְׂכִּיל עַבְדִּי יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא גִּלָּה לָהֶם דַּרְכֵי הַתּוֹרָה לָלֶכֶת בָּהֶם. בֹּא רְאֵה, הַפָּסוּק הַזֶּה הוּא סוֹד עֶלְיוֹן, הִנֵּה יַשְׂכִּיל עַבְדִּי וּבֵאֲרוּהָ. אֲבָל בֹּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אֶת הַלְּבָנָה וְהִקְטִין לָהּ אֶת אוֹרָהּ, שֶׁהֲרֵי אֵין לָהּ מֵעַצְמָהּ כְּלוּם. וּמִשּׁוּם שֶׁהִקְטִינָה אֶת עַצְמָהּ, הֵאִירָה בִּגְלַל הַשֶּׁמֶשׁ וּבְחֹזֶק הָאוֹרוֹת הָעֶלְיוֹנִים.</p>\n<p>וּבִזְמַן שֶׁהָיָה בֵּית הַמִּקְדָּשׁ קַיָּם, יִשְׂרָאֵל הָיוּ מִשְׁתַּדְּלִים בְּקָרְבָּנוֹת וְעוֹלוֹת וַעֲבוֹדוֹת שֶׁהָיוּ עוֹשִׂים הַכֹּהֲנִים וּלְוִיִּם וְיִשְׂרְאֵלִים כְּדֵי לִקְשֹׁר קְשָׁרִים וּלְהָאִיר אוֹרוֹת.</p>\n<p>וּלְאַחַר שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ, נֶחְשַׁךְ הָאוֹר, וְהַלְּבָנָה לֹא הוּאֲרָה מִן הַשֶּׁמֶשׁ, וְהַשֶּׁמֶשׁ הִסְתַּלֵּק מִמֶּנָּה וְלֹא הֵאִירָה, וְאֵין לְךְ יוֹם שֶׁלֹּא שׁוֹלְטִים בּוֹ קְלָלוֹת וְצַעַר וּכְאֵבִים, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וּבְאוֹתוֹ זְמַן שֶׁהִגִּיעַ זְמַן הַלְּבָנָה לְהָאִיר, מַה כָּתוּב? הִנֵּה יַשְׂכִּיל עַבְדִּי. נֶאֱמַר עַל הַלְּבָנָה הִנֵּה יַשְׂכִּיל עַבְדִּי, זֶהוּ סוֹד הָאֱמוּנָה. הִנֵּה יַשְׂכִּיל - שֶׁמִּתְעוֹרֶרֶת הִתְעוֹרְרוּת שֶׁלְּמַעְלָה, כְּמִי שֶׁהֵרִיחַ רֵיחַ וּבָא לְהִתְעוֹרֵר וּלְהִסְתַּכֵּל. יָרוּם - מִצַּד הָאוֹר הָעֶלְיוֹן שֶׁל כָּל הָאוֹרוֹת.</p>\n<p>יָרוּם - כְּמוֹ שֶׁנֶּאֱמַר (ישעיה ל) וְלָכֵן יָרוּם לְרַחֶמְכֶם. וְנִשָּׂא - מֵהַצַּד שֶׁל אַבְרָהָם. וְגָבַהּ - מֵהַצַּד שֶׁל יִצְחָק. מְאֹד - מִצִּדּוֹ שֶׁל יַעֲקֹב. וְאַף עַל גַּב שֶׁבֵּאֲרוּהוּ, וְהַכֹּל אֶחָד בַּסּוֹד שֶׁל הַחָכְמָה.</p>\n<p>וּבְאוֹתוֹ זְמַן יְעוֹרֵר הַקָּדוֹשׁ בָּרוּךְ הוּא הִתְעוֹרְרוּת עֶלְיוֹנָה לְהָאִיר לַלְּבָנָה כָּרָאוּי, כְּמוֹ שֶׁנֶּאֱמַר (שם) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים. וּמִשּׁוּם כָּךְ תִּתּוֹסֵף לָהּ רוּחַ עֶלְיוֹנָה, וּמִשּׁוּם כָּךְ יִתְעוֹרְרוּ אָז כָּל אוֹתָם הַמֵּתִים שֶׁהֵם בְּתוֹךְ הֶעָפָר.</p>\n<p>וְזֶהוּ עַבְדִּי, הַסּוֹד שֶׁמַּפְתְּחוֹת רִבּוֹנוֹ בְּיָדוֹ, כְּמוֹ שֶׁנֶּאֱמַר (אל עבדו זקן ביתו, וכמו שנאמר) (בראשית כד) וַיֹּאמֶר אַבְרָהָם אֶל עַבְדּוֹ. זוֹ הַלְּבָנָה כְּמוֹ שֶׁנֶּאֱמַר, מטטרו\"ן שֶׁהוּא עֶבֶד שְׁלִיחַ רִבּוֹנוֹ.</p>\n<p>זְקַן בֵּיתוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים לז) נַעַר הָיִיתִי גַּם זָקַנְתִּי. הַמֹּשֵׁל בְּכָל אֲשֶׁר לוֹ, מִשּׁוּם שֶׁכָּל הַגְּוָנִים נִרְאִים בּוֹ יָרֹ\"ק וְלָבָ\"ן וְאָדֹ\"ם.</p>\n<p>שִׂים נָא יָדְךְ תַּחַת יְרֵכִי - זֶהוּ הַצַּדִּיק, סוֹד הַדָּבָר קִיּוּם הָעוֹלָם, שֶׁהֲרֵי אָז הָעֶבֶד הַזֶּה מְמֻנֶּה בְּסוֹד עֶלְיוֹן לְהַחֲיוֹת אֶת שׁוֹכְנֵי הֶעָפָר, וְיֵעָשֶׂה שָׁלִיחַ בְּרוּחַ שֶׁל מַעְלָה לְהָשִׁיב הָרוּחוֹת וְהַנְּשָׁמוֹת לִמְקוֹמָן לְאוֹתָם גּוּפִים (שנאכלו) שֶׁהִתְבַּלּוּ וְנִרְקְבוּ תַּחַת הֶעָפָר.</p>\n<p>וְאַשְׁבִּיעָךָ בַּה' אֱלֹהֵי הַשָּׁמַיִם. וְאַשְׁבִּיעֲךְ - מַה זֶה וְאַשְׁבִּיעֲךְ? לְהִתְלַבֵּשׁ בְּסוֹד שֶׁל שִׁבְעָה אוֹרוֹת עֶלְיוֹנִים, שֶׁהֵם סוֹד הַשְּׁלֵמוּת הָעֶלְיוֹנָה. אֲשֶׁר לֹא תִקַּח אִשָּׁה - זֶהוּ הַגּוּף שֶׁתַּחַת הֶעָפָר שֶׁיֵּשׁ לוֹ קִיּוּם לְהָקִים מֵהֶעָפָר, שֶׁכּל אוֹתָם שֶׁנִּקְבְּרוּ בָהּ וְזָכוּ לְהִקָּבֵר בְּאֶרֶץ יִשְׂרָאֵל, הֵם יִתְעוֹרְרוּ בָּרִאשׁוֹנָה, כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (ישעיה כו) יִחְיוּ מֵתֶיךְ, בָּרִאשׁוֹנָה - אֵלּוּ הַמֵּתִים שֶׁל אֶרֶץ יִשְׂרָאֵל. נְבֵלָתִי יְקוּמוּן - אוֹתָם הַמֵּתִים שֶׁל שְׁאָר הָאֲרָצוֹת. וְעַל זֶה לְאוֹתָם גּוּפִים שֶׁל יִשְׂרָאֵל שֶׁנִּקְבְּרוּ שָׁם, וְלֹא לְגוּפוֹת שְׁאָר הָעַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁהָאָרֶץ נִטְמְאָה מֵהֶם.</p>\n<p>וְעַל כֵּן, אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי. מַה זֶּה לִבְנִי? שֶׁכָּל נִשְׁמוֹת הָעוֹלָם שֶׁיּוֹצְאוֹת מֵאוֹתוֹ נָהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, הֵם בָּנִים לַקָּדוֹשׁ- בָּרוּךְ-הוּא. וְעַל זֶה אֲשֶׁר לֹא תִקַּח אִשָּׁה - זֶה הַגּוּף. לִבְנִי - זוֹ הַנְּשָׁמָה. מִבְּנוֹת הַכְּנַעֲנִי - אֵלּוּ גוּפוֹת שֶׁל עַמִּים עוֹבְדֵי עֲבוֹדָה זָרָה שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְנַעֵר אוֹתָם מֵהָאָרֶץ הַקְּדוֹשָׁה, כְּמוֹ שֶׁנֶּאֱמַר (איוב לח) וְיִנָּעֲרוּ רְשָׁעִים מִמֶּנָּה, כְּמִי שֶׁמְּנַעֵר טַלִּית מְהַזֻּהֲמָה שֶׁלָּה.</p>\n<p>כִּי אֶל אַרְצִי וְאֶל מוֹלַדְתִּי תֵּלֵךְ. אַרְצִי - זוֹ הָאָרֶץ הַקְּדוֹשָׁה שֶׁהִיא רִאשׁוֹנָה לְכָל שְׁאָר הָאֲרָצוֹת, כְּמוֹ שֶׁנִּתְבָּאֵר. (ועל זה כי אל ארצי, זו הארץ הקדושה, שהיא שלו בין כל שאר הארצות שחלק אותם לממנים אחרים), וְעַל זֶה כִּי אֶל אַרְצִי וְאֶל מוֹלַדְתִּי. כֵּיוָן שֶׁאָמַר אֶל אַרְצִי, מַה זֶּה וְאֶל מוֹלַדְתִּי? אֶלָּא אֶל אַרְצִי, כְּמוֹ שֶׁנֶּאֱמַר. (מה זה) וְאֶל מוֹלַדְתִּי? אֵלּוּ הֵם יִשְׂרָאֵל</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, וַיִּקַּח הָעֶבֶד - כְּמוֹ שֶׁנִּתְבָּאֵר. עֲשָׂרָה גְמַלִּים - אֵלּוּ הֵם עֶשֶׂר דְּרָגוֹת שֶׁהָעֶבֶד הַזֶּה שׁוֹלֵט עֲלֵיהֶם כְּמוֹ שֶׁלְּמַעְלָה. מִגְּמַלֵּי אֲדנָיו - שֶׁהֵם בְּאוֹתוֹ גָוֶן מַמָּשׁ, כְּמוֹ שֶׁנִּתְבָּאֵר, וְהָעֶבֶד הַזֶּה שׁוֹלֵט וְנִתְקָן בָּהֶם.</p>\n<p>וְכָל טוּב אֲדנָיו בְּיָדוֹ - כָּל אוֹתוֹ טוּב הָרֵיחוֹת הָעֶלְיוֹנִים שֶׁיּוֹצְאִים מִתּוֹךְ אוֹתָם אוֹרוֹת וּמְאוֹרוֹת עֶלְיוֹנִים. וְכָל טוֹב אֲדנָיו - אוֹתוֹ הַשִּׁמּוּשׁ שֶׁל הַשֶּׁמֶשׁ שֶׁנִּמְשְׁכָה בָּהּ בַּלְּבָנָה.</p>\n<p>וַיָּקָם וַיֵּלֶךְ אֶל אֲרַם נַהֲרַיִם - זֶהוּ הַמָּקוֹם שֶׁל הָאָרֶץ הַקְּדוֹשָׁה שֶׁשָּׁם בָּכְתָה רָחֵל כְּשֶׁחָרַב בֵּית הַמִּקְדָּשׁ. וַיַּבְרֵךְ הַגְּמַלִּים מִחוּץ לָעִיר אֶל בְּאֵר הַמָּיִם - לְהִתְחַזֵּק כֹּחָהּ בְּחָזְקָהּ כָּרָאוּי טֶרֶם תִּכָּנֵס לְהָקִים אֶת אוֹתָם הַגּוּפִים.</p>\n<p>לְעֵת עֶרֶב, מַה זֶּה לְעֵת עֶרֶב? זֶה עֶרֶב שַׁבָּת שֶׁהוּא הַזְּמַן שֶׁל הָאֶלֶף הַשִּׁשִּׁי. לְעֵת עֶרֶב - כְּמוֹ שֶׁנֶּאֱמַר (תהלים קד) וְלַעֲבוֹדָתוֹ עֲדֵי עָרֶב, וְכָתוּב (ירמיה ו) כִּי יִנָּטוּ צִלֲלֵי עָרֶב.</p>\n<p>לְעֵת צֵאת הַשּּׁאֲבֹת - שֶׁבְּאוֹתוֹ זְמַן עֲתִידִים לָקוּם וּלְהֵחָיוֹת. בָּרִאשׁוֹנָה מִכָּל שְׁאָר בְּנֵי הָעוֹלָם אוֹתָם שֶׁשּׁוֹאֲבִים מֵימֵי הַתּוֹרָה (ושואבים), כְּדֵי שֶׁיִּתְעַסְּקוּ לִשְׁאֹב מֵימֵי הַתּוֹרָה, וְהִתְחַזְּקוּ בְּעֵץ הַחַיִּים, וְהֵם יָצְאוּ בָרִאשׁוֹנָה, שֶׁעֵץ הַחַיִּים גָּרַם לָהֶם שֶׁיָּקוּמוּ בָּרִאשׁוֹנָה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>וּבְנוֹת אַנְשֵׁי הָעִיר יצְאֹת, מַה זֶּה יֹצְאֹת? כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כו) וָאָרֶץ רְפָאִים תַּפִּיל, שֶׁעֲתִידָה הָאָרֶץ לִפְלֹט מִמֶּנָּה כָּל הַגּוּפוֹת שֶׁהֵם בְּתוֹכָהּ, וְעַל כָּךְ כָּתוּב יצְאֹת. לִשְׁאֹב מָיִם - לִטֹּל נְשָׁמָה וּלְקַבְּלָהּ כָּרָאוּי מְתֻקֶּנֶת מִמְּקוֹמָהּ כָּרָאוּי.</p>\n<p>וְהָיָה הַנַּעֲרָה אֲשֶׁר אֹמַר אֵלֶיהָ הַטִּי נָא כַדֵּךְ וְאֶשְׁתֶּה, מִשּׁוּם שֶׁהֲרֵי נִתְבָּאֵר, שֶׁכָּל אוֹתָן נְשָׁמוֹת שֶׁל הָעוֹלָם שֶׁהִתְקַיְּמוּ בָּעוֹלָם הַזֶּה וְהִשְׁתַּדְּלוּ לָדַעַת אֶת רִבּוֹנָם בְּסוֹד הַחָכְמָה הָעֶלְיוֹנָה, הִיא עוֹלָה וּמִתְקַיֶּמֶת בְּדַרְגָּה עֶלְיוֹנָה עַל כָּל אוֹתָם שֶׁלֹּא נִדְבְּקוּ וְלֹא יָדְעוּ, וְהֵם מִתְקַיְּמִים בָּרִאשׁוֹנָה. וְזוֹ הַשְּׁאֵלָה שֶׁעָמַד אוֹתוֹ הָעֶבֶד לָדַעַת וְלִשְׁאֹל, בַּמָּה הִתְעַסְּקָה אוֹתָהּ הַנְּשָׁמָה בָּעוֹלָם הַזֶּה.</p>\n<p>וְאָמְרָה אֵלַי גַּם אַתָּה שְׁתֵה, אַתָּה צָרִיךְ לִשְׁתּוֹת וְלִהְיוֹת מֻשְׁקֶה בָּרִאשׁוֹנָה, וְאַחֲרֶיךְ - וְגַם (ל) גְמַלֶּיךְ אַשְׁקֶה, מִשּׁוּם שֶׁכָּל אוֹתָם שְׁאָר הַמֶּרְכָּבוֹת, אַף עַל גַּב שֶׁנִּשְׁקִים מֵהַדַּרְגָּה הַזּוֹ, כֻּלָּם נִשְׁקִים מֵעֲבוֹדַת הַצַּדִּיקִים שֶׁיּוֹדְעִים עֲבוֹדַת רִבּוֹנָם כָּרָאוּי, שֶׁהַצַּדִּיקִים יוֹדְעִים לְסַפֵּק לְכָל דַּרְגָּה וְדַרְגָּה כָּרָאוּי. וְעַל זֶה וְגַם (ל) גְמַלֶּיךְ אַשְׁקֶה. וַדַּאי הִיא הָאִשָּׁה אֲשֶׁר הֹכִיחַ ה' לְבֶן אֲדנִי. וַדַּאי הַהִיא (ס\"א בהתעוררות של התפלה שלי) הוּא הַגּוּף שֶׁהִזְדַּמֵּן לְאוֹתָהּ הַנְּשָׁמָה הָעֶלְיוֹנָה.</p>\n<p>בֹּא רְאֵה, שֶׁהִנֵּה נִתְבָּאֵר שֶׁתְּשׁוּקַת הַזָּכָר לַנְּקֵבָה עוֹשָׂה נְשָׁמָה, וּתְשׁוּקַת הַנְּקֵבָה לַזָּכָר עוֹלֶה וּמִתְעָרֵב עִמָּהּ שֶׁלְּמַעְלָה, וְנִכְלָלִים זֶה עִם זֶה וְעוֹשֶׂה נְשָׁמָה. וּמִשּׁוּם כָּךְ, הִיא הָאִשָּׁה - זֶהוּ הַגּוּף וַדַּאי, שֶׁהוּא זָמִין לְאוֹתוֹ רָצוֹן שֶׁל הַנְּשָׁמָה שֶׁיָּצְאָה מִן הַזָּכָר.</p>\n<p>וְאוֹתָם הַגּוּפִים עֲתִידִים לְהִתְעוֹרֵר בָּרִאשׁוֹנָה, כְּמוֹ שֶׁאָמַרְנוּ. וּלְאַחַר שֶׁאֵלּוּ יָקוּמוּ, יָקוּמוּ כָּל הָאֲחֵרִים שֶׁבִּשְׁאָר הָאֲרָצוֹת וְיִתְקַיְּמוּ בְּקִיּוּם שָׁלֵם, וְיִתְחַדְּשׁוּ בְּהִתְחַדְּשׁוּת הַלְּבָנָה, וְיִתְחַדֵּשׁ הָעוֹלָם כְּמוֹ מִקֹּדֶם, וְאָז כָּתוּב בְּאוֹתוֹ הַזְּמַן (תהלים קד) יִשְׂמַח ה' בְּמַעֲשָׂיו.</p>\n<p>וּמִשּׁוּם כָּךְ, הִנֵּה יַשְׂכִּיל עַבְדִּי - לְהַחֲזִיר הַנְּשָׁמוֹת כָּל אַחַת וְאַחַת לִמְקוֹמָהּ. יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד - מֵהַצַּד שֶׁל כָּל אוֹתָן הַדְּרָגוֹת הָעֶלְיוֹנוֹת, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>(ישעיה נב) כַּאֲשֶׁר שָׁמְמוּ עָלֶיךְ רַבִּים כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ וְתֹאֲרוֹ מִבְּנֵי אָדָם, בּא רְאֵה, שֶׁהִנֵּה נֶאֱמַר שֶׁכַּאֲשֶׁר נֶחֱרַב בֵּית הַמִּקְדָּשׁ וְהַשְּׁכִינָה גָּלְתָה לְתוֹךְ אֲרָצוֹת נָכְרִיּוֹת בֵּינֵיהֶם, מַה כָּתוּב? (שם לג) הֵן אֶרְאֶלָּם צָעֲקוּ חֻצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן, כֻּלָּם בָּכוּ עַל זֶה וְקָשְׁרוּ בְּכִיָּה וְאֵבֶל, וְכָל זֶה עַל הַשְּׁכִינָה שֶׁגָּלְתָה מִמְּקוֹמָהּ. וְכַמָּה שֶׁהִיא מִשְׁתַּנֵּית מִכְּמוֹ שֶׁהָיְתָה, אַף כָּךְ בַּעְלָהּ לֹא מֵאִיר אוֹרוֹ וְהִשְׁתַּנָּה מִכְּמוֹ שֶׁהָיָה, שֶׁכָּתוּב (שם יג) חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ, וְעַל זֶה כָּתוּב כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ.</p>\n<p>דָּבָר אַחֵר כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ - מֵהָעֶבֶד הַזֶּה שֶׁהִשְׁתַּנָּה דְיוֹקְנוֹ וְגוֹנוֹ מִכְּמוֹ שֶׁהָיָה. דָּבָר אַחֵר כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ - כְּמוֹ שֶׁנֶּאֱמַר (שם נ) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. שֶׁהֲרֵי מִיּוֹם שֶׁנֶּחֱרַב בֵּית הַמִּקְדָּשׁ לֹא עָמְדוּ הַשָּׁמַיִם בְּאוֹרָם, וְסוֹד הַדָּבָר - הַבְּרָכוֹת לֹא שׁוֹרוֹת אֶלָּא בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה, וּבֵאֲרוּהוּ כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם, וּמִשּׁוּם כָּךְ מִשְׁחַת מֵאִישׁ מַרְאֵהוּ.</p>\n<p>וְזְהִוּ כַּכָּתוּב (ישעיה נז) הַצַּדִּיק אָבָד. אָבוּד אוֹ נֶאֱבָד לֹא נֶאֱמַר, אֶלָּא אָבָד, שֶׁאֵין שׁוֹרוֹת בְּרָכוֹת אֶלָּא בְּמָקוֹם שֶׁנִּמְצָאִים זָכָר וּנְקֵבָה יַחַד, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>מִשּׁוּם זֶה בְּאוֹתוֹ זְמַן שֶׁלֹּא נִמְצָא הַזָּכָר עִמָּהּ, וְאָז כָּל אוֹתָן נְשָׁמוֹת שֶׁיּוֹצְאוֹת, לְכֻלָּן הָיָה לָהֶן שִׁנּוּי מִכְּמוֹ שֶׁהָיוּ בִּזְמַן שֶׁהַשֶּׁמֶשׁ מִתְחַבֵּר בַּלְּבָנָה, כְּמוֹ שֶׁנִּתְבָּאֵר. וְלָכֵן אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף וְגוֹ', וְנִתְבָּאֵר.</p>\n<p>וְהוּא נַעַר, מִשּׁוּם שֶׁאֵין נִפְרָדִים לְעוֹלָמִים, צַדִּי\"ק וְצֶדֶ\"ק הֵם יַחַד. כְּמוֹ שֶׁהִיא נִקְרֵאת בַּשֵּׁם שֶׁל הַזָּכָר, גַּם כָּךְ הוּא נִקְרָא בַּשֵּׁם שֶׁלָּהּ, שֶׁכָּתוּב וְהוּא נַעַר.</p>\n<p>אֶת בְּנֵי בִלְהָה וְאֶת בְּנֵי זִלְפָּה. בְּכֻלָּם עוֹמֶדֶת לְחַדֵּשׁ אוֹתָם כָּרָאוּי וּלְהִשְׁתַּעֲשֵׁעַ לָהֶם בַּשִּׂמְחָה שֶׁלּוֹ. שֶׁכָּל הָעֲנָפִים וְכָל הֶעָלִים, כֻּלָּם מִתְבָּרְכִים בְּשִׂמְחָתוֹ.</p>\n<p>אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁכָּל דְּמוּתוֹ שֶׁל יַעֲקֹב הָיְתָה בְּיוֹסֵף, וְכָל מַה שֶּׁאֵרַע לָזֶה אֵרַע לָזֶה, וּשְׁנֵיהֶם הוֹלְכִים יַחַד. וְזֶהוּ הַסּוֹד שֶׁל הָאוֹת וָ\"ו, שֶׁשְּׁנֵיהֶם הוֹלְכִים יַחַד, מִשּׁוּם שֶׁהֵם סוֹד אֶחָד וּדְמוּת אַחַת.</p>\n<p>וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, הֲרֵי פֵּרְשׁוּהָ שֶׁהָיָה אוֹמֵר לְאָבִיו עֲלֵיהֶם שֶׁהָיוּ אוֹכְלִים אֵיבָר מִבַּעֲלֵי חַיִּים כְּשֶׁהֵם חַיִּים. וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, וְכִי זֶה בְּמִנְיָן הָיוּ אוֹתָם בְּנֵי הַשְּׁפָחוֹת, אֵיךְ הָיוּ מְזַלְזְלִים בָּהֶם בְּנֵי לֵאָה, וְאֵיךְ הָיוּ אוֹכְלִים אֵיבָר מִן הַחַי וְהָיוּ עוֹבְרִים עַל מִצְוַת רִבּוֹנָם, שֶׁהֲרֵי צִוָּה עַל בְּנֵי נֹחַ מִצְוָה זוֹ, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ט) אַךְ בָּשָׂר בְּנַפְשׁוֹ דָּמוֹ לֹא תֹאכֵלוּ, וְהֵם הָיוּ אוֹכְלִים אוֹתָם וְעוֹבְרִים עַל מִצְוַת רִבּוֹנָם? אֶלָּא יוֹסֵף הָיָה אוֹמֵר, וְעַל זֶה נֶעֱנַשׁ.</p>\n<p>רַבִּי יְהוּדָה אָמַר, אֶת דִּבָּתָם רָעָה - כְּמוֹ שֶׁבֵּאֲרוּהוּ שֶׁנָּתְנוּ עֵינֵיהֶם בִּבְנוֹת הָאָרֶץ, וְזֶהוּ דִּבָּתָם רָעָה, לְהֵינִיק אֶת כָּל אוֹתָן הַדְּרָגוֹת שֶׁאֵינָן קְדוֹשׁוֹת (ד\"א אף על גב) שֶׁבָּאוֹת מִצַּד הַטֻּמְאָה.</p>"],[9522011376,"<p>וְיִשְׂרָאֵל אָהַב אֶת יוֹסֵף מִכָּל בָּנָיו כִּי בֶן זְקֻנִים הוּא לוֹ וְעָשָׂה לוֹ כְּתֹנֶת פַּסִּים. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (ישעיה כו) לֵךְ עַמִּי בֹּא בַחֲדָרֶיךְ וּסְגֹר דְּלָתְךְ בַּעֲדֶךְ חֲבִי כִמְעַט רֶגַע עַד יַעֲבָר זַעַם. לֵךְ עַמִּי בֹּא בַחֲדָרֶיךְ. בֹּא רְאֵה כַּמָּה אוֹהֵב הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת יִשְׂרָאֵל, וּבִשְׁבִיל אַהֲבָתָם שֶׁאוֹהֵב אוֹתָם עַל כָּל הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, הִזְהִיר אוֹתָם וְרוֹצֶה לִשְׁמֹר אוֹתָם בְּכָל מַה שֶּׁהֵם עוֹשִׂים.</p>\n<p>בֹּא רְאֵה, שָׁלֹשׁ פְּעָמִים יֵשׁ בַּיּוֹם שֶׁהַדִּין שׁוֹרֶה בָּעוֹלָם, וּכְשֶׁבָּא אוֹתוֹ הַזְּמַן, צָרִיךְ הָאָדָם לְהִזָּהֵר וּלְהִשָּׁמֵר שֶׁלֹּא יִפְגַּע בּוֹ אוֹתוֹ הַדִּין, וְהֵם זְמַנִּים יְדוּעִים, וַהֲרֵי בֵּאֲרוּהָ.</p>\n<p>מִשּׁוּם שֶׁהֲרֵי כְּשֶׁעוֹלֶה הַבֹּקֶר, אַבְרָהָם מִתְעוֹרֵר בָּעוֹלָם וְאוֹחֵז אֶת הַדִּין לִקְשֹׁר אוֹתוֹ עִמּוֹ, וּבְרֵאשִׁית שְׁלֹשׁ הַשָּׁעוֹת הָרִאשׁוֹנוֹת נוֹסֵעַ הַדִּין מִמְּקוֹמוֹ לְהִתְעוֹרֵר בּוֹ בְּיַעֲקֹב, עַד שֶׁמִּתְעוֹרֶרֶת תְּפִלַּת הַמִּנְחָה שֶׁמַּחֲזִירָה אֶת הַדִּין לִמְקוֹמוֹ, וּמִתְעוֹרֵר הַדִּין שֶׁלְּמַטָּה לְהִתְקַשֵּׁר בַּדִּין שֶׁל מַעְלָה, שֶׁהֲרֵי אָז נִקְשָׁר דִּין עִם דִּין, וְצָרִיךְ לְהִזָּהֵר.</p>\n<p>עוֹד, כְּשֶׁהַדִּין מִתְעוֹרֵר בָּעוֹלָם וְהַמָּוֶת נִמְצָא בָּעִיר, לֹא צָרִיךְ הָאָדָם לָלֶכֶת יְחִידִי בַּשּׁוּק, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים, אֶלָּא צָרִיךְ לִסְגֹּר אֶת עַצְמוֹ שֶׁלֹּא יֵצֵא הַחוּצָה, כְּמוֹ שֶׁבֵּאֲרוּהוּ בְּנֹחַ שֶׁסָּגַר אֶת עַצְמוֹ בַּתֵּבָה שֶׁלֹּא יִמָּצֵא לִפְנֵי הַמַּשְׁחִית.</p>\n<p>וְעַל זֶה לֵךְ עַמִּי בַחֲדָרֶיךְ, סְגֹר אֶת עַצְמְךְ, וּסְגֹר דְּלָתְךְ בַּעֲדֶךְ, שֶׁלֹּא יִתְרָאֶה לִפְנֵי הַמַּשְׁחִית. חֲבִי כִמְעַט רֶגַע עַד יַעֲבָר זַעַם, שֶׁאַחַר שֶׁעוֹבֵר הַדִּין אֵין רְשׁוּת לַמַּשְׁחִית לְהַשְׁחִית.</p>\n<p>בֹּא רְאֵה, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בִּשְׁבִיל הָאַהֲבָה שֶׁהוּא אוֹהֵב אֶת יִשְׂרָאֵל וְקֵרַב אוֹתָם אֵלָיו, כָּל שְׁאָר הָעַמִּים עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת שׂוֹנְאִים אֶת יִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם מְרֻחָקִים וְיִשְׂרָאֵל קְרוֹבִים.</p>\n<p>וּבֹא רְאֵה, מִשּׁוּם הָאַהֲבָה שֶׁאָהַב יַעֲקֹב אֶת יוֹסֵף יוֹתֵר מֵאֶחָיו, אַף עַל גַּב שֶׁכֻּלָּם הָיוּ לוֹ אַחִים, מַה כָּתוּב? וַיִּתְנַכְּלוּ אֹתוֹ לַהֲמִיתוֹ. כָּל שֶׁכֵּן הָעַמִּים עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת לְיִשְׂרָאֵל.</p>\n<p>בֹּא רְאֵה כַּמָּה גָרְמָה לוֹ אוֹתָהּ אַהֲבָה שֶׁאָהַב אוֹתוֹ יוֹתֵר, שֶׁגָּרַם לוֹ שֶׁהָגְלָה מֵאָבִיו, וְגָלָה אָבִיו עִמּוֹ, וְגָרַם לָהֶם גָּלוּת וְלַשְּׁכִינָה שֶׁגָּלְתָה בֵּינֵיהֶם, וְאַף עַל פִּי שֶׁנִּגְזְרָה הַגְּזֵרָה, וּבֵאֲרוּהוּ שֶׁבִּשְׁבִיל כְּתֹנֶת הַפַּסִּים שֶׁעָשָׂה לוֹ יוֹתֵר, מַה כָּתוּב? וַיִּרְאוּ אֶחָיו.</p>"],[9522011377,"<p>וַיַּחֲלֹם יוֹסֵף חֲלוֹם וְגוֹ'. רַבִּי חִיָּיא פָּתַח וְאָמַר, (במדבר יב) וַיֹּאמֶר שִׁמְעוּ נָא דְּבָרָי אִם יִהְיֶה נְבִיאֲכֶם ה' בַּמַּרְאָה אֵלָיו אֶתְוַדָּע בַּחֲלוֹם אֲדַבֶּר בּוֹ. בֹּא רְאֵה כַּמָּה דְרָגוֹת לִדְרָגוֹת עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא, כֻּלָּם עוֹמְדִים זֶה עַל זֶה, דַּרְגָּה עַל דַּרְגָּה, זוֹ לְמַעְלָה מִזּוֹ, וְכֻלָּן יוֹנְקוֹת אֵלּוּ מֵאֵלּוּ כָּרָאוּי לָהֶם, אֵלּוּ מִיָּמִין וְאֵלּוּ מִשְּׂמֹאל, וְכֻלָּם מְמֻנּוֹת אֵלּוּ עַל אֵלּוּ הַכֹּל כָּרָאוּי.</p>\n<p>בֹּא רְאֵה, כָּל נְבִיאֵי הָעוֹלָם, כֻּלָּם יוֹנְקִים מִצַּד אֶחָד מִתּוֹךְ שְׁתֵּי דְרָגוֹת יְדוּעוֹת, וְאוֹתָן הַדְּרָגוֹת הָיוּ נִרְאוֹת בְּתוֹךְ הָאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה, שֶׁכָּתוּב בַּמַּרְאָה אֵלָיו אֶתְוַדָּע. מַה הִיא הַמַּרְאָה? כְּמוֹ שֶׁנֶּאֱמַר (שמראה) הַמַּרְאֶה שֶׁכָּל הַגְּוָנִים נִרְאִים בְּתוֹכָהּ, וְזוֹהִי הָאַסְפַּקְלַרְיָה שֶׁאֵינָהּ מְאִירָה. בַּחֲלוֹם אֲדַבֶּר בּוֹ, זֶהוּ אֶחָד מִשִּׁשִּׁים בִּנְבוּאָה, כְּמוֹ שֶׁבֵּאֲרוּהוּ, וְהִיא הַדַּרְגָּה הַשִּׁשִּׁית מֵאוֹתָהּ הַדַּרְגָּה שֶׁל נְבוּאָה, וְהִיא הַדַּרְגָּה שֶׁל גַּבְרִיאֵל שֶׁמְּמֻנֶּה עַל הַחֲלוֹם, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, כָּל חֲלוֹם שֶׁהוּא כָּרָאוּי, בָּא מִן הַדַּרְגָּה הַזּוֹ, וְעַל כֵּן אֵין לְךְ חֲלוֹם שֶׁלֹּא יִתְעָרְבוּ בוֹ דְּבָרִים כּוֹזְבִים, כְּמוֹ שֶׁבֵּאַרְנוּ. וּמִשּׁוּם כָּךְ מֵהֶם אֱמֶת וּמֵהֶם כּוֹזְבִים, וְאֵין לְךְ חֲלוֹם שֶׁאֵין בּוֹ מִצַּד זֶה וּמִצַּד זֶה.</p>\n<p>וּמִשּׁוּם שֶׁיֵּשׁ בַּחֲלוֹם הַכֹּל כְּמוֹ שֶׁאָמַרְנוּ, כָּל הַחֲלוֹמוֹת שֶׁבָּעוֹלָם הוֹלְכִים אַחַר פִּתְרוֹן הַפֶּה, וּבֵאֲרוּהוּ שֶׁכָּתוּב (בראשית מא) וַיְהִי כַּאֲשֶׁר פָּתַר לָנוּ כֵּן הָיָה. מָה הַטַּעַם? מִשּׁוּם שֶׁיֵּשׁ בַּחֲלוֹם כָּזָב וֶאֱמֶת, וְהַדִּבּוּר שׁוֹלֵט עַל הַכֹּל, וּמִשּׁוּם כָּךְ צָרִיךְ הַחֲלוֹם פִּתְרוֹן טוֹב. רַבִּי יְהוּדָה אָמַר, מִשּׁוּם שֶׁכָּל חֲלוֹם הוּא מֵהַמַּדְרֵגָה שֶׁלְּמַטָּה, וְהַדִּבּוּר שׁוֹלֵט עָלָיו, וּמִשּׁוּם כָּךְ כָּל חֲלוֹם הוֹלֵךְ אַחַר הַפִּתְרוֹן.</p>\n<p>פָּתַח וְאָמַר, (איוב לג) בַּחֲלוֹם חֶזְיוֹן לַיְלָה בִּנְפֹל תַּרְדֵּמָה עַל אֲנָשִׁים בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב אָז יִגְלֶה אֹזֶן אֲנָשִׁים וּבְמֹסָרָם יַחְתֹּם. בֹּא רְאֵה, כְּשֶׁעוֹלֶה אָדָם לְמִטָּתוֹ, הוּא צָרִיךְ לְהַמְלִיךְ עָלָיו מַלְכוּת שָׁמַיִם בָּרִאשׁוֹנָה, וְאַחַר כָּךְ יֹאמַר פָּסוּק אֶחָד שֶׁל רַחֲמִים, וּבֵאֲרוּהוּ הַחֲבֵרִים. מִשּׁוּם שֶׁהִנֵּה כַּאֲשֶׁר אָדָם יָשֵׁן עַל מִטָּתוֹ, הִנֵּה נִשְׁמָתוֹ יוֹצֵאת מִמֶּנּוּ וְהוֹלֶכֶת וּמְשׁוֹטֶטֶת לְמַעְלָה, כָּל אֶחָד וְאֶחָד כְּפִי דַרְכּוֹ, וְכָךְ עוֹלֶה, כְּמוֹ שֶׁנִּתְבָּאֵר.</p>\n<p>מַה כָּתוּב? בַּחֲלוֹם חֶזְיוֹן לַיְלָה, כְּשֶׁבְּנֵי אָדָם שׁוֹכְבִים בְּמִטָּתָם יְשֵׁנִים וְהַנְּשָׁמָה יוֹצֵאת מֵהֶם. זֶהוּ שֶׁכָּתוּב בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב אָז יִגְלֶה אֹזֶן אֲנָשִׁים. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מוֹדִיעַ לַנְּשָׁמָה, בְּאוֹתָהּ הַדַּרְגָּה שֶׁעוֹמֶדֶת עַל הַחֲלוֹם, אוֹתָם הַדְּבָרִים שֶׁעֲתִידִים לָבֹא עַל הָעוֹלָם, אוֹ אוֹתָם דְּבָרִים כְּפִי אוֹתָם הַהִרְהוּרִים שֶׁלּ לִבּוֹ, מִשּׁוּם שֶׁאָדָם נוֹטֵל דֶּרֶךְ שֶׁל תּוֹכְחוֹת הָעוֹלָם.</p>\n<p>מִשּׁוּם שֶׁהִנֵּה לֹא מוֹדִיעִים לָאָדָם בְּעוֹד שֶׁהוּא עוֹמֵד בְּכֹחַ הַגּוּף (נ\"א של הרוח) כְּמוֹ שֶׁאָמַרְנוּ, אֶלָּא מַלְאָךְ מוֹדִיעַ לַנְּשָׁמָה, וְהַנְּשָׁמָה לָאָדָם, וְאוֹתוֹ הַחֲלוֹם הוּא מִלְמַעְלָה, כְּשֶׁהַנְּשָׁמוֹת יוֹצְאוֹת מִן הַגּוּפִים וְעוֹלוֹת כָּל אַחַת וְאַחַת כְּפִי דַרְכָּהּ.</p>\n<p>וְכַמָּה דְּרָגוֹת עַל דְּרָגוֹת בְּסוֹד הַחֲלוֹם, כֻּלָּן בְּסוֹד הַחָכְמָה. וּבא וּרְאֵה, הַחֲלוֹם דַּרְגָּה אַחַת, הַמַּרְאֶה דַּרְגָּה אַחַת, הַנְּבוּאָה דַּרְגָּה אַחַת, וְכֻלָּם דְּרָגוֹת לִדְרָגוֹת אֵלֶּה עַל אֵלֶּה.</p>\n<p>וַיַּחֲלֹם יוֹסֵף חֲלוֹם וַיַּגֵּד לְאֶחָיו וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ עַל חֲלוֹמוֹתָיו. מִכָּאן שֶׁלֹּא צָרִיךְ הָאָדָם לוֹמַר אֶת חֲלוֹמוֹ רַק לְאוֹתוֹ הָאָדָם שֶׁאוֹהֵב אוֹתוֹ, וְאִם לֹא - הוּא גוֹרֵם לוֹ. שֶׁאִם אוֹתוֹ הַחֲלוֹם מִתְהַפֵּךְ לְגָוֶן אַחֵר - הוּא גוֹרֵם לְסַלְּקוֹ</p>\n<p>בֹּא רְאֵה שֶׁיּוֹסֵף אָמַר אֶת הַחֲלוֹם לְאֶחָיו, וְעַל כֵּן גָּרְמוּ לוֹ לְסַלֵּק אֶת חֲלוֹמוֹ עֶשְׂרִים וּשְׁתַּיִם שָׁנִים שֶׁהִתְעַכֵּב. רַבִּי יוֹסֵי אָמַר, מִנַּיִן לָנוּ? שֶׁכָּתוּב וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ. מַה זֶה שְׂנֹא אֹתוֹ? שֶׁגָּרְמוּ לוֹ בָּזֶה קִטְרוּגִים.</p>\n<p>מַה כָּתוּב? וַיֹּאמֶר אֲלֵיהֶם שִׁמְעוּ נָא הַחֲלוֹם הַזֶּה אֲשֶׁר חָלָמְתִּי. שֶׁרָצָה מֵהֶם שֶׁיִּשְׁמְעוּ לוֹ, וְהוּא הוֹדִיעַ לָהֶם אוֹתוֹ הַחֲלוֹם, שֶׁאִלְמָלֵא הֵם שֶׁהָפְכוּ אוֹתוֹ לְגָוֶן אַחֵר - כָּךְ הִתְקַיֵּם, וְהֵם הֵשִׁיבוּ וְאָמְרוּ, הֲמָלֹךְ תִּמְלֹךְ עָלֵינוּ אִם מָשׁוֹל תִּמְשֹׁל בָּנוּ!? מִיָּד אָמְרוּ לוֹ אֶת פֵּשֶׁר הַחֲלוֹם וְגָזְרוּ גְזֵרָה, וּמִשּׁוּם כָּךְ וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ.</p>\n<p>רַבִּי חִיָּיא וְרַבִּי יוֹסֵי הָיוּ מְצוּיִים לִפְנֵי רַבִּי שִׁמְעוֹן. אָמַר רַבִּי חִיָּיא, הִנֵּה שָׁנִינוּ, חֲלוֹם שֶׁלֹּא נִפְתָּר כְּמוֹ אִגֶּרֶת שֶׁלֹּא נִקְרְאָה, אִם מִשּׁוּם שֶׁהִתְקַיֵּם וְהוּא לֹא יָדַע, אוֹ שֶׁלֹּא הִתְקַיֵּם כְּלָל. אָמַר לוֹ, הִתְקַיֵּם וְלֹא נוֹדַע, שֶׁהֲרֵי אוֹתוֹ הַחֲלוֹם תָּלוּי עָלָיו כֹּחַ, וְהוּא לֹא נוֹדַע וְלֹא יָדוּעַ אִם הִתְקַיֵּם וְאִם לֹא הִתְקַיֵּם.</p>\n<p>וְאֵין לְךְ דָּבָר בָּעוֹלָם שֶׁטֶּרֶם יָבֹא לָעוֹלָם שֶׁאֵינוֹ תָלוּי בַּחֲלוֹם אוֹ עַל יְדֵי כָרוֹז, שֶׁהֲרֵי נֶאֱמַר שֶׁכָּל דָּבָר וְדָבָר בְּטֶרֶם יָבֹא לָעוֹלָם מַכְרִיזִים עָלָיו בָּרָקִיעַ, וּמִשָּׁם מִתְפַּשֵּׁט בָּעוֹלָם וְנִתָּן עַל יְדֵי הַכָּרוֹז, וְהַכֹּל מִשּׁוּם שֶׁכָּתוּב (עמוס ג) כִּי לֹא יַעֲשֶׂה ה' אֱלֹהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים, בִּזְמַן שֶׁנְּבִיאִים נִמְצָאִים בָּעוֹלָם, וְאִם לֹא - אַף עַל גַּב שֶׁנְּבוּאָה לֹא שׁוֹרָה, חֲכָמִים עֲדִיפִים מִנְּבִיאִים, וְאִם לֹא - נִתָּן בַּחֲלוֹם, וְאִם לֹא - הַדָּבָר נִמְצָא בְּצִפֳּרֵי הַשָּׁמַיִם, וַהֲרֵי בֵּאֲרוּהָ.</p>"],[9522011378,"<p>וַיֵּלְכוּ אֶחָיו לִרְעוֹת אֶת צֹאן אֲבִיהֶם בִּשְׁכֶם. רַבִּי שִׁמְעוֹן אָמַר, לִרְעוֹת צֹאן אֲבִיהֶם הָיָה צָרִיךְ לִהְיוֹת! מַה זֶּה אֶ\"ת נָקוּד מֵעָלָיו? לְרַבּוֹת שְׁכִינָה עִמָּהֶם, שֶׁהִיא שְׁרוּיָה עִמָּהֶם, מִשּׁוּם שֶׁהֵם הָיוּ עֲשָׂרָה, שֶׁהֲרֵי יוֹסֵף לֹא הָיָה עִמָּהֶם, וּבִנְיָמִין הוּא קָטָן בַּבַּיִת, וּמִשּׁוּם כָּךְ הֵם הָיוּ עֲשָׂרָה, וּכְשֶׁהָלְכוּ, הַשְּׁכִינָה הָיְתָה בֵינֵיהֶם, וְעַל כֵּן נָקוּד מִלְמַעְלָה.</p>\n<p>וּמִשּׁוּם כָּךְ, בִּזְמַן שֶׁמָּכְרוּ אֶת יוֹסֵף, הִשְׁתַּתְּפוּ כֻלָּם עִם הַשְּׁכִינָה, וְשִׁתְּפוּ אוֹתָהּ עִמָּהֶם כְּשֶׁעָשׂוּ שְׁבוּעָה, וְעַד שֶׁהִתְגַּלָּה דְּבַר יוֹסֵף, לֹא שָׁרְתָה שְׁכִינָה עַל יַעֲקֹב.</p>\n<p>וְאִם תֹּאמַר שֶׁהַשְּׁכִינָה לֹא נִמְצְאָה עִמָּהֶם - בֹּא רְאֵה, שֶׁכָּתוּב (תהלים קכב) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהוֹדוֹת לְשֵׁם ה'. כֻּלָּם צַדִּיקִים וַחֲסִידִים, הַקִּיּוּם שֶׁל כָּל הָעוֹלָם, הֵם קִיּוּם לְמַעְלָה וּלְמַטָּה.</p>"],[9522011379,"<p>פָּתַח וְאָמַר, (שם) שָׂמַחְתִּי בְּאֹמְרִים לִי בֵּית ה' נֵלֵךְ. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, שֶׁדָּוִד הָיָה עִם לִבּוֹ לִבְנוֹת הַבַּיִת, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ח) וַיְהִי עִם לְבַב דָּוִד אָבִי לִבְנוֹת בַּיִת לְשֵׁם ה' וְגוֹ'. וְאַחַר כָּךְ מַה כָּתוּב? רַק אַתָּה לֹא תִבְנֶה הַבָּיִת כִּי אִם בִּנְךְ הַיֹּצֵא מֵחֲלָצֶיךְ הוּא יִבְנֶה הַבַּיִת לִשְׁמִי. וְכָל יִשְׂרָאֵל הָיוּ יוֹדְעִים אֶת זֶה, וְהָיוּ אוֹמְרִים מָתַי יָמוּת דָּוִד וְיָקוּם שְׁלֹמֹה בְּנוֹ וְיִבְנֶה אֶת הַבַּיִת, וְאָז עֹמְדוֹת הָיוּ רַגְלֵינוּ בִּשְׁעָרַיִךְ יְרוּשָׁ לם, אָז נַעֲלֶה וְנַקְרִיב שָׁם קָרְבָּנוֹת.</p>\n<p>וְעִם כָּל זֶה, אַף עַל גַּב שֶׁהָיוּ אוֹמְרִים מָתַי יָמוּת הַזָּקֵן הַזֶּה, אֲזַי שָׂמַחְתִּי וְשִׂמְחָה הָיְתָה לִי בִּשְׁבִיל בְּנִי, שֶׁהָיוּ אוֹמְרִים שֶׁבְּנִי יָקוּם תַּחְתַּי לִגְמֹר אֶת הַמִּצְוָה לִבְנוֹת אֶת הַבַּיִת. אָז הִתְחִיל לְשַׁבֵּחַ אוֹתָהּ וְאָמַר, יְרוּשָׁלַיִם הַבְּנוּיָה כְּעִיר שֶׁחֻבְּרָה לָּהּ יַחְדָּו.</p>\n<p>שָׁנִינוּ, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא יְרוּשָׁלַיִם לְמַטָּה כְּמוֹ שֶׁלְּמַעְלָה, וְזוֹ מְתֻקֶּנֶת (זו) כְּנֶגֶד זוֹ, שֶׁכָּתוּב (שמות טו) מָכוֹן לְשִׁבְתְּךְ פָּעַלְתָּ ה'. הַבְּנוּיָה, שֶׁעָתִיד הַקָּדוֹשׁ בָּרוּךְ הוּא לְהוֹרִיד אֶת יְרוּשָׁלַיִם שֶׁלְּמַעְלָה כָּרָאוּי, וּמִשּׁוּם כָּךְ הַבְּנוּיָה. שֶׁחֻבְּרָהּ לָּהּ יַחְדָּו, וַהֲרֵי בֵּאֲרוּהָ, שֶׁחֻבְּרָה? הָיָה צָרִיךְ לִהְיוֹת שֶׁחִבְּרוּ! אֶלָּא שֶׁהִתְחַבְּרָה הָאֵם עִם הַבַּת וְנִהְיוּ יַחַד, וּבֵאֲרוּהוּ.</p>\n<p>וְנֶאֱמַר שֶׁשָּׁם עָלוּ שְׁבָטִים, אֵלּוּ הֵם קִיּוּם שֶׁל הָעוֹלָם וְהַתִּקּוּן שֶׁל הָעוֹלָם הַתַּחְתּוֹן. וְאַל תֹּאמַר שֶׁהָעוֹלָם הַתַּחְתּוֹן לְבַדּוֹ, אֶלָּא אֲפִלּוּ שֶׁל הָעוֹלָם הָעֶלְיוֹן, שֶׁכָּתוּב שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, דַּוְקָא לְיִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם הַקִּיּוּם לְמַטָּה, עֵדוּת הֵם לְמַעְלָה, וְהַכֹּל - לְהוֹדוֹת לְשֵׁם ה', לְהוֹדוֹת לְשֵׁם הַקָּדוֹשׁ בָּרוּךְ הוּא לְכָל הַצְּדָדִים, שֶׁכָּתוּב לְהוֹדוֹת לְשֵׁם ה'.</p>"],[9522011380,"<p>וַיִּמְצָאֵהוּ אִישׁ וְהִנֵּה תֹעֶה בַּשָּׂדֶה וַיִּשְׁאָלֵהוּ הָאִישׁ לֵאמֹר מַה תְּבַקֵּשׁ. מַה כָּתוּב לְמַעְלָה? וַיֹּאמֶר יִשְׂרָאֵל אֶל יוֹסֵף הֲלוֹא אַחֶיךְ רֹעִים בִּשְׁכֶם לְכָה וְאֶשְׁלָחֲךְ אֲלֵיהֶם. וְכִי יַעֲקֹב הַשָּׁלֵם, שֶׁהָיָה אוֹהֵב אֶת יוֹסֵף מִכָּל בָּנָיו וְהָיָה יוֹדֵעַ שֶׁכָּל אֶחָיו הָיוּ שׂוֹנְאִים אוֹתוֹ, לָמָּה שָׁלַח אוֹתוֹ אֲלֵיהֶם? אֶלָּא הוּא לֹא חָשַׁד עֲלֵיהֶם, שֶׁהָיָה יוֹדֵעַ שֶׁכֻּלָּם הָיוּ צַדִּיקִים וְלֹא חָשַׁד אוֹתָם, אֶלָּא הַקָּדוֹשׁ בָּרוּךְ הוּא גָּרַם אֶת כָּל זֶה כְּדֵי לְקַיֵּם אֶת הַגְּזֵרָה שֶׁגָּזַר בֵּין הַבְּתָרִים.</p>\n<p>מָצָאנוּ בְּסִפְרֵי הַקַּדְמוֹנִים, שֶׁצְּרִיכִים בְּנֵי יַעֲקֹב הַלָּלוּ לִשְׁלֹט עָלָיו בְּטֶרֶם יֵרֵד לְמִצְרַיִם, שֶׁאִלּוּ הוּה יָרַד לְמִצְרַיִם וְהֵם לֹא הָיוּ שׁוֹלְטִים בּוֹ בָּרִאשׁוֹנָה, יָכְלוּ הַמִּצְרִים לִשְׁלֹט עַל יִשְׂרָאֵל לְעוֹלָמִים, וְהִתְקַיֵּם בְּיוֹסֵף שֶׁנִּמְכַּר לְעֶבֶד, וְהֵם שָׁלְטוּ עָלָיו, וְאַף עַל גַּב שֶׁיּוֹסֵף הָיָה אַחַר כָּךְ מֶלֶךְ וְהַמִּצְרִים הָיוּ עֲבָדִים שֶׁלּוֹ, נִמְצְאוּ יִשְׂרָאֵל שֶׁשָּׁלְטוּ עַל כֻּלָּם.</p>\n<p>בֹּא רְאֵה שֶׁיּוֹסֵף הוּא הַבְּרִית הָעֶלְיוֹנָה, כָּל זְמַן שֶׁמִּתְקַיֵּם הַבְּרִית, הַשְּׁכִינָה מִתְקַיֶּמֶת עִם יִשְׂרָאֵל בְּשָׁלוֹם כָּרָאוּי. כֵּיוָן שֶׁהִסְתַּלֵּק יוֹסֵף, הַבְּרִית הָעֶלְיוֹנָה, מִן הָעוֹלָם, אָז הַבְּרִית וְהַשְּׁכִינָה וְיִשְׂרָאֵל יָצְאוּ כֻלָּם לַגָּלוּת, וְהִנֵּה בֵּאַרְנוּ שֶׁכָּתוּב (שמות א) וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרַיִם אֲשֶׁר לֹא יָדַע אֶת יוֹסֵף, וְהַכֹּל הָיָה מֵעִם הַקָּדוֹשׁ בָּרוּךְ הוּא כָּרָאוּי.</p>\n<p>בֹּא רְאֵה, וַיִּמְצָאֵהוּ אִישׁ - זֶה גַבְרִיאֵל. וּפֵרְשׁוּהוּ, כָּתוּב כָּאן וַיִּמְצָאֵהוּ אִישׁ, וְכָתוּב שָׁם (דניאל ט) וְהָאִישׁ גַּבְרִיאֵל אֲשֶׁר רָאִיתִי בֶחָזוֹן בַּתְּחִלָּה. וְהִנֵּה תֹעֶה - תּוֹעֶה בַּכֹּל, שֶׁבָּטַח עַל אֶחָיו שֶׁהָיָה מְבַקֵּשׁ אֶת הָאַחֲוָה שֶׁלָּהֶם וְלֹא מָצָא, וּבִקֵּשׁ אוֹתָם וְלֹא מָצָא, וְעַל כֵּן תּוֹעֶה בַּכֹּל. וְעַל זֶה, וַיִּשְׁאָלֵהוּ הָאִישׁ לֵאמֹר מַה תְּבַקֵּשׁ.</p>"],[9522011381,"<p>וַיֹּאמֶר אֶת אַחַי אָנֹכִי מְבַקֵּשׁ וְגוֹ'. וַיֹּאמֶר הָאִישׁ נָסְעוּ מִזֶּה וְגוֹ'. רַבִּי יְהוּדָה פָּתַח (שיר ח) מִי יִתֶּנְךְ כְּאָח לִי יוֹנֵק שְׁדֵי אִמִּי אֶמְצָאֲךְ בַחוּץ אֶשָּׁקְךְ גַּם לֹא יָבֻזוּ לִי. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּ הַחֲבֵרִים, אֲבָל אֶת הַפָּסוּק הַזֶּה אָמְרָה כְּנֶסֶת יִשְׂרָאֵל לַמֶּלֶךְ שֶׁהַשָּׁלוֹם שֶׁלּוֹ, מִי יִתֶּנְךְ כְּאָח לִי, כְּיוֹסֵף עַל אֶחָיו, שֶׁאָמַר וְעַתָּה אַל תִּירָאוּ אָנֹכִי אֲכַלְכֵּל אֶתְכֶם וְאֶת טַפְּכֶם. נָתַן לָהֶם מָזוֹן וְזָן אוֹתָם בָּרָעָב. מִשּׁוּם כָּךְ, מִי יִתֶּנְךְ כְּאָח לִי.</p>\n<p>דָּבָר אַחֵר מִי יִתֶּנְךְ כְּאָח לִי - זֶה יוֹסֵף, אֶל הַשְּׁכִינָה, שֶׁנֶּאֱחַז עִמָּהּ וְנִדְבַּק עִמָּהּ. יוֹנֵק שְׁדֵי אִמִּי - שֶׁהֲרֵי אָז אַחֲוָה וּשְׁלֵמָה עִמָּהֶם. אֶמְצָאֲךְ בַחוּץ - בְּתוֹךְ הַגָּלוּת, שֶׁהִיא בְּאֶרֶץ אַחֶרֶת. אֶשָּׁקְךְ - כְּדֵי לְהַדְבִּיק רוּחַ עִם רוּחַ. גַּם לֹא יָבֻזוּ לִי - אַף עַל גַּב שֶׁאֲנִי נִמְצֵאת בְּאֶרֶץ אַחֶרֶת</p>\n<p>בֹּא רְאֵה שֶׁיּוֹסֵף, אַף עַל גַּב שֶׁאֶחָיו לֹא הָיוּ לוֹ כְּמוֹ אַחִים כְּשֶׁנָּפַל בִּידֵיהֶם, הוּא הָיָה לָהֶם כְּמוֹ אָח כְּשֶׁנָּפְלוּ בְיָדוֹ, וַהֲרֵי פֵּרְשׁוּהָ שֶׁכָּתוּב (בראשית נ) וַיְנַחֵם אוֹתָם וַיְדַבֵּר עַל לִבָּם, בַּכֹּל הוּא דִּבֵּר, עַל לִבָּם.</p>"],[9522011382,"<p>וּבֹא וּרְאֵה מַה כָּתוּב, וַיֹּאמְרוּ אִישׁ אֶל אָחִיו. זֶה שִׁמְעוֹן וְלֵוִי שֶׁהֵם הָיוּ וַדַּאי אַחִים בַּכֹּל, מִשּׁוּם שֶׁבָּאוּ מִצַּד הַדִּין הַקָּשֶׁה, וּמִשּׁוּם כָּךְ רָגְזָם הוּא רֹגֶז שֶׁל הֶרֶג בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (שם מט) אָרוּר אַפָּם כִּי עָז וְעֶבְרָתָם כִּי קָשָׁתָה</p>\n<p>בֹּא רְאֵה אֶת סוֹד הַדָּבָר, יֵשׁ רֹגֶז וְיֵשׁ רֹגֶז. יֵשׁ רֹגֶז שֶׁהוּא מְבֹרָךְ מִמַּעְלָה וּמִמַּטָּה, וְנִקְרָא בָּרוּךְ, כְּמוֹ שֶׁנִּתְבָּאֵר שֶׁכָּתוּב (שם יד) בָּרוּךְ אַבְרָם לְאֵל עֶלְיוֹן קֹנֵה שָׁמַיִם וָאָרֶץ, וַהֲרֵי פֵּרְשׁוּהָ. וְיֵשׁ רֹגֶז מְקֻלָּל לְמַעְלָה וּמַטָּה, כְּמוֹ שֶׁנִּתְבָּאֵר, שֶׁנִּקְרָא אָרוּר, שֶׁכָּתוּב (שם ג) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וּמִכֹּל חַיַּת הַשָּׂדֶה. אָרוּר אַפָּם כִּי עָז.</p>\n<p>וְעַל הַסּוֹד הַזֶּה יֵשׁ שְׁנֵי הָרִים, שֶׁכָּתוּב (דברים יא) וְנָתַתָּה אֶת הַבְּרָכָה עַל הַר גְּרִזִּים וְאֶת הַקְּלָלָה עַל הַר עֵיבָל, כְּנֶגֶד שְׁתֵּי הַדְּרָגוֹת הַלָּלוּ. וְעַל כֵּן זֶה נִקְרָא אָרוּר וְזֶה נִקְרָא בָּרוּךְ. וְשִׁמְעוֹן וְלֵוִי הֵם מִצַּד הַדִּין הַקָּשֶׁה, וּמִצַּד הַדִּין הַקָּשֶׁה הֶחָזָק יוֹצֵא רֹגֶז שֶׁמְּקֵלָּל.</p>\n<p>וּבֹא וּרְאֵה, מִצַּד הַדִּין הַקָּשֶׁה יוֹצֵא רֹגֶז לִשְׁנֵי צְדָדִים - אֶחָד שֶׁהִתְבָּרֵךְ וְאֶחָד שֶׁהִתְקַלֵּל, אֶחָד בָּרוּךְ וְאֶחָד אָרוּר. כְּמוֹ כֵן מֵהַצַּד שֶׁל יִצְחָק יָצְאוּ שְׁנֵי בָנִים - אֶחָד מְבֹרָךְ, וְאֶחָד שֶׁהִתְקַלֵּל לְמַעְלָה וּלְמַטָּה. זֶה נִפְרַד לְצִדּוֹ וְזֶה נִפְרַד לְצִדּוֹ. זֶה דִּיּוּרוֹ בָּאָרֶץ הַקְּדוֹשָׁה, וְזֶה דִּיּוּרוֹ בְּהַר שֵׂעִיר, שֶׁכָּתוּב (בראשית כד) אִישׁ יֹדֵעַ צַיִד אִישׁ שָׂדֶה. זֶה מְקוֹמוֹ בְּמָקוֹם שֶׁל מִדְבָּר, חָרְבָּה וּשְׁמָמָה, וְזֶה יֹשֵׁב אֹהָלִים, וְהַכֹּל כְּמוֹ שֶׁצָּרִיךְ.</p>\n<p>וּמִשּׁוּם כָּךְ שְׁתֵּי דְרָגוֹת הֵן - בָּרוּךְ וְאָרוּר, זֶה לְצִדּוֹ וְזֶה לְצִדּוֹ. מִזֶּה יוֹצְאוֹת כָּל הַבְּרָכוֹת שֶׁל הָעוֹלָמוֹת לְמַעְלָה וּלְמַטָּה וְכָל הַטּוֹב וְכָל הָאוֹר וְכָל גְּאֻלָּה וְכָל הַצָּלָה, וּמִזֶּה יוֹצְאוֹת כָּל הַקְּלָלוֹת וְכָל חֶרֶב וְכָל דָּם וְכָל שְׁמָמָה וְכָל הָרָעוֹת וְכָל הַטֻּמְאָה שֶׁל הָעוֹלָם.</p>\n<p>רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (תהלים כו) אֶרְחַץ בְּנִקָּיוֹן כַּפָּי וַאֲסוֹבְבָה אֶת מִזְבַּחֲךְ ה'. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל בֹּא רְאֵה כָּאן אֶת סוֹד הַדָּבָר, שֶׁהֲרֵי אֵין לְךְ אָדָם בָּעוֹלָם שֶׁאֵינוֹ טוֹעֵם אֶת טַעַם הַמָּוֶת בַּלַּיְלָה, וְרוּחַ הַטֻּמְאָה שׁוֹרָה עַל אוֹתוֹ הַגּוּף, מָה הַטַּעַם? מִשּׁוּם שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה מִסְתַּלֶּקֶת מִן הָאָדָם וְיוֹצֵאת מִמֶּנּוּ, וְעַל שֶׁהַנְּשָׁמָה הַקְּדוֹשָׁה יוֹצֵאת וּמִסְתַּלֶּקֶת מִמֶּנּוּ, שׁוֹרָה רוּחַ שֶׁל טֻמְאָה עַל אוֹתוֹ הַגּוּף וְנִטְמָא.</p>\n<p>כְּשֶׁהַנְּשָׁמָה חוֹזֶרֶת לַגּוּף, עוֹבֶרֶת אוֹתָהּ הַזֻּהֲמָה, וַהֲרֵי נִתְבָּאֵר שֶׁבִּידֵי הָאָדָם נִשְׁאֶרֶת זֻהֲמַת הַטֻּמְאָה, וְעַל כֵּן אַל יַעֲבִיר יָדוֹ עַל עֵינוֹ, מִשּׁוּם שֶׁאוֹתָהּ רוּחַ הַטֻּמְאָה שׁוֹרָה עָלָיו עַד שֶׁנּוֹטֵל אוֹתָם, וּכְשֶׁנּוֹטֵל יָדוֹ כָּרָאוּי, אָז מִתְקַדֵּשׁ וְנִקְרָא קָדוֹשׁ.</p>\n<p>וְאֵיךְ צָרִיךְ לְהִתְקַדֵּשׁ? צָרִיךְ כְּלִי אֶחָד לְמַטָּה וּכְלִי אֶחָד מִלְמַעְלָה, כְּדֵי שֶׁיִּתְקַדֵּשׁ מֵאוֹתוֹ שֶׁלְּמַעְלָה, וְאוֹתוֹ שֶׁלְּמַטָּה שֶׁיּוֹשֵׁב בַּזֻּהֲמָה שֶׁטֻּמְאָה בּוֹ. וְזֶה הַכְּלִי לְקַבֵּל טֻמְאָה, וְזֶה לְהִתְקַדֵּשׁ מִמֶּנּוּ. זֶה בָּרוּךְ וְזֶה אָרוּר. וְלֹא צָרִיךְ לִשְׁפֹּךְ בַּבַּית אֶת אוֹתָם מַיִם שֶׁל הַזֻּהֲמָה, שֶׁלֹּא יִקְרַב אֲלֵיהֶם אִישׁ, שֶׁהֲרֵי בָּהֶם מִתְכַּנְּסִים הַצַּד שֶׁלָּהֶם, וְיָכוֹל לְקַבֵּל נֵזֶק מֵאוֹתָם הַמַּיִם הַטְּמֵאִים.</p>\n<p>וְעַד שֶׁיַּעֲבֹר הַזֻּהֲמָה מִיָּדוֹ לֹא יְבָרֵךְ, וּבֵאַרְנוּ. וּמִשּׁוּם כָּךְ, בְּטֶרֶם יְקַדֵּשׁ הָאָדָם אֶת יָדָיו בַּבֹּקֶר, נִקְרָא טָמֵא. כֵּיוָן שֶׁהִתְקַדֵּשׁ, נִקְרָא טָהוֹר. וּמִשּׁוּם כָּךְ אַל יִטֹּל אֶלָּא מִיָּד שֶׁנִּטְהֲרָה בָּרִאשׁוֹנָה, שֶׁכָּתוּב (במדבר יט) וְהִזָּה הַטָּהוֹר עַל הַטָּמֵא. זֶה נִקְרָא טָהוֹר, וְזֶה נִקְרָא טָמֵא.</p>\n<p>מִשּׁוּם כָּךְ כְּלִי אֶחָד לְמַעְלָה וּכְלִי אֶחָד לְמַטָּה, זֶה קָדוֹשׁ וְזֶה טָמֵא. וְאָסוּר לַעֲשׂוֹת דָּבָר עִם אוֹתָם הַמַּיִם, אֶלָּא צָרִיךְ לִשְׁפֹּךְ אוֹתָם בְּמָקוֹם שֶׁאֲנָשִׁים לֹא עוֹבְרִים עֲלֵיהֶם וְלֹא יָלִין אוֹתָם בַּבַּיִת, שֶׁהֲרֵי כֵּיוָן שֶׁנִּשְׁפְּכוּ בָּאָרֶץ, רוּחַ הַטֻּמְאָה נִמְצֵאת שָׁם וִיכוֹלָה לְהַזִּיק. וְאִם חָפַר לָהֶם מִדְרוֹן תַּחַת הָאָרֶץ שֶׁלֹּא יֵרָאוּ - יָפֶה.</p>\n<p>וְלֹא יִתֵּן אוֹתָם לְנָשִׁים מְכַשְּׁפוֹת שֶׁיּוּכְלוּ לְהָרַע בָּהֶם לִבְנֵי אָדָם, מִשּׁוּם שֶׁאוֹתָם הַמַּיִם שֶׁהִתְקַלְּלוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה לְטַהֵר אֶת יִשְׂרָאֵל שֶׁיִּהְיוּ קְדוֹשִׁים, שֶׁכָּתוּב (יחזקאל לו) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים מִכֹּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם.</p>"],[9522011383,"<p>וַיִּקָּחֻהוּ וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה וְהַבּוֹר רֵק אֵין בּוֹ מָיִם. רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים יט) תּוֹרַת ה' תְּמִימָה מְשִׁיבַת נָפֶשׁ. (מי שמבטל דברי תורה כאלו החריב עולם שלם) כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִשְׁתַּדֵּל בַּתּוֹרָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, יִהְיוּ לוֹ חַיִּים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא וְזוֹכֶה בִּשְׁנֵי עוֹלָמוֹת. וַאֲפִלּוּ מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וְלֹא מִשְׁתַּדֵּל בָּהּ לִשְׁמָהּ כָּרָאוּי, זוֹכֶה לְשָׂכָר טוֹב בָּעוֹלָם הַזֶּה, וְאֵין דָּנִים אוֹתוֹ בָּעוֹלָם הַהוּא.</p>\n<p>וּבֹא וּרְאֵה, כָּתוּב (משלי ג) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד. אֹרֶךְ יָמִים בְּאוֹתוֹ שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה לִשְׁמָהּ, שֶׁיֵּשׁ לוֹ אֹרֶךְ יָמִים בָּעוֹלָם הַהוּא שֶׁבּוֹ אֹרֶךְ הַיָּמִים, וְאוֹתָם הַיָּמִים הֵם וַדַּאי יָמִים, שָׁם הוּא בִּטְחוֹן הַקְּדֻשָּׁה שֶׁלְּמַעְלָה שֶׁבּוֹטֵחַ אָדָם בָּעוֹלָם הַזֶּה לְהִשְׁתַּדֵּל בַּתּוֹרָה, לְהִתְחַזֵּק בָּעוֹלָם הַהוּא, בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד, יֵשׁ לוֹ שָׂכָר טוֹב וְשַׁלְוָה בָּעוֹלָם הַזֶּה.</p>\n<p>וְכָל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה לִשְׁמָהּ, כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, הַתּוֹרָה הוֹלֶכֶת לְפָנָיו וּמַכְרִיזָה לְפָנָיו וּמְגִנָּה עָלָיו שֶׁלֹּא יִקְרְבוּ אֵלָיו בַּעֲלֵי הַדִּין. כְּשֶׁשּׁוֹכֵב הַגּוּף בַּקֶּבֶר, הִיא שׁוֹמֶרֶת אוֹתוֹ. כְּשֶׁהַנְּשָׁמָה הוֹלֶכֶת לְהִסְתַּלֵּק לָשׁוּב לִמְקוֹמָהּ, הִיא הוֹלֶכֶת לִפְנֵי הַנְּשָׁמָה הַהִיא. וְכַמָּה שְׁעָרִים נִשְׁבָּרִים מִלִּפְנֵי הַתּוֹרָה עַד שֶׁנִּכְנֶסֶת לִמְקוֹמָהּ, וְעוֹמֶדֶת עַל הָאָדָם עַד שֶׁיִּתְעוֹרֵר בַּזְּמַן שֶׁיָּקוּמוּ הַמֵּתִים שֶׁל הָעוֹלָם, וְהִיא מְלַמֶּדֶת עָלָיו סָנֵגוֹרְיָה.</p>\n<p>זֶהוּ שֶׁכָּתוּב (משלי ו) בְּהִתְהַלֶּכְךְ תַּנְחֶה אֹתָךְ בְּשָׁכְבְּךְ תִּשְׁמֹר עָלֶיךְ וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךְ. בְּהִתְהַלֶּכְךְ תַּנְחֶה אֹתָךְ - כְּמוֹ שֶׁנִּתְבָּאֵר. בְּשָׁכְבְּךְ תִּשְׁמֹר עָלֶיךְ - בְּשָׁעָה שֶׁשּׁוֹכֵב הַגּוּף בַּקֶּבֶר, שֶׁהֲרֵי אָז בַּזְּמַן הַהוּא נִדּוֹן הַגּוּף בַּקֶּבֶר, וְאָז הַתּוֹרָה מְגִנָּה עָלָיו. וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךְ - כְּמוֹ שֶׁנִּתְבָּאֵר, בִּזְמַן שֶׁיִּתְעוֹרְרוּ הַמֵּתִים שֶׁל הָעוֹלָם מִן הֶעָפָר, הִיא תְשִׂיחֶךְ לִהְיוֹת עָלֶיךְ סָנֵגוֹר.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, הִיא תְשִׂיחֶךְ, מַה זֶּה הִיא תְשִׂיחֶךְ? מִשּׁוּם שֶׁאַף עַל גַּב שֶׁעַכְשָׁו יָקוּמוּ מֵהֶעָפָר, הַתּוֹרָה לֹא תִשְׁתַּכַּח מֵהֶם, שֶׁהֲרֵי אָז יֵדְעוּ אֶת כָּל אוֹתָהּ הַתּוֹרָה שֶׁעָזְבוּ כְּשֶׁהִסְתַּלְּקוּ מִן הָעוֹלָם הַזֶּה. אוֹתָהּ הַתּוֹרָה שְׁמוּרָה מֵאוֹתוֹ זְמַן, וְתִכָּנֵס לִמְעֵיהֶם כְּמוֹ מִקֹּדֶם, וְהִיא תְדַבֵּר בִּמְעֵיהֶם.</p>\n<p>וְכָל הַדְּבָרִים מְתֻקָּנִים יוֹתֵר מִכְּמוֹ שֶׁהָיוּ בָּרִאשׁוֹנָה, שֶׁהֲרֵי כָּל אוֹתָם הַדְּבָרִים שֶׁהוּא לֹא יָכֹל לְהַשִּׂיג אוֹתָם כָּרָאוּי וְהוּא הִשְׁתַּדֵּל בָּהֶם וְלֹא נִדְבַּק בָּהֶם - כֻּלָּם נִכְנָסִים לְמֵעָיו מְתֻקָּנִים וְהַתּוֹרָה תְּדַבֵּר בּוֹ. זֶהוּ שֶׁכָּתוּב וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךְ. רַבִּי יְהוּדָה אָמַר, כְּמוֹ זֶה כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה בָּעוֹלָם הַזֶּה, זוֹכֶה לְהִשְׁתַּדֵּל בָּהּ לָעוֹלָם הַבָּא, וְהִנֵּה נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, אוֹתוֹ הָאִישׁ שֶׁלֹּא זוֹכֶה לְהִשְׁתַּדֵּל בָּעוֹלָם הַזֶּה בַּתּוֹרָה וְהוּא הוֹלֵךְ בַּחֲשֵׁכָה, כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, נוֹטְלִים אוֹתוֹ וּמַכְנִיסִים אוֹתוֹ לַגֵּיהִנֹּם לַמָּקוֹם הַתַּחְתּוֹן, שֶׁלֹּא יִהְיֶה מְרַחֵם עָלָיו, שֶׁנִּקְרָא בּוֹר שָׁאוֹן טִיט הַיָּוֵן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים מ) וַיַּעֲלֵנִי מִבּוֹר שָׁאוֹן מִטִּיט הַיָּוֵן וַיָּקֶם עַל סֶלַע רַגְלָי כּוֹנֵן אֲשׁוּרָי.</p>\n<p>וּמִשּׁוּם כָּךְ, אוֹתוֹ שֶׁלֹּא מִשְׁתַּדֵּל בַּתּוֹרָה בָּעוֹלָם הַזֶּה וּמִתְטַנֵּף בַּטִּנּוֹפוֹת שֶׁל הָעוֹלָם, מַה כָּתוּב? וַיִּקָּחֻהוּ וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה - זֶה הוּא הַגֵּיהִנֹּם, הַמָּקוֹם שֶׁדָּנִים אֶת אוֹתָם שֶׁלֹּא הִשְׁתַּדְּלוּ בַּתּוֹרָה. וְהַבּוֹר רֵק - כְּמוֹ שֶׁהוּא הָיָה רֵיק, מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא הָיָה בּוֹ מַיִם.</p>\n<p>וּבֹא וּרְאֵה כַּמָּה הוּא הָעֹנֶשׁ שֶׁל הַתּוֹרָה, שֶׁהֲרֵי לֹא גָלוּ יִשְׂרָאֵל מֵהָאָרֶץ הַקְּדוֹשָׁה אֶלָּא מִשּׁוּם שֶׁהִסְתַּלְּקוּ מִן הַתּוֹרָה וְנֶעֶזְבוּ מִמֶּנָּה, זֶהוּ שֶׁכָּתוּב (ירמיה ט) מִי הָאִישׁ הֶחָכָם וְיָבֵן אֶת זאת וְגוֹ' עַל מָה אָבְדָה הָאָרֶץ וְגוֹ'. וַיּאמֶר ה' עַל עָזְבָם אֶת תּוֹרָתִי וְגוֹ'. רַבִּי יוֹסֵי אָמַר, מִכָּאן (ישעיה ה) לָכֵן גָּלָה עַמִּי מִבְּלִי דָעַת.</p>\n<p>מִשּׁוּם כָּךְ הַכֹּל עוֹמֵד עַל קִיּוּם הַתּוֹרָה, וְהָעוֹלָם לֹא מִתְקַיֵּם בְּקִיּוּמוֹ אֶלָּא בַּתּוֹרָה, שֶׁהִיא קִיּוּם הָעוֹלָמוֹת, מַעְלָה וּמַטָּה, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי.</p>\n<p>וַיִקָּחֻהוּ וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה, רֶמֶז עַל שֶׁזָּרְקוּ אוֹתוֹ לְתוֹךְ הַמִּצְרִים, הַמָּקוֹם שֶׁלֹּא נִמְצָא בּוֹ סוֹד הָאֱמוּנָה כְּלָל. רַבִּי יִצְחָק אָמַר, אִם נְחָשִׁים וְעַקְרַבִּים הָיוּ בוֹ, לָמָּה כָּתוּב בִּרְאוּבֵן לְמַעַן הַצִּיל אֹתוֹ מִיָּדָם לַהֲשִׁיבוֹ אֶל אָבִיו, וְכִי לֹא חָשַׁשׁ רְאוּבֵן לָזֶה שֶׁהִנֵּה אוֹתָם נְחָשִׁים וְעַקְרַבִּים יַזִּיקוּ אוֹתוֹ, וְאֵיךְ אָמַר לַהֲשִׁיבוֹ אֶל אָבִיו, וְכָתוּב לְמַעַן הַצִּיל אוֹתוֹ?</p>\n<p>אֶלָּא שֶׁרָאָה רְאוּבֵן שֶׁהַנֵּזֶק נִמְצָא בִּידֵי אֶחָיו, מִשּׁוּם שֶׁיָּדַע כַּמָּה הֵם שׂוֹנְאִים אוֹתוֹ וּרְצוֹנָם לַהֲרֹג אוֹתוֹ. אָמַר רְאוּבֵן, טוֹב לְהַפִּיל אוֹתוֹ לְתוֹךְ בּוֹר הַנְּחָשִׁים וְהָעַקְרַבִּים וְלֹא יִמָּסֵר בִּידֵי שׂוֹנְאָיו שֶׁלֹּא מְרַחֲמִים עָלָיו. מִכָּאן אָמְרוּ, יַפִּיל אָדָם עַצְמוֹ לָאֵשׁ אוֹ לְבוֹר שֶׁל נְחָשִׁים וְעַקְרַבִּים וְלֹא יִמָּסֵר בִּידֵי שׂוֹנְאָיו (שמעטים הם שיכולים להנצל, ומשום כך אמר למען הציל אתו מידם).</p>\n<p>מִשּׁוּם שֶׁכָּאן בִּמְקוֹם הַנְּחָשִׁים וְהָעַקְרַבִּים - אִם הוּא צַדִּיק, הַקָּדוֹשׁ בָּרוּךְ הוּא יַרְחִישׁ לוֹ נֵס, וְלִפְעָמִים שֶׁזְּכוּת אָבוֹת מְסַיְּעִים לָאָדָם וְיִנָּצֵל מֵהֶם. אֲבָל כֵּיוָן שֶׁנִּמְסָר בִּידֵי שׂוֹנְאָיו, מְעַטִּים הֵם שֶׁיְּכוֹלִים לְהִנָּצֵל.</p>\n<p>וּמִשּׁוּם כָּךְ אָמַר לְמַעַן הַצִּיל אֹתוֹ מִיָּדָם, מִיָּדָם דַּוְקָא, וְלֹא כָתוּב לְמַעַן הַצִּיל אוֹתוֹ וְיוֹתֵר לֹא. אֶלָּא אָמַר רְאוּבֵן, יִנָּצֵל מִיָּדָם, וְאִם יָמוּת בַּבּוֹר - יָמוּת. וּמִשּׁוּם כָּךְ כָּתוּב וַיִּשְׁמַע רְאוּבֵן וַיַּצִּלֵהוּ מִיָּדָם</p>\n<p>בֹּא רְאֵה כַּמָּה הִיא חֲסִידוּתוֹ שֶׁל רְאוּבֵן, שֶׁמִּשּׁוּם שֶׁיָּדַע שֶׁשִּׁמְעוֹן וְלֵוִי, הַשֻּׁתָּפוּת וְהַחָכְמָה וְהַחֲבֵרוּת שֶׁלָּהֶם הֵם קָשִׁים, שֶׁכַּאֲשֶׁר הִתְחַבְּרוּ בִּשְׁכֶם הָרְגוּ כָּל זָכָר (ס\"א וזה שהרגו כל זכר), לֹא דַי לָהֶם, אֶלָּא שֶׁנּוֹטְלִים נָשִׁים וָטַף וְכֶסֶף וְזָהָב וְכָל הַבְּהֵמוֹת וְכָל כְּלֵי יְקָר וְכָל מִי שֶׁנִּמְצָא בַּקִּרְיָה, וְלֹא דַי, אֶלָּא שֶׁאֲפִלּוּ כָּל מַה שֶּׁבַּשָּׂדֶה נָטְלוּ, שֶׁכָּתוּב (בראשית לד) וְאֶת אֲשֶׁר בָּעִיר וְאֶת אֲשֶׁר בַּשָּׂדֶה לָקָחוּ.</p>\n<p>אָמַר, וּמָה הַקִּרְיָה הַגְּדוֹלָה כָּזוֹ לֹא נִצַּל מֵהֶם - אִלְמָלֵא הָעֶלֶם הַזֶּה יִפֹּל בִּידֵיהֶם, לֹא יַשְׁאִירוּ מִמֶּנּוּ חֲתִיכַת בָּשָׂר בָּעוֹלָם, וְעַל כֵּן אָמַר טוֹב לְהִנָּצֵל מֵהֶם, שֶׁלֹּא יַשְׁאִירוּ מִמֶּנּוּ שְׁאֵרִית בָּעוֹלָם וְלֹא יִרְאֶה מִמֶּנּוּ אַבָּא כְּלוּם לְעוֹלָמִים.</p>\n<p>וְכָאן אִם יָמוּת, לֹא יְכוֹלִים לוֹ, וְיִשָּׁאֵר כָּל גּוּפוֹ שָׁלֵם וְאָשִׁיב אוֹתוֹ לְאַבָּא שָׁלֵם, וְעַל כֵּן לְמַעַן הַצִּיל אֹתוֹ מִיָּדָם לַהֲשִׁיבוֹ אֶל אָבִיו, אַף עַל גַּב שֶׁיָּמוּת שָׁם. וּמִשּׁוּם כָּךְ אָמַר הַיֶּלֶד אֵינֶנּוּ, וְלֹא אָמַר אֵינֶנּוּ חַי, אֶלָּא אָמַר אֵינֶנּוּ - אֲפִלּוּ מֵת.</p>\n<p>בֹּא רְאֵה מַה שֶּׁעָשָׂה, שֶׁהוּא בְחָכְמָה הָיָה מְשַׁתֵּף עַצְמוֹ עִמָּהֶם, שֶׁכָּתוּב לֹא נַכֶּנּוּ נָפֶשׁ, וְלֹא כָתוּב לֹא תַכּוּהוּ, וְהוּא לֹא הָיָה שָׁם כְּשֶׁנִּמְכַּר יוֹסֵף, שֶׁהֲרֵי כֻּלָּם שִׁמְּשׁוּ אֶת אֲבִיהֶם, כָּל אֶחָד וְאֶחָד יוֹם אֶחָד, וְאוֹתוֹ הַיּוֹם הָיָה שֶׁל רְאוּבֵן, וְעַל כֵּן רָצָה שֶׁבְּאוֹתוֹ הַיּוֹם שֶׁהָיָה הַשִּׁמּוּשׁ שֶׁלּוֹ לֹא יֵאָבֵד יוֹסֵף, וּמִשּׁוּם כָּךְ כָּתוּב וַיָּשָׁב רְאוּבֵן אֶל הַבּוֹר וְהִנֵּה אֵין יוֹסֵף בַּבּוֹר וַיִּקְרַע אֶת בְּגָדָיו. וְהִנֵּה אֵין יוֹסֵף דַּוְקָא, אֲפִלּוּ (חי או) מֵת, מִיָּד וַיָּשָׁב אֶל אֶחָיו וַיֹּאמֶר הַיֶּלֶד אֵינֶנּוּ.</p>\n<p>וַאֲפִלּוּ רְאוּבֵן לֹא יָדַע מֵאוֹתָהּ הַמְּכִירָה שֶׁל יוֹסֵף. וַהֲרֵי בֵּאֲרוּהוּ שֶׁהַשְּׁכִינָה הִשְׁתַּתְּפָה עִמָּהֶם, וְעַל כֵּן לֹא יָדַע רְאוּבֵן מֵהַמְּכִירָה הַהִיא שֶׁל יוֹסֵף, וְלֹא הִתְגַּלְּתָה לוֹ עַד אוֹתוֹ הַזְּמַן שֶׁיּוֹסֵף הִתְגַּלָּה לְאֶחָיו.</p>\n<p>בֹּא רְאֵה כַּמָּה גָרַם לִרְאוּבֵן מִשּׁוּם שֶׁהוּא הִשְׁתַּדֵּל לְהַחֲיוֹת אֶת יוֹסֵף. מַה כָּתוּב? (דברים לג) יְחִי רְאוּבֵן וְאַל יָמֹת וְגוֹ'. שֶׁהֲרֵי מִשּׁוּם זֶה, אַף עַל גַּב שֶׁיָּדַע שֶׁנִּלְקְחָה בְכוֹרָתוֹ מִמֶּנּוּ וְנִתְּנָה לְיוֹסֵף, הִשְׁתַּדֵּל לְהַחֲיוֹת אוֹתוֹ, וְהִתְפַּלֵּל מֹשֶׁה וְאָמַר יְחִי רְאוּבֵן וְאַל יָמֹת, וְהִתְקַיֵּם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. מָה הַטַּעַם? מִשּׁוּם זֶה, וּמִשּׁוּם שֶׁעָשָׂה תְשׁוּבָה מֵהַמַּעֲשֶׂה הַהוּא. שֶׁכָּל מִי שֶׁעוֹשֶׂה תְשׁוּבָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מְקַיֵּם אוֹתוֹ בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב? וַיִּקְחוּ אֶת כְּתֹנֶת יוֹסֵף וְגוֹ'. הֲרֵי בֵּאֲרוּהוּ, שֶׁמִּשּׁוּם שֶׁדַּם הַשָּׂעִיר דּוֹמֶה לְדָם שֶׁל אָדָם. אֲבָל בּא רְאֵה, אַף עַל גַּב שֶׁהַדָּבָר בָּא כָּרָאוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא מְדַקְדֵּק עִם הַצַּדִּיקִים אֲפִלּוּ כְּחוּט הַשַּׂעֲרָה.</p>\n<p>יַעָקֹב עָשָׂה מַעֲשֶׂה כָּרָאוּי, בַּמֶּה? מִשּׁוּם שֶׁהִקְרִיב לְאָבִיו שָׂעִיר, שֶׁהוּא צַד הַדִּין הַקָּשֶׁה, וְעִם כָּל זֶה, מִשּׁוּם שֶׁהוּא הִקְרִיב שָׂעִיר וְהִכְחִישׁ אֶת אָבִיו שֶׁהוּא הַצַּד שֶׁלּוֹ, נֶעֱנַשׁ בַּשָּׂעִיר הָאַחֵר הַזֶּה שֶׁהִקְרִיבוּ לוֹ בָּנָיו אֶת הַדָּם שֶׁלּוֹ.</p>\n<p>בּוֹ כָּתוּב (בראשית כז) וְאֵת עֹרֹת גְּדָיֵי הָעִזִּים הִלְבִּישָׁה עַל יָדָיו וְעַל חֶלְקַת צַוָּארָיו, מִשּׁוּם כָּךְ - וַיִּטְבְּלוּ אֶת הַכֻּתֹּנֶת בַּדָּם, הִקְרִיבוּ לוֹ כֻּתֹּנֶת לְהַכְחִישׁ אוֹתוֹ. וְהַכֹּל זֶה כְּנֶגֶד זֶה. הוּא גָּרַם שֶׁכָּתוּב וַיֶּחֱרַד יִצְחָק חֲרָדָה גְּדֹלָה עַד מְאֹד, מִשּׁוּם כָּךְ גָּרְמוּ לוֹ שֶׁחָרַד חֲרָדָה בַּזְּמַן הַהוּא, שֶׁכָּתוּב הַכֶּר נָא הַכְּתֹנֶת בִּנְךְ הִיא אִם לֹא.</p>\n<p>רַבִּי חִיָּיא אָמַר, כָּתוּב בּוֹ (שם) הַאַתָּה זֶה בְּנִי עֵשָׂו אִם לֹא - לוֹ כָּתוּב, הַכְּתֹנֶת בִּנְךְ הִיא אִם לֹא. וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מְדַקְדֵּק עִם הַצַּדִּיקִים בְּכָל מַה שֶּׁהֵם עוֹשִׂים.</p>\n<p>רַבִּי אַבָּא אָמַר (נ\"א: אמר רבי אבא), כֵּיוָן שֶׁכָּל הַשְּׁבָטִים רָאוּ אוֹתוֹ הַצַּעַר שֶׁל אֲבִיהֶם, וַדַּאי הִתְנַחֲמוּ וְנָתְנוּ עַצְמָם עַל יוֹסֵף שֶׁיִּפְדּוּ אוֹתוֹ אִלְמָלֵא יִמְצְאוּ אוֹתוֹ. כֵּיוָן שֶׁרָאוּ שֶׁלֹּא יְכוֹלִים, חָזְרוּ אֶל יְהוּדָה וְהֶעֱבִירוּ אוֹתוֹ מֵעֲלֵיהֶם, מִשּׁוּם שֶׁהוּא הָיָה מֶלֶךְ עֲלֵיהֶם, (ואז ס\"א וכיון ש) הֶעֱבִירוּהוּ מֵעֲלֵיהֶם, מַה כָּתוּב? וַיְהִי בָּעֵת הַהִיא וַיֵּרֶד יְהוּדָה וְגוֹ'.</p>"],[9522011384,"<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (תהלים יח) וַיַּרְעֵם בַּשָּׁמַיִם ה' וְעֶלְיוֹן יִתֵּן קוֹלוֹ בָּרָד וְגַחֲלֵי אֵשׁ. בּא רְאֵה, כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, הִתְקִין לוֹ שִׁבְעָה עַמּוּדִים עַל מַה שֶּׁעוֹמֵד, וְכָל הָעַמּוּדִים עוֹמְדִים בְּעַמּוּד אֶחָד יְחִידִי, וַהֲרֵי פֵּרְשׁוּהָ שֶׁכָּתוּב (משלי ט) חָכְמוֹת בָּנְתָה בֵיתָהּ חָצְבָה עַמּוּדֶיהָ שִׁבְעָה, וְכָל אֵלֶּה הֵם עוֹמְדִים בְּדַרְגָּה אַחַת מֵהֶם שֶׁנִּקְרֵאת (שם י) צַדִּיק יְסוֹד עוֹלָם.</p>\n<p>וּכְשֶׁנִּבְרָא הָעוֹלָם, נִבְרָא מֵאוֹתוֹ הַמָּקוֹם שֶׁהוּא הַשְּׁלֵמוּת שֶׁל הָעוֹלָם וְתִקּוּנוֹ, שֶׁהוּא נְקֻדָּה אַחַת שֶׁל הָעוֹלָם וְהָאֶמְצַע שֶׁל הַכֹּל, וּמִי הוּא? צִיּוֹן, שֶׁכָּתוּב (תהלים נ) מִזְמוֹר לְאָסָף אֶל אֱלֹהִים ה' דִּבֶּר וַיִּקְרָא אָרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבֹאוֹ. וּמֵאֵיזֶה מָקוֹם? מִצִּיּוֹן, שֶׁכָּתוּב מִצִּיּוֹן מִכְלַל יֹפִי אֱלֹהִים הוֹפִיעַ. מֵאוֹתוֹ הַמָּקוֹם שֶׁהוּא צַד הַשְּׁלֵמוּת שֶׁל הָאֱמוּנָה הַשְּׁלֵמָה כָּרָאוּי (וכעת ישראל החזיקו בו בסודות המצוות של התורה, משום שכל יום ויום מחזיק אדם בציצית שמתעטף בה), וְצִיּוֹן הַחֹזֶק וְהַנְּקֻדָּה שֶׁל כָּל הָעוֹלָם, וּמֵהַמָּקוֹם הַהוּא נִתְקַן כָּל הָעוֹלָם וְנַעֲשָׂה, וּמִתּוֹכוֹ נִזּוֹן כָּל הָעוֹלָם.</p>\n<p>וּבֹא וּרְאֵה, וַיַּרְעֵם בַּשָּׁמַיִם ה' וְעֶלְיוֹן יִתֵּן קוֹלוֹ וְגוֹ'. כֵּיוָן שֶׁאָמַר וַיַּרְעֵם בַּשָּׁמַיִם ה', לָמָּה כָּתוּב וְעֶלְיוֹן יִתֵּן קוֹלוֹ? הִנֵּה (ס\"א אלא) כָּאן סוֹד הָאֱמוּנָה (על מה עולם) שֶׁאָמַרְנוּ שֶׁצִּיּוֹן הִיא הַשְּׁלֵמוּת וְהַיֹּפִי שֶׁל הָעוֹלָם, וְהָעוֹלָם נִזּוֹן מִמֶּנּוּ, מִשּׁוּם שֶׁשְּׁתֵּי דְרָגוֹת הֵן, וְהֵן אַחַת, הֵם צִיּוֹן וִירוּשָׁלַיִם, זֶה דִּין וְזֶה רַחֲמִים, וּשְׁנֵיהֶם אֶחָד, מִכָּאן דִּין וּמִכָּאן רַחֲמִים.</p>\n<p>מִמַּעִִלָה לְמַעְלָה יוֹצֵא קוֹל שֶׁנִּשְׁמָע. לְאַחַר שֶׁאוֹתוֹ הַקּוֹל יוֹצֵא וְנִשְׁמָע, אָז יוֹצְאִים הַדִּינִים וְדַרְכֵי הַדִּין, וְהָרַחֲמִים יוֹצְאִים וְנִפְרָדִים מִשָּׁם. וַיַּרְעֵם בַּשָּׁמַיִם ה', זֶה בֵּית הַדִּין בְּרַחֲמִים. וְעֶלְיוֹן, אַף עַל גַּב שֶׁאֵינוֹ נִמְצָא וְאֵינוֹ נוֹדָע, כֵּיוָן שֶׁהַקּוֹל הַהוּא יוֹצֵא, אָז נִמְצָא הַכֹּל, דִּין וְרַחֲמִים. זֶהוּ שֶׁכָּתוּב וְעֶלְיוֹן יִתֵּן קוֹלוֹ. כֵּיוָן שֶׁיִּתֵּן קוֹלוֹ, אָז בָּרָד וְגַחֲלֵי אֵשׁ, מַיִם וְאֵשׁ.</p>\n<p>בֹּא רְאֵה, בְּשָׁעָה שֶׁנּוֹלַד יְהוּדָה, מַה כָּתוּב? (בראשית כט) וַתַּעֲמֹד מִלֶּדֶת, מִשּׁוּם שֶׁזֶּה הוּא הַיְסוֹד הָרְבִיעִי מֵאוֹתָם הָאַרְבָּעָה שֶׁהֵם הַמֶּרְכָּבָה הָעֶלְיוֹנָה, עַמּוּד אֶחָד מֵאוֹתָם אַרְבָּעָה הָעַמּוּדִים, מַה כָּתוּב בּוֹ? וַיְהִי בָּעֵת הַהִיא וַיֵּרֶד יְהוּדָה מֵאֵת אֶחָיו, שֶׁהָיָה מֶלֶךְ עֲלֵיהֶם. מָה הַטַּעַם? מִשּׁוּם שֶׁהוֹרִידוּ אֶת יוֹסֵף לְמִצְרַיִם, כְּמוֹ שֶׁאָמַ רְנוּ.</p>"],[9522011385,"<p>וַיַּרְא שָׁם יְהוּדָה בַּת אִישׁ כְּנַעֲנִי, וְכִי כְּנַעֲנִי הָיָה? אֶלָּא הִנֵּה פֵּרְשׁוּהוּ הַחֲבֵרִים. וַתַּהַר וַתֵּלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ עֵר. שְׁלֹשָׁה בָנִים הָיוּ לִיהוּדָה, וְלֹא נִשְׁאַר מֵהֶם רַק אֶחָד, וְזֶה הוּא שֵׁלָה.</p>\n<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי וְרַבִּי חִיָּיא הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי אֶלְעָזָר, לָמָּה כָּתוּב בִּבְנֵי יְהוּדָה, בָּרִאשׁוֹן - וַיִּקְרָא אֶת שְׁמוֹ עֵר, וּבִשְׁנֵי הָאֲחֵרִים כָּתוּב, וַתִּקְרָא אֶת שְׁמוֹ אוֹנָן, וַתִּקְרָא אֶת שְׁמוֹ שֵׁלָה?</p>\n<p>אָמַר לוֹ, בּא רְאֵה, הַפָּרָשָׁה הַזּוֹ הִיא סוֹד עֶלְיוֹן, וְהַכֹּל הוּא כָּרָאוּי. וַיֵּרֶד יְהוּדָה מֵאֵת אֶחָיו, שֶׁהִנֵּה נִכְסְתָה הַלְּבָנָה וְיָרְדָה מֵהַדַּרְגָּה שֶׁל תִּקּוּן לְתוֹךְ דַּרְגָּה אַחֶרֶת, שֶׁהִתְחַבֵּר בָּהּ הַנָּחָשׁ, כְּמוֹ שֶׁנֶּאֱמַר וַיֵּט עַד אִישׁ עֲדֻלָּמִי וּשְׁמוֹ חִירָה.</p>\n<p>וַתַּהַר וַתֵּלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ עֵר, וְהוּא רַע, וְהַכֹּל אֶחָד, שֶׁבָּא מִצַּד הַיֵּצֶר הָרָע, וּמִשּׁוּם כָּךְ כָּתוּב וַיִּקְרָא אֶת שְׁמוֹ וְלֹא כָתוּב וַיִּקְרָא שְׁמוֹ. בְּיַעֲקֹב כָּתוּב וַיִּקְרָא שְׁמוֹ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לוֹ יַעֲקֹב, וְכָאן אֶת - לְרַבּוֹת דַּרְגָּה אַחֶרֶת שֶׁזֻּהֲמַת הַטֻּמְאָה נוֹלַד, וְזֶה הוּא עֵר רַע, וְהַכֹּל אֶחָד.</p>\n<p>אַחַר כָּךְ לֹא הִתְבַּסֵּם הַמָּקוֹם עַד שֶׁבָּא שֵׁלָה שֶׁהָיָה הָעִקָּר שֶׁל כֻּלָּם. מַה כָּתוּב? וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה'. כָּתוּב כָּאן רַע, וְכָתוּב שָׁם (בראשית ח) כִּי יֵצֶר לֵב הָאָדָם רַע מִנְּעֻרָיו. רַע שֶׁשּׁוֹפֵךְ דָּמִים, שׁוֹפֵךְ זֶרַע עַל הָאָרֶץ, וּמִשּׁוּם כָּךְ וַיְמִתֵהוּ ה'. מַה כָּתוּב אַחֲרָיו? וַיֹּאמֶר יְהוּדָה לְאוֹנָן בֹּא אֶל אֵשֶׁת אָחִיךְ וְגוֹ'.</p>"],[9522011386,"<p>וַיֹּאמֶר יְהוּדָה לְאוֹנָן בּא אֶל אֵשֶׁת אָחִיךְ וְגוֹ'. רַבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (ישעיה מא) הֲעִירוֹתִי מִצָּפוֹן וַיַּאת מִמִּזְרַח שֶׁמֶשׁ יִקְרָא בִשְׁמִי וְיָבֹא סְגָנִים כְּמוֹ חֹמֶר וּכְמוֹ יוֹצֵר יִרְמָס טִיט. בּא רְאֵה כַּמָּה בְּנֵי אָדָם הֵם טִפְּשִׁים שֶׁאֵין יוֹדְעִים וְאֵין מִסְתַּכְּלִים לָדַעַת דִּבְרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁהִנֵּה כֻּלָּם יְשֵׁנִים, שֶׁאֵין מִתְעוֹרְרִים, וְשֵׁנָה בְּנִקְבֵי עֵינֵיהֶם.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הָאָדָם כְּמוֹ שֶׁלְּמַעְלָה, הַכֹּל הוּא בְּחָכְמָה, וְאֵין לְךְ אֵיבָר וְאֵיבָר בָּאָדָם שֶׁאֵינוֹ עוֹמֵד בְּחָכְמָה עֶלְיוֹנָה. שֶׁהֲרֵי כֵּיוָן שֶׁנִּתְקַן כָּל הַגּוּף בְּאֵיבָרָיו כָּרָאוּי, הַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁתַּתֵּף (התחזק) עִמּוֹ וְהִכְנִיס בּוֹ נְשָׁמָה קְדוֹשָׁה כְּדֵי לְלַמֵּד אֶת הָאָדָם לָלֶכֶת בְּדַרְכֵי הַתּוֹרָה וְלִשְׁמֹר מִצְווֹתָיו, כְּדֵי שֶׁאָדָם יִתְתַּקֵּן כָּרָאוּי.</p>\n<p>(ומשום זה) (ובעוד) שֶׁיֵּשׁ בּוֹ נְשָׁמָה קְדוֹשָׁה, צָרִיךְ לָאָדָם לְהַגְדִּיל אֶת דְּמוּת הַמֶּלֶךְ הָעֶלְיוֹן בָּעוֹלָם. וְסוֹד זֶה, שֶׁהֲרֵי אוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא לֹא פוֹסְקִים מֵימָיו לְעוֹלָמִים, וְעַל זֶה צָרִיךְ לָאָדָם שֶׁלֹּא יַפְסִיק אֶת הַנָּהָר וְהַמָּקוֹר שֶׁלּוֹ בָּעוֹלָם הַזֶּה. (נה\"ר רמז לברית הקדש שחתום בבשרו, שהוא דגמא של אותו הנה\"ר הסוד של צדיק שמתחבר עם צד\"ק יחד למעלה, משום כך צריך אדם למטה להתחבר עם אשתו בקדשה כדי שיתחזק באותו העולם,) וְכָל זְמַן שֶׁאָדָם לֹא יַצְלִיחַ בָּעוֹלָם הַזֶּה (ס\"א ועל כן צריך לאדם שלא יפסיק את הנהר והמקור שלו בעולם הזה, ואם לא) הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹקֵר אוֹתוֹ וְנוֹטֵעַ אוֹתוֹ בְּכַמָּה פְעָמִים כְּמוֹ מִקֹּדֶם.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, הַעִירוֹתִי מִצָּפוֹן וַיַּאת. הַעִירוֹתִי - זוֹ הַהִתְעוֹרְרוּת שֶׁל הַזִּוּוּג שֶׁל הָאָדָם בָּעוֹלָם הַזֶּה, שֶׁהִיא הִתְעוֹרְרוּת מִצַּד הַצָּפוֹן. וַיַּאת - זוֹ הִיא הַנְּשָׁמָה הַקְּדוֹשָׁה שֶׁבָּאָה מִלְמַעְלָה, וְהַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹלֵחַ אוֹתָהּ מִלְמַעְלָה, בָּאָה לָעוֹלָם הַזֶּה וְנִכְנֶסֶת לְתוֹךְ בְּנֵי אָדָם, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>מִמִּזְרַח שֶׁמֶשׁ - זֶה הַמָּקוֹם שֶׁל אוֹתוֹ הַנָּהָר שֶׁשּׁוֹפֵעַ וְיוֹצֵא, שֶׁמִּשָּׁם יוֹצֵאת הַנְּשָׁמָה וּמְאִירָה. וְיָבֹא סְגָנִים (כמו חמר) - אֵלּוּ הֵם חֵילוֹת הָעוֹלָם שֶׁבָּאִים מִשּׁוּם (בתוך) אוֹתָהּ הַהִתְעוֹרְרוּת שֶׁל הַנְּשָׁמוֹת. כְּמוֹ חֹמֶר - כְּמוֹ שֶׁמִּתְעוֹרֵר אָדָם בַּגּוּף.</p>\n<p>שֶׁהֲרֵי מִשּׁוּם זֶה הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה זִוּוּגִים וּמַטִּיל נְשָׁמוֹת בָּעוֹלָם, וְנִמְצֵאת חֲבֵרוּת לְמַעְלָה וּלְמַטָּה, וְהַמָּקוֹר שֶׁל הַכֹּל הוּא (ס\"א יהיה) בָּרוּךְ. וּמִשּׁוּם כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה אֶת הָאָדָם, כְּדֵי לְהִשְׁתַּדֵּל בִּדְרָכָיו, וְלֹא יַפְסִיק אֶת מְקוֹרוֹ וּמַעְיָנוֹ לְעוֹלָמִים. וְכָל מִי שֶׁמַּפְסִיק מְקוֹרוֹ (מלמטה ומיבש אותו, כביכול גורם להפסק למעלה, אז (איוב יד) אזלו מים מני ים ונהר יחרב ויבש, והואיל ובן אדם הוקם למטה כדגמא שלמעלה מי שמקורו ימיש מעשות פרות, כמו זה שלא רצה לשא אשה, או שנשא אותה והשתדל ולא יכל, אלו ששני הפכים הם זה מזה, (או אותו) שימיש מעשות פרות, אין לו תקנה לעולם, (קהלת א) מעות לא יוכל לתקן, משום שלא רצה לשא אשה ולהשתדל בפריה ורביה, ואותו שהשתדל ונשא אשה ולא יכל, זה מתקן בגואלו שקרוב לו, שהוא אחיו של אותו מת בלי בנים). כְּשֶׁיּוֹצֵא מִן הָעוֹלָם הַזֶּה, אוֹתוֹ הָאִישׁ לֹא נִכְנָס לַפַּרְגּוֹד וְלֹא נוֹטֵל חֵלֶק בָּעוֹלָם הַהוּא (ונשמתו לא נכללת במקום שכל הנשמות נכללו, ונגזרת דמותו משם, זהו שכתוב ונכרתה הנפש ההיא מלפני, הואיל וכך הוא, בורא לו הקדוש ברוך הוא גואל שיגאלנו מיד המשחיתים, וזה אחיו שקרוב אליו, שנאמר (דברים כה) כי ישבו אחים יחדו וגו', וכתוב בא אל אשת אחיך ויבם אתה וגו', משום שנשמתו לא נכנסת לפני הקדוש ברוך הוא, אלא היא עומדת בחוץ, משום שלא זכה להאיר בעולם הזה בגוף ההוא, מי שלא זוכה במקום הזה, ילך למקום אחר ויזכה בו, כמו כן עץ שדולק ואורו לא עולה, יכו אותו ויעלה בו אור ויאיר, עץ הוא אדם, שכתוב (שם כ) כי האדם עץ השדה, רוצה לומר, שהאדם כשהוא בעולם הזה והולך ותאב ואוכל ושותה ומזדוג עם אשה ולא זוכה לבנים, זהו עץ שדולק ואורו לא עולה, כלומר, נשמתו לא זוכה באותו הגוף להיות מוארת, אלא היא בחשכה),</p>\n<p>בֹּא רְאֵה, כָּתוּב (ישעיה מה) לֹא תֹהוּ בְּרָאָהּ לָשֶׁבֶת יְצָרָהּ, שֶׁמִּשּׁוּם כָּךְ עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָאָדָם כָּרָאוּי, כְּמוֹ שֶׁאָמַרְנוּ, וְהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד עִם הָעוֹלָם בּא רְאֵה מַה כָּתוּב, (בראשית כה) וַיֹּסֶף אַבְרָהָם וַיִּקַּח אִשָּׁה וּשְׁמָהּ קְטוּרָה. סוֹד הַנְּשָׁמָה שֶׁבָּאָה לְהִתְתַּקֵּן כְּמוֹ מִקֹּדֶם.</p>\n<p>בֹּא רְאֵה בְּאוֹתוֹ הַגּוּף מַה כָּתוּב, (ישעיה נג) וַה' חָפֵץ דַּכְּאוֹ הֶחֱלִי אִם תָּשִׂים אָשָׁם נַפְשׁוֹ יִרְאֶה זֶרַע יַאֲרִיךְ יָמִים וְחֵפֶץ ה' בְּיָדוֹ יִצְלָח. וַה' חָפֵץ דַּכְּאוֹ, בַּפָּסוּק הַזֶּה יֵשׁ לְהִסְתַּכֵּל, לָמָּה חָפֵץ? כְּדֵי שֶׁיִּטְהַר. אִם תָּשִׂים אָשָׁם - הָיָה צָרִיךְ לִהְיוֹת אִם יָשִׂים אָשָׁם! מַה זֶּה אִם תָּשִׂים? אֶלָּא עַל הַנְּשָׁמָה חוֹזֵר הַדָּבָר. אִם הַנְּשָׁמָה הַהִיא רוֹצָה לְהִתְתַּקֵּן כָּרָאוּי - יִרְאֶה זֶרַע, מִשּׁוּם שֶׁאוֹתָהּ הַנְּשָׁמָה הוֹלֶכֶת וּמְשׁוֹטֶטֶת וּמְזֻמֶּנֶת לְהִכָּנֵס לְאוֹתוֹ הַזֶּרַע שֶׁהִתְעַסֵּק בָּהּ הָאָדָם בִּפְרִיָּה וּרְבִיָּה, וְאָז יַאֲרִיךְ יָמִים, וְחֵפֶץ ה' - זוֹ הַתּוֹרָה - בְּיָדוֹ יִצְלָח.</p>\n<p>בֹּא רְאֵה, אַף עַל גַּב שֶׁאָדָם מִשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה וּמְקוֹרוֹ וּמַעְיָנוֹ עוֹמֵד בּוֹ לְחִנָּם, אֵין לוֹ מָקוֹם לְהִכָּנֵס לַפַּרְגּוֹד. וַהֲרֵי נֶאֱמַר שֶׁבְּאֵר הַמַּיִם, אִם לֹא נִכְנָס בָּהּ אוֹתוֹ הַמָּקוֹר וְהַמַּעְיָן, אֵינָהּ בְּאֵר, שֶׁהַבְּאֵר וְהַמָּקוֹר הֵם יַחַד וְהֵם סוֹד אֶחָד, וּבֵאַרְנוּ.</p>\n<p>כָּתוּב (תהלים קכז) שָׁוְא לָכֶם מַשְׁכִּימֵי קוּם מְאַחֲרֵי שֶׁבֶת אֹכְלֵי לֶחֶם הָעֲצָבִים כֵּן יִתֵּן לִידִידוֹ שֵׁנָא. בֹּא רְאֵה כַּמָּה הֵם חֲבִיבִים דִּבְרֵי הַתּוֹרָה, שֶׁבְּכָל דָּבָר וְדָבָר בַּתּוֹרָה יֵשׁ בּוֹ סוֹדוֹת עֶלְיוֹנִים קְדוֹשִׁים, וַהֲרֵי נֶאֱמַר שֶׁכַּאֲשֶׁר נָתַן הַקָּדוֹשׁ בָּרוּךְ הוּא הַתּוֹרָה לְיִשְׂרָאֵל, אֶת כָּל הַגְּנָזִים הָעֶלְיוֹנִים הַקְּדוֹשִׁים כֻּלָּם נָתַן לָהֶם (וכלם) בַּתּוֹרָה, וְכֻלָּם נִתְּנוּ לְיִשְׂרָאֵל בְּשָׁעָה שֶׁקִּבְּלוּ הַתּוֹרָה בְּסִינַי.</p>\n<p>בֹּא רְאֵה, שָׁוְא לָכֶם מַשְׁכִּימֵי קוּם - אֵלּוּ הֵם הַיְחִידִים שֶׁנִּמְצָאִים, שֶׁאֵינָם זָכָר וּנְקֵבָה כָּרָאוּי, וּמַקְדִּימִים בַּבֹּקֶר לַעֲבוֹדָתָם, כְּמוֹ שֶׁנֶּאֱמַר (קהלת ד) יֵשׁ אֶחָד וְאֵין שֵׁנִי וְגוֹ', וְאֵין קֵץ לְכָל עֲמָלוֹ. מְאַחֲרֵי שֶׁבֶת - מְאַחֲרִים הַמְּנוּחָה, כְּמוֹ שֶׁנֶּאֱמַר כִּי בוֹ שָׁבַת, מִשּׁוּם שֶׁהָאִשָּׁה אֶל הָאָדָם הִיא נַחַת וַדַּאי אֶצְלוֹ.</p>\n<p>אֹכְלֵי לֶחֶם הָעֲצָבִים, מַה זֶּה לֶחֶם הָעֲצָבִים? שֶׁכַּאֲשֶׁר לָאָדָם יֵשׁ בָּנִים, אוֹתוֹ הַלֶּחֶם שֶׁאוֹכֵל, אוֹכֵל אוֹתוֹ בְּשִׂמְחָה וּבִרְצוֹן הַלֵּב. וְזֶה שֶׁאֵין לוֹ בָּנִים, אוֹתוֹ לֶחֶם שֶׁאוֹכֵל הוּא לֶחֶם שֶׁל עֶצֶב, וְאֵלּוּ הֵם אֹכְלֵי לֶחֶם הָעֲצָבִים וַדַּאי.</p>\n<p>כֵּן יִתֵּן לִידִידוֹ שֵׁנָא, מַה זֶּה יִתֵּן לִידִידוֹ? זֶהוּ שֶׁמְּקוֹרוֹ מְבֹרָךְ, שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן לוֹ שֵׁנָה בָּעוֹלָם הַהוּא, כְּמוֹ שֶׁנֶּאֱמַר (משלי ג) וְשָׁכַבְתָּ וְעָרְבָה שְׁנָתֶךְ, מִשּׁוּם שֶׁיֵּשׁ לוֹ חֵלֶק בָּעוֹלָם הַבָּא, כְּדֵי שֶׁאוֹתוֹ הָאִישׁ יִשְׁכַּב וְיֵהָנֶה בָּעוֹלָם הַבָּא הַהוּא כָּרָאוּי.</p>\n<p>יִשִׁ אֶחָד וְאֵין שֵׁנִי וְגוֹ', יֵשׁ אֶחָד - זֶהוּ אָדָם שֶׁהוּא יְחִידִי בָּעוֹלָם, לֹא יְחִידִי כָּרָאוּי, אֶלָּא שֶׁהוּא בְּלִי זִוּוּג. וְאֵין שֵׁנִי - שֶׁאֵין עִמּוֹ סֶמֶךְ. גַּם בֵּן - שֶׁיָּקִים שְׁמוֹ בְּיִשְׂרָאֵל לֹא הִשְׁאִיר. וָאָח אֵין לוֹ - שֶׁיָּבִיא אוֹתוֹ לְתִקּוּן.</p>\n<p>וְאֵין קֵץ לְכָל עֲמָלוֹ - שֶׁהוּא עָמֵל תָּמִיד, שֶׁמַּקְדִּים יוֹם וָלַיְלָה. גַּם עֵינוֹ לֹא תִשְׂבַּע עֹשֶׁר - וְאֵין לוֹ לֵב לְהַשְׁגִּיחַ וְלוֹמַר, לְמִי אֲנִי עָמֵל וּמְחַסֵּר אֶת נַפְשִׁי מִטּוֹבָה. וְאִם תֹּאמַר שֶׁכְּדֵי שֶׁיּאכַל וְיִשְׁתֶּה יוֹתֵר וְיַעֲשֶׂה מִשְׁתֶּה בְּכָל יוֹם תָּמִיד - לֹא כָּךְ, שֶׁהֲרֵי הַנֶּפֶשׁ אֵינָהּ נֶהֱנֵית מִמֶּנּוּ. אֶלָּא וַדַּאי הוּא מְחַסֵּר אֶת נַפְשׁוֹ מִטּוֹב שֶׁל הָאוֹר שֶׁל הָעוֹלָם הַבָּא מִשּׁוּם שֶׁזּוֹהִי נֶפֶשׁ חֲסֵרָה, שֶׁלֹּא הֻשְׁלְמָה כָּרָאוּי. בֹּא רְאֵה כַּמָּה חָס הַקָּדוֹשׁ בָּרוּךְ הוּא עַל מַעֲשָׂיו, מִשּׁוּם שֶׁרוֹצֶה שֶׁיֶּתֻקַּן וְלֹא יֹאבַד מֵאוֹתוֹ הָעוֹלָם הַבָּא, כְּמוֹ שֶׁאָמַרְנוּ.</p>\n<p>רַבִּי חִיָּיא שָׁאַל, זֶה שֶׁהוּא צַדִּיק שָׁלֵם וּמִשְׁתַּדֵּל בַּתּוֹרָה יָמִים וְלֵילוֹת וְכָל מַעֲשָׂיו לִשְׁמוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא וְלֹא זָכָה לְבָנִים בָּעוֹלָם הַזֶּה, כְּמוֹ שֶׁהִשְׁתַּדֵּל בָּהֶם וְלֹא זָכָה, אוֹ שֶׁהָיוּ לוֹ וּמֵתוּ - מַה הֵם לָעוֹלָם הַבָּא? אָמַר לוֹ רַבִּי יוֹסֵי, מַעֲשָׂיו וְהַתּוֹרָה הַהִיא מְגִנִּים עָלָיו לָעוֹלָם הַהוּא.</p>\n<p>אָמַר רַבִּי יִצְחָק, עֲלֵיהֶם וְעַל אוֹתָם צַדִּיקֵי הָאֱמֶת, (כמו רבי יוחנן שהיו לו בנים ומתו, וכמו רבי חזקיה שהוא עקר) עֲלֵיהֶם כָּתוּב (ישעיה נו) כֹּה אָמַר ה' לַסָּרִיסִים אֲשֶׁר יִשְׁמְרוּ אֶת שַׁבְּתוֹתַי וּבָחֲרוּ בַּאֲשֶׁר חָפַצְתִּי וּמַחֲזִיקִים בִּבְרִיתִי. מַה כָּתוּב אַחֲרָיו? וְנָתַתִּי לָהֶם בְּבֵיתִי וּבְחוֹמֹתַי יָד וָשֵׁם טוֹב מִבָּנִים וּמִבָּנוֹת שֵׁם עוֹלָם אֶתֶּן לוֹ אֲשֶׁר לֹא יִכָּרֵת, מִשּׁוּם שֶׁלְּאֵלֶּה יֵשׁ חֵלֶק לָעוֹלָם הַבָּא. אָמַר לוֹ רַבִּי יוֹסֵי, נָאֶה הוּא וְיָפֶה.</p>\n<p>בֹּא רְאֵה, צַדִּיק שָׁלֵם שֶׁהָיוּ בוֹ כָּל אֵלֶּה וְהֻשְׁלַם כָּרָאוּי וּמֵת בְּלִי בָנִים, וְהִנֵּה יוֹרֵשׁ מְקוֹמוֹ בָּעוֹלָם הַהוּא - הַאִם אִשְׁתּוֹ צְרִיכָה יִבּוּם אוֹ לֹא? אִם תֹּאמַר שֶׁצְּרִיכָה לְהִתְיַבֵּם, הֲרֵי זֶה לְרֵיקָנוּת, שֶׁהֲרֵי אֶת מְקוֹמוֹ יָרַשׁ בָּעוֹלָם הַהוּא.</p>\n<p>אֶלָּא וַדַּאי צְרִיכָה לְיִבּוּם, מִשּׁוּם שֶׁאֵינֶנּוּ יוֹדְעִים אִם הָיָה שָׁלֵם בְּמַעֲשָׂיו וְאִם לֹא. וְאִם הִיא מִתְיַבֶּמֶת, זֶה לֹא הָיָה בְּרֵיקָנוּת, מִשּׁוּם שֶׁיֵּשׁ מָקוֹם לַקָּדוֹשׁ-בָּרוּךְ- הוּא לָאִישׁ הַזֶּה שֶׁהָיָה בָּעוֹלָם וּמֵת בְּלִי בָנִים וְגוֹאֵל לֹא הָיָה לוֹ בָּעוֹלָם. כֵּיוָן שֶׁהַצַּדִּיק הַשָּׁלֵם הַזֶּה מֵת וְאִשְׁתּוֹ מִתְיַבֶּמֶת, וְהוּא יָרַשׁ אֶת מְקוֹמוֹ, בָּא הָאִישׁ הַהוּא וּמִשְׁתַּלֵּם כָּאן, וּבֵין כָּךְ וּבֵין כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא מַזְמִין לוֹ מָקוֹם לָעוֹלָם עַד שֶׁיָּמוּת הַצַּדִּיק הַשָּׁלֵם הַזֶּה וְהוּא יִשְׁתַּלֵּם בָּעוֹלָם. זֶהוּ שֶׁכָּתוּב (במדבר לב) כִּי בְעִיר מִקְלָטוֹ יֵשֵׁב עַד מוֹת הַכֹּהֵן הַגָּדוֹל וְגוֹ'.</p>\n<p>וְזְהִוּ שֶׁשָּׁנִינוּ, בָּנִים מְזֻמָּנִים לַצַּדִּיקִים בְּמִיתָתָם. בְּחַיֵּיהֶם לֹא זָכוּ, וּבְמִיתָתָם זָכוּ. וּמִשּׁוּם כָּךְ כָּל מַעֲשָׂיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא כֻּלָּם אֱמֶת וּזְכוּת, (וחס) וְחַיִּים עַל הַכֹּל.</p>\n<p>(קהלת ד) טוֹבִים הַשְּׁנַיִם מִן הָאֶחָד אֲשֶׁר יֵשׁ לָהֶם שָׂכָר טוֹב בַּעֲמָלָם - אֵלּוּ הֵם שֶׁמִּתְעַסְּקִים בָּעוֹלָם הַזֶּה לְהוֹלִיד בָּנִים, שֶׁאוֹתָם בָּנִים שֶׁהִשְׁאִירוּ, בִּגְלָלָם יֵשׁ לָהֶם שָׂכָר טוֹב בָּעוֹלָם הַזֶּה וּבִגְלָלָם יוֹרְשִׁים אֲבוֹתֵיהֶם חֵלֶק בָּעוֹלָם הַהוּא, וּבֵאֲרוּהוּ.</p>\n<p>בֹּא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹטֵעַ אִילָנוֹת בָּעוֹלָם הַזֶּה. אִם הִצְלִיחוּ - יָפֶה. לֹא הִצְלִיחוּ - עוֹקֵר אוֹתָם וְשׁוֹתֵל אוֹתָם אֲפִלּוּ כַּמָּה פְעָמִים, וּמִשּׁוּם כָּךְ כָּל דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הֵן לְטוֹב וּלְתַקֵּן אֶת הָעוֹלָם.</p>\n<p>בֹּא אֶל אֵשֶׁת אָחִיךְ וְיַבֵּם אֹתָהּ. שֶׁהֲרֵי יְהוּדָה וְכָל הַשְּׁבָטִים הָיוּ יוֹדְעִים אֶת זֶה וְעִקַּר הַדָּבָר וְהָקֵם זֶרַע, מִשּׁוּם שֶׁאוֹתוֹ הַזֶּרַע צָרִיךְ לְהִתְתַּקֵּן הַדָּבָר וְלִגְלֹם גֹּלֶם לְתִקּוּן שֶׁלֹּא יִפָּרֵד הַזֶּרַע מִשָּׁרְשׁוֹ כָּרָאוּי, זֶהוּ שֶׁכָּתוּב (איוב לד) וְאָדָם עַל עָפָר יָשׁוּב.</p>\n<p>וּכְשֶׁנִּתְקָן אַחַר כָּךְ כָּרָאוּי, אֵלּוּ מִשְׁתַּבְּחִים בָּעוֹלָם הַהוּא, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהֶם, וּמִשּׁוּם כָּךְ כָּתוּב (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, דַּוְקָא, מִן הַחַיִּים אֲשֶׁר הֵם חַיִּים עֲדֶנָה. מַה זֶּה עֲדֶנָה? כְּמוֹ שֶׁנֶּאֱמַר (בראשית יח) אַחֲרֵי בְלֹתִי הָיְתָה לִּי עֶדְנָה, וְכָתוּב (איוב לג) יָשׁוּב לִימֵי עֲלוּמָיו.</p>\n<p>וְטוֹב מִשְּׁנֵיהֶם אֵת אֲשֶׁר עֲדֶן לֹא הָיָה (שלא שב לימי עלומיו) אֲשֶׁר לֹא רָאָה אֶת הַמַּעֲשֶׂה הָרָע אֲשֶׁר נַעֲשָׂה תַּחַת הַשָּׁמֶשׁ. וְטוֹב מִשְּׁנֵיהֶם אֵת אֲשֶׁר עֲדֶן לֹא הָיָה, שֶׁלֹּא שָׁב לִימֵי עֲלוּמָיו וְלֹא צָרִיךְ לְהִתְתַּקֵּן וְלֹא סוֹבֵל חֲטָאִים רִאשׁוֹנִים, מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא נָתַן לוֹ מָקוֹם מְתֻקָּן בָּעוֹלָם הַהוּא כָּרָאוּי.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב? (קהלת ח) וּבְכֵן רָאִיתִי רְשָׁעִים קְבֻרִים וְגוֹ', כְּמוֹ שֶׁנֶּאֱמַר מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה חֶסֶד וְלֹא רוֹצֶה לְכַלּוֹת אֶת הָעוֹלָם, אֶלָּא כְּמוֹ שֶׁנִּתְבָּאֵר, וְכָל דְּרָכָיו כֻּלָּם אֱמֶת וּזְכוּת לְהֵיטִיב לָהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהֵם הוֹלְכִים בְּדֶרֶךְ הָאֱמֶת, עֲלֵיהֶם כָּתוּב (תהלים לז) צַדִּיקִים יִירְשׁוּ אָרֶץ.</p>"],[9522011387,"<p>וַיֵּרַע בְּעֵינֵי ה' אֲשֶׁר עָשָׂה וַיָּמֶת גַּם אֹתוֹ. רַבִּי חִיָּיא פָּתַח, (קהלת יא) בַּבֹּקֶר זְרַע אֶת זַרְעֶךְ וְלָעֶרֶב אַל תַּנַּח יָדֶךְ וְגוֹ'. בֹּא רְאֵה כַּמָּה רָאוּי לָאָדָם לְהִזָּהֵר מֵחֲטָאָיו וּלְהִזָּהֵר בְּמַעֲשָׂיו לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, מִשּׁוּם שֶׁכַּמָּה שְׁלוּחִים וְכַמָּה מְמֻנִּים הֵם בָּעוֹלָם שֶׁהֵם הוֹלְכִים וּמְשׁוֹטְטִים וְרוֹאִים אֶת מַעֲשֵׂי בְּנֵי הָאָדָם וּמְעִידִים עָלָיו (ז\"ח עליהם), וְהַכֹּל כְּתוּבִים בַּסֵּפֶר.</p>\n<p>וּבֹא וּרְאֵה, בְּכָל אוֹתָם הַחֲטָאִים שֶׁנִּטְמָא בָהֶם הָאָדָם יוֹתֵר בָּעוֹלָם הַזֶּה, זֶהוּ חֵטְא שֶׁנִּטְמָא בוֹ אָדָם יוֹתֵר בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא - מִי שֶׁשּׁוֹפֵךְ זַרְעוֹ לָרִיק וּמוֹצִיא זֶרַע לְחִנָּם בַּיָּד אוֹ בָרֶגֶל וְנִטְמָא בּוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים ה) כִּי לֹא אֵל חָפֵץ רֶשַׁע אָתָּה לֹא יְגֻרְךְ רָע.</p>\n<p>בִּגְלַל זֶה לֹא נִכְנָס לַמְּחִצָּה וְלֹא רוֹאֶה תֹּאַר פָּנָיו שֶׁל עַתִּיק יוֹמִין, כְּמוֹ שֶׁלָּמַדְנוּ, כָּתוּב כָּאן לֹא יְגֻרְךְ רָע, וְכָתוּב וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה', וּמִשּׁוּם כָּךְ כָּתוּב (ישעיה א) יְדֵיכֶם דָּמִים מָלֵאוּ. אַשְׁרֵי חֶלְקוֹ שֶׁל הָאִישׁ שֶׁיָּרֵא מֵרִבּוֹנוֹ וְיִהְיֶה שָׁמוּר מִדֶּרֶךְ רָעָה, וִיטַהֵר עַצְמוֹ לְהִשְׁתַּדֵּל בְּיִרְאַת רִבּוֹנוֹ.</p>\n<p>בֹּא רְאֵה, בַּבּקֶר זְרַע (את) זַרְעֶךְ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, בַּבֹּקֶר - זֶהוּ בִּזְמַן שֶׁאָדָם עוֹמֵד בְּכֹחוֹ וְיִהְיֶה בַּעֲלוּמָיו, אָז יִשְׁתַּדֵּל לְהוֹלִיד בָּנִים עִם אִשָּׁה שֶׁרְאוּיָה לוֹ, שֶׁכָּתוּב בַּבֹּקֶר זְרַע אֶת זַרְעֶךְ.</p>\n<p>שֶׁהֲרֵי אָז הוּא הַזְּמַן, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קכז) כְּחִצִּים בְּיַד גִּבּוֹר כֵּן בְּנֵי הַנְּעוּרִים, מִשּׁוּם שֶׁיָּכוֹל לְלַמֵּד אוֹתָם דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְיִהְיֶה לוֹ שָׂכָר טוֹב לָעוֹלָם הַבָּא, שֶׁכָּתוּב אַשְׁרֵי הַגֶּבֶר אֲשֶׁר מִלֵּא אֶת אַשְׁפָּתוֹ מֵהֶם לֹא יֵבוֹשׁוּ כִּי יְדַבְּרוּ אֶת אוֹיְבִים בַּשַּׁעַר. לֹא יֵבוֹשׁוּ - בָּעוֹלָם הַהוּא, בִּזְמַן שֶׁבַּעֲלֵי הַדִּין יָבוֹאוּ לְקַטְרֵג עָלָיו, שֶׁאֵין לְךְ שָׂכָר טוֹב בָּעוֹלָם הַהוּא כְּמוֹ הַהוּא שֶׁמְּלַמֵּד אֶת בְּנוֹ יִרְאַת רִבּוֹנוֹ בְּדַרְכֵי הַתּוֹרָה.</p>\n<p>בֹּא רְאֵה מָה אָמַר בְּאַבְרָהָם, שֶׁכָּתוּב (בראשית יח) כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה אֶת בָּנָיו וְאֶת בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶּרֶךְ ה' לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט, וְעַל כֵּן אוֹתָהּ הַזְּכוּת קַיֶּמֶת לוֹ בָּעוֹלָם הַהוּא אֵצֶל כָּל בַּעֲלֵי הַדִּין.</p>\n<p>וּמִשּׁוּם כָּךְ בַּבֹּקֶר זְרַע אֶת זַרְעֶךְ, וְלָעֶרֶב אַל תַּנַּח יָדֶךְ - אֲפִלּוּ בִּימֵי הַזִּקְנָה, שֶׁהוּא הַזְּמַן שֶׁאָדָם זָקֵן, (לא יאמר כבר השתדלתי ודי לי, או כבר השתדלתי ואיני יכול, וכעת שאני זקן איני רוצה, ועם כל זה) מַה כָּתוּב? אַל תַּנַּח יָדֶךְ. לֹא יַנִּיחַ מִלְּהוֹלִיד בָּעוֹלָם הַזֶּה. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא תֵדַע אֵיזֶה יִכְשַׁר הֲזֶה אוֹ זֶה. לִפְנֵי הָאֱלֹהִים - כְּדֵי שֶׁיַּעַמְדוּ בִּשְׁבִילוֹ בָּעוֹלָם הַהוּא.</p>\n<p>וְעַל כֵּן כָּתוּב (תהלים קכז) הִנֵּה נַחֲלַת ה' בָּנִים. זֶהוּ צְרוֹר הַנְּשָׁמוֹת, הַצַּד שֶׁל הָעוֹלָם הַבָּא. וְלַנַּחֲלָה הַזּוֹ, מִי מְזַכֶּה אֶת הָאָדָם לְהִכָּנֵס לְאוֹתָהּ נַחֲלַת ה'? הַבָּנִים. אוֹתָם הַבָּנִים מְזַכִּים אוֹתוֹ לְנַחֲלַת ה', וְעַל כֵּן אַשְׁרֵי אוֹתוֹ הָאִישׁ שֶׁמְּזַכֶּה אוֹתָם לְלַמֵּד אוֹתָם דַּרְכֵי הַתּוֹרָה כְּמוֹ שֶׁנִּתְבָּאֵר.</p>"],[9522011388,"<p>וַתָּסַר בִּגְדֵי אַלְמְנוּתָהּ מֵעָלֶיהָ וְגוֹ'. בֹּא רְאֵה, תָּמָר הָיְתָה בַּת כֹּהֵן, וְכִי תַעֲלֶה עַל דַּעְתְּךְ שֶׁהִיא הָלְכָה כְּדֵי לִזְנוֹת עִם חָמִיהָ? שֶׁהֲרֵי הִיא, צְנִיעוּת נִמְצְאָה בָּהּ תָּמִיד. אֶלָּא הִיא הָיְתָה צַדֶּקֶת, וּבְחָכְמָה עָשְׂתָה אֶת זֶה, שֶׁהֲרֵי הִיא לֹא הִפְקִירָה אֶת עַצְמָהּ אֵלָיו, אֶלָּא מִשּׁוּם שֶׁיָּדְעָה יְדִיעָה וּבְחָכְמָה הִתְבּוֹנְנָה, וְעַל כֵּן הִיא בָּאָה אֵלָיו לַעֲשׂוֹת (עמו) חֶסֶד וֶאֱמֶת, וְעַל זֶה בָּאָה (בפרהסיא) וְהִשְׁתַּדְּלָה בָּעֵסֶק הַזֶּה.</p>\n<p>בֹּא רְאֵה, מִשּׁוּם שֶׁהִיא יָדְעָה יְדִיעָה וְהִשְׁתַּדְּלָה בְּעֵסֶק זֶה, הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה שָׁם סִיּוּעַ בַּמַּעֲשֶׂה הַהוּא וּמִיָּד הִתְעַבְּרָה, וְהַכֹּל הָיָה מִמֶּנּוּ. וְאִם תֹּאמַר, לָמָּה לֹא הֵבִיא הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתָם בָּנִים מֵאִשָּׁה אַחֶרֶת? לָמָּה מִזּוֹ? אֶלָּא וַדַּאי שֶׁהִיא הֻצְרְכָה לַמַּעֲשֶׂה הַזֶּה וְלֹא אִשָּׁה אַחֶרֶת.</p>\n<p>שְׁתֵּי נָשִׁים הָיוּ שֶׁמֵּהֶן נִבְנָה הַזֶּרַע שֶׁל יְהוּדָה, וּבָאוּ מֵהֶן דָּוִד הַמֶּלֶךְ וּשְׁלֹמֹה הַמֶּלֶךְ וּמֶלֶךְ הַמָּשִׁיחַ, וּשְׁתֵּי הַנָּשִׁים הַלָּלוּ זוֹ כְּמוֹ זוֹ, תָּמָר וְרוּת שֶׁמֵּתוּ בַּעְלֵיהֶן בָּרִאשׁוֹנָה, וְהֵן הִשְׁתַּדְּלוּ לַמַּעֲשֶׂה הַזֶּה.</p>\n<p>תָּמָר הִשְׁתַּדְּלָה אֵצֶל חָמִיהָ, שֶׁהוּא יוֹתֵר קָרוֹב לְבָנָיו שֶׁמֵּתוּ. מָה הַטַּעַם הִיא הִשְׁתַּדְּלָה אֶצְלוֹ? שֶׁכָּתוּב כִּי רָאֲתָה כִּי גָדַל שֵׁלָה וְהִיא לֹא נִתְּנָה לוֹ לְאִשָּׁה, וּמִשּׁוּם זֶה הִשְׁתַּדְּלָה בַּמַּעֲשֶׂה הַזֶּה אֵצֶל חָמִיהָ.</p>\n<p>רוּת מֵת בַּעְלָהּ, וְאַחַר כָּךְ הִשְׁתַּדְּלָה בַּמַּעֲשֶׂה הַזֶּה אֵצֶל בֹּעַז, שֶׁכָּתוּב (רות ג) וַתְּגַל מַרְגְּלֹתָיו וַתִּשְׁכָּב, וְהִשְׁתַּדְּלָה עִמּוֹ, וְאַחַר כָּךְ הוֹלִידָה אֶת עוֹבֵד. וְאִם תֹּאמַר, לָמָּה לֹא יָצָא עוֹבֵד מֵאִשָּׁה אַחֶרֶת? אֶלָּא וַדַּאי הִיא הֻצְרְכָה וְלֹא אִשָּׁה אַחֶרֶת. וּמִשְּׁתֵּי אֵלּוּ נִבְנָה וְנִתְקַן זַרְעוֹ שֶׁל יְהוּדָה, וּשְׁתֵּיהֶן עָשׂוּ בְּכַשְׁרוּת, לַעֲשׂוֹת חֶסֶד עִם אוֹתָם הַמֵּתִים לְתַקֵּן אֶת הָעוֹלָם לְאַחַר מִכֵּן.</p>\n<p>וְזְהִוּ כְּמוֹ שֶׁנֶּאֱמַר (קהלת ד) וְשַׁבֵּחַ אֲנִי אֶת הַמֵּתִים שֶׁכְּבָר מֵתוּ, שֶׁהֲרֵי כְּשֶׁהָיוּ חַיִּים בַּהַתְחָלָה, לֹא הָיָה בָּהֶם שֶׁבַח (ז\"ח ואחר כך היה בהם שבח), וּשְׁתֵּיהֶן הִשְׁתַּדְּלוּ לַעֲשׂוֹת חֶסֶד וֶאֱמֶת עִם אוֹתָם הַמֵּתִים, וְהַקָּדוֹשׁ בָּרוּךְ הוּא סִיַּע בְּאוֹתוֹ הַמַּעֲשֶׂה וְהַכֹּל הָיָה כָּרָאוּי. אַשְׁרֵי הוּא מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה יוֹמָם וָלַיְלָה, כְּמוֹ שֶׁנֶּאֱמַר (יהושע א) וְהָגִיתָ בּוֹ יוֹמָם וָלָיְלָה לְמַעַן תִּשְׁמֹר לַעֲשׂוֹת כְּכָל הַכָּתוּב בּוֹ כִּי אָז תַּצְלִיחַ אֶת דְּרָכֶךְ וְגוֹ'.</p>"],[9522011389,"<p>וְיוֹסֵף הוּרַד מִצְרָיְמָה וַיִּקְנֵהוּ פּוֹטִיפַר וְגוֹ'. (מה כתוב למעלה? ויכר יהודה ויאמר, הוא אמר לאביו הכר נא וגו', ועל כן ויכר יהודה, וכתוב והנה תאומים בבטנה, תאומים היו מקדם לכן אחים היו, רבי חזקיה אמר, לא כך נשמע, אלא בנים אחרים נולדו, אמר רבי אבא, משום כך השתדלה למצא האבדה שנאבדה בא ראה מה כתוב, ויהי כמשיב ידו והנה יצא אחיו ותאמר מהפרצת עליך פרץ, רמז כאן התפרצות ראשונה שפרץ זה שמת עליו, ממשמע שכתוב פרצת עליך, התפרצות בגלל שהצטרכת להטריח לאדונך, ומשום כך התפרצות תעשה בשאר אמות עובדי עבודת כוכבים ומזלות, ועל זה ויקרא שמו פרץ, ולאחר שכל מעשה של יהודה נאמר שיהודה מכר לו ליוסף, והוא גרם לו לכל זה, שאם יהודה היה אומר נחזיר אותו לאבינו, היו עושים לו אחיו כך, ועל זה הורידו אותו אחיו משלטונו שעליהם, ולבסוף שגלה מאחיו ובא עליו כל זה, חזר ואמר ויוסף הורד מצרימה) מַה זֶּה הוּרַד? שֶׁהִסְכִּים הַקָּדוֹשׁ בָּרוּךְ הוּא לְאוֹתוֹ הַמַּעֲשֶׂה לְקַיֵּם אֶת הַגְּזֵרָה שֶׁלּוֹ שֶׁגָּזַר בֵּין הַבְּתָרִים, שֶׁכָּתוּב (בראשית טו) יָדוֹעַ תֵּדַע כִּי גֵר יִהְיֶה זַרְעֲךְ וְגוֹ'. וַיִּקְנֵהוּ פּוֹטִיפַר, לְצַד הַחֵטְא קָנָה אוֹתוֹ.</p>\n<p>פָּתַח וְאָמַר, (איוב ט) הָאֹמֵר לַחֶרֶס וְלֹא יִזְרָח וּבְעַד כּוֹכָבִים יַחְתֹּם. בֹּא רְאֵה, שִׁבְעָה כּוֹכָבִים עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא בָּרָקִיעַ, וּבְכָל רָקִיעַ וְרָקִיעַ יֵשׁ כַּמָּה שַׁמָּשִׁים מְמֻנִּים לְשִׁמּוּשׁוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>מִשּׁוּם שֶׁאֵין לְךְ שַׁמָּשׁ אוֹ מְמֻנֶּה שֶׁאֵין לוֹ עֲבוֹדָה וְשִׁמּוּשׁ לַאֲדוֹנוֹ, וְעוֹמְדִים כָּל אֶחָד וְאֶחָד עַל אוֹתוֹ הַשִּׁמּוּשׁ שֶׁנִּתְמַנָּה בוֹ, וְכָל אֶחָד יוֹדֵעַ עֲבוֹדָתוֹ לְשַׁמֵּשׁ.</p>\n<p>מֵהֶם שֶׁמְּשַׁמְּשִׁים בִּשְׁלִיחוּת רִבּוֹנָם וּמֻפְקָדִים בָּעוֹלָם עַל כָּל מַעֲשֵׂי בְּנֵי הָאָדָם, וּמֵהֶם שֶׁמְּשַׁבְּחִים אוֹתוֹ, וְהֵם (הרי) מֻפְקָדִים עַל הַשִּׁירָה. וְאַף עַל גַּב שֶׁהֵם מֻפְקָדִים עַל זֶה, אֵין לְךְ כָּל חַיִל בַּשָּׁמַיִם וְכוֹכָבִים וּמַזָּלוֹת שֶׁכֻּלָּם לֹא מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא.</p>\n<p>שֶׁהֲרֵי בְּשָׁעָה שֶׁנִּכְנָס הַלַּיְלָה, אָז נִפְרָדִים שְׁלֹשָׁה צְדָדִים מַחֲנוֹת לִשְׁלֹשֶׁת צִדְדֵי הָעוֹלָם, וּבְכָל צַד וְצַד אֶלֶף אֲלָפִים וְרִבּוֹא רְבָבוֹת, וְכֻלָּם מְמֻנִּים עַל הַשִּׁירָה.</p>\n<p>שְׁלשָה מַחֲנוֹת הֵם, וְחַיָּה קְדוֹשָׁה אַחַת מְמֻנָּה עֲלֵיהֶם וְעוֹמֶדֶת עֲלֵיהֶם, וְכֻלָּם מְשַׁבְּחִים אֶת הַקָּדוֹשׁ בָּרוּךְ הוּא עַד שֶׁבָּא הַבֹּקֶר. כְּשֶׁבָּא הַבֹּקֶר, כָּל אוֹתָם שֶׁבְּצַד דָּרוֹם וְכָל הַכּוֹכָבִים שֶׁמְּאִירִים, כֻּלָּם מְשַׁבְּחִים וְאוֹמְרִים שִׁירָה לַקָּדוֹשׁ-בָּרוּךְ-הוּא, כְּמוֹ שֶׁנֶּאֱמַר (איוב לח) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים. בְּרָן יַחַד כֹּכְבֵי בֹקֶר - אֵלּוּ הַכּוֹכָבִים שֶׁבְּצַד דָּרוֹם, כְּמוֹ שֶׁנֶּאֱמַר (בראשית יט) וַיַּשְׁכֵּם אַבְרָהָם</p>\n<p>בַּבּקֶר. וַיָּרִיעוּ כָּל בְּנֵי אֱלֹהִים - אֵלּוּ הֵם שֶׁבְּצַד שְׂמֹאל שֶׁנִּכְלְלוּ בַּיָּמִין. וְאָז מֵאִיר הַבּקֶר, וְיִשְׂרָאֵל נוֹשְׂאִים שִׁירָה וּמְשַׁבְּחִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא בַּיּוֹם, שָׁלֹשׁ פְּעָמִים בַּיּוֹם כְּנֶגֶד שָׁלֹשׁ פְּעָמִים שֶׁל הַלַּיְלָה, וְעוֹמְדִים אֵלֶּה כְּנֶגֶד אֵלֶּה, עַד שֶׁמִּתְעַלֶּה כְבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא בַּיּוֹם וּבַלַּיְלָה כָּרָאוּי, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה בַּשֵּׁשׁ הַלָּלוּ.</p>\n<p>אוֹתָהּ הַחַיָּה הַקְּדוֹשָׁה שֶׁעוֹמֶדֶת עֲלֵיהֶם לְמַעְלָה, עוֹמֶדֶת עַל יִשְׂרָאֵל לְמַטָּה כְּדֵי לְתַקֵּן הַכֹּל כָּרָאוּי. מַה כָּתוּב בָּהּ? (משלי לא) וַתָּקָם בְּעוֹד לַיְלָה וַתִּתֵּן טֶרֶף לְבֵיתָהּ וְחֹק לְנַעֲרֹתֶיהָ. וַתִּתֵּן טֶרֶף לְבֵיתָהּ - אֵלּוּ אוֹתָם הַמַּחֲנוֹת שֶׁלְּמַעְלָה. וְחֹק לְנַעֲרֹתֶיהָ - אֵלּוּ הַמַּחֲנוֹת שֶׁל יִשְׂרָאֵל לְמַטָּה. וּמִשּׁוּם כָּךְ כְּבוֹדוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא מִתְעַלֶּה מִכָּל הַצְּדָדִים, מִמַּעְלָה וּמִמַּטָּה, וְעַל כֵּן הַכֹּל הָיָה (הוא) עוֹמֵד בִּרְשׁוּתוֹ וְהַכֹּל הוּא בִּרְצוֹנוֹ.</p>\n<p>(איוב ט) הָאֹמֵר לַחֶרֶס וְלֹא יִזְרָח - רַבִּי שִׁמְעוֹן אָמַר זֶה יוֹסֵף. וּבְעַד כּוֹכָבִים יַחְתֹּם - אֵלּוּ הֵם אֶחָיו, שֶׁכָּתוּב בָּהֶם וְאַחַד עָשָׂר כּוֹכָבִים מִשְׁתַּחֲוִים לוֹ. דָּבָר אַחֵר, הָאֹמֵר לַחֶרֶס - זֶה יַעֲקֹב בְּשָׁעָה שֶׁאָמְרוּ לוֹ הַכֶּר נָא. וְלֹא יִזְרָח - בְּשָׁעָה שֶׁהִסְתַּלְּקָה מִמֶּנּוּ הַשְּׁכִינָה. וּבְעַד כּוֹכָבִים יַחְתֹּם - מִשּׁוּם בָּנָיו נֶחְתַּם וְנִסְתַּם הָאוֹר שֶׁלּוֹ, הַשֶּׁמֶשׁ חָשַׁךְ וְהַכּוֹכָבִים לֹא הֵאִירוּ, מִשּׁוּם שֶׁיּוֹסֵף נִפְרַד מֵאָבִיו. וּבֹא וּרְאֵה, מֵאוֹתוֹ הַיּוֹם שֶׁל אוֹתוֹ הַמַּעֲשֶׂה שֶׁל יוֹסֵף, נִפְרַד יַעֲקֹב מִשִּׁמּוּשׁ הַמִּטָּה, וְנִשְׁאַר אָבֵל עַד אוֹתוֹ הַיּוֹם שֶׁהִתְבַּשֵּׂר בְּשׂוֹרַת יוֹסֵף.</p>"],[9522011390,"<p>וַיְהִי ה' אֶת יוֹסֵף וַיְהִי אִישׁ מַצְלִיחַ וַיְהִי בְּבֵית אֲדנָיו וְגוֹ'. רַבִּי יוֹסֵי פָּתַח, (תהלים לז) כִּי ה' אֹהֵב מִשְׁפָּט וְלֹא יַעֲזֹב אֶת חֲסִידָיו לְעוֹלָם נִשְׁמָרוּ. הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ בְּאַבְרָהָם. אֶת חֲסִידָיו, כָּתוּב חֲסִידוֹ, וַהֲרֵי נִתְבָּאֵר.</p>\n<p>בֹּא רְאֵה, בְּכָל מָקוֹם שֶׁהַצַּדִּיקִים הוֹלְכִים, הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אוֹתָם וְלֹא עוֹזֵב אוֹתָם. דָּוִד אָמַר (שם כג) גַּם כִּי אֵלֵךְ בְּגֵיא צַלְמָוֶת לֹא אִירָא רָע כִּי אַתָּה עִמָּדִי שִׁבְטְךְ וּמִשְׁעַנְתֶּךְ וְגוֹ'. בְּכָל מָקוֹם שֶׁהַצַּדִּיקִים הוֹלְכִים, הַשְּׁכִינָה הוֹלֶכֶת עִמָּהֶם וְלֹא עוֹזֶבֶת אוֹתָם.</p>\n<p>יוֹסֵף הָלַךְ בְּגֵיא צַלְמָוֶת וְהוֹרִידוֹ אוֹתוֹ לְמִצְרַיִם - הַשְּׁכִינָה הָיְתָה עִמּוֹ, זֶהוּ שֶׁכָּתוּב וַיְהִי ה' אֶת יוֹסֵף. וּמִשּׁוּם שֶׁשְּׁכִינָה הָיְתָה עִמּוֹ - בְּכָל מַה שֶּׁהָיָה עוֹשֶׂה, הָיָה מַצְלִיחַ בְּיָדוֹ. שֶׁאֲפִלּוּ מַה שֶּׁהָיָה בְּיָדוֹ וְהָיָה מְבַקֵּשׁ אוֹתוֹ אֲדוֹנוֹ בְּגָוֶן אַחֵר - הָיָה מִתְהַפֵּךְ בְּיָדוֹ לְאוֹתָהּ הַצּוּרָה שֶׁרְצוֹן אֲדוֹנוֹ הָיָה רוֹצֶה בָהּ, כְּמוֹ שֶׁנֶּאֱמַר וַיַּרְא אֲדנָיו כִּי ה' אִתּוֹ וְכֹל אֲשֶׁר הוּא עֹשֶׂה ה' מַצְלִיחַ בְּיָדוֹ. מַצְלִיחַ בְּיָדוֹ וַדַּאי, כִּי ה' אִתּוֹ.</p>\n<p>בֹּא רְאֵה, וַיֵּדַע אֲדנָיו כִּי ה' אִתּוֹ לֹא כָתוּב, אֶלָּא וַיַּרְא אֲדנָיו, שֶׁהֲרֵי בְּעֵינוֹ הָיָה רוֹאֶה מַעֲשֵׂה נִסִּים בְּכָל יוֹם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה בְּיָדוֹ, וְעַל כֵּן וַיְבָרֶךְ ה' אֶת בֵּית הַמִּצְרִי בִּגְלַל יוֹסֵף. הַקָּדוֹשׁ בָּרוּךְ הוּא שׁוֹמֵר אֶת הַצַּדִּיקִים, וּבִגְלָלָם הוּא שׁוֹמֵר אֶת הָרְשָׁעִים, שֶׁהֲרֵי הָרְשָׁעִים מִתְבָּרְכִים מִשּׁוּם הַצַּדִּיקִים. כְּמוֹ כֵן כָּתוּב (שמואל ב ו) וַיְבָרֶךְ ה', אֶת בֵּית עֹבֵד אֱדם, (הגתי) בַּעֲבוּר אֲרוֹן הָאֱלֹהִים.</p>\n<p>הַצַדִּיקִים, מִתְבָּרְכִים הָאֲחֵרִים בִּגְלָלָן, וְהֵם לֹא יָכְלוּ לְהִזּוֹן (ס\"א להנצל) בִּזְכוּתָם, וַהֲרֵי פֵּרְשׁוּהָ. יוֹסֵף הִתְבָּרֵךְ אֲדוֹנוֹ בִּגְלָלוֹ, וְהוּא לֹא יָכֹל לְהִנָּצֵל מִמֶּנּוּ בִּזְכוּתוֹ וְלָצֵאת לְחֵרוּת.</p>\n<p>וְאַחַר כָּךְ הִכְנִיס אוֹתוֹ לְבֵית הַסֹּהַר, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קה) עִנּוּ בַכֶּבֶל רַגְלוֹ בַּרְזֶל בָּאָה נַפְשׁוֹ, עַד שֶׁלְּאַחַר מִכֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא הוֹצִיא אוֹתוֹ לַחֵרוּת וְהִשְׁלִיט אוֹתוֹ עַל כָּל אֶרֶץ מִצְרַיִם. וּמִשּׁוּם כָּךְ כָּתוּב וְלֹא יַעֲזב אֶת חֲסִידָיו לְעוֹלָם נִשְׁמָרוּ. כָּתוּב חֲסִידוֹ וְנִתְבָּאֵר, וְהַקָּדוֹשׁ בָּרוּךְ הוּא מֵגֵן עַל הַצַּדִּיקִים בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא, שֶׁכָּתוּב (תהלים ה) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךְ אֹהֲבֵי שְׁמֶךְ.</p>"],[9522011391,"<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַתִּשָּׂא אֵשֶׁת אֲדנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף. רַבִּי חִיָּיא פָּתַח וְאָמַר, (שם קג) בָּרְכוּ ה' מַלְאָכָיו גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ לִשְׁמֹעַ בְּקוֹל דְּבָרוֹ בּא רְאֵה כַּמָּה צָרִיךְ הָאָדָם לְהִשָּׁמֵר מֵחֲטָאָיו וְלָלֶכֶת בְּדֶרֶךְ מְתֻקֶּנֶת, כְּדֵי שֶׁלֹּא יָסִיט אוֹתוֹ הַיֵּצֶר הָרָע הַהוּא, שֶׁהוּא מְקַטְרֵג לוֹ כָּל יוֹם וָיוֹם, כְּמוֹ שֶׁנֶּאֱמַר.</p>\n<p>וּמִשּׁוּם שֶׁהוּא מְקַטְרֵג לוֹ תָּמִיד, צָרִיךְ הָאָדָם לְהִתְגַּבֵּר עָלָיו וּלְהִתְעַלּוֹת עָלָיו בְּמָקוֹם שֶׁל חֹזֶק, שֶׁצָּרִיךְ לִהְיוֹת גּוֹבֵר עָלָיו וּלְהִשְׁתַּתֵּף בְּמָקוֹם שֶׁל גְּבוּרָה, מִשּׁוּם שֶׁכַּאֲשֶׁר אָדָם גּוֹבֵר עָלָיו, אָז הוּא בְּצַד הַגְּבוּרָה וְנִדְבָּק בּוֹ לְהִתְגַּבֵּר, וּמִשּׁוּם שֶׁאוֹתוֹ יֵצֶר הָרָע תַּקִּיף, צָרִיךְ הָאָדָם לִהְיוֹת תַּקִּיף מִמֶּנּוּ.</p>\n<p>וּבְנֵי הָאָדָם הַלָּלוּ שֶׁמִּתְגַּבְּרִים, נִקְרָאִים גִּבּוֹרֵי כֹחַ, שֶׁיִּמְצָא מִין עִם מִינוֹ, וְאֵלּוּ הֵם מַלְאָכָיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבָּאִים מִצַּד הַגְּבוּרָה הַקָּשָׁה, לְהִתְגַּבֵּר עָלָיו, גִּבֹּרֵי כֹחַ עֹשֵׂי דְבָרוֹ. בָּרְכוּ ה' מַלְאָכָיו - כְּמוֹ יוֹסֵף שֶׁנִּקְרָא צַדִּיק וְגִבּוֹר וְשָׁמַר בְּרִית הַקֹּדֶשׁ הָרְשׁוּמָה בְּתוֹכוֹ.</p>\n<p>רַבִּי אֶלְעָזָר אָמַר, וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה, מַה זֶּה הִיא? הֲרֵי פֵּרְשׁוּהָ, מָקוֹם זֶה שֶׁיֵּצֶר הָרָע מְקַטְרֵג, שֶׁהוּא הַדַּרְגָּה אַחַר הַדְּבָרִים. מִשּׁוּם שֶׁיּוֹסֵף נָתַן לוֹ מָקוֹם לְקַטְרֵג, שֶׁהָיָה יוֹסֵף מְסַלְסֵל בִּשְׂעָרוֹ וּמְתַקֵּן אֶת עַצְמוֹ וּמְקַשֵּׁט אוֹתוֹ, אָז נָתַן מָקוֹם לַיֵּצֶר הָרָע לְקַטְרֵג, שֶׁאָמַר: וּמָה אָבִיו מִתְאַבֵּל עָלָיו, וְיוֹסֵף מְקַשֵּׁט אֶת עַצְמוֹ וּמְסַלְסֵל בִּשְׂעָרוֹ!? אָז הִתְגָּרָה בּוֹ הַדֹּב וְקִטְרֵג לוֹ.</p>\n<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה. בֹּא רְאֵה, בִּזְמַן שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מַשְׁגִּיחַ בָּעוֹלָם לָדוּן אוֹתוֹ וּמוֹצֵא רְשָׁעִים בָּעוֹלָם, מַה כָּתוּב? (דברים יא) וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר וְהָאֲדָמָה לֹא תִתֵּן אֶת יְבוּלָהּ. וְאָז - וַאֲבַדְתֶּם מְהֵרָה. שֶׁהֲרֵי מִשּׁוּם חֲטָאֵי בְּנֵי הָאָדָם הַשָּׁמַיִם נֶעֱצָרִים וְלֹא נוֹהֲגִים בְּחֻקּוֹתֵיהֶם כָּרָאוּי.</p>\n<p>וּבֹא וּרְאֵה, אוֹתָם שֶׁלֹּא שׁוֹמְרִים אֶת בְּרִית הַקֹּדֶשׁ הַזּוֹ, גּוֹרְמִים הִתְפָּרְדוּת בֵּין יִשְׂרָאֵל לַאֲבִיהֶם שֶׁבַּשָּׁמַיִם, מִשּׁוּם שֶׁכָּתוּב וְסַרְתֶּם וַעֲבַדְתֶּם אֱלֹהִים אֲחֵרִים וְהִשְׁתַּחֲוִיתֶם לָהֶם, וְכָתוּב וְעָצַר אֶת הַשָּׁמַיִם וְלֹא יִהְיֶה מָטָר. שֶׁזֶּהוּ כְּמוֹ שֶׁמִּשְׁתַּחֲוֶה לֵאלוֹהַּ אַחֵר, שֶׁמְּשַׁקֵּר בְּאוֹת הַבְּרִית הַקְּדוֹשָׁה הַזּוֹ.</p>\n<p>וְכַאֲשֶׁר הַבְּרִית הַקְּדוֹשָׁה נִשְׁמֶרֶת בָּעוֹלָם כָּרָאוּי, אָז הַקָּדוֹשׁ בָּרוּךְ הוּא נוֹתֵן בְּרָכוֹת לְמַעְלָה לְהָרִיק בָּעוֹלָם, כְּמוֹ שֶׁנֶּאֱמַר (תהלים סח) גֶּשֶׁם נְדָבוֹת תָּנִיף אֱלֹהִים נַחֲלָתְךְ וְנִלְאָה אַתָּה כוֹנַנְתָּה. גֶּשֶׁם נְדָבוֹת - זֶהוּ גִּשְׁמֵי רָצוֹן, כְּשֶׁמִּתְרַצֶּה הַקָּדוֹשׁ בָּרוּךְ הוּא עִם כְּנֶסֶת יִשְׂרָאֵל וְרוֹצֶה לְהָרִיק לָהּ בְּרָכוֹת, אֲזַי נַחֲלָתְךְ וְנִלְאָה אַתָּה כוֹנַנְתָּה.</p>\n<p>נַחֲלָתְךָ - הֵם יִשְׂרָאֵל, שֶׁהֵם נַחֲלָתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא, כְּמוֹ שֶׁנֶּאֱמַר (דברים לב) יַעֲקֹב חֶבֶל נַחֲלָתוֹ. וְנִלְאָה - זוֹ כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא נִלְאָה בְּאֶרֶץ אַחֶרֶת. שֶׁהִיא צְמֵאָה לִשְׁתּוֹת, וְאָז הִיא נִלְאָה. וּכְשֶׁאוֹתוֹ גֶשֶׁם שֶׁל רָצוֹן נִתָּן, אָז אַתָּה כוֹנַנְתָּה.</p>\n<p>וְעַל כֵּן שָׁמַיִם וָאָרֶץ וְכָל צְבָאָם, כֻּלָּם עוֹמְדִים עַל הַקִּיּוּם הַזֶּה, שֶׁכָּתוּב (ירמיה לג) אִם לֹא בְרִיתִי יוֹמָם וָלָיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לֹא שָׂמְתִּי, וּמִשּׁוּם כָּךְ צָרִיךְ לְהִזָּהֵר בָּזֶה, וַהֲרֵי פֵּרְשׁוּהָ. וּמִשּׁוּם כָּךְ כָּתוּב וַיְהִי יוֹסֵף יְפֵה תֹאַר וִיפֵה מַרְאֶה, וְאַחֲרָיו כָּתוּב וַתִּשָּׂא אֵשֶׁת אֲדנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף.</p>"],[9522011392,"<p>וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (משלי ו) לִשְׁמָרְךְ מֵאֵשֶׁת רָע וְגוֹ'. אַשְׁרֵי הַצַּדִּיקִים שֶׁיּוֹדְעִים אֶת דַּרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לָלֶכֶת בָּהֶם, מִשּׁוּם שֶׁהֵם מִשְׁתַּדְּלִים בַּתּוֹרָה יוֹמָם וָלַיְלָה, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה יָמִים וְלֵילוֹת, נוֹחֵל שְׁנֵי עוֹלָמוֹת - הָעוֹלָם הָעֶלְיוֹן וְהָעוֹלָם הַתַּחְתּוֹן. נוֹחֵל אֶת הָעוֹלָם הַזֶּה - אַף עַל גַּב שֶׁאֵין הָאָדָם מִתְעַסֵּק בָּהּ לִשְׁמָהּ. וְיוֹרֵשׁ הָעוֹלָם הָעֶלְיוֹן הַהוּא - כְּשֶׁמִּתְעַסֵּק בָּהּ הָאָדָם לִשְׁמָהּ.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, (משלי ג) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד. אֹרֶךְ יָמִים בִּימִינָהּ - מִי שֶׁהוֹלֵךְ לִימִין הַתּוֹרָה, אֹרֶךְ שֶׁל חַיִּים הוּא לָעוֹלָם הַבָּא, שֶׁזּוֹכֶה שָׁם לִכְבוֹד הַתּוֹרָה, שֶׁהוּא כָּבוֹד וְכֶתֶר לְהִתְעַטֵּר עַל הַכֹּל, שֶׁכֶּתֶר הַתּוֹרָה הוּא בָּעוֹלָם הַהוּא. בִּשְׂמֹאלָהּ עֹשֶׁר וְכָבוֹד - בָּעוֹלָם הַזֶּה, שֶׁאַף עַל גַּב שֶׁאֵינוֹ מִתְעַסֵּק בָּהּ לִשְׁמָהּ, זוֹכֶה בָּעוֹלָם הַזֶּה לְעֹשֶׁר וְכָבוֹד.</p>\n<p>שֶׁהֲרֵי רַבִּי חִיָּיא, כַּאֲשֶׁר בָּא מִשָּׁם לְאֶרֶץ יִשְׂרָאֵל, קָרָא בַּתּוֹרָה, עַד שֶׁהָיוּ פָנָיו מְאִירִים כְּמוֹ הַשֶּׁמֶשׁ, וּכְשֶׁהָיוּ עוֹמְדִים לְפָנָיו כָּל אוֹתָם שֶׁעָסְקוּ בַתּוֹרָה, הָיָה אוֹמֵר: זֶה הִשְׁתַּדֵּל בַּתּוֹרָה לִשְׁמָהּ, וְזֶה לֹא הִשְׁתַּדֵּל לִשְׁמָהּ. וְהָיָה מִתְפַּלֵּל עַל אוֹתוֹ שֶׁמִּתְעַסֵּק לִשְׁמָהּ, שֶׁכָּךְ יִהְיֶה תָמִיד וְיִזְכֶּה לָעוֹלָם הַבָּא. וּמִתְפַּלֵּל עַל אוֹתוֹ שֶׁלֹּא הִתְעַסֵּק לִשְׁמָהּ, שֶׁיָּבא לְהִתְעַסֵּק בָּהּ לִשְׁמָהּ וְיִזְכֶּה לְחַיֵּי עוֹלָם.</p>\n<p>יוֹם אֶחָד רָאָה תַלְמִיד אֶחָד שֶׁהָיָה עוֹסֵק בַּתּוֹרָה וּפָנָיו מוֹרִיקִים. אָמַר, וַדַּאי מְהַרְהֵר בַּעֲבֵרָה הוּא זֶה. אָחַז אוֹתוֹ לְפָנָיו, וְהִמְשִׁיךְ עָלָיו דִּבְרֵי תוֹרָה עַד שֶׁהִתְיַשְּׁבָה רוּחוֹ בְּתוֹכוֹ. מֵאוֹתוֹ הַיּוֹם וָהָלְאָה שָׂם עַל רוּחוֹ שֶׁלֹּא יִרְדֹּף אַחַר אוֹתָם הַהִרְהוּרִים הָרָעִים וְיִשְׁתַּדֵּל בַּתּוֹרָה לִשְׁמָהּ.</p>\n<p>אָמַר רַבִּי יוֹסֵי, כְּשֶׁאָדָם רוֹאֶה שֶׁבָּאִים אֵלָיו הִרְהוּרִים רָעִים, יִתְעַסֵּק בַּתּוֹרָה, וְאָז יַעַבְרוּ מִמֶּנּוּ. אָמַר רַבִּי אֶלְעָזָר, כְּשֶׁאוֹתוֹ הַצַּד הָרָע בָּא לְפַתּוֹת אֶת הָאָדָם, יִמְשֹׁךְ אוֹתוֹ לַתּוֹרָה, וְיִפָּרֵד מִמֶּנּוּ.</p>\n<p>בֹּא רְאֵה, שֶׁהִנֵּה שָׁנִינוּ, שֶׁכַּאֲשֶׁר הַצַּד הָרָע הַזֶּה עוֹמֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׂטִין עַל הָעוֹלָם מִשּׁוּם מַעֲשִׂים רָעִים, הַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל הָעוֹלָם, וְנוֹתֵן עֵצָה לִבְנֵי אָדָם לְהִנָּצֵל מִמֶּנּוּ, וְלֹא יוּכַל לִשְׁלֹט עֲלֵיהֶם וְלֹא עַל מַעֲשֵׂיהֶם. וּמַה הִיא הָעֵצָה? לְהִשְׁתַּדֵּל בַּתּוֹרָה, וְנִצּוֹלִים מִמֶּנּוּ. מִנַּיִן לָנוּ? שֶׁכָּתוּב (שם ו) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר וְדֶרֶךְ חַיִּים תּוֹכְחוֹת מוּסָר. מַה כָּתוּב אַחֲרָיו? לִשְׁמָרְךְ מֵאֵשֶׁת רָע מֵחֶלְקַת לָשׁוֹן נָכְרִיָּה.</p>\n<p>זֶהוּ צַד הַטֻּמְאָה. הַצַּד הָאַחֵר - שֶׁעוֹמֵד תָּמִיד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְהַשְׂטִין עַל חֲטָאֵי בְּנֵי הָאָדָם, וְעוֹמֵד תָּמִיד לְהַשְׂטִין לְמַטָּה לִבְנֵי אָדָם. עוֹמֵד תָּמִיד לְמַעְלָה כְּדֵי לְהַזְכִּיר חֲטָאֵי בְּנֵי הָאָדָם וּלְהַשְׂטִין לָהֶם עַל מַעֲשֵׂיהֶם, וּמִשּׁוּם שֶׁנִּתְּנוּ בִּרְשׁוּתוֹ, כְּמוֹ שֶׁעָשָׂה לוֹ לְאִיּוֹב.</p>\n<p>וְכֵן עוֹמֵד עֲלֵיהֶם לְהַשְׂטִין אֶת יִשְׂרָאֵל וּלְהַזְכִּיר חֲטָאֵיהֶם בְּכָל מַה שֶּׁעָשׂוּ בְּאוֹתָן הַפְּעָמִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא עוֹמֵד עֲלֵיהֶם בְּדִין, אֲזַי עוֹמֵד לְהַשְׂטִין לָהֶם וּלְהַזְכִּיר חֲטָאֵיהֶם, וְהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל יִשְׂרָאֵל וְנוֹתֵן לָהֶם עֵצָה לְהִנָּצֵל מִמֶּנּוּ, וּבַמֶּה? בַּשּׁוֹפָר, בַּיּוֹם שֶׁל רֹאשׁ הַשָּׁנָה, וּבְיוֹם הַכִּפּוּרִים בַּשָּׂעִיר הַמִּשְׁתַּלֵּחַ שֶׁנּוֹתְנִים לוֹ, כְּדֵי לְהִפָּרֵד מֵהֶם וּלְהִשְׁתַּדֵּל בְּאוֹתוֹ הַחֵלֶק שֶׁלּוֹ, וַהֲרֵי בֵּאֲרוּהָ.</p>\n<p>בֹּא רְאֵה מַה כָּתוּב, (שם ה) רַגְלֶיהָ יֹרְדוֹת מָוֶת שְׁאוֹל צְעָדֶיהָ יִתְמֹכוּ. וּבְסוֹד הָאֱמוּנָה מַה כָּתוּב? (שם ג) דְּרָכֶיהָ דַרְכֵי נֹעַם וְכָל נְתִיבֹתֶיהָ שָׁלוֹם. וְאֵלּוּ הֵם דַּרְכֵי וּשְׁבִילֵי הַתּוֹרָה, וְהַכֹּל אֶחָד. זֶה שָׁלוֹם וְזֶה מָוֶת, וְהַכֹּל הֲפוּכִים זֶה מִזֶּה.</p>\n<p>אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁנִּדְבָּקִים בַּקָּדוֹשׁ-בָּרוּךְ-הוּא כָּרָאוּי וְנוֹתֵן לָהֶם עֵצָה לְהִנָּצֵל מִכָּל הַצְּדָדִים הָאֲחֵרִים שֶׁל הָעוֹלָם, מִשּׁוּם שֶׁהֵם עַם קָדוֹשׁ לְנַחֲלָתוֹ וְחֶלְקוֹ, וְעַל כֵּן נוֹתֵן לָהֶם עֵצָה בַּכֹּל. אַשְׁרֵיהֶם בָּעוֹלָם הַזֶּה וּבָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, כְּשֶׁהַצַּד הָרָע הַזֶּה יוֹרֵד וּמְשׁוֹטֵט בָּעוֹלָם וְרוֹאֶה אֶת מַעֲשֵׂי בְּנֵי הָאָדָם, שֶׁהֵם כֻּלָּם סוֹטִים דַּרְכֵיהֶם בָּעוֹלָם, הוּא עוֹלֶה וּמַשְׂטִין עֲלֵיהֶם, וְאִלְמָלֵא שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל מַעֲשֵׂי יָדָיו, הֵם לֹא הָיוּ נִשְׁאָרִים בָּעוֹלָם.</p>\n<p>מַה כָּתוּב? וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם. כְּדַבְּרָהּ - שֶׁעוֹלֶה וּמַעֲלֶה בְּכָל יוֹם וָיוֹם, וְאוֹמֵר לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא כַּמָּה רָעוֹת, כַּמָּה מַלְשִׁינוּת, כְּדֵי לְכַלּוֹת בְּנֵי אָדָם.</p>\n<p>מַה כָּתוּב? וְלֹא שָׁמַע אֵלֶיהָ לִשְׁכַּב אֶצְלָהּ לִהְיוֹת עִמָּהּ. וְלֹא שָׁמַע אֵלֶיהָ - מִשּׁוּם שֶׁהוּא חָס עַל הָעוֹלָם. לִשְׁכַּב אֶצְלָהּ, מַהוּ לִשְׁכַּב אֶצְלָהּ? כְּדֵי לָקַחַת שִׁלְטוֹן לִשְׁלֹט עַל הָעוֹלָם, וְהַשִּׁלְטוֹן לֹא שׁוֹלֵט עַד שֶׁנִּתֶּנֶת לוֹ רְשׁוּת.</p>\n<p>דָּבָר אַחֵר לִשְׁכַּב אֶצְלָהּ - כְּמוֹ שֶׁנֶּאֱמַר (ויקרא טו) וּלְאִישׁ אֲשֶׁר יִשְׁכַּב עִם טְמֵאָה. לִהְיוֹת עִמָּהּ - לָתֵת לָהּ גַּדְלוּת וּבְרָכוֹת וְסִיּוּעַ, שֶׁאִלְמָלֵא הָיָה לָהּ סִיּוּעַ מִלְמַעְלָה, לֹא נִשְׁאָר בָּעוֹלָם אֲפִלּוּ אֶחָד, אֲבָל מִשּׁוּם שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָס עַל הָעוֹלָם, נִשְׁאָר הָעוֹלָם בְּקִיּוּמוֹ.</p>\n<p>רַבִּי אַבָּא אָמַר, הַכֹּל הוּא דֶּרֶךְ אַחַת, אֲבָל יֵצֶר הָרָע הוּא שֶׁהוֹלֵךְ וּמְפַתֶּה אֶת בְּנֵי הָאָדם כְּדֵי לְהַסְטוֹת אֶת דַּרְכֵיהֶם וּלְהִדָּבֵק בָּהֶם בְּכָל יוֹם וָיוֹם, וּבְכָל עִדָּן וְעִדָּן. מַסְטֶה אֶת הָאָדָם מִדֶּרֶךְ הָאֱמֶת כְּדֵי לִדְחוֹתוֹ מִדֶּרֶךְ הַחַיִּים, לִמְשּךְ אוֹתוֹ לַגֵּיהִנֹּם.</p>\n<p>אַשְׁרָיו מִי שֶׁעוֹשֶׂה וְשׁוֹמֵר (אשרי מי שעושה, שומר) דְּרָכָיו וּשְׁבִילָיו כְּדֵי שֶׁלֹּא יִדְבַּק בּוֹ, הַיְנוּ מַה שֶּׁכָּתוּב וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם וְלֹא שָׁמַע אֵלֶיהָ, כְּמוֹ (במה) שֶׁהִיא אוֹמֶרֶת לוֹ בְּכָל יוֹם. שֶׁהֲרֵי רוּחַ הַטֻּמְאָה, יֵצֶר הָרָע, מְפַתֶּה אֶת הָאָדָם בְּכָל יוֹם לִשְׁכַּב אֶצְלָהּ, בְּתוֹךְ הַגֵּיהִנֹּם, וּלְהִדּוֹן שָׁם, לִהְיוֹת עִמָּהּ.</p>\n<p>בֹּא רְאֵה, כְּשֶׁאָדָם נִדְבָּק לְאוֹתוֹ הַצַּד, נִמְשָׁךְ אַחֲרֶיהָ, וְנִטְמָא עִמָּהּ בָּעוֹלָם הַזֶּה וְנִטְמָא עִמָּהּ בָּעוֹלָם הָאַחֵר. בּא רְאֵה, צַד הַטֻּמְאָה הַזֶּה הוּא מְנֻוָּל, הוּא מְלֻכְלָךְ, כַּכָּתוּב (ישעיה ל) צֵא תֹּאמַר לוֹ, צוֹאָה מַמָּשׁ, וּבוֹ נִדּוֹן מִי שֶׁמַּסְטֶה דַרְכּוֹ מֵהַתּוֹרָה, וּבוֹ נִדּוֹנִים אוֹתָם הָרְשָׁעִים שֶׁל הָעוֹלָם שֶׁאֵין לָהֶם אֱמוּנָה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>מַה כָּתוּב? וַיְהִי כְּהַיּוֹם הַזֶּה וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ וְאֵין אִישׁ מֵאַנְשֵׁי הַבַּיִת שָׁם בַּבָּיִת. וַיְהִי כְּהַיּוֹם הַזֶּה - הַיּוֹם שֶׁיֵּצֶר הָרָע שׁוֹלֵט בָּעוֹלָם וְיוֹרֵד לְהַשְׂטִין לִבְנֵי הָאָדָם. מָתַי? הַיּוֹם שֶׁבָּא אָדָם לָשׁוּב בִּתְשׁוּבָה עַל חֲטָאָיו, אוֹ לְהִשְׁתַּדֵּל בַּתּוֹרָה וְלַעֲשׂוֹת מִצְווֹת הַתּוֹרָה, וְאָז יוֹרֵד בְּאוֹתוֹ הַזְּמַן כְּדֵי לְהַשְׂטִין לִבְנֵי הָאָדָם.</p>\n<p>וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ, כְּדֵי לְהִשְׁתַּדֵּל בַּתּוֹרָה וְלַעֲשׂוֹת מִצְווֹת הַתּוֹרָה, שֶׁהִיא מְלַאכְתּוֹ שֶׁל הָאָדָם בָּעוֹלָם הַזֶּה. וְכֵיוָן שֶׁעֲבוֹדַת הָאָדָם בָּעוֹלָם הַזֶּה הִיא עֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, צָרִיךְ לָאָדָם לִהְיוֹת תַּקִּיף כְּאַרְיֵה בְּכָל צְדָדָיו כְּדֵי שֶׁלֹּא יִשְׁלֹט עָלָיו הַצַּד הָאַחֵר וְלֹא יוּכַל לְפַתּוֹת אוֹתוֹ. מַה כָּתוּב? וְאֵין אִישׁ, אֵין גֶּבֶר שֶׁיַּעֲמֹד לִפְנֵי הַיֵּצֶר הָרָע וְיִלָּחֵם בּוֹ קְרָב כָּרָאוּי.</p>\n<p>מַה דַּרְכּוֹ שֶׁל יֵצֶר הָרָע? כֵּיוָן שֶׁרוֹאֶה שֶׁאֵין הָאָדָם עוֹמֵד כְּנֶגְדּוֹ וְיוֹצֵא לִקְרָב אִתּוֹ, מִיָּד - וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי. וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ, מִשּׁוּם שֶׁכַּאֲשֶׁר יֵצֶר הָרָע שׁוֹלֵט עַל הָאָדָם, מַתְקִין אוֹתוֹ וּמְקַשֵּׁט לוֹ אֶת לְבוּשׁוֹ, מְסַלְסֵל בִּשְׂעָרוֹ. זֶהוּ שֶׁכָּתוּב וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי, הִדָּבֵק עִמִּי.</p>\n<p>מִי שֶׁהוּא צַדִּיק, מִתְגַּבֵּר כְּנֶגְדּוֹ וְנִלְחָם בּוֹ קְרָב. מַה כָּתוּב? וַיַּעֲזֹב בִּגְדוֹ בְּיָדָהּ וַיָּנָס וַיֵּצֵא הַחוּצָה. יַעֲזֹב אוֹתוֹ וְיִתְגַּבֵּר כְּנֶגְדּוֹ (וילחם בו קרב) וְיִבְרַח מִמֶּנּוּ כְּדֵי לְהִנָּצֵל מִמֶּנּוּ, וְלֹא יִשְׁלֹט עָלָיו.</p>\n<p>אָמַר רַבִּי יִצְחָק, עֲתִידִים הֵם הַצַּדִּיקִים לִרְאוֹת אֶת יֵצֶר הָרָע כְּמוֹ הַר גָּדוֹל, וְיִתְמְהוּ וְיֹאמְרוּ, אֵיךְ יָכֹלְנוּ לְהַכְנִיעַ אֶת הָהָר הַגָּדוֹל הָעֶלְיוֹן הַזֶּה!? וַעֲתִידִים הָרְשָׁעִים לִרְאוֹת אֶת הַיֵּצֶר הָרָע דַּקִּיק כְּמוֹ חוּט שֶׁל שַׂעֲרָה, וְיִתְמְהוּ וְיֹאמְרוּ, אֵיךְ לֹא יָכֹלְנוּ לְהַכְנִיעַ אֶת חוּט הַשַּׂעֲרָה כָּזֶה דַּקִּיק!? אֵלּוּ יִבְכּוּ וְאֵלּוּ יִבְכּוּ. וְהַקָּדוֹשׁ בָּרוּךְ הוּא יְבַעֵר אוֹתוֹ מִן הָעוֹלָם וְיִשְׁחַט אוֹתוֹ לְעֵינֵיהֶם, וְלֹא יִשְׁלֹט עוֹד בָּעוֹלָם, וְיִרְאוּ הַצַּדִּיקִים וְיִשְׂמְחוּ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים קמ) אַךְ צַדִּיקִים יוֹדוּ לִשְׁמֶךְ יֵשְׁבוּ יְשָׁרִים אֶת פָּנֶיךְ.</p>"],[9522011393,"<p>וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה חָטְאוּ מַשְׁקֵה מֶלֶךְ מִצְרַיִם וְגוֹ'. רַבִּי יְהוּדָה פָּתַח, (עמוס ג) הֲיִשְׁאַג אַרְיֵה בַּיַּעַר וְטֶרֶף אֵין לוֹ הֲיִתֵּן כְּפִיר קוֹלוֹ מִמְּעוֹנתוֹ בִּלְתִּי אִם לָכָד. הֲיִשְׁאַג אַרְיֵה בַּיַּעַר. בֹּא רְאֵה כַּמָּה יֵשׁ לַאֲנָשִׁים לְהַשְׁגִּיחַ בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וּבַעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא, פַּחְדּוֹ וְיִרְאָתוֹ הֵם עַל הַכֹּל, שֶׁהֲרֵי כְּשֶׁבָּרָא הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת הָעוֹלָם, עָשָׂה אֶת כָּל הַבְּרִיּוֹת שֶׁל הָעוֹלָם כָּל אֶחָד וְאֶחָד בִּדְמוּתוֹ כָּרָאוּי לוֹ, וְאַחַר כָּךְ בָּרָא אֶת הָאָדָם בִּדְמוּת עֶלְיוֹנָה, וְהִשְׁלִיט אוֹתוֹ עַל כֻּלָּם בַּדְּמוּת הַזּוֹ.</p>\n<p>שֶׁכָּל זְמַן שֶׁאָדָם עוֹמֵד בָּעוֹלָם, כָּל אוֹתָם הַבְּרִיּוֹת שֶׁל הָעוֹלָם זוֹקְפִים רֹאשָׁם וּמִסְתַּכְּלִים בַּדְּמוּת הָעֶלְיוֹנָה שֶׁל הָאָדָם, אָז כֻּלָּם פּוֹחֲדִים וְזָעִים מִלְּפָנָיו, כְּמוֹ שֶׁנֶּאֱמַר (בראשית ב) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמַיִם וְגוֹ'. וְהַדְּבָרִים הַלָּלוּ, כְּשֶׁמִּסְתַּכְּלִים וְרוֹאִים אוֹתוֹ, הַדְּמוּת הַזּוֹ, וְהַנְּשָׁמָה בּוֹ.</p>\n<p>אָמַר רַבִּי אֶלְעָזָר, אַף עַל גַּב שֶׁאֵין בּוֹ נְשָׁמָה, הַצַּדִּיקִים לֹא מִשְׁתַּנִּים מִכְּמוֹ שֶׁהָיְתָה דְמוּתָם בַּהַתְחָלָה, וּכְשֶׁאָדָם לֹא הוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, הַדְּמוּת הַקְּדוֹשָׁה הַזּוֹ מִתְחַלֶּפֶת לוֹ, וְאָז חַיַּת הַבָּר וְעוֹף הַשָּׁמַיִם יְכוֹלִים לִשְׁלֹט עָלָיו, מִשּׁוּם שֶׁהַדְּמוּת הַקְּדוֹשָׁה הַזּוֹ הִתְחַלְּפָה לוֹ, הִתְחַלְּפָה לוֹ הַדְּמוּת הַזּוֹ שֶׁל בֶּן אָדָם.</p>\n<p>וּבֹא וּרְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַחֲלִיף הַמַּעֲשִׂים שֶׁלְּמַעְלָה וּמַטָּה כְּדֵי לְהַחֲזִיר הַדְּבָרִים לִמְקוֹמָם, וְשֶׁיִּמָּצֵא רְצוֹנוֹ בְּכָל מַעֲשֵׂי הָעוֹלָם. הַדְּמוּת שֶׁל דָּנִיֵּאל לֹא הִשְׁתַּנְּתָה כְּשֶׁהִפִּילוּ אוֹתוֹ לְגֹב הָאֲרָיוֹת, וּמִשּׁוּם כָּךְ נִצּוֹל. אָמַר רַבִּי חִזְקִיָּה, אִם כָּךְ, הִנֵּה כָּתוּב (דניאל ו) אֱלֹהַי שָׁלַח אֶת מַלְאָכוֹ וְסָגַר אֶת פִּי הָאֲרָיוֹת וְלֹא חִבְּלוּ אוֹתִי. מַשְׁמָע שֶׁמִּשּׁוּם הַמַּלְאָךְ שֶׁסָּגַר אֶת פִּיהֶם, לֹא נִזּוֹק.</p>\n<p>אָמַר לוֹ, מִשּׁוּם זֶה לֹא נִזּוֹק, שֶׁהֲרֵי אוֹתָהּ דְּמוּת הָאָדָם הַצַּדִּיק הִיא הַמַּלְאָךְ מַמָּשׁ, שֶׁסּוֹגֵר אֶת הַפֶּה וְקוֹשֵׁר אוֹתָם לִשְׁמֹר אוֹתוֹ שֶׁלֹּא יַזִּיקוּ לוֹ, וּמִשּׁוּם כָּךְ אֱלָהִי שְׁלַח מַלְאֲכֵהּ, אוֹתוֹ שֶׁכָּל הַדְּמֻיּוֹת שֶׁבָּעוֹלָם חֲקוּקוֹת בּוֹ, וְהוּא הֶחֱזִיק בִּי אֶת דְּמוּתִי וְלֹא יָכְלוּ לִשְׁלֹט בִּי, וְסָגַר אֶת פִּיהֶם. וְעַל זֶה שָׁלַח וַדַּאי אֶת מַלְאָכוֹ.</p>\n<p>וְהַמַּלְאָךָ הַזֶּה, אוֹתוֹ שֶׁכָּל הַדְּמֻיּוֹת חֲקוּקוֹת בּוֹ, שֶׁכָּתוּב (תהלים קי) יָדִין בַּגּוֹיִם מָלֵא גְוִיּוֹת, הוּא שֶׁלֹּא מִשְׁתַּנֶּה לְפָנָיו כָּל דְּמֻיּוֹת הָעוֹלָם, וְעַל כֵּן צָרִיךְ הָאָדָם לִשְׁמֹר דְּרָכָיו וּשְׁבִילָיו כְּדֵי שֶׁלֹּא יֶחֱטָא לִפְנֵי רִבּוֹנוֹ, וְיִתְקַיֵּם בִּדְמוּת שֶׁל אָדָם.</p>\n<p>בֹּא רְאֵה, יְחֶזְקֵאל שָׁמַר אֶת פִּיו מִמַּאֲכָלוֹת אֲסוּרִים, שֶׁכָּתוּב (יחזקאל ד) וְלֹא בָא בְּפִי בְּשַׂר פִּגּוּל, זָכָה וְנִקְרָא בֶּן אָדָם. מַה כָּתוּב בְּדָנִיֵּאל? (דניאל א) וַיָּשֶׂם דָּנִיֵּאל עַל לִבּוֹ אֲשֶׁר לֹא יִתְגָּאַל בְּפַת בַּג הַמֶּלֶךְ וּבְיֵין מִשְׁתָּיו, זָכָה הוּא וְהִתְקַיֵּם בִּדְמוּת שֶׁל אָדָם. מִשּׁוּם שֶׁכָּל דִּבְרֵי הָעוֹלָם, כֻּלָּם מְפַחֲדִים מִלִּפְנֵי דְמוּתוֹ שֶׁל אָדָם, שֶׁהוּא שַׁלִּיט עַל כֻּלָּם וְהוּא הַמֶּלֶךְ עַל הַכֹּל.</p>\n<p>אָמַר רַבִּי יוֹסֵי, מִשּׁוּם זֶה צָרִיךְ לָאָדָם לְהִשָּׁמֵר מֵחֲטָאָיו וְלֹא יִסְטֶה לְיָמִין וְלִשְׂמֹאל, וְעִם כָּל זֶה צָרִיךְ לָאָדָם לִבְדּק בַּחֲטָאָיו בְּכָל יוֹם וָיוֹם, שֶׁהֲרֵי כְּשֶׁאָדָם עוֹמֵד מִמִּטָּתוֹ, שְׁנֵי עֵדִים עוֹמְדִים לְפָנָיו וְהוֹלְכִים עִמּוֹ כָּל הַיּוֹם.</p>\n<p>רוֹצֶה הָאָדָם לָקוּם - אוֹתָם הָעֵדִים אוֹמְרִים לוֹ בְּשָׁעָה שֶׁפּוֹתֵחַ עֵינָיו: (משלי ד) עֵינֶיךְ לְנֹכַח יַבִּיטוּ וְעַפְעַפֶּיךְ יַיְשִׁירוּ נֶגְדֶּךְ. קָם וּמְסַדֵּר רַגְלָיו לָלֶכֶת - אוֹתָם הָעֵדִים אוֹמְרִים לוֹ: (שם) פַּלֵּס מַעְגַּל רַגְלֶךְ וְגוֹ'. וְעַל כֵּן, כְּשֶׁהוֹלֵךְ הָאָדָם בְּכָל יוֹם, צָרִיךְ לוֹ לְהִשָּׁמֵר מֵחֲטָאָיו.</p>\n<p>בְּכָל יוֹם וָיוֹם, כְּשֶׁבָּא הַלַּיְלָה, צָרִיךְ לְהִתְבּוֹנֵן וְלִבְדֹּק בְּכָל מַה שֶּׁעָשָׂה כָּל הַיּוֹם הַהוּא כְּדֵי שֶׁיָּשׁוּב מֵהֶם וְיִסְתַּכֵּל בָּהֶם תָּמִיד, כְּדֵי שֶׁיָּשׁוּב לִפְנֵי רִבּוֹנוֹ, כְּמוֹ שֶׁנֶּאֱמַר (תהלים נא) וְחַטָּאתִי נֶגְדִּי תָמִיד, כְּדֵי שֶׁיָּשׁוּב מֵהֶם.</p>\n<p>וּבֹא וּרְאֵה, בִּזְמַן שֶׁיִּשְׂרָאֵל הָיוּ בָּאָרֶץ הַקְּדוֹשָׁה, לֹא נִמְצָא בִידֵיהֶם חֵטְא, כְּמוֹ שֶׁבֵּאֲרוּהוּ, מִשּׁוּם שֶׁאוֹתָם הַקָּרְבָּנוֹת שֶׁהָיוּ מַקְרִיבִים בְּכָל יוֹם הָיוּ מְכַפְּרִים עֲלֵיהֶם. עַכְשָׁו שֶׁיִּשְׂרָאֵל גָּלוּ מִן הָאָרֶץ וְאֵין מִי שֶׁמְּכַפֵּר עֲלֵיהֶם, הַתּוֹרָה מְכַפֶּרֶת עֲלֵיהֶם וּמַעֲשִׂים כְּשֵׁרִים, מִשּׁוּם שֶׁהַשְּׁכִינָה עִמָּהֶם בַּגָּלוּת, וּמִי שֶׁאֵינוֹ מִסְתַּכֵּל בְּדַרְכֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, גּוֹרֵם לַשְּׁכִינָה לְהִכָּנַע בְּתוֹךְ הֶעָפָר, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה כו) יַשְׁפִּילֶנָּה יַשְׁפִּילָהּ עַד אֶרֶץ וְגוֹ'.</p>\n<p>אָמַר רַבִּי יִצְחָק, וְכֵן מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה וּבְמַעֲשִׂים כְּשֵׁרִים, גּוֹרֵם לִכְנֶסֶת יִשְׂרָאֵל לְהָרִים רֹאשׁ בְּתוֹךְ הַגָּלוּת. אַשְׁרֵי חֶלְקָם שֶׁל אוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה יָמִים וְלֵילוֹת.</p>\n<p>בֹּא רְאֵה, גִּלְגֵּל הַקָּדוֹשׁ בָּרוּךְ הוּא גִּלְגּוּלִים בָּעוֹלָם כְּדֵי לְהָרִים אֶת רֹאשׁ הַצַּדִּיקִים, שֶׁהֲרֵי כְּדֵי שֶׁיּוֹסֵף יָרִים אֶת רֹאשׁוֹ בָּעוֹלָם עַל שֶׁנִּמְצָא צַדִּיק לְפָנָיו, הִרְגִּיז אֶת הָאָדוֹן עַל עֲבָדָיו, כְּמוֹ שֶׁנֶּאֱמַר חָטְאוּ מַשְׁקֵה מֶלֶךְ מִצְרַיִם וְהָאֹפֶה לַאֲדנֵיהֶם לְמֶלֶךְ מִצְרָיִם, וְהַכֹּל כְּדֵי לְהָרִים אֶת רֹאשׁוֹ שֶׁל יוֹסֵף הַצַּדִּיק. וּבֹא וּרְאֵה, עַל יְדֵי הַחֲלוֹם נִכְנַע מֵעִם אֶחָיו, וְעַל יְדֵי הַחֲלוֹם הִתְגַּדֵּל עַל אֶחָיו, וְהִתְגַּדֵּל עַל כָּל הָעוֹלָם.</p>\n<p>וַיַּחְלְמוּ חֲלוֹם שְׁנֵיהֶם אִישׁ חֲלֹמוֹ בְּלַיְלָה אֶחָד אִישׁ כְּפִתְרוֹן וְגוֹ'. בֹּא רְאֵה שֶׁהִנֵּה נֶאֱמַר שֶׁכָּל הַחֲלוֹמוֹת הוֹלְכִים אַחֲרֵי הַפֶּה. כַּאֲשֶׁר יוֹסֵף פָּתַר לָהֶם אֶת הַחֲלוֹם, לָמָּה לָזֶה פָּתַח פִּתְרוֹן טוֹב, וְלָזֶה פִּתְרוֹן רַע? אֶלָּא שֶׁאוֹתָם הַחֲלוֹמוֹת הָיוּ עַל יוֹסֵף, וּמִשּׁוּם שֶׁיָּדַע הַדָּבָר עַל עִקָּרוֹ וְשָׁרְשׁוֹ, מִשּׁוּם כָּךְ פָּתַר לָהֶם הַחֲלוֹם כְּמוֹ שֶׁצָּרִיךְ, לְכָל אֶחָד וְאֶחָד פָּתַר לָהֶם פִּתְרוֹן לְהַחֲזִיר הַדָּבָר עַל מְקוֹמוֹ.</p>\n<p>מַה כָּתוּב? וַיֹּאמֶר אֲלֵיהֶם יוֹסֵף הֲלוֹא לֵאלֹהִים פִּתְרֹנִים סַפְּרוּ נָא לִי. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּךְ צָרִיךְ לוֹ לִפְתֹּר הַחֲלוֹם - לְהַפְקִיד אֶת הַפִּתְרוֹן לַקָּדוֹשׁ-בָּרוּךְ-הוּא, מִשּׁוּם שֶׁשָּׁם הוּא הַקִּיּוּם שֶׁל הַכֹּל וּבוֹ עוֹמֵד הַפִּתְרוֹן.</p>\n<p>בֹּא רְאֵה, הֲרֵי נֶאֱמַר שֶׁדַּרְגַּת הַחֲלוֹם לְמַטָּה הִיא, וְהִיא הַדַּרְגָּה הַשִּׁשִּׁית, מִשּׁוּם שֶׁהֲרֵי מִמְּקוֹם הַנְּבוּאָה הִיא שׁוֹרָה, עַד הַדַּרְגָּה הַזּוֹ שֶׁל הַחֲלוֹם, שֵׁשׁ דְּרָגוֹת הֵן, וְעוֹלֶה הַפִּתְרוֹן מִדַּרְגַּת הַחֲלוֹם לְדַרְגָּה אַחֶרֶת. הַחֲלוֹם הוּא הַדַּרְגָּה שֶׁלְּמַטָּה, וְהַפִּתְרוֹן עוֹמֵד עֲלֵיהֶם, וְהַפִּתְרוֹן עוֹמֵד בַּדִּבּוּר, וְעַל כֵּן בַּדִּבּוּר עוֹמֵד הַדָּבָר, שֶׁכָּתוּב הֲלוֹא לֵאלֹהִים פִּתְרֹנִים. הֲלוֹא לֵאלֹהִים וַדַּאי.</p>"],[9522011394,"<p>בֹּא רְאֵה מַה כָּתוּב. וַיְסַפֵּר שַׂר הַמַּשְׁקִים אֶת חֲלוֹמוֹ לְיוֹסֵף וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (מלכים ב ב) וַיְהִי כְעָבְרָם וְאֵלִיָּהוּ אָמַר אֶל אֱלִישָׁע שְׁאַל מָה אֶעֱשֶׂה לָּךְ בְּטֶרֶם אֶלָּקַח מֵעִמָּךְ וַיֹּאמֶר אֱלִישָׁע וִיהִי נָא פִּי שְׁנַיִם בְּרוּחֲךְ אֵלָי. כָּאן יֵשׁ לְהִסְתַּכֵּל, שֶׁהַפָּסוּק הַזֶּה הוּא תְמִיהָה. וְאֵלִיָּהוּ אָמַר אֶל אֱלִישָׁע שְׁאַל מָה אֶעֱשֶׂה לָּךְ, וְכִי בִּרְשׁוּתוֹ זֶה עוֹמֵד? וַהֲרֵי הוּא בִּרְשׁוּתוֹ שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא! וְעוֹד, שֶׁאֱלִישָׁע גַּם כֵּן הָיָה יוֹדֵעַ, מָה הַטַּעַם שֶׁאָמַר וִיהִי נָא פִּי שְׁנַיִם בְּרוּחֲךְ אֵלָי?</p>\n<p>אֶלָּא וַדַּאי, מִי שֶׁאוֹחֵז בַּשָּׁמַיִם וָאָרֶץ וְכָל הָעוֹלָמוֹת, אֵיךְ זֶה לֹא יִהְיוּ בִּרְשׁוּתוֹ? וַדַּאי שֶׁאֵלִיָּהוּ וּשְׁאָר הַצַּדִּיקִים, הַקָּדוֹשׁ בָּרוּךְ הוּא עוֹשֶׂה תָמִיד אֶת רְצוֹנָם, שֶׁכָּתוּב (תהלים קמה) רְצוֹן יְרֵאָיו יַעֲשֶׂה, וְכָל שֶׁכֵּן שֶׁאוֹתָהּ רוּחַ הַקֹּדֶשׁ שֶׁעָלָיו הוֹרִישׁ לֶאֱלִישָׁע הַצַּדִּיק, שֶׁהָיָה הַשַּׁמָּשׁ שֶׁלּוֹ, וְהִנֵּה הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ (מלכים א יט) וְאֶת אֱלִישָׁע בֶּן שָׁפָט מֵאָבֵל מְחוֹלָה תִּמְשַׁח לְנָבִיא תַּחְתֶּיךְ, וְעַל כֵּן הָיָה לֶאֱלִישָׁע לָרֶשֶׁת אוֹתוֹ.</p>\n<p>פִּי שְׁנַיִם בְּרוּחֲךְ, מַה זֶּה פִּי שְׁנַיִם בְּרוּחֲךְ אֵלָי? וְכִי יַעֲלֶה עַל דַּעְתְּךְ שֶׁעַל אֶחָד בִּקֵּשׁ שְׁנַיִם? וּמַה שֶּׁלֹּא הָיָה בִּרְשׁוּתוֹ אֵיךְ בִּקֵּשׁ מִמֶּנּוּ? אֶלָּא הוּא לֹא בִקֵּשׁ רוּחַ עַל כָּל אֶחָד שְׁנַיִם, אֶלָּא (הוא) כָּךְ בִּקֵּשׁ מִמֶּנּוּ - בְּאוֹתָהּ הָרוּחַ שֶׁהָיְתָה לוֹ, שֶׁיַּעֲשֶׂה שְׁתֵּי הַנְהָגוֹת בָּעוֹלָם בְּאוֹתָהּ הָרוּחַ.</p>\n<p>מַה כָּתוּב? וַיֹּאמֶר הִקְשֵׁיתָ לִשְׁאוֹל אִם תִּרְאֶה אֹתִי לֻקָּח מֵאִתְּךְ יְהִי לְךְ כֵן וְאִם אַיִן לֹא יִהְיֶה. מָה הַטַּעַם אִם תִּרְאֶה אֹתִי? אֶלָּא אָמַר לוֹ, אִם תּוּכַל לַעֲמֹד עַל עִקַּר הָרוּחַ שֶׁהִשְׁאַרְתִּי לְךְ בְּשָׁעָה שֶׁאֶלָּקַח מִמְּךְ - יִהְיֶה לְךְ כָּזֶה, שֶׁהֲרֵי כָּל אוֹתוֹ הָעִקָּר שֶׁל הָרוּחַ בְּשָׁעָה שֶׁיִּתְבּוֹנֵן בּוֹ, כַּאֲשֶׁר יִרְאֶה אֶת אֵלִיָּהוּ, תִּהְיֶה דְבֵקוּת בּוֹ כָּרָאוּי.</p>\n<p>בֹּא רְאֵה, מִי שֶׁמִּסְתַּכֵּל בְּמַה שֶּׁלּוֹמֵד מֵרַבּוֹ וְרוֹאֶה אוֹתוֹ בְּאוֹתָהּ הַחָכְמָה, יָכוֹל לְהִתּוֹסֵף יוֹתֵר בְּאוֹתָהּ הָרוּחַ. בֹּא רְאֵה, שֶׁהֲרֵי יוֹסֵף בְּכָל מַה שֶּׁעָשָׂה הָיָה רוֹאֶה בָּרוּחַ שֶׁל הַחָכְמָה אֶת אוֹתָהּ הַדְּמוּת שֶׁל אָבִיו. הָיָה מִתְבּוֹנֵן, וּמִשּׁוּם כָּךְ הָיָה הַדָּבָר מִסְתַּיֵּעַ לוֹ, וְנוֹסְפָה לוֹ רוּחַ אַחֶרֶת בְּאוֹר יוֹתֵר עֶלְיוֹן.</p>\n<p>בְּשָׁעָה שֶׁאָמַר לוֹ אוֹתוֹ הָרָשָׁע וְהִנֵּה גֶפֶן לְפָנָי, הִזְדַּעֲזַע יוֹסֵף, שֶׁלֹּא הָיָה יוֹדֵעַ עַל מַה יָּבֹא הַדָּבָר. כֵּיוָן שֶׁאָמַר וּבַגֶּפֶן שְׁלֹשָׁה שָׂרִיגִם, מִיָּד הִתְעוֹרְרָה רוּחוֹ וְנוֹסַף בְּאוֹר, וְהִסְתַּכֵּל בִּדְמוּת אָבִיו, וְאָז הֵאִירָה רוּחוֹ וְיָדַע אֶת הַדָּבָר.</p>\n<p>מַה כָּתוּב? וּבַגֶּפֶן שְׁלֹשָׁה שָׂרִיגִם. אָמַר יוֹסֵף, הִנֵּה וַדַּאי בְּשׂוֹרָה שֶׁל שִׂמְחָה בִּשְׁלֵמוּת הִיא. מָה הַטַּעַם? מִשּׁוּם שֶׁהַגֶּפֶן הַזּוֹ נִרְאֵית עַל כְּנֶסֶת יִשְׂרָאֵל, וְהִתְבַּשֵּׂר יוֹסֵף עַל זֶה. וּבַגֶּפֶן שְׁלֹשָׁה שָׂרִיגִם - אֵלּוּ הֵם שָׁלֹשׁ דְּרָגוֹת עֶלְיוֹנוֹת שֶׁיּוֹצְאוֹת מִן הַגֶּפֶן הַזּוֹ, כֹּהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים.</p>\n<p>וְהִיא כְפֹרַחַת עָלְתָה נִצָּהּ, שֶׁהֲרֵי בִּגְלָלָם עוֹלָה כְּנֶסֶת יִשְׂרָאֵל וּמִתְבָּרֶכֶת מֵעִם הַמֶּלֶךְ הָעֶלְיוֹן. הִבְשִׁילוּ אַשְׁכְּלֹתֶיהָ עֲנָבִים - אֵלּוּ הַצַּדִּיקִים שֶׁל הָעוֹלָם, שֶׁהֵם כְּמוֹ עֲנָבִים מְבֻשָּׁלִים כָּרָאוּי. דָּבָר אַחֵר הִבְשִׁילוּ אַשְׁכְּלֹתֶיהָ עֲנָבִים - זֶהוּ הַיַּיִן הַמְשֻׁמָּר בַּעֲנָבָיו מִשֵּׁשֶׁת יְמֵי בְרֵאשִׁית.</p>\n<p>עַד כָּאן הִתְבַּשֵּׂר יוֹסֵף בַּחֲלוֹמוֹ, מִכָּאן וָהָלְאָה הַחֲלוֹם הוּא שֶׁלּוֹ, מִשּׁוּם שֶׁיֵּשׁ לוֹ חֲלוֹמוֹת, וְלַאֲחֵרִים. וָאֶקַּח אֶת הָעֲנָבִים, שֶׁהוּא לוֹ, לְעַצְמוֹ.</p>\n<p>שָׁנִינוּ, מִי שֶׁרוֹאֶה עֲנָבִים לְבָנִים בַּחֲלוֹם, סִימָן יָפֶה לוֹ. שְׁחוֹרִים - לֹא. מָה הַטַּעַם? מִשּׁוּם שֶׁהוּא הַסּוֹד שֶׁל שְׁתֵּי דְרָגוֹת יְדוּעוֹת, אוֹתָם שְׁחוֹרִים וּלְבָנִים. זֶה הוּא טוֹב, וְזֶה הוּא לֹא טוֹב, וְכָל הָעֲנָבִים תְּלוּיִים בְּסוֹד הָאֱמוּנָה, וְעַל כֵּן נִפְרָדִים בְּחָכְמָה, הֵן לְטוֹב הֵן לְרַע. אֵלּוּ צְרִיכִים רַחֲמִים, וְאֵלּוּ הַשְׁגָּחָה שֶׁל רַחֲמִים.</p>\n<p>בֹּא רְאֵה, אָדָם הָרִאשׁוֹן, אִשְׁתּוֹ סָחֲטָה לוֹ עֲנָבִים וְגָרְמָה לוֹ מָוֶת וּלְכָל יִשְׂרָאֵל וּלְכָל הָעוֹלָם. נֹחַ בָּא לָעֲנָבִים הַלָּלוּ, וְלֹא נִשְׁמַר כָּרָאוּי, מַה כָּתוּב? (בראשית ט) וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה, בְּהֵ\"א. בְּנֵי אַהֲרֹן שָׁתוּ יַיִן מֵהֶם, וְהִקְרִיבוּ קָרְבָּן בְּאוֹתוֹ הַיַּיִן וּמֵתוּ, וַהֲרֵי נִתְבָּאֵר. וּמִשּׁוּם כָּךְ כָּתוּב (דברים לב) עֲנָבֵמוֹ עִנְּבֵי רוֹשׁ אַשְׁכְּלֹת מְרֹרֹת לָמוֹ, מִשּׁוּם שֶׁאוֹתָם הָעֲנָבִים גָּרְמוּ אֶת זֶה.</p>\n<p>רָאָה עֲנָבִים שֶׁהֵם טוֹבִים בְּאוֹתוֹ הַכֶּרֶם שֶׁמַּעֲלִים נַחַת וְרֵיחַ בִּדְרָגוֹת שְׁלֵמוֹת כָּרָאוּי. וְעַל זֶה יוֹסֵף יָדַע אֶת הַדָּבָר וְהִסְתַּכֵּל בָּעִקָּר וּפָתַר הַחֲלוֹם עַל בֻּרְיוֹ, מִשּׁוּם שֶׁהִתְבַּשֵּׂר בְּאוֹתוֹ הַחֲלוֹם כָּרָאוּי, וּמִשּׁוּם כָּךְ פָּתַר הַפִּתְרוֹן לְטוֹב וְכָךְ הִתְקַיֵּם.</p>\n<p>מַה כָּתוּב? וַיַּרְא שַׂר הָאֹפִים כִּי טוֹב פָּתָר וַיֹּאמֶר אֶל יוֹסֵף אַף אֲנִי בַּחֲלוֹמִי וְהִנֵּה שְׁלֹשָׁה סַלֵּי חֹרִי עַל רֹאשִׁי. בֹּא רְאֵה, אֲרוּרִים הֵם הָרְשָׁעִים, שֶׁכָּל מַעֲשֵׂיהֶם כֻּלָּם לְרַע, וְכָל אוֹתָם הַדְּבָרִים שֶׁהֵם אוֹמְרִים, כֻּלָּם לְרַע וּלְהָרַע.</p>\n<p>כֵּיוָן שֶׁפָּתַח אֶת פִּיו בְּאַף, מִיָּד פָּחַד יוֹסֵף, וְיָדַע שֶׁכָּל דְּבָרָיו הֵם לְהָרַע וּבְשׂוֹרָה שֶׁל רַע בְּפִיו. וְהִנֵּה שְׁלֹשָׁה סַלֵּי חֹרִי עַל רֹאשִׁי. אָז יָדַע יוֹסֵף שֶׁהִתְבַּשֵּׂר עַל חֻרְבַּן בֵּית הַמִּקְדָּשׁ, וְיִשְׂרָאֵל בַּגָּלוּת, שֶׁיִּגְלוּ מִן הָאָרֶץ הַקְּדוֹשָׁה.</p>\n<p>רְאֵה מַה כָּתוּב, וּבַסַּל הָעֶלְיוֹן מִכֹּל מַאֲכַל פַּרְעֹה מַעֲשֵׂה אֹפֶה וְהָעוֹף אֹכֵל אֹתָם מִן הַסַּל מֵעַל רֹאשִׁי. אֵלּוּ הֵם שְׁאָר הָעַמִּים שֶׁמִּתְכַּנְּסִים עַל יִשְׂראֵל וְהוֹרְגִים אוֹתָם וּמַחֲרִיבִים בֵּיתָם וּמְפַזְּרִים אוֹתָם לְאַרְבַּעַת צִדְדֵי הָעוֹלָם. וְהַכֹּל הִסְתַּכֵּל יוֹסֵף, וְיָדַע שֶׁאוֹתוֹ הַחֲלוֹם עַל יִשְׂרָאֵל כְּשֶׁיִּהְיוּ בְּחִיּוּב לִפְנֵי הַמֶּלֶךְ. מִיָּד פָּתַר לוֹ פִּתְרוֹן לְרַע, וְהִתְקַיֵּם בּוֹ.</p>\n<p>וּבֹא וּרְאֵה, שְׁתֵּי הַדְּרָגוֹת הַלָּלוּ שֶׁרָאָה זֶה וְרָאָה זֶה - זֶה רָאָה כְּשֶׁעוֹלָה וְשׁוֹלֶטֶת הַדַּרְגָּה הָעֶלְיוֹנָה וּמְאִירָה הַלְּבָנָה, וְזֶה רָאָה שֶׁנֶּחְשָׁךְ וְשׁוֹלֵט עָלֶיהָ הַנָּחָשׁ הָרַע, וּמִשּׁוּם כָּךְ הִסְתַּכֵּל יוֹסֵף בַּחֲלוֹם הַהוּא, וּפָתַר אוֹתוֹ פִּתְרוֹן לְרַע. וְעַל כֵּן הַכֹּל עוֹמֵד בְּפִתְרוֹן, וְזֶה וָזֶה רָאוּ, בִּשְׁתֵּי הַדְּרָגוֹת הַלָּלוּ, שֶׁשּׁוֹלֵט זֶה וְשׁוֹלֵט זֶה.</p>"],[9522011395,"<p>רַבִּי יְהוּדָה פָּתַח, (תהלים נא) לֵב טָהוֹר בְּרָא לִי אֱלֹהִים וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ, אֲבָל לֵב טָהוֹר, כְּמוֹ שֶׁנֶּאֱמַר (מלכים א ג) וְנָתַתָּ לְעַבְדְּךְ לֵב שּמֵעַ וְגוֹ', וְכָתוּב (משלי טו) וְטוֹב לֵב מִשְׁתֶּה תָּמִיד, וּמִשּׁוּם כָּךְ לֵב טָהוֹר וַדַּאי.</p>\n<p>וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי - זֶהוּ רוּחַ נָכוֹן וַדַּאי, כְּמוֹ שֶׁנֶּאֱמַר (בראשית א) וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, וְהִתְעוֹרְרוּ, זוֹ רוּחוֹ שֶׁל הַמָּשִׁיחַ, וְהִתְעוֹרְרוּ (יחזקאל יא) וְרוּחַ חֲדָשָׁה אֶתֵּן בְּקִרְבְּכֶם. וְדָוִד הִתְפַּלֵּל, אוֹתוֹ רוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי.</p>\n<p>מִשּׁוּם שֶׁיֵּשׁ מֵהַצַּד הָאַחֵר לֵב טָמֵא וְרוּחַ עִוְעִים שֶׁמַּסְטֶה אֶת בְּנֵי הָעוֹלָם, וְזוֹ הִיא רוּחַ טֻמְאָה שֶׁנִּקְרֵאת רוּחַ עִוְעִים, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה יט) ה' מָסַךְ בְּקִרְבָּהּ רוּחַ עִוְעִים, וְעַל כֵּן וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. מַה זֶּה חַדֵּשׁ? זֶה חִדּוּשׁ הַלְּבָנָה. בְּשָׁעָה שֶׁמִּתְחַדֶּשֶׁת הַלְּבָנָה, דָּוִד מֶלֶךְ יִשְׂרָאֵל חַי וְקַיָּם, וּמִשּׁוּם כָּךְ חַדֵּשׁ.</p>\n<p>רַבִּי אֶלְעָזָר וְרַבִּי יוֹסֵי הָיוּ הוֹלְכִים בַּדֶּרֶךְ. אָמַר רַבִּי יוֹסֵי לְרַבִּי אֶלְעָזָר, זֶה שֶׁכָּתוּב (מלכים א כב) וַיֵּצֵא הָרוּחַ וַיַּעֲמֹד לִפְנֵי ה' וַיֹּאמֶר אֲנִי אֲפַתֶּנּוּ וַיֹּאמֶר ה' אֵלָיו בַּמָּה. וַיֹּאמֶר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר בְּפִי כָּל נְבִיאָיו וַיֹּאמֶר תְּפַתֶּה וְגַם תּוּכָל צֵא וַעֲשֵׂה כֵן. וְשָׁנִינוּ שֶׁהָיְתָה רוּחַ נָבוֹת הַיִּזְרְעֵאלִי. וְכִי הַנְּשָׁמוֹת, כֵּיוָן שֶׁעוֹלוֹת וְעוֹמְדוֹת לְמַעְלָה, הֵן יְכוֹלוֹת לָשׁוּב לָעוֹלָם הַזֶּה? וְהַדָּבָר תָּמוּהַּ שֶׁאָמַר, אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר בְּפִי וְגוֹ'.</p>\n<p>וְעוֹד, מָה הַטַּעַם נֶעֱנַשׁ עָלָיו אַחְאָב? שֶׁהֲרֵי דִּין הַתּוֹרָה שֶׁשָּׂם שְׁמוּאֵל לִפְנֵי יִשְׂרָאֵל כָּךְ הוּא, שֶׁכָּתוּב (שמואל א ח) אֶת שְׂדוֹתֵיכֶם וְכַרְמֵיכֶם וְזֵיתֵיכֶם הַטּוֹבִים יִקָּח, וְאִם אַחְאָב נָטַל אוֹתָהּ כֶּרֶם בְּנָבוֹת, דִּין הָיָה! וְעוֹד, שֶׁהָיְתָה לוֹ כֶּרֶם אַחֶרֶת, אוֹ זָהָב, וְלֹא רָצָה!</p>\n<p>אָמַר לוֹ, יָפֶה שָׁאַלְתָּ. בֹּא רְאֵה, הָרוּחַ הַזּוֹ שֶׁאָמְרוּ שֶׁהִיא רוּחַ שֶׁל נָבוֹת, כָּאן יֵשׁ לְהִסְתַּכֵּל - וְכִי הָרוּחַ שֶׁל נָבוֹת יְכוֹלָה לַעֲלוֹת וְלַעֲמֹד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא לְבַקֵּשׁ שֶׁקֶר, שֶׁכָּתוּב וַיֵּצֵא הָרוּחַ? וְאִם הוּא צַדִּיק, אֵיךְ יְבַקֵּשׁ שֶׁקֶר בָּעוֹלָם הַהוּא, שֶׁהוּא עוֹלָם שֶׁל אֱמֶת? וּמָה בָּעוֹלָם הַזֶּה לֹא צָרִיךְ צַדִּיק שֶׁקֶר, בָּעוֹלָם הַהוּא לֹא כָּל שֶׁכֵּן? וְאִם אֵינוֹ צַדִּיק, אֵיךְ יָכוֹל לַעֲמֹד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא?</p>\n<p>אֶלָּא וַדַּאי נָבוֹת לֹא הָיָה כָּל כָּךְ צַדִּיק לַעֲמֹד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, אֶלָּא רוּחַ אַחֶרֶת הָיְתָה שֶׁשָּׁלְטָה בָּעוֹלָם, שֶׁזּוֹהִי רוּחַ שֶׁתָּמִיד עוֹמֶדֶת וְעוֹלָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְזוֹהִי שֶׁמַּסְטָה אֶת בְּנֵי הָעוֹלָם לְשַׁקֵּר, וּמִי שֶׁהוּא רָגִיל בְּשֶׁקֶר, מִשְׁתַּדֵּל תָּמִיד בְּשֶׁקֶר, וְעַל זֶה אָמַר אֵצֵא וְהָיִיתִי רוּחַ שֶׁקֶר וְגוֹ', וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא אָמַר לוֹ צֵא וַעֲשֵׂה כֵן. צֵא מִכָּאן, כְּמוֹ שֶׁבֵּאֲרוּהוּ שֶׁכָּתוּב (תהלים קא) דֹּבֵר שְׁקָרִים לֹא יִכּוֹן לְנֶגֶד עֵינָי, וּמִשּׁוּם זֶה הִיא רוּחַ שֶׁקֶר וַדַּאי.</p>\n<p>וְעוֹד, עַל מַה שֶּׁהָרַג אֶת נָבוֹת וְנָטַל אֶת כַּרְמוֹ, לָמָּה הָרַג אוֹתוֹ הֶרֶג? אֶלָּא שֶׁהָרַג אוֹתוֹ בְּלִי דִין נֶעֱנַשׁ. הָרַג אוֹתוֹ בְּלִי דִין וְנָטַל אֶת כַּרְמוֹ, וּמִשּׁוּם כָּךְ כָּתוּב (מלכים א כא) הֲרָצַחְתָּ וְגַם יָרָשְׁתָּ, וְעַל כֵּן נֶעֱנַשׁ. וּבא וּרְאֵה כַּמָּה הֵם בְּנֵי אָדָם בָּעוֹלָם שֶׁרוּחַ הַשֶּׁקֶר הַזּוֹ מַסְטָה אוֹתָם בְּשֶׁקֶר, וְהוּא שׁוֹלֵט בָּעוֹלָם בְּכַמָּה צְדָדִים וּבְכַמָּה מַעֲשִׂים, וְהִנֵּה בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>\n<p>וְעַל כֵּן דָּוִד הַמֶּלֶךְ בִּקֵּשׁ לְהִשָּׁמֵר מִמֶּנּוּ וְרָצָה לָצֵאת מִתּוֹךְ הַטֻּמְאָה, שֶׁכָּתוּב (תהלים נא) לֵב טָהוֹר בְּרָא לִי אֱלֹהִים וְרוּחַ נָכוֹן חַדֵּשׁ בְּקִרְבִּי. זוֹ הִיא רוּחַ נָכוֹן, וְהָאַחֵר הוּא רוּחַ שֶׁקֶר. וְעַל כֵּן שְׁתֵּי דְרָגוֹת הֵן, אַחַת קְדוֹשָׁה וְאַחַת טְמֵאָה.</p>\n<p>פָּתַח וְאָמַר, (יואל ב) וַה' נָתַן קוֹלוֹ לִפְנֵי חֵילוֹ כִּי רַב מְאֹד מַחֲנֵהוּ כִּי עָצוּם עֹשֵׂה דְבָרוֹ וְגוֹ'. אֶת הַפָּסוּק הַזֶּה בֵּאֲרוּהוּ. אֲבָל וַה', בְּכָל מָקוֹם הוּא וּבֵית דִּינוֹ. נָתַן קוֹלוֹ - זֶהוּ הַקּוֹל שֶׁכָּתוּב (דברים ד) קוֹל דְּבָרִים. וְכָתוּב שָׁם (שמות ד) לֹא אִישׁ דְּבָרִים. מִי אִישׁ הַדְּבָרִים? כְּמוֹ שֶׁנֶּאֱמַר (דברים לג) אִישׁ הָאֱלֹהִים. לִפְנֵי חֵילוֹ - אֵלּוּ הֵם יִשְׂרָאֵל.</p>\n<p>כִּי רַב מְאֹד מַחֲנֵהוּ - כְּמוֹ שֶׁנֶּאֱמַר (איוב כה) הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. שֶׁכַּמָּה מְמֻנִּים וּשְׁלוּחִים יֵשׁ לַקָּדוֹשׁ-בָּרוּךְ-הוּא, וְכֻלָּם עוֹמְדִים לְהַשְׂטִין עַל יִשְׂרָאֵל (ז\"ח כדי לטמא אותם), וְעַל כֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא מִזְדַּמֵּן לִפְנֵי יִשְׂרָאֵל כְּדֵי לִשְׁמֹר אוֹתָם, וְלֹא יוּכְלוּ לְקַטְרֵג לָהֶם.</p>\n<p>כִּי עָצוּם עֹשֵׂה דְבָרוֹ, מִי עָצוּם? זֶהוּ הַצַּדִּיק, אוֹתוֹ שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה הַקְּדוֹשָׁה יוֹמָם וָלַיְלָה. דָּבָר אַחֵר כִּי עָצוּם - זֶה הַמְקַטְרֵג שֶׁנִּמְצָא לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהוּא חָזָק כְּבַרְזֶל, קָשֶׁה כַּסֶּלַע. עֹשֵׂה דְבָרוֹ - שֶׁנּוֹטֵל רְשׁוּת מִלְמַעְלָה, וְנוֹטֵל אֶת הַנְּשָׁמָה מִלְּמַטָּה.</p>\n<p>כִּי גָדוֹל יוֹם ה' וְנוֹרָא מְאֹד וּמִי יְכִילֶנּוּ - שֶׁהוּא שׁוֹלֵט עַל הַכֹּל וְעֶלְיוֹן וְתַקִּיף עַל כֻּלָּם, וְכֻלָּם תַּחַת שִׁלְטוֹנוֹ. אַשְׁרֵי הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא רוֹצֶה בָהֶם תָּמִיד לְזַכּוֹת אוֹתָם לָעוֹלָם הַבָּא וּלְשַׂמֵּחַ אוֹתָם בְּשִׂמְחַת הַצַּדִּיקִים שֶׁעֲתִידִים לִשְׂמֹחַ עִם הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁכָּתוּב (תהלים ה) וְיִשְׂמְחוּ כָל חוֹסֵי בָךְ לְעוֹלָם יְרַנֵּנוּ וְתָסֵךְ עָלֵימוֹ וְיַעְלְצוּ בְךְ אֹהֲבֵי שְׁמֶךְ. בָּרוּךְ ה' לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9522011396,"<p>וַיְהִי מִקֵּץ. רַבִּי חִיָּיא פָּתַח וְאָמַר, (איוב כח) קֵץ שָׂם לַחֹשֶׁךְ וּלְכָל תַּכְלִת הוּא חוֹקֵר אֶבֶן אֹפֶל וְצַלְמָוֶת. הַפָּסוּק הַזֶּה נִתְבָּאֵר, קֵץ שָׂם לַחֹשֶׁךְ - זֶהוּ הַקֵּץ שֶׁל הַשְּׂמֹאל, שֶׁהוּא מְשׁוֹטֵט בָּעוֹלָם וּמְשׁוֹטֵט לְמַעְלָה, וְעוֹמֵד לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּמַסְטִין וּמְקַטְרֵג עַל הָעוֹלָם, וַהֲרֵי נִתְבָּאֵר. וּלְכָל תַּכְלִית הוּא חוֹקֵר - שֶׁהֲרֵי כָּל מַעֲשָׂיו אֵינָם לְטוֹב, אֶלָּא תָּמִיד לְכַלּוֹת וְלַעֲשׂוֹת כְּלָיָה בָּעוֹלָם.</p>\n<p>אֶבֶן אֹפֶל וְצַלְמָוֶת - זוֹ אֶבֶן נֶגֶף שֶׁבָּהּ נִכְשָׁלִים הָרְשָׁעִים, וְעוֹמֶדֶת בָּזֶה שֶׁנִּקְרֵאת (שם י) אֶרֶץ עֵפָתָה כְּמוֹ אֹפֶל. בּא רְאֵה, יֵשׁ אֶרֶץ חַיִּים לְמַעְלָה, וְזוֹ הִיא אֶרֶץ יִשְׂרָאֵל. (ויש ארץ למטה, ונקראת) אֹפֶל וְצַלְמָוֶת. אֹפֶל שֶׁיָּצְאָה מֵאֶרֶץ עֵפָתָה. מַהוּ אֹפֶל וְצַלְמָוֶת? זֶהוּ הַקֵּץ, שֶׁהוּא מִצַּד שֶׁל הַחֹשֶׁךְ, זֻהֲמַת הַזָּהָב, וְהִנֵּה נִתְבָּאֵר</p>\n<p>בֹּא רְאֵה כַּמָּה יֵשׁ לִבְנֵי אָדָם לְהִתְבּוֹנֵן בַּעֲבוֹדַת הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהִשְׁתַּדֵּל בַּתּוֹרָה יָמִים וְלֵילוֹת כְּדֵי שֶׁיֵּדְעוּ וְיִסְתַּכְּלוּ בַּעֲבוֹדָתוֹ, שֶׁהֲרֵי הַתּוֹרָה מַכְרִיזָה בְּכָל יוֹם לִפְנֵי הָאָדָם וְאוֹמֶרֶת: (משלי ט) מִי פֶתִי יָסֻר הֵנָּה חֲסַר לֵב וְאָמְרָה לּוֹ, וַהֲרֵי בֵּאַרְנוּ אֶת הַדְּבָרִים.</p>\n<p>וּכְשֶׁאָדָם מִשְׁתַּדֵּל בַּתּוֹרָה וְנִדְבָּק בָּהּ, זוֹכֶה לְהִתְחַזֵּק בְּעֵץ הַחַיִּים, שֶׁכָּתוּב (שם ג) עֵץ חַיִּים וְגוֹ'. וּבא וּרְאֵה, כְּשֶׁאָדָם מַחֲזִיק בְּעֵץ הַחַיִּים בָּעוֹלָם הַזֶּה, הוּא מַחֲזִיק בּוֹ לָעוֹלָם הַבָּא. שֶׁהֲרֵי כְּמוֹ הַנְּשָׁמוֹת יוֹצְאוֹת מִן הָעוֹלָם הַזֶּה, כָּךְ מְתֻקָּנוֹת לָהֶן דְּרָגוֹת לָעוֹלָם הַבָּא.</p>\n<p>בֹּא רְאֵה, עֵץ הַחַיִּים הוּא בְּכַמָּה דְרָגוֹת נִפְרָדִים זֶה מִזֶּה, וְכֻלָּם אֶחָד. שֶׁהֲרֵי בְּעֵץ הַחַיִּים יֵשׁ דְּרָגוֹת אֵלּוּ עַל אֵלּוּ, עֲנָפִים וְעָלִים, קְלִפּוֹת, וְגוּף הָאִילָן, שָׁרָשִׁים, וְהַכֹּל הוּא הָאִילָן. כְּמוֹ כֵן כָּל מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, הוּא נִתְקָן וּמִתְחַזֵּק בְּעֵץ הַחַיִּים.</p>\n<p>וְכָל בְּנֵי הָאֱמוּנָה, יִשְׂרָאֵל, כֻּלָּם מִתְגַּבְּרִים בְּעֵץ הַחַיִּים, כֻּלָּם אֲחוּזִים בָּעֵץ מַמָּשׁ, מֵהֶם בְּאוֹתוֹ הַגּוּף שֶׁבּוֹ, מֵהֶם אֲחוּזִים בָּעֲנָפִים, מֵהֶם בֶּעָלִים, מֵהֶם בַּשָּׂרָשִׁים. נִמְצְאוּ שֶׁכֻּלָּם אֲחוּזִים בְּעֵץ הַחַיִּים. וְאוֹתָם שֶׁמִּשְׁתַּדְּלִים בַּתּוֹרָה, כֻּלָּם אֲחוּזִים בְּגוּף הָאִילָן. וּמִשּׁוּם כָּךְ מִי שֶׁמִּשְׁתַּדֵּל בַּתּוֹרָה, הוּא אָחוּז בַּכֹּל, וַהֲרֵי פֵּרְשׁוּהָ וְנִתְבָּאֵר.</p>\n<p>וַיְהִי מִקֵּץ, מַה זֶּה מִקֵּץ? רַבִּי שִׁמְעוֹן אָמַר, הַמָּקוֹם שֶׁאֵין בּוֹ זְכִירָה, וְזֶהוּ קֵץ הַשְּׂמֹאל. מָה הַטַּעַם? מִשּׁוּם שֶׁכָּתוּב (בראשית מ) כִּי אִם זְכַרְתַּנִי אִתְּךְ כַּאֲשֶׁר יִיטַב לָךְ. וְכִי כָּךְ רָאוּי לְיוֹסֵף הַצַּדִּיק שֶׁהוּא אָמַר כִּי אִם זְכַרְתַּנִי אִתְּךְ? אֶלָּא כֵּיוָן שֶׁהִסְתַּכֵּל יוֹסֵף בַּחֲלוֹמוֹ, אָמַר, וַדַּאי חֲלוֹם שֶׁל זְכִירָה הוּא, וְהוּא טָעָה בָּזֶה, שֶׁהֲרֵי הַכֹּל הָיָה בַּקָּדוֹשׁ-בָּרוּךְ-הוּא.</p>\n<p>וְעַל כֵּן הַמָּקוֹם שֶׁהָיְתָה בּוֹ שִׁכְחָה, עָמַד לְפָנָיו. מַה כָּתוּב? וְלֹא זָכַר שַׂר הַמַּשְׁקִים אֶת יוֹסֵף וַיִּשְׁכָּחֵהוּ. כֵּיוָן שֶׁאָמַר וְלֹא זָכַר שַׂר הַמַּשְׁקִים, מַה זֶּה וַיִּשְׁכָּחֵהוּ? אֶלָּא וַיִּשְׁכָּחֵהוּ, הַמָּקוֹם שֶׁיֵּשׁ בּוֹ שִׁכְחָה, וְזֶהוּ הַקֵּץ שֶׁל צַד הַחֹשֶׁךְ. שְׁנָתַיִם יָמִים, מַה זֶּה שְׁנָתַיִם? שֶׁשָּׁבָה הַדַּרְגָּה לַדַּרְגָּה שֶׁיֵּשׁ בָּהּ זְכִירָה.</p>\n<p>וּפַרְעֹה חֹלֵם וְהִנֵּה עֹמֵד עַל הַיְאֹר. זֶה הָיָה הַחֲלוֹם שֶׁל יוֹסֵף, מִשּׁוּם שֶׁכָּל נָהָר הוּא שֶׁל יוֹסֵף הַצַּדִּיק, וְזֶהוּ הַסּוֹד שֶׁמִּי שֶׁרוֹאֶה נָהָר בַּחֲלוֹם רוֹאֶה שָׁלוֹם, שֶׁכָּתוּב (ישעיה סו) הִנְנִי נֹטֶה אֵלֶיהָ כְּנָהָר שָׁלוֹם.</p>"]]});
